				text5 = string.Format("SELECT {1}, tCore_Header{0}.iDate,tCore_Data{0}.iDueDate,Voucher,InnerTable.iMasterId, \r\n                        Debit, Credit,TranDr,TranCr,LocalDr,LocalCr,bBrs,tCore_Header{0}.iVoucherClass, InnerTable.iVoucherType\r\n                        FROM \r\n                        (\r\n                            SELECT tCore_Data{0}.iBodyId, cCore_Vouchers{0}.sAbbr+' : '+tCore_Header{0}.sVoucherNo[Voucher],\r\n                            mCore_Account.sName[Account], iBookNo[iMasterId],\r\n                            CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n                            CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit,\r\n\t                        CASE WHEN ISNULL(mFxAmount2,mAmount2) < 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranDr, \r\n\t                        CASE WHEN ISNULL(mFxAmount2,mAmount2) > 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranCr,\r\n                            CASE WHEN ISNULL(fLocalAmount2,mAmount2) < 0 THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END LocalDr, \r\n\t                        CASE WHEN ISNULL(fLocalAmount2,mAmount2) > 0 THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END LocalCr\r\n                            , tCore_Header{0}.iVoucherType \r\n                            FROM \r\n                            tCore_Data{0}\r\n                            JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                            JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n                            JOIN mCore_Account ON tCore_Data{0}.iCode = mCore_Account.iMasterId\r\n                            LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId\r\n                            WHERE tCore_Data{0}.iBookNo  <> 2 and tCore_Data{0}.iType in (0,1) {3} \r\n                            UNION ALL\r\n                            SELECT tCore_Data{0}.iBodyId,  cCore_Vouchers{0}.sAbbr+' : '+tCore_Header{0}.sVoucherNo[Voucher],\r\n                            mCore_Account.sName[Account], iCode[iMasterId],\r\n                            CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n                            CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit,\r\n\t                        CASE WHEN ISNULL(mFXAmount1,mAmount1) < 0 THEN ISNULL(mFXAmount1,mAmount1) ELSE 0 END TranDr, \r\n\t                        CASE WHEN ISNULL(mFXAmount1,mAmount1) > 0 THEN ISNULL(mFXAmount1,mAmount1) ELSE 0 END TranCr,\r\n                            CASE WHEN ISNULL(fLocalAmount1,mAmount1) < 0 THEN ISNULL(fLocalAmount1,mAmount1) ELSE 0 END LocalDr, \r\n\t                        CASE WHEN ISNULL(fLocalAmount1,mAmount1) > 0 THEN ISNULL(fLocalAmount1,mAmount1) ELSE 0 END LocalCr\r\n                            , tCore_Header{0}.iVoucherType \r\n                            FROM \r\n                            tCore_Data{0} \r\n                            JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                            JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n                            JOIN mCore_Account ON tCore_Data{0}.iBookNo = mCore_Account.iMasterId\r\n                            LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId\r\n                            WHERE tCore_Data{0}.iCode  <> 2 and tCore_Data{0}.iType in (0,1) {3} \r\n                            UNION ALL\r\n\t                        SELECT TOP 1 tCore_Data{0}.iBodyId, '','', tCore_Data{0}.iBookNo,\r\n                            mAmount1,0,ISNULL(mFXAmount1,mAmount1)mFXAmount1,0,ISNULL(fLocalAmount1,mAmount1),0 , tCore_Header{0}.iVoucherType  \r\n\t                        FROM tCore_Data{0} \r\n\t                        JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                            LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId\r\n\t                        WHERE tCore_Data{0}.iBookNo  = 2 and tCore_Data{0}.iType in (0,1) {3} \r\n                            {2} \r\n                        )InnerTable\r\n                        JOIN tCore_Data{0} ON tCore_Data{0}.iBodyId = InnerTable.iBodyId  \r\n                        JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                        LEFT JOIN tCore_Indta{0} ON tCore_Indta{0}.iBodyId = tCore_Data{0}.iBodyId \r\n                        --LEFT JOIN tCore_Indta{0} Cogs ON Cogs.iBodyId = tCore_Data{0}.iMainBodyId AND iType=5\r\n                        LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = InnerTable.iBodyId\r\n                        JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n                        JOIN vrCore_Account BookNo ON tCore_Data{0}.iBookNo = BookNo.iMasterId AND BookNo.iTreeId = 0\r\n                        JOIN vrCore_Account Code ON tCore_Data{0}.iCode = Code.iMasterId AND Code.iTreeId = 0\r\n                        LEFT JOIN mCore_Currency WITH (READUNCOMMITTED) ON mCore_Currency.iCurrencyId = tCore_Data{0}.iCurrencyId ", Suffix, text7, text38, text39);
			}
			break;
		case FocusReport.DayBook:
			text6 = $"tCore_Header{Suffix}.iHeaderId,Voucher";
			if (FConvert.GetInputValue(objRec.Inputs, 1) == 1)
			{
				text6 = string.Format("CASE WHEN AccountType = 1 AND tCore_Header{0}.iVoucherClass = {1} THEN 0 ELSE tCore_Header{0}.iHeaderId END[iHeaderId]\r\n                        ,CASE WHEN AccountType = 1 AND tCore_Header{0}.iVoucherClass = {1} THEN 'Cash Sales for the day' ELSE Voucher END[Voucher]", Suffix, 3328);
			}
			text5 = string.Format("SELECT {3},InnerTable.Account, \r\n                    SUM(CASE WHEN AccountType = {1} THEN Credit ELSE 0 END)[Cash Credit],\r\n                    SUM(CASE WHEN AccountType = {1} THEN Debit ELSE 0 END)[Cash Debit],\r\n                    SUM(CASE WHEN AccountType = {2} THEN Credit ELSE 0 END)[Bank Credit],\r\n                    SUM(CASE WHEN AccountType = {2} THEN Debit ELSE 0 END)[Bank Debit],\r\n                    SUM(CASE WHEN AccountType <> {1} AND AccountType <> 2 THEN Credit ELSE 0 END)[Other Credit],\r\n                    SUM(CASE WHEN AccountType <> {1} AND AccountType <> 2 THEN Debit ELSE 0 END)[Other Debit],\r\n                    SUM(Debit)[Debit Amount], SUM(Credit)[Credit Amount],\r\n                    SUM(TranDr)[TranDr], SUM(TranCr)[TranCr],\r\n                    SUM(LocalDr)[LocalDr], SUM(LocalCr)[LocalCr],\r\n                    CONVERT(VARCHAR(10),dbo.IntToDate(iDate),105)[Date]\r\n                    FROM \r\n                    (\r\n\t                    SELECT tCore_Data{0}.iBodyId, cCore_Vouchers{0}.sAbbr+' : '+tCore_Header{0}.sVoucherNo[Voucher],\r\n\t                    mCore_Account.sName[Account], mCore_Account.iAccountType[AccountType], iBookNo[iMasterId],\r\n\t                    CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n\t                    CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit,\r\n                        CASE WHEN ISNULL(mFxAmount2,mAmount2) < 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranDr, \r\n\t                    CASE WHEN ISNULL(mFxAmount2,mAmount2) > 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranCr,\r\n                        CASE WHEN ISNULL(fLocalAmount2,mAmount2) < 0 THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END LocalDr, \r\n\t                    CASE WHEN ISNULL(fLocalAmount2,mAmount2) > 0 THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END LocalCr \r\n\t                    FROM tCore_Header{0}\r\n\t                    JOIN tCore_Data{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t                    LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId\r\n\t                    JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n\t                    JOIN mCore_Account ON tCore_Data{0}.iBookNo = mCore_Account.iMasterId\r\n\t                    WHERE tCore_Data{0}.iBookNo  <> 2\r\n\t                    UNION ALL\r\n\t                    SELECT tCore_Data{0}.iBodyId, cCore_Vouchers{0}.sAbbr+' : '+tCore_Header{0}.sVoucherNo[Voucher],\r\n\t                    mCore_Account.sName[Account], mCore_Account.iAccountType[AccountType], iCode[iMasterId],\r\n\t                    CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n\t                    CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit,\r\n                        CASE WHEN ISNULL(mFXAmount1,mAmount1) < 0 THEN ISNULL(mFXAmount1,mAmount1) ELSE 0 END TranDr, \r\n\t                    CASE WHEN ISNULL(mFXAmount1,mAmount1) > 0 THEN ISNULL(mFXAmount1,mAmount1) ELSE 0 END TranCr,\r\n                        CASE WHEN ISNULL(fLocalAmount1,mAmount1) < 0 THEN ISNULL(fLocalAmount1,mAmount1) ELSE 0 END LocalDr, \r\n\t                    CASE WHEN ISNULL(fLocalAmount1,mAmount1) > 0 THEN ISNULL(fLocalAmount1,mAmount1) ELSE 0 END LocalCr\r\n\t                    FROM tCore_Header{0}\r\n\t                    JOIN tCore_Data{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                        LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId\r\n\t                    JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n\t                    JOIN mCore_Account ON tCore_Data{0}.iCode = mCore_Account.iMasterId\r\n\t                    WHERE tCore_Data{0}.iCode  <> 2\r\n                    )InnerTable\r\n                    JOIN tCore_Data{0} ON tCore_Data{0}.iBodyId = InnerTable.iBodyId  \r\n                    JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                    JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType", Suffix, (byte)1, (byte)2, text6);
			break;
		case FocusReport.VirtualBankLedger:
			text5 = string.Format("SELECT InnerTable.iMasterId, InnerTable.iMasterId, CASE WHEN tCore_Header{0}.iVoucherClass IN(7168,5888) THEN tCore_Data{0}.iDueDate ELSE tCore_Header{0}.iDate END[iDate]\r\n                    ,SUM(Debit)[Debit], SUM(Credit)Credit, 0[Bal], SUM(PDCDebit)PDCDebit, SUM(PDCCredit)PDCCredit, 0[PDCBal]\r\n                    ,SUM(TranDr)TranDr, SUM(TranCr)TranCr, 0[TranBal], SUM(PDCTranDr)PDCTranDr, SUM(PDCTranCr)PDCTranCr, 0[PDCTranBal]\r\n                    ,SUM(LocalDr)LocalDr, SUM(LocalCr)LocalCr, 0[LocalBal], SUM(PDCLocalDr)PDCLocalDr, SUM(PDCLocalCr)PDCLocalCr, 0[PDCLocalBal]\r\n                    FROM \r\n                    (\r\n                        SELECT tCore_Data{0}.iBodyId, iBookNo[iMasterId],\r\n                        CASE WHEN mAmount2 < 0 AND iVoucherClass NOT IN (5888,7168) THEN mAmount2 ELSE 0 END Debit, \r\n                        CASE WHEN mAmount2 > 0 AND iVoucherClass NOT IN (5888,7168) THEN mAmount2 ELSE 0 END Credit,\r\n                        CASE WHEN mAmount2 < 0 AND iVoucherClass IN (5888,7168) THEN mAmount2 ELSE 0 END PDCDebit, \r\n                        CASE WHEN mAmount2 > 0 AND iVoucherClass IN (5888,7168) THEN mAmount2 ELSE 0 END PDCCredit,\r\n                        CASE WHEN ISNULL(mFxAmount2,mAmount2) < 0 AND iVoucherClass NOT IN (5888,7168) THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranDr, \r\n                        CASE WHEN ISNULL(mFxAmount2,mAmount2) > 0 AND iVoucherClass NOT IN (5888,7168) THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranCr,\r\n                        CASE WHEN ISNULL(mFxAmount2,mAmount2) < 0 AND iVoucherClass IN (5888,7168) THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END PDCTranDr, \r\n                        CASE WHEN ISNULL(mFxAmount2,mAmount2) > 0 AND iVoucherClass IN (5888,7168) THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END PDCTranCr,\r\n                        CASE WHEN ISNULL(fLocalAmount2,mAmount2) < 0 AND iVoucherClass NOT IN (5888,7168) THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END LocalDr, \r\n                        CASE WHEN ISNULL(fLocalAmount2,mAmount2) > 0 AND iVoucherClass NOT IN (5888,7168) THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END LocalCr,\r\n                        CASE WHEN ISNULL(fLocalAmount2,mAmount2) < 0 AND iVoucherClass IN (5888,7168) THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END PDCLocalDr, \r\n                        CASE WHEN ISNULL(fLocalAmount2,mAmount2) > 0 AND iVoucherClass IN (5888,7168) THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END PDCLocalCr\r\n                        FROM tCore_Header{0} \r\n                        JOIN tCore_Data{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                        LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId\r\n                        WHERE tCore_Header{0}.iVoucherClass <> 256\r\n                        UNION ALL\r\n                        SELECT tCore_Data{0}.iBodyId, iCode[iMasterId],\r\n                        CASE WHEN mAmount1 < 0 AND iVoucherClass NOT IN (5888,7168) THEN mAmount1 ELSE 0 END Debit, \r\n                        CASE WHEN mAmount1 > 0 AND iVoucherClass NOT IN (5888,7168) THEN mAmount1 ELSE 0 END Credit,\r\n                        CASE WHEN mAmount1 < 0 AND iVoucherClass IN (5888,7168) THEN mAmount1 ELSE 0 END PDCDebit, \r\n                        CASE WHEN mAmount1 > 0 AND iVoucherClass IN (5888,7168) THEN mAmount1 ELSE 0 END PDCCredit,\r\n                        CASE WHEN ISNULL(mFXAmount1,mAmount1) < 0 AND iVoucherClass NOT IN (5888,7168) THEN ISNULL(mFXAmount1,mAmount1) ELSE 0 END TranDr, \r\n                        CASE WHEN ISNULL(mFXAmount1,mAmount1) > 0 AND iVoucherClass NOT IN (5888,7168) THEN ISNULL(mFXAmount1,mAmount1) ELSE 0 END TranCr,\r\n                        CASE WHEN ISNULL(mFXAmount1,mAmount1) < 0 AND iVoucherClass IN (5888,7168) THEN ISNULL(mFXAmount1,mAmount1) ELSE 0 END PDCTranDr, \r\n                        CASE WHEN ISNULL(mFXAmount1,mAmount1) > 0 AND iVoucherClass IN (5888,7168) THEN ISNULL(mFXAmount1,mAmount1) ELSE 0 END PDCTranCr,\r\n                        CASE WHEN ISNULL(fLocalAmount1,mAmount1) < 0 AND iVoucherClass NOT IN (5888,7168) THEN ISNULL(fLocalAmount1,mAmount1) ELSE 0 END LocalDr, \r\n                        CASE WHEN ISNULL(fLocalAmount1,mAmount1) > 0 AND iVoucherClass NOT IN (5888,7168) THEN ISNULL(fLocalAmount1,mAmount1) ELSE 0 END LocalCr,\r\n                        CASE WHEN ISNULL(fLocalAmount1,mAmount1) < 0 AND iVoucherClass IN (5888,7168) THEN ISNULL(fLocalAmount1,mAmount1) ELSE 0 END PDCLocalDr, \r\n                        CASE WHEN ISNULL(fLocalAmount1,mAmount1) > 0 AND iVoucherClass IN (5888,7168) THEN ISNULL(fLocalAmount1,mAmount1) ELSE 0 END PDCLocalCr\r\n                        FROM tCore_Header{0}\r\n                        JOIN tCore_Data{0}  ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                        LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId\r\n                        WHERE tCore_Header{0}.iVoucherClass <> 256\r\n                    )InnerTable\r\n                    JOIN @XML.nodes('/Master/r') T(c) ON InnerTable.iMasterId = T.c.value('./@id', 'int')\r\n                    JOIN tCore_Data{0} ON tCore_Data{0}.iBodyId = InnerTable.iBodyId\r\n                    JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId ", Suffix);
			break;
		case FocusReport.OpeningBalanceRegister:
			text5 = string.Format("SELECT tCore_Data{0}.iBodyId,tCore_Header{0}.iDate, cCore_Vouchers{0}.sAbbr+' : '+tCore_Header{0}.sVoucherNo[Voucher],\r\n                        mCore_Account.sName [Account],\r\n                        CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Debit, \r\n                        CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Credit,\r\n\t                    CASE WHEN ISNULL(mFxAmount2,mAmount2) > 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranDr, \r\n\t                    CASE WHEN ISNULL(mFxAmount2,mAmount2) < 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranCr,\r\n                        CASE WHEN ISNULL(fLocalAmount2,mAmount2) > 0 THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END LocalDr, \r\n\t                    CASE WHEN ISNULL(fLocalAmount2,mAmount2) < 0 THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END LocalCr\r\n                        FROM tCore_Header{0}\r\n                        JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n                        LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId   \r\n                        JOIN mCore_Account ON mCore_Account.iMasterId = tCore_Data{0}.iCode AND mCore_Account.iStatus <> 5\r\n                        JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType", Suffix);
			break;
		case FocusReport.ReceipRegister:
		case FocusReport.PaymentRegister:
			text5 = string.Format("SELECT tCore_Data{0}.iBodyId,tCore_Header{0}.iDate, cCore_Vouchers{0}.sAbbr+' : '+tCore_Header{0}.sVoucherNo[Voucher],\r\n                        mCore_Account.sName [Account],\r\n                        CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n                        CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit,\r\n\t                    CASE WHEN ISNULL(mFxAmount2,mAmount2) < 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranDr, \r\n\t                    CASE WHEN ISNULL(mFxAmount2,mAmount2) > 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranCr,\r\n                        CASE WHEN ISNULL(fLocalAmount2,mAmount2) < 0 THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END LocalDr, \r\n\t                    CASE WHEN ISNULL(fLocalAmount2,mAmount2) > 0 THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END LocalCr\r\n                        FROM tCore_Header{0}\r\n                        JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n                        LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId   \r\n                        JOIN mCore_Account ON mCore_Account.iMasterId = tCore_Data{0}.iCode AND mCore_Account.iStatus <> 5\r\n                        JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType", Suffix);
			break;
		case FocusReport.JournalEntryRegister:
			text5 = string.Format("SELECT tCore_Data{0}.iBodyId,tCore_Header{0}.iDate, cCore_Vouchers{0}.sAbbr+' : '+tCore_Header{0}.sVoucherNo[Voucher],\r\n                        mCore_Account.sName [Account],\r\n                        CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n                        CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit,\r\n\t                    CASE WHEN ISNULL(mFxAmount2,mAmount2) < 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranDr, \r\n\t                    CASE WHEN ISNULL(mFxAmount2,mAmount2) > 0 THEN ISNULL(mFxAmount2,mAmount2) ELSE 0 END TranCr,\r\n                        CASE WHEN ISNULL(fLocalAmount2,mAmount2) < 0 THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END LocalDr, \r\n\t                    CASE WHEN ISNULL(fLocalAmount2,mAmount2) > 0 THEN ISNULL(fLocalAmount2,mAmount2) ELSE 0 END LocalCr\r\n                        FROM tCore_Header{0}\r\n                        JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n                        LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId   \r\n                        JOIN mCore_Account ON mCore_Account.iMasterId = tCore_Data{0}.iCode AND mCore_Account.iStatus <> 5\r\n                        JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType", Suffix);
			break;
		case FocusReport.CreditNoteRegister:
		case FocusReport.DebitNoteRegister:
			text5 = string.Format("SELECT tCore_Data{0}.iBodyId,tCore_Header{0}.iDate, cCore_Vouchers{0}.sAbbr+' : '+tCore_Header{0}.sVoucherNo[Voucher],\r\n                        mCore_Account.sName [Account], tCore_Data{0}.mAmount2[Amount]\r\n                        FROM tCore_Header{0}\r\n                        JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n                        JOIN mCore_Account ON mCore_Account.iMasterId = tCore_Data{0}.iCode \r\n                        JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType", Suffix);
			break;
