ore_Header{text11}  on tCore_Header{text11}.iHeaderId= tCore_Data{text11}.iHeaderId\r\n                                join #MasterIdTable MasterIdTable on  tCore_Refrn{text11}.iCode=MasterIdTable.iMasterId\r\n                                where iRefType=0\r\n\t\t\t\t\t\t    ) NewRef\r\n\t\t\t\t\t\t    left join (\r\n\t\t\t\t\t\t\t    select iRef, sum(mBaseAmount)AgainstBase,  {objRec.EndingDate} AgaintDue from tCore_Refrn{text11}  WITH (READUNCOMMITTED)\r\n                                inner join tCore_Data{text11}  on tCore_Refrn{text11}.iBodyId= tCore_Data{text11}.iBodyId\r\n                                inner join tCore_Header{text11}  on tCore_Header{text11}.iHeaderId= tCore_Data{text11}.iHeaderId\r\n                                join #MasterIdTable MasterIdTable on  tCore_Refrn{text11}.iCode=MasterIdTable.iMasterId\r\n                                where iRefType=2 and tCore_Data{text11}.bSuspendUpdateFA <> 1 AND tCore_Header{text11}.bSuspended = 0 AND tCore_Data{text11}.iAuthStatus < 2 \r\n                                AND (tCore_Header{text11}.iDate BETWEEN 0 AND {objRec.EndingDate} )\r\n\t\t\t\t\t\t\t    group by iRef\r\n\t\t\t\t\t\t    ) AgainstRef  on NewRef.iRef= AgainstRef.iRef\r\n\t\t\t\t\t    ) GetDiff on \ttCore_Refrn{text11}.iRef = GetDiff.iRef\r\n                        --Left Join vrCore_Product ON vrCore_Product.iMasterId= tCore_Indta{text11}.iProduct AND vrCore_Product.iTreeId = 0\r\n                        --Inner join(Select iMasterId, iSeq iRowSeq from dbo.fCore_GetAccountTreeSequence(0,0)) RowSeq on ParentRef.iCode= RowSeq.iMasterId\r\n                        {strJoinQuery.Replace(Suffix, text11)}\r\n                        {text23} {text9}\r\n                        Union all \r\n                        ";
