			text5 += $"SELECT tCore_Data{suffix}.iBodyId,cCore_Vouchers{suffix}.sAbbr+':'+tCore_Header{suffix}.sVoucherNo[sVoucherNo], \r\n                        tCore_Refrn{suffix}.iDueDate[Date],vrCore_Account.sName[Particulars],\r\n                        CASE WHEN tCore_Refrn{suffix}.iRefType IN(0,1)  THEN mInvoiceAmount ELSE 0 END [Invoice Amount], \r\n                        --ParentRef.mAmount[Balance Amount],\r\n                        Round(CASE WHEN tCore_Refrn{suffix}.iRefType IN(0,1,2) then ParentRef.mAmount else 0 end,2)[Balance Amount],\r\n                        --CASE WHEN DateDiff(dd,dbo.IntToGregDate(ParentData.iDueDate), dbo.IntToGregDate(tCore_Header{suffix}.iDate)) > 0 THEN DateDiff(dd,dbo.IntToGregDate(ParentData.iDueDate), dbo.IntToGregDate(tCore_Header{suffix}.iDate)) ELSE 0 END[Delay in Payment],\r\n                        --abs(DateDiff(dd,dbo.IntToGregDate(ParentRef.iDueDate), dbo.IntToGregDate(tCore_Header{suffix}.iDate))) [Delay in Payment],\r\n                        --Case when abs(mInvoiceAmount)>0 then\r\n\t\t\t\t\t\t--Case when abs(ParentRef.mAmount)=0 then\r\n\t\t\t\t\t\t \r\n\t\t\t\t\t\t --Case when DateDiff(dd,dbo.IntToGregDate(ParentRef.iNewRefDueDate),dbo.IntToGregDate(ParentRef.iDueDate))<0 then 0 else \r\n\t\t\t\t\t\t--\tcast(abs(ceiling(cast(DateDiff(dd,dbo.IntToGregDate(ParentRef.iNewRefDueDate),dbo.IntToGregDate(ParentRef.iDueDate)) as decimal(18,2))/iCount)) as int)\r\n\t\t\t\t\t\t\r\n\t\t\t\t\t\t-- end\r\n\t\t\t\t\t\t-- else\r\n\t\t\t\t\t\t--\t\tCase when DateDiff(dd,dbo.IntToGregDate(ParentRef.iNewRefDueDate),dbo.IntToGregDate(ParentRef.iDueDate))<0 then \r\n\t\t\t\t\t\t--\t\t\tDateDiff(dd,dbo.IntToGregDate(ParentRef.iNewRefDueDate),dbo.IntToGregDate({objRec.EndingDate}) ) \r\n\t\t\t\t\t\t\t\t\t\r\n\t\t\t\t\t\t--\t\t else\r\n\t\t\t\t\t\t--\t\t\tCase when abs(ParentRef.mAmount)=0 then\r\n\t\t\t\t\t\t--\t\t\t\tDateDiff(dd,dbo.IntToGregDate(ParentRef.iNewRefDueDate),dbo.IntToGregDate(ParentRef.iDueDate)) \r\n\t\t\t\t\t\t\t\t\t\t\r