erIdTable mCore_Account_Props on isnull(tCore_Refrn{0}.iCode,0)=mCore_Account_Props.iMasterId\r\n                    \t\t\t\t\t inner join \r\n\t\t\t\t\t (Select iRef from tCore_Refrn{0} a\r\n                                        inner join tCore_Data{0} b on a.iBodyId= b.iBodyId\r\n\t\t\t\t\t\t\t\t\t\tinner join tCore_Header{0} c on b.iHeaderId= c.iHeaderId\r\n                                        \r\n\t\t\t\t\t\t\t\t\t\t where c.iDate>{8} and iRefType=0 and b.bUpdateFA = 1 AND b.bSuspendUpdateFA <> 1 \r\n                        AND c.bSuspended = 0 ) FutureRef on tCore_Refrn{0}.iRef=FutureRef.iRef\r\n                        inner join {14} mCore_Account on tCore_Refrn{0}.iCode=mCore_Account.iMasterId\r\n\t\t\t\t\t    \r\n\t\t\t\t\t where tCore_Header{0}.iDate<={8} and iRefType=2 and tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA <> 1 \r\n                        AND tCore_Header{0}.bSuspended = 0  \r\n                    group by mCore_Account_Props.iParentId, tCore_Refrn{0}.iCode) FutureAdjustments on #MasterIdTable.iMasterId=FutureAdjustments.iCode\r\n                    full outer join( Select mCore_Account_Props.iParentId iMasterId, mCore_Account.iMasterId iCode, sum(mAmount1) ForexExchangeAmount\r\n                                        from tCore_Data{0} b \r\n\t\t\t\t\t\t\t\t\t\tinner join tCore_Header{0} c on b.iHeaderId= c.iHeaderId\r\n\t\t\t\t\t\t\t\t\t\tjoin #MasterIdTable mCore_Account_Props on isnull(b.iCode,0)=mCore_Account_Props.iMasterId\r\n\t\t\t\t\t\t\t\t\t\tjoin {14} mCore_Account on isnull(b.iCode,0)= mCore_Account.iMasterId and iAccountType in(5,6,7)\r\n                     where c.iDate<={8} and bForexFlux =1\r\n                     group by mCore_Account_Props.iParentId   ,mCore_Account.iMasterId \r\n                    having sum(mAmount1)<>0) ForexExchange on #MasterIdTable.iMasterId=ForexExchange.iCode\r\n                    --Left Join vrCore_Product ON vrCore_Product.iMasterId= tCore_Indta{0}.iProduct AND vrCore_Prod