odyId,CASE WHEN iCode = {4} THEN iCode ELSE iBookNo END [iCode]\r\n\t\t                    ,CASE WHEN iCode = {4} THEN {9} ELSE {10} END Amt\r\n\t\t                    FROM tCore_Header{0}   \r\n\t\t                    JOIN tCore_Data{0} on tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId {19} \r\n\t\t                    JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType = tCore_Header{0}.iVoucherType\r\n                            WHERE tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280)\r\n\t\t                    AND tCore_Header{0}.iDate BETWEEN {1} AND {2}\r\n\t\t                    AND tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA <> 1 AND tCore_Header{0}.bSuspended = 0 AND tCore_Data{0}.iAuthStatus < 2 \r\n\t\t                    AND cCore_Vouchers{0}.bPostVAT = 1 AND tCore_Data{0}.iType <> 5 AND bInventory = 1 AND (iBookNo = {16} OR iCode = {16}) \r\n\t                    )Temp\r\n                        JOIN tCore_Refrn{0} b ON Temp.iMainBodyId = b.iBodyId AND iRefType = 2\r\n                        GROUP BY Temp.iBodyId,(CASE WHEN Temp.iCode = {4} THEN Amt ELSE 0.0 END)\r\n\r\n                        UNION -- pur adv\r\n                        SELECT Temp.iBodyId[iBodyId],(CASE WHEN Temp.iCode = {3} THEN Amt ELSE 0.0 END)[VATAmt]\r\n\t                    ,CASE WHEN (CASE WHEN Temp.iCode = {3} THEN Amt ELSE 0.0 END) <> 0 then sum(b.mBaseAmount) ELSE 0 END[Net]\r\n\t                    FROM\r\n\t                    (\r\n\t\t                    SELECT iMainBodyId,tCore_Data{0}.iBodyId,CASE WHEN iCode = {3} THEN iCode ELSE iBookNo END [iCode]\r\n\t\t                    ,-CASE WHEN iCode = {3} THEN {9} ELSE {10} END Amt\r\n\t\t                    FROM tCore_Header{0}   \r\n\t\t                    JOIN tCore_Data{0} on tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId {19} \r\n\t\t                    JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType = tCore_Header{0}.iVoucherType\r\n                            WHERE tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144)\r\n\t\t                    AND tCore_Header{0}.iDate BETWEEN {1} AND {2}\r\n\t\t                    AND tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA <> 1 AND tCore_Header{0}.bSuspended = 0 AND tCore_Data{0}.iAuthStatus < 2 \r\n\t\t                    AND cCore_Vouchers{0}.bPostVAT = 1 AND tCore_Data{0}.iType <> 5 AND bInventory = 1 AND (iBookNo = {17} OR iCode = {17}) \r\n\t                    )Temp\r\n                        JOIN tCore_Refrn{0} b ON Temp.iMainBodyId = b.iBodyId AND iRefType = 2\r\n                        GROUP BY Temp.iBodyId,(CASE WHEN Temp.iCode = {3} THEN Amt ELSE 0.0 END)\r\n\r\n                    )v_Vat ON v_Vat.iBodyId = tCore_Data{0}.iBodyId \r\n                    GROUP BY v_Vat.iBodyId\r\n                    )InnerTable \r\n                    JOIN tCore_Data{0}  ON tCore_Data{0}.iBodyId = InnerTable.iMainBodyId\r\n                    JOIN tCore_Header{0}  ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n                    JOIN cCore_Vouchers{0} ON cCore_Vouchers{0}.iVoucherType = tCore_Header{0}.iVoucherType\r\n                    JOIN mCore_Account Acct1 ON Acct1.iMasterId = tCore_Data{0}.iBookNo --AND BookNo.iTreeId = 0\r\n                    JOIN mCore_Account Acct2 ON Acct2.iMasterId = tCore_Data{0}.iCode --AND Code.iTreeId = 0\r\n                    LEFT JOIN tCore_Indta{0}  ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId  \r\n                    LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId \r\n                    LEFT JOIN tCore_Data_Tags{0} ON tCore_Data_Tags{0}.iBodyId = tCore_Data{0}.iBodyId \r\n                    LEFT JOIN {20} vmCore_Jurisdiction ON vmCore_Jurisdiction.iMasterId = tCore_Data_Tags{0}.iTag{6} \r\n                    LEFT JOIN\r\n                    (\r\n                        Select 0[iHeaderId]\r\n                        --Select distinct h.iHeaderId 