			break;
		case FocusReport.AuditTransactionDetail:
			text5 = string.Format("SELECT tCore_Header{0}.iHeaderId, 'Modified'[Status], sAbbr+':'+sVoucherNo[VoucherNo], 0 [Srno], ''[Fieldname], ''[NewValue], ''[OldValue]\r\n                    , tCore_Header{0}.iCreatedDate, tCore_Header{0}.iCreatedTime, EUser.sLoginName\r\n                    , tCore_Header{0}.iModifiedDate, tCore_Header{0}.iModifiedTime, MUser.sLoginName, 'Modified'[Action], ''[Reason]\r\n                    FROM tCore_Header{0} \r\n                    JOIN cCore_Vouchers{0} ON cCore_Vouchers{0}.iVoucherType = tCore_Header{0}.iVoucherType\r\n                    JOIN mSec_Users EUser with (ReadUncommitted) ON EUser.iUserId = tCore_Header{0}.iUserId\r\n                    JOIN mSec_Users MUser with (ReadUncommitted) ON MUser.iUserId = tCore_Header{0}.iModifiedBy\r\n                    WHERE tCore_Header{0}.iDate BETWEEN {1} AND {2} AND tCore_Header{0}.iModifiedTime != tCore_Header{0}.iCreatedTime", Suffix, objRec.StartingDate, objRec.EndingDate);
			if (objRec.Code > 0)
			{
				text5 += $" AND tCore_Header{Suffix}.iVoucherType = {objRec.Code}";
			}
			text5 += string.Format(" ORDER BY tCore_Header{0}.iDate Desc, tCore_Header{0}.iHeaderId", Suffix);
			break;
		case FocusReport.EntryStatsReport:
			text5 = string.Format("SELECT tCore_Header{0}.iVoucherType, tCore_Header{0}.iCreatedDate, cCore_Vouchers{0}.sName, ISNULL(mSec_USers.sUserName, mSec_USers.sLoginName)[sUserName]\r\n                    , COUNT(tCore_Header{0}.iCreatedDate)[new], 0[Edit], 0[Delete], mSec_Users.iUserId, tCore_Header{0}.iModifiedDate\r\n                    FROM tCore_Header{0} \r\n                    JOIN cCore_Vouchers{0} ON tCore_Header{0}.iVoucherType = cCore_Vouchers{0}.iVoucherType\r\n                    JOIN mSec_USers ON mSec_USers.iUserId = tCore_Header{0}.iUserId", Suffix);
			break;
		case FocusReport.ScheduledReport:
			text5 = string.Format("SELECT iId, sAssembly, sMethod, sReportName, vbRecurrence, iLastFired, iModuleId FROM tCore_Scheduler\r\n                                            LEFT JOIN cCore_Reports{0} ON tCore_Scheduler.iId = cCore_Reports{0}.iReportId", Suffix);
			break;
		case FocusReport.AuthorizationDelayReport:
			text5 = string.Format("SELECT iRoleOrUserId, sName\r\n                    , AVG(datediff(day, dbo.IntToDate(case when tCore_TransAuth{0}.iDate = 0 then tCore_Header{0}.iDate else tCore_TransAuth{0}.iDate end), dbo.IntToDate(iAuthDate)))[Days], sUserName\r\n                    FROM tCore_Header{0}\r\n                    JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n                    JOIN tCore_TransAuth{0} ON tCore_TransAuth{0}.iBodyId = tCore_Data{0}.iBodyId\r\n                    JOIN tCore_TransAuthUsers{0} ON tCore_TransAuthUsers{0}.iAuthId = tCore_TransAuth{0}.iAuthId\r\n                    LEFT JOIN mSec_Users ON tCore_TransAuthUsers{0}.iRoleOrUserId = mSec_Users.iUserId AND bRole = 0\r\n                    JOIN cCore_Vouchers{0} ON cCore_Vouchers{0}.iVoucherType = tCore_Header{0}.iVoucherType", Suffix);
			break;
		case FocusReport.AverageDaysToPayReport:
			num2 = FConvert.GetInputValue(objRec.Inputs, 2);
			num2 = ((num2 < 1) ? 1 : num2);
			text3 = ((FConvert.GetInputValue(objRec.Inputs, 3) != 1) ? $", CEILING(AVG(CAST(DATEDIFF(DD, dbo.IntToDate(NewDue),  dbo.IntToDate(ISNULL(AgaintDue,{objRec.EndingDate})) ) as numeric(28,2)))) [SimpleAverageDelay]" : $",CEILING(SUM(CAST(DATEDIFF(DD, dbo.IntToDate(NewDue),  dbo.IntToDate(ISNULL(AgaintDue,{objRec.EndingDate})) ) as numeric(28,2)) * Newbase)/SUM(Newbase))  [WeightedAverageDelay]");
			text5 = string.Format("SELECT TOP {1} NewRef.iCode, vrCore_Account.sName\r\n                    , SUM(NewRef.Newbase) [TotalInvoiceAmount], SUM(ISNULL(AgainstBase, 0)) [TotalPaidAmount] {3}\r\n                    FROM \r\n                    (\r\n\t                    SELECT iRef, tCore_Refrn{0}.iCode, mBaseAmount Newbase, tCore_Header{0}.iDate NewDue \r\n\t                    FROM tCore_Refrn{0} WITH (READUNCOMMITTED)\r\n                        JOIN tCore_Data{0} ON tCore_Refrn{0}.iBodyId = tCore_Data{0}.iBodyId\r\n                        JOIN tCore_Header{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n                        JOIN cCore_Vouchers{0} on tCore_Header{0}.iVoucherType=cCore_Vouchers{0}.iVoucherType\r\n                        WHERE iRefType < 2 AND tCore_Data{0}.bSuspendUpdateFA <> 1 \r\n                        AND (tCore_Header{0}.iDate BETWEEN {4} AND {2})\r\n                        AND tCore_Header{0}.bSuspended = 0 AND tCore_Data{0}.iAuthStatus < 2 AND cCore_Vouchers{0}.bUpdateInv=1\r\n                    ) NewRef\r\n                    LEFT JOIN \r\n                    (\r\n\t                    SELECT iRef,tCore_Refrn{0}.iCode, SUM(mBaseAmount-mExchangeDiff)AgainstBase, max(tCore_Header{0}.iDate) AgaintDue \r\n\t                    FROM tCore_Refrn{0} WITH (READUNCOMMITTED)\r\n\t                    JOIN tCore_Data{0} ON tCore_Refrn{0}.iBodyId = tCore_Data{0}.iBodyId\r\n\t                    JOIN tCore_Header{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n\t                    WHERE iRefType = 2 AND tCore_Data{0}.bSuspendUpdateFA <> 1 \r\n                        AND tCore_Header{0}.bSuspended = 0 AND tCore_Data{0}.iAuthStatus < 2 \r\n\t                    AND (((tCore_Data{0}.bUpdateFA = 1 OR tCore_Header{0}.iVoucherClass NOT IN(7168,5888)) OR tCore_Data{0}.bPdc = 1))\r\n\t                    GROUP BY iRef, tCore_Refrn{0}.iCode\r\n                    ) AgainstRef  ON NewRef.iRef= AgainstRef.iRef\r\n                    JOIN vrCore_Account ON vrCore_Account.iMasterId = NewRef.iCode  and vrCore_Account.iTreeId = 0", Suffix, num2, objRec.EndingDate, text3, objRec.StartingDate);
			break;
		case FocusReport.UserAuditReport:
			text5 = $"SELECT iAuditId, CUser.sLoginName, CUser.iCreatedDate, CUser.iCreatedTime, Users.sLoginName, tSec_Users_LogHeader.iModifiedDate, tSec_Users_LogHeader.iModifiedTime, mSec_Users.sLoginName,\r\n                        CASE WHEN CUser.iCreatedTime = CUser.iModifiedTime THEN 'Newly created' ELSE 'Modified' END [Action]\r\n                        FROM tSec_Users_LogHeader\r\n                        JOIN mSec_Users ON mSec_Users.iUserId = tSec_Users_LogHeader.iCreatedby\r\n                        JOIN mSec_Users CUser ON CUser.iUserId = tSec_Users_LogHeader.iUserId\r\n                        LEFT JOIN mSec_Users users on users.iUserId = CUser.iCreatedBy and CUser.iCreatedBy > 0";
			break;
		case FocusReport.BackupSchedulerAuditReport:
			text5 = $"SELECT iSchedulerLogId, ISNULL(sUSerName, sLoginName)sUSerName, a.iModifiedDate, a.iModifiedTime,\r\n                                CASE WHEN (a.vbRecurrence IS NULL AND c.vbRecurrence IS NOT NULL) THEN 'NEW' WHEN c.vbRecurrence IS NULL THEN 'DELETED' ELSE 'MODIIFIED' END[Action]\r\n                                FROM tCore_SchedulerLog a\r\n                                JOIN mSec_USers b ON b.iUserId = a.iUserId\r\n                                LEFT JOIN tCore_Scheduler c ON c.iId = a.iRefId";
			break;
		case FocusReport.LockUnlockDatabaseAuditReport:
			text5 = "SELECT Distinct mCore_LockDatabase" + Suffix + ".iVoucherType, cCore_Vouchers" + Suffix + ".sName FROM mCore_LockDatabase" + Suffix + " JOIN cCore_Vouchers" + Suffix + " ON mCore_LockDatabase" + Suffix + ".iVoucherType = cCore_Vouchers" + Suffix + ".iVoucherType";
			if (objRec.Code > 0)
			{
				text5 += $" WHERE mCore_LockDatabase{Suffix}.iVoucherType = {objRec.Code}";
			}
			break;
		}
		return text5;
	}

