	private string GetUsersInGroup(int iUserId, int iCompanyId, ref string sUserName)
	{
		List<string> list = new List<string>();
		string text = string.Format("SELECT iUserId,CASE WHEN sLoginName  <> sUserName THEN sUserName + ' ['+ sLoginName + ']' ELSE sUserName END [sUserName] \r\n            FROM mSec_Users WITH (READUNCOMMITTED) WHERE (iUserId = {0} OR iGroupId = {0})", iUserId);
		IDataReader dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		while (dataReader.Read())
		{
			list.Add(Convert.ToString(dataReader["iUserId"]));
			sUserName = Convert.ToString(dataReader["sUserName"]);
		}
		dataReader.Close();
		return string.Join(",", list);
	}

	private string getAccountSubledger(int iAccount, int iCompanyId)
	{
		List<string> list = new List<string>();
		string text = $"WITH RecursionCTE (iMasterId, iParentId, bGroup)  AS  \r\n                        (   SELECT vmCore_SubLedger.iMasterId, vmCore_SubLedger.iParentId, vmCore_SubLedger.bGroup\r\n                            FROM vmCore_SubLedger\r\n\t                        JOIN vmCore_Account ON vmCore_Account.iSubLedger = vmCore_SubLedger.iMasterId\r\n                            WHERE vmCore_Account.iMasterId = {iAccount} AND vmCore_Account.iTreeId = 0\r\n                            UNION ALL  \r\n                            SELECT R1.iMasterId, R1.iParentId, R1.bGroup\r\n                            FROM vmCore_SubLedger AS R1\r\n                            JOIN RecursionCTE AS R2 ON R1.iParentId = R2.iMasterId\r\n                        )SELECT iMasterId  FROM RecursionCTE WHERE bGroup = 0";
		IDataReader dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		while (dataReader.Read())
		{
			list.Add(Convert.ToString(dataReader["iMasterId"]));
		}
		dataReader.Close();
		return string.Join(",", list);
	}

	public int IsAccountPropertyEnable(IdValuePair[] arrInputs, ComboData[] arrMasters, FocusReport oReport, int iCode, ref int iDisplayTotal)
	{
		int num = -1;
		if (oReport == FocusReport.SubLedger)
		{
			if (iCode <= 0 && arrMasters != null && arrMasters.Length == 1)
			{
				iCode = arrMasters[0].ID;
			}
		}
		else if (iCode <= 0 && arrMasters != null && arrMasters.Length != 0)
		{
			iCode = arrMasters[0].ID;
		}
		for (int i = 0; i < arrInputs?.Length; i++)
		{
			if (arrInputs[i].ID != -5)
			{
				continue;
			}
			for (int j = 0; j < ((IdValuePair[])arrInputs[i].Value).Length; j++)
			{
				if (iCode == ((IdValuePair[])arrInputs[i].Value)[j].ID && Convert.ToInt32(((IdValuePair[])arrInputs[i].Value)[j].Value) > 0)
				{
					num = Convert.ToInt32(((IdValuePair[])arrInputs[i].Value)[j].Value);
				}
			}
			break;
		}
		if (oReport == FocusReport.SubLedger && iCode > 0 && num == -1)
		{
			num = GetGroupLedgerAccountProperty(iCode);
		}
		if (num > 3)
		{
			iDisplayTotal = num - 3;
			num = 0;
		}
		if (num != -1)
		{
			return num;
		}
		return 0;
	}

	private ComboData[] GetVouchers(bool bInventoryType)
	{
		string text = null;
		DbCommand dbCommand = null;
		ComboData comboData = null;
		IDataReader dataReader = null;
		List<ComboData> list = null;
		text = ((!bInventoryType) ? $"select iVoucherType,sName from cCore_Vouchers{Suffix} where bUpdateFA = 1" : $"select iVoucherType,sName from cCore_Vouchers{Suffix} where bUpdateInv = 1");
		dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		dataReader = m_objDatabase.ExecuteReader(dbCommand);
		list = new List<ComboData>();
		while (dataReader.Read())
		{
			comboData = new ComboData();
			comboData.ID = Convert.ToInt32(dataReader["iVoucherType"]);
			comboData.Name = Convert.ToString(dataReader["sName"]);
			list.Add(comboData);
		}
		dataReader.Close();
		return list.ToArray();
	}

	private double GetTotalDrCrBalance(RepRecord objRec)
	{
		string text = null;
		string text2 = null;
		string text3 = null;
		if (objRec.Masters != null && !objRec.IsSelectAll)
		{
			text2 = $" AND vrCore_Account.iMasterId IN ({General.GetMasters(objRec.Masters)}) AND vrCore_Account.iTreeId=0";
		}
		if (Convert.ToInt32(FConvert.GetInputValue(objRec.Inputs, 2)) != 1)
		{
			text3 = "SUM([Debit])+SUM([Credit])";
		}
		else
		{
			text3 = ((Convert.ToInt32(FConvert.GetInputValue(objRec.Inputs, 3)) == 0) ? "MIN([Debit])" : "MAX([Credit])");
		}
		text = string.Format("SELECT ISNULL(SUM(Bal),0) FROM(SELECT {1}[Bal]\r\n                    FROM \r\n                    (\r\n\t                    SELECT InnerTable.iMasterId, vrCore_Account.sName[Account],Debit, Credit\r\n                        FROM \r\n                        (\r\n\t                        SELECT tCore_Data{0}.iBodyId, iBookNo[iMasterId],\r\n\t                        CASE WHEN mAmount2 < 0 THEN mAmount2 ELSE 0 END Debit, \r\n\t                        CASE WHEN mAmount2 > 0 THEN mAmount2 ELSE 0 END Credit\r\n\t                        FROM \r\n\t                        tCore_Data{0} \r\n\t                        JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t                        JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n\t                        JOIN mCore_Account ON tCore_Data{0}.iCode = mCore_Account.iMasterId\r\n\t                        WHERE tCore_Data{0}.iBookNo <> 2\r\n\t                        UNION ALL\r\n\t                        SELECT tCore_Data{0}.iBodyId, iCode[iMasterId],\r\n\t                        CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit, \r\n\t                        CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit\r\n\t                        FROM \r\n\t                        tCore_Data{0} \r\n\t                        JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t                        JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n\t                        JOIN mCore_Account ON tCore_Data{0}.iBookNo = mCore_Account.iMasterId\r\n\t                        WHERE tCore_Data{0}.iCode <> 2\r\n\t                        UNION ALL\r\n\t                        SELECT TOP 1 tCore_Data{0}.iBodyId, 0,0,0  \r\n\t                        FROM tCore_Data{0} \r\n\t                        JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t                        WHERE tCore_Data{0}.iBookNo = 2\r\n                        )InnerTable\r\n                        JOIN tCore_Data{0} ON tCore_Data{0}.iBodyId = InnerTable.iBodyId  \r\n                        JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                        JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n                        JOIN vrCore_Account ON InnerTable.iMasterId = vrCore_Account.iMasterId AND vrCore_Account.iTreeId = 0\r\n                        WHERE tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA <> 1 \r\n                        AND tCore_Header{0}.bSuspended = 0 AND tCore_Header{0}.iDate BETWEEN {2} AND {3} {4}\r\n                    ) TempTable", Suffix, text3, objRec.StartingDate, objRec.EndingDate, text2);
		text += $" GROUP BY [iMasterId]";
		if (Convert.ToInt32(FConvert.GetInputValue(objRec.Inputs, 2)) == 1)
		{
			text = ((Convert.ToInt32(FConvert.GetInputValue(objRec.Inputs, 3)) != 0) ? (text + " HAVING MAX([Credit]) > 0") : (text + " HAVING MIN([Debit]) < 0"));
		}
		else
		{
			text = ((Convert.ToInt32(FConvert.GetInputValue(objRec.Inputs, 3)) != 0) ? (text + " HAVING SUM([Debit])+SUM([Credit]) > 0") : (text + " HAVING SUM([Debit])+SUM([Credit]) < 0"));
		}
		text += ")MyT";
		return Convert.ToDouble(m_objDatabase.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
	}

	private bool IsFieldAdded(List<MasterIdNameCode> strFields, string sFieldName, string sGroup, int iFieldId, bool bStatus, bool bSearchByFieldId)
	{
		if (bSearchByFieldId)
		{
			return strFields.Where((MasterIdNameCode p) => p.iMasterId == iFieldId && p.Status == bStatus).Count() > 0;
		}
		return strFields.Where((MasterIdNameCode p) => p.Name == sFieldName && p.Code == sGroup).Count() > 0;
	}

	private string GetAgeingColumnStringsForMonth(string strDateColumn, string strValueColumn, int iMonth, int iCurrYear, int iPrevYearDate, string strColType, byte iPDC, short iReceivables)
	{
		string text = "";
		text = $",SUM(case when  iDate >={iPrevYearDate} and dDiff>=0  then  case when ({strDateColumn} & 0xff00)/256 = {iMonth} THEN ";
		text = ((iPDC == 1) ? (iReceivables switch
		{
			0 => text + "\r\n                    case when With" + strValueColumn + " <0 then With" + strValueColumn + "-OnAccount" + strColType + "Amt else 0 end ", 
			1 => text + "\r\n                    case when With" + strValueColumn + " >0 then With" + strValueColumn + "-OnAccount" + strColType + "Amt else 0 end   ", 
			_ => text + "\r\n                    With" + strValueColumn + "-OnAccount" + strColType + "Amt   ", 
		}) : (iReceivables switch
		{
			0 => text + "\r\n                    case when WithOut" + strValueColumn + " <0 then WithOut" + strValueColumn + "-OnAccount" + strColType + "AmtWithOutPDC else 0 end", 
			1 => text + "\r\n                    case when WithOut" + strValueColumn + " >0 then WithOut" + strValueColumn + "-OnAccount" + strColType + "AmtWithOutPDC else 0 end   ", 
			_ => text + "\r\n                    WithOut" + strValueColumn + "-OnAccount" + strColType + "AmtWithOutPDC  ", 
		}));
		return text + $"\r\n                ELSE 0 END ELSE 0 END)[{iMonth}-{iCurrYear} Month]";
	}

	private string GetAgeingColumnStringsForHavingClause(string Col1, string Col2, string Col3, string Col4, string Col5, byte iPDC, short iReceivables)
	{
		string text = "";
		text += "\r\n                Having(";
		text += "\r\n                ISNull(sum( ";
		text = ((iPDC == 1) ? (iReceivables switch
		{
			0 => text + "case when " + Col1 + " < 0 then " + Col1 + " else 0 end ", 
			1 => text + "case when " + Col1 + " > 0 then " + Col1 + " else 0 end", 
			_ => text + Col1, 
		}) : (iReceivables switch
		{
			0 => text + "case when " + Col2 + " < 0 then " + Col2 + " else 0 end ", 
			1 => text + "case when " + Col2 + " > 0 then " + Col2 + " else 0 end", 
			_ => text + Col2, 
		}));
		if (Col5 == "")
		{
			return text + "),0)" + Col3 + Col4 + "<>0)";
		}
		return text + "),0)" + Col3 + Col4 + "<>0 or isnull(avg(" + Col5 + "),0)<>0)";
	}

	private string GetAgeingColumnStringsForBalanceAmount(string Col1, string Col2, string Col3, string Col4, string Lable, byte iPDC, short iReceivables, bool bAvailable)
	{
		string text = "";
		text = text ?? "";
		if (bAvailable)
		{
			text += "\r\n                ,ISNull(sum( ";
			text = ((iPDC == 1) ? (iReceivables switch
			{
				0 => text + "case when " + Col1 + " < 0 then " + Col1 + " else 0 end ", 
				1 => text + "case when " + Col1 + " > 0 then " + Col1 + " else 0 end", 
				_ => text + Col1, 
			}) : (iReceivables switch
			{
				0 => text + "case when " + Col2 + " < 0 then " + Col2 + " else 0 end ", 
				1 => text + "case when " + Col2 + " > 0 then " + Col2 + " else 0 end", 
				_ => text + Col2, 
			}));
			if (Col3 != "")
			{
				if ("WithPDCBaseAdj" == Col1)
				{
					return text + "),0)+ISNull(avg(" + Col3 + "),0)" + Col4 + "[" + Lable + "]";
				}
				return text + "),0)" + Col4 + "[" + Lable + "]";
			}
			if ("WithPDCBaseAdj" == Col1)
			{
				return text + "),0)" + Col4 + "[" + Lable + "]";
			}
			return text + "),0)[" + Lable + "]";
		}
		return text + ",0 [" + Lable + "]";
	}

	private string GetAgeingColumnStringsForTotalAmount(string Col1, string Col2, string Col3, string Col4, string Col5, string Lable, byte iPDC, short iReceivables, bool bAvailable)
	{
		string text = "";
		text = text ?? "";
		if (bAvailable)
		{
			text += "\r\n                ,ISNull(sum( ";
			text = ((iPDC == 1) ? (iReceivables switch
			{
				0 => text + "case when " + Col1 + " < 0 then " + Col1 + "-" + Col2 + " else 0 end ", 
				1 => text + "case when " + Col1 + " > 0 then " + Col1 + "-" + Col2 + " else 0 end", 
				_ => text + Col1 + "-" + Col2, 
			}) : (iReceivables switch
			{
				0 => text + "case when " + Col3 + " < 0 then " + Col3 + "-" + Col4 + " else 0 end ", 
				1 => text + "case when " + Col3 + " > 0 then " + Col3 + "-" + Col4 + " else 0 end", 
				_ => text + Col3 + "-" + Col4, 
			}));
			if (Col5 != "")
			{
				return text + "),0)+ISNull(avg(" + Col5 + "),0)[" + Lable + "]";
			}
			return text + "),0)[" + Lable + "]";
		}
		return ", 0[" + Lable + "]";
	}

	private string GetAgeingColumnStringsForCurrent(int iEndingDate, string Col1, string Col2, string Col3, string Col4, string Lable, byte iPDC, short iReceivables)
	{
		string text = "";
		text += ",SUM( CASE WHEN dDiff < 0 THEN ";
		text = ((iPDC == 1) ? (iReceivables switch
		{
			0 => text + "\r\n                    case when " + Col1 + " <0 then " + Col1 + "-" + Col2 + " else 0 end  ", 
			1 => text + "\r\n                    case when " + Col1 + " >0 then " + Col1 + "-" + Col2 + " else 0 end  ", 
			_ => text + "\r\n                     " + Col1 + "-" + Col2 + "  ", 
		}) : (iReceivables switch
		{
			0 => text + "\r\n                    case when " + Col3 + " <0 then " + Col3 + "-" + Col4 + " else 0 end ", 
			1 => text + "\r\n                    case when " + Col3 + " >0 then " + Col3 + "-" + Col4 + " else 0 end  ", 
			_ => text + "\r\n                    " + Col3 + "-" + Col4 + "    ", 
		}));
		return text + " ELSE 0 END)[" + Lable + "]";
	}

	private string GetAgeingColumnStringsForSlabs(int iEndingDate, int iSlabe1, int iSlabe2, string Col1, string Col2, string Col3, string Col4, string Lable, byte iPDC, short iReceivables, bool bAvailable)
	{
		string text = "";
		if (bAvailable)
		{
			if (iSlabe1 > 0 && iSlabe2 == 0)
			{
				text += $"\r\n                ,SUM(CASE WHEN dDiff > {iSlabe1} THEN ";
			}
			else if (iSlabe1 == 0 && iSlabe2 == 0)
			{
				text += $"\r\n                ,SUM(CASE WHEN dDiff >= {iSlabe1} THEN ";
			}
			else
			{
				text = ((iSlabe1 != 0 || iSlabe2 == 0) ? (text + $"\r\n                ,SUM(CASE WHEN dDiff > {iSlabe1} AND \r\n                dDiff <= {iSlabe2} THEN ") : (text + $"\r\n                ,SUM(CASE WHEN dDiff >= {iSlabe1} AND \r\n                dDiff <= {iSlabe2} THEN "));
			}
			text = ((iPDC == 1) ? (iReceivables switch
			{
				0 => text + "\r\n                    case when " + Col1 + " <0 then " + Col1 + "-" + Col2 + " else 0 end   ", 
				1 => text + "\r\n                    case when " + Col1 + " >0 then " + Col1 + "-" + Col2 + "  else 0 end  ", 
				_ => text + "\r\n                     " + Col1 + "-" + Col2 + "  ", 
			}) : (iReceivables switch
			{
				0 => text + "\r\n                    case when " + Col3 + " <0 then " + Col3 + "-" + Col4 + "  else 0 end ", 
				1 => text + "\r\n                    case when " + Col3 + " >0 then " + Col3 + "-" + Col4 + "   else 0 end  ", 
				_ => text + "\r\n                    " + Col3 + "-" + Col4 + "    ", 
			}));
			if (iSlabe1 > 0 && iSlabe2 == 0)
			{
				return text + $"\r\n                               ELSE 0 END)[>{iSlabe1} {Lable}]";
			}
			return text + $"\r\n                               ELSE 0 END)[{iSlabe1}-{iSlabe2} {Lable}]";
		}
		return text + $",0 [{iSlabe1}-{iSlabe2} {Lable}]";
	}

	private string GetAgeingColumnStringsForOthers(string strDateColumn, string strValueColumn, int iPrevYearDate, string strCurrencyType, byte iPDC, short iReceivables, bool bAvailable)
	{
		string text = "";
		if (bAvailable)
		{
			text = $",SUM(case when iDate <{iPrevYearDate} then";
			text = ((iPDC == 1) ? (iReceivables switch
			{
				0 => text + "\r\n                    case when With" + strValueColumn + " <0 then With" + strValueColumn + " else 0 end ", 
				1 => text + "\r\n                    case when With" + strValueColumn + " >0 then With" + strValueColumn + " else 0 end   ", 
				_ => text + "\r\n                     With" + strValueColumn + "   ", 
			}) : (iReceivables switch
			{
				0 => text + "\r\n                    case when WithOut" + strValueColumn + " <0 then WithOut" + strValueColumn + " else 0 end ", 
				1 => text + "\r\n                    case when WithOut" + strValueColumn + " >0 then WithOut" + strValueColumn + " else 0 end   ", 
				_ => text + "\r\n                    WithOut" + strValueColumn + "  ", 
			}));
			return text + "\r\n                                ELSE 0 END)[Others " + strCurrencyType + "]";
		}
		return text + ",0 [Others " + strCurrencyType + "]";
	}

	private int GetGroupLedgerAccountProperty(int iMasterId)
	{
		if (m_objDatabase == null)
		{
			m_objDatabase = DatabaseWrapper.GetDatabase2(m_iCompId);
		}
		return Convert.ToInt32(m_objDatabase.ExecuteScalar(CommandType.Text, $"SELECT CASE WHEN iDisplayCreditTotal > 0 THEN iDisplayCreditTotal + 3 ELSE iConsolidationoftransactions END[iConsolidationoftransactions]\r\n            FROM mCore_Account_Props WHERE iMasterId = {iMasterId}"));
	}

	private void SetVATReturnAdjustment(RepRecord objRec, int iVATInputAc, int iVATOutputAc, string strScreenData, string sUniqueId)
	{
		string text = null;
		bool flag = false;
		IDataReader dataReader = null;
		LedgerBalanceData ledgerBalanceData = null;
		List<int> list = new List<int>();
		Dictionary<int, LedgerBalanceData> dictionary = new Dictionary<int, LedgerBalanceData>();
		try
		{
			text = string.Format("SELECT a.iLinkPathId FROM mCore_LinkPath{0} a JOIN mCore_LinkNodes{0} b ON a.iToLinkId = b.iLinkId WHERE (b.iVoucherType & 0xff00) = 1792", Suffix);
			dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			while (dataReader.Read())
			{
				list.Add(Convert.ToInt32(dataReader["iLinkPathId"]));
				flag = true;
			}
			dataReader.Close();
			if (!flag)
			{
				text = $"SELECT iVoucherType FROM cCore_VoucherFields{Suffix} WHERE (iVoucherType & 0xff00) = 1792 AND sFieldName = 'InvoiceNo' AND bHeader = 1";
				dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				while (dataReader.Read())
				{
					list.Add(Convert.ToInt32(dataReader["iVoucherType"]));
				}
				dataReader.Close();
			}
			if (list.Count > 0)
			{
				text = GetStandardQuery(objRec.StartingDate, objRec.EndingDate, iVATInputAc, iVATOutputAc, strScreenData, bSales: true, list.ToArray(), flag);
				dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				while (dataReader.Read())
				{
					ledgerBalanceData = new LedgerBalanceData();
					if (dictionary.TryGetValue(Convert.ToInt32(dataReader["iBodyId"]), out ledgerBalanceData))
					{
						ledgerBalanceData.UnadjustedBalance = new decimal[1];
						ledgerBalanceData.UnadjustedBalance[0] = Convert.ToDecimal(dataReader["Taxable"]);
						dictionary[Convert.ToInt32(dataReader["iBodyId"])] = ledgerBalanceData;
					}
					else
					{
						ledgerBalanceData = new LedgerBalanceData();
						ledgerBalanceData.UnadjustedBalance = new decimal[1];
						ledgerBalanceData.UnadjustedBalance[0] = Convert.ToDecimal(dataReader["Taxable"]);
						dictionary.Add(Convert.ToInt32(dataReader["iBodyId"]), ledgerBalanceData);
					}
				}
				dataReader.Close();
			}
			flag = false;
			list.Clear();
			text = string.Format("SELECT a.iLinkPathId FROM mCore_LinkPath{0} a JOIN mCore_LinkNodes{0} b ON a.iToLinkId = b.iLinkId WHERE (b.iVoucherType & 0xff00) = 6400", Suffix);
			dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			while (dataReader.Read())
			{
				list.Add(Convert.ToInt32(dataReader["iLinkPathId"]));
				flag = true;
			}
			dataReader.Close();
			if (!flag)
			{
				text = $"SELECT iVoucherType FROM cCore_VoucherFields{Suffix} WHERE (iVoucherType & 0xff00) = 6400 AND sFieldName = 'InvoiceNo' AND bHeader = 1";
				dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				while (dataReader.Read())
				{
					list.Add(Convert.ToInt32(dataReader["iVoucherType"]));
				}
				dataReader.Close();
			}
			if (list.Count > 0)
			{
				text = GetStandardQuery(objRec.StartingDate, objRec.EndingDate, iVATInputAc, iVATOutputAc, strScreenData, bSales: false, list.ToArray(), flag);
				dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				while (dataReader.Read())
				{
					ledgerBalanceData = new LedgerBalanceData();
					if (dictionary.TryGetValue(Convert.ToInt32(dataReader["iBodyId"]), out ledgerBalanceData))
					{
						ledgerBalanceData.UnadjustedBalance = new decimal[1];
						ledgerBalanceData.UnadjustedBalance[0] = Convert.ToDecimal(dataReader["Taxable"]);
						dictionary[Convert.ToInt32(dataReader["iBodyId"])] = ledgerBalanceData;
					}
					else
					{
						ledgerBalanceData = new LedgerBalanceData();
						ledgerBalanceData.UnadjustedBalance = new decimal[1];
						ledgerBalanceData.UnadjustedBalance[0] = Convert.ToDecimal(dataReader["Taxable"]);
						dictionary.Add(Convert.ToInt32(dataReader["iBodyId"]), ledgerBalanceData);
					}
				}
				dataReader.Close();
			}
			if (dictionary.Count > 0 && _focus.company(m_iCompId).report(sUniqueId).accountBalance == null)
			{
				_focus.company(m_iCompId).report(sUniqueId).accountBalance = dictionary;
			}
		}
		catch (Exception ex)
		{
			FConvert.LogFile(FConvert.CompanyCodeFromId(m_iCompId) + "FQuery.log", "GetVATReturnAdjustment: " + ex.ToString());
		}
	}

	public string GetStandardQuery(int iStartDate, int iEndDate, int iVATInputAc, int iVATOutputAc, string strScreenData, bool bSales, int[] arrReturnLinkId, bool bReturnLinkExist)
	{
		string text = null;
		string text2 = null;
		string text3 = null;
		string suffix = Suffix;
		if (arrReturnLinkId != null && arrReturnLinkId.Length != 0)
		{
			text2 = $" AND tCore_Header{suffix}.iVoucherClass = {(bSales ? 1792 : 6400)}";
		}
		text = ((!bSales) ? string.Format("SELECT (CASE WHEN iCode = {3} THEN iMainBodyId ELSE iBodyId END)[iBodyId]\r\n\t            FROM\r\n\t            (\r\n\t\t            SELECT tCore_Data{0}.iMainBodyId, tCore_Data{0}.iBodyId, CASE WHEN iCode = {3} THEN iCode ELSE iBookNo END [iCode]\r\n\t\t            FROM tCore_Header{0} JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId  \r\n\t\t            JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n                    WHERE tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144)\r\n\t\t            AND tCore_Header{0}.iDate BETWEEN {1} AND {2}\r\n\t\t            AND tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA <> 1 AND tCore_Header{0}.bSuspended = 0 \r\n\t\t            AND tCore_Data{0}.iAuthStatus < 2 AND cCore_Vouchers{0}.bPostVAT = 1 AND tCore_Data{0}.iType <> 5\r\n\t            ) Temp ", suffix, iStartDate, iEndDate, iVATInputAc, iVATOutputAc) : string.Format("SELECT (CASE WHEN iCode = {4} THEN iMainBodyId ELSE iBodyId END)[iBodyId]\r\n\t            FROM\r\n\t            (\r\n\t\t            SELECT tCore_Data{0}.iMainBodyId, tCore_Data{0}.iBodyId, CASE WHEN iCode = {4} THEN iCode ELSE iBookNo END [iCode] \r\n                    FROM tCore_Header{0} JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId  \r\n\t\t            JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n                    WHERE  tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280)\r\n\t\t            AND tCore_Header{0}.iDate BETWEEN {1} AND {2}\r\n\t\t            AND tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA <> 1 AND tCore_Header{0}.bSuspended = 0 AND tCore_Data{0}.iAuthStatus < 2 \r\n\t\t            AND cCore_Vouchers{0}.bPostVAT = 1 AND tCore_Data{0}.iType <> 5\r\n\t            )Temp\r\n\t            UNION\r\n\t            SELECT (CASE WHEN iCode = {3} THEN iMainBodyId ELSE iBodyId END)[iBodyId]\r\n\t            FROM\r\n\t            (\r\n\t\t            SELECT tCore_Data{0}.iMainBodyId, tCore_Data{0}.iBodyId, CASE WHEN iCode = {3} THEN iCode ELSE iBookNo END [iCode]\r\n\t\t            FROM tCore_Header{0} JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId  \r\n\t\t            JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType=tCore_Header{0}.iVoucherType\r\n                    WHERE  tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144)\r\n\t\t            AND tCore_Header{0}.iDate BETWEEN {1} AND {2}\r\n\t\t            AND tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA <> 1 AND tCore_Header{0}.bSuspended = 0 \r\n\t\t            AND tCore_Data{0}.iAuthStatus < 2 AND cCore_Vouchers{0}.bPostVAT = 1 AND tCore_Data{0}.iType <> 5\r\n\t            ) Temp ", suffix, iStartDate, iEndDate, iVATInputAc, iVATOutputAc));
		if (!string.IsNullOrEmpty(strScreenData))
		{
			text3 = string.Format(" LEFT JOIN\r\n                (\r\n                    {1}\r\n                )ScreenData ON ScreenData.iBodyId = tCore_Data{0}.iBodyId ", suffix, strScreenData);
		}
		if (arrReturnLinkId != null && arrReturnLinkId.Length != 0)
		{
			text3 = ((!bReturnLinkExist) ? (text3 + string.Format("LEFT JOIN\r\n                    (\r\n\t                    SELECT a.iHeaderId, b.iDate FROM \r\n                        (\r\n\t                        SELECT iDate, a.iHeaderId, c.iVoucherType iBaseVoucher, (SELECT value FROM string_split(InvoiceNo, ':') \r\n\t                        ORDER BY (SELECT NULL) OFFSET 1 ROWS FETCH NEXT 1 ROWS ONLY) BaseVoucher \r\n                            FROM tCore_Header{0} a \r\n                            JOIN tCore_HeaderData{1}{0} b ON a.iHeaderId = b.iHeaderId\r\n\t                        JOIN cCore_Vouchers{0} c ON c.sAbbr = (SELECT TOP 1 value FROM string_split(InvoiceNo, ':'))\r\n\t                        WHERE iDate <= {2} AND LEN(InvoiceNo) > 4\r\n                        ) a JOIN tCore_Header{0} b ON a.iBaseVoucher = b.iVoucherType AND a.BaseVoucher = b.sVoucherNo\r\n                    )BaseReturn on BaseReturn.iHeaderId = tCore_Header{0}.iHeaderId", suffix, arrReturnLinkId[0], iEndDate)) : (text3 + string.Format("LEFT JOIN\r\n                    (\r\n\t                    select distinct b.iBodyId, e.iDate\r\n\t                    from tCore_Header{0} a \r\n\t                    join tCore_Data{0} b on a.iHeaderId = b.iHeaderId\r\n\t                    join tCore_Links{0} c on b.iTransactionId = c.iTransactionId and bBase = 0\r\n\t                    join tCore_Data{0} d on c.iRefId = d.iTransactionId and bBase = 0 \r\n\t                    join tCore_Header{0} e on d.iHeaderId = e.iHeaderId\r\n\t                    where iLinkId in ({1})\r\n                    )BaseReturn on BaseReturn.iBodyId = tCore_Data{0}.iBodyId", suffix, string.Join(",", arrReturnLinkId.Select((int p) =>
			{
				int num = p;
				return num.ToString();
			}).ToArray()))));
		}
		return string.Format("SELECT tCore_Data{0}.iBodyId, ISNULL(SUM(ScreenData.Taxable),0)Taxable\r\n            FROM \r\n            (\r\n                SELECT v_Vat.iBodyId[iMainBodyId] FROM tCore_Data{0}   \r\n                LEFT JOIN\r\n                (\r\n\t                {7}\r\n                )v_Vat ON v_Vat.iBodyId = tCore_Data{0}.iBodyId \r\n                GROUP BY v_Vat.iBodyId\r\n            )InnerTable \r\n            JOIN tCore_Data{0}  ON tCore_Data{0}.iBodyId = InnerTable.iMainBodyId\r\n            JOIN tCore_Header{0}  ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n            JOIN cCore_Vouchers{0} WITH(READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType = tCore_Header{0}.iVoucherType\r\n            LEFT JOIN tCore_Indta{0}  ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId  \r\n            {5}\r\n            WHERE tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA = 0 \r\n            AND tCore_Header{0}.bSuspended = 0 AND tCore_Data{0}.iAuthStatus < 2\r\n            AND cCore_Vouchers{0}.bPostVAT = 1 AND BaseReturn.iDate < {1}\r\n            AND tCore_Data{0}.iType = 0 {6}\r\n            GROUP BY tCore_Data{0}.iBodyId", suffix, iStartDate, iEndDate, iVATInputAc, iVATOutputAc, text3, text2, text);
	}

	public string getMultiEntityTagId(CountryVAT iCountryId, int iCompanyId)
	{
		string text = null;
		string text2 = null;
		string result = string.Empty;
		IDataReader dataReader = null;
		List<string> list = null;
		try
		{
			if (m_objDatabase == null)
			{
				m_objDatabase = DatabaseWrapper.GetDatabase2(iCompanyId);
			}
			text = $"SELECT iMasterId FROM mCore_Country WHERE sCode = ";
			text = iCountryId switch
			{
				CountryVAT.KSA => text + "'SAU'", 
				CountryVAT.BH => text + "'BHR'", 
				CountryVAT.OM => text + "'OMN'", 
				_ => text + "'ARE'", 
			};
			iCountryId = (CountryVAT)Convert.ToInt32(m_objDatabase.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
			if (iCountryId > CountryVAT.KSA)
			{
				text = $"SELECT 'mu' + sModule + '_' + sMasterName + '_VAT_Settings' sVatTable FROM cCore_MasterDef WHERE iMasterTypeId = {_focus.company(iCompanyId).faTagId}";
				text2 = Convert.ToString(m_objDatabase.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
				if (!string.IsNullOrEmpty(text2))
				{
					text = $"SELECT iMasterId FROM {text2} WHERE iCountry = {iCountryId}";
					dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
					list = new List<string>();
					while (dataReader.Read())
					{
						list.Add(Convert.ToString(dataReader["iMasterId"]));
					}
					dataReader.Close();
					if (list.Count > 0)
					{
						result = string.Join(",", list);
					}
				}
			}
		}
		catch (Exception ex)
		{
			FConvert.LogFile("Focus8VATUI.log", DateTime.Now.ToString() + " [getMultiEntityTagId] : " + ex.Message);
		}
		return result;
	}

	public string getVatInnerQuery(int iStartDate, int iEndDate, bool bEnableLocaCurrency, int iCompanyId)
	{
		string suffix = FConvert.GetSuffix(iCompanyId);
		int preferenceValue = _focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.VAT, 15);
		int preferenceValue2 = _focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.VAT, 22);
		int preferenceValue3 = _focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.VAT, 26);
		int preferenceValue4 = _focus.company(iCompanyId).getPreferenceValue(PreferenceCategories.VAT, 27);
		string text = $"tCore_Data{suffix}.mAmount1";
		string text2 = $"tCore_Data{suffix}.mAmount2";
		string text3 = string.Empty;
		string text4 = ((preferenceValue3 > 0) ? string.Format("AND 1 = CASE WHEN bInventory = 1 AND (iBookNo = {0} OR iCode = {0}) THEN 0 ELSE 1 END", preferenceValue3) : string.Empty);
		string text5 = ((preferenceValue4 > 0) ? string.Format("AND 1 = CASE WHEN bInventory = 1 AND (iBookNo = {0} OR iCode = {0}) THEN 0 ELSE 1 END", preferenceValue4) : string.Empty);
		if (!string.IsNullOrEmpty(text5))
		{
			text5 += string.Format(" AND 1 = case when bInventory = 1 then 1 else case when (not((iCode = {0} and iBookNo = {1}) OR (iCode = {1} and iBookNo = {0}))) then 1 else 0 end end", preferenceValue, preferenceValue2);
		}
		if (bEnableLocaCurrency)
		{
			text = string.Format("ISNULL(tCore_Data_FX{0}.fLocalAmount1, tCore_Data{0}.mAmount1)", suffix);
			text2 = string.Format("ISNULL(tCore_Data_FX{0}.fLocalAmount2, tCore_Data{0}.mAmount2)", suffix);
			text3 = string.Format("LEFT JOIN tCore_Data_FX{0} ON tCore_Data_FX{0}.iBodyId = tCore_Data{0}.iBodyId", suffix);
		}
		return $"SELECT v_Vat.iBodyId[iMainBodyId], SUM(v_Vat.[Net])[Net], SUM(v_Vat.VATAmt) [VATAmt] FROM tCore_Data{suffix}   \r\n            LEFT JOIN\r\n            (\r\n\t            SELECT CASE WHEN iCode = {preferenceValue2} THEN iMainBodyId ELSE iBodyId END[iBodyId]\r\n                ,CASE WHEN iCode = {preferenceValue2} THEN Amt ELSE 0.0 END[VATAmt]\r\n\t            ,CASE WHEN (CASE WHEN iCode = {preferenceValue2} THEN Amt ELSE 0.0 END) <> 0 THEN 100.0/5.0*(CASE WHEN iCode = {preferenceValue2} THEN Amt ELSE 0.0 END) ELSE 0 END[Net]\r\n\t            FROM\r\n\t            (\r\n\t\t            SELECT iMainBodyId, tCore_Data{suffix}.iBodyId,CASE WHEN iCode = {preferenceValue2} THEN iCode ELSE iBookNo END [iCode] ,CASE WHEN iCode = {preferenceValue2} THEN {text} ELSE {text2} END Amt\r\n\t\t            FROM tCore_Header{suffix} JOIN tCore_Data{suffix} on tCore_Header{suffix}.iHeaderId = tCore_Data{suffix}.iHeaderId {text3}\r\n\t\t            JOIN cCore_Vouchers{suffix} WITH (READUNCOMMITTED) ON cCore_Vouchers{suffix}.iVoucherType = tCore_Header{suffix}.iVoucherType\r\n                    WHERE tCore_Header{suffix}.iVoucherClass NOT IN(768,6400,2560,1280)\r\n\t\t            AND tCore_Header{suffix}.iDate BETWEEN {iStartDate} AND {iEndDate}\r\n\t\t            AND tCore_Data{suffix}.bUpdateFA = 1 AND tCore_Data{suffix}.bSuspendUpdateFA <> 1 AND tCore_Header{suffix}.bSuspended = 0 AND tCore_Data{suffix}.iAuthStatus < 2 \r\n\t\t            AND cCore_Vouchers{suffix}.bPostVAT = 1 AND tCore_Data{suffix}.iType <> 5 {text4}\r\n\t            )Temp\r\n\t            UNION\r\n\t            SELECT CASE WHEN iCode = {preferenceValue} THEN iMainBodyId ELSE iBodyId END[iBodyId]\r\n                ,-(CASE WHEN iCode = {preferenceValue} THEN Amt ELSE 0.0 END)[Vat]\r\n                ,CASE WHEN (CASE WHEN iCode = {preferenceValue} THEN Amt ELSE 0.0 END) <> 0 THEN 100.0/5.0*(CASE WHEN iCode = {preferenceValue} THEN Amt ELSE 0.0 END) else 0 END[Net]\r\n\t            FROM\r\n\t            (\r\n\t\t            SELECT iMainBodyId, tCore_Data{suffix}.iBodyId, CASE WHEN iCode = {preferenceValue} THEN iCode ELSE iBookNo END [iCode], CASE WHEN iCode = {preferenceValue} THEN {text} ELSE {text2} END Amt\r\n\t\t            FROM tCore_Header{suffix} JOIN tCore_Data{suffix} on tCore_Header{suffix}.iHeaderId = tCore_Data{suffix}.iHeaderId {text3} \r\n\t\t            JOIN cCore_Vouchers{suffix} WITH (READUNCOMMITTED) ON cCore_Vouchers{suffix}.iVoucherType=tCore_Header{suffix}.iVoucherType\r\n                    WHERE tCore_Header{suffix}.iVoucherClass NOT IN(3328,1792,5632,6144)\r\n\t\t            AND tCore_Header{suffix}.iDate BETWEEN {iStartDate} AND {iEndDate}\r\n\t\t            AND tCore_Data{suffix}.bUpdateFA = 1 AND tCore_Data{suffix}.bSuspendUpdateFA <> 1 AND tCore_Header{suffix}.bSuspended = 0 \r\n\t\t            AND tCore_Data{suffix}.iAuthStatus < 2 AND cCore_Vouchers{suffix}.bPostVAT = 1 AND tCore_Data{suffix}.iType <> 5 {text5}\r\n\r\n\t            ) Temp \r\n                UNION -- sales adv\r\n                SELECT Temp.iBodyId[iBodyId]\r\n                ,CASE WHEN Temp.iCode = {preferenceValue2} THEN Amt ELSE 0.0 END[VATAmt]\r\n\t            ,CASE WHEN (CASE WHEN Temp.iCode = {preferenceValue2} THEN Amt ELSE 0.0 END) <> 0 THEN sum(b.mBaseAmount) ELSE 0 END[Net]\r\n\t            FROM\r\n\t            (\r\n\t\t            SELECT iMainBodyId, tCore_Data{suffix}.iBodyId, CASE WHEN iCode = {preferenceValue2} THEN iCode ELSE iBookNo END [iCode], CASE WHEN iCode = {preferenceValue2} THEN {text} ELSE {text2} END Amt\r\n\t\t            FROM tCore_Header{suffix} JOIN tCore_Data{suffix} on tCore_Header{suffix}.iHeaderId = tCore_Data{suffix}.iHeaderId {text3} \r\n\t\t            JOIN cCore_Vouchers{suffix} WITH (READUNCOMMITTED) ON cCore_Vouchers{suffix}.iVoucherType=tCore_Header{suffix}.iVoucherType\r\n                    WHERE tCore_Header{suffix}.iVoucherClass NOT IN(768,6400,2560,1280)\r\n\t\t            AND tCore_Header{suffix}.iDate BETWEEN {iStartDate} AND {iEndDate}\r\n\t\t            AND tCore_Data{suffix}.bUpdateFA = 1 AND tCore_Data{suffix}.bSuspendUpdateFA <> 1 AND tCore_Header{suffix}.bSuspended = 0 AND tCore_Data{suffix}.iAuthStatus < 2 \r\n\t\t            AND cCore_Vouchers{suffix}.bPostVAT = 1 AND tCore_Data{suffix}.iType <> 5 AND bInventory = 1 AND (iBookNo = {preferenceValue3} OR iCode = {preferenceValue3}) \r\n\t            )Temp\r\n                JOIN tCore_Refrn{suffix} b ON Temp.iMainBodyId = b.iBodyId AND iRefType = 2\r\n                GROUP BY Temp.iBodyId,(CASE WHEN Temp.iCode = {preferenceValue2} THEN Amt ELSE 0.0 END)\r\n                UNION -- pur adv\r\n                SELECT Temp.iBodyId[iBodyId]\r\n                ,CASE WHEN Temp.iCode = {preferenceValue} THEN Amt ELSE 0.0 END[VATAmt]\r\n\t            ,CASE WHEN (CASE WHEN Temp.iCode = {preferenceValue} THEN Amt ELSE 0.0 END) <> 0 then sum(b.mBaseAmount) ELSE 0 END[Net]\r\n\t            FROM\r\n\t            (\r\n\t\t            SELECT iMainBodyId, tCore_Data{suffix}.iBodyId, CASE WHEN iCode = {preferenceValue} THEN iCode ELSE iBookNo END [iCode], -CASE WHEN iCode = {preferenceValue} THEN {text} ELSE {text2} END Amt\r\n\t\t            FROM tCore_Header{suffix} JOIN tCore_Data{suffix} on tCore_Header{suffix}.iHeaderId = tCore_Data{suffix}.iHeaderId {text3} \r\n\t\t            JOIN cCore_Vouchers{suffix} WITH (READUNCOMMITTED) ON cCore_Vouchers{suffix}.iVoucherType=tCore_Header{suffix}.iVoucherType\r\n                    WHERE tCore_Header{suffix}.iVoucherClass NOT IN(3328,1792,5632,6144)\r\n\t\t            AND tCore_Header{suffix}.iDate BETWEEN {iStartDate} AND {iEndDate}\r\n\t\t            AND tCore_Data{suffix}.bUpdateFA = 1 AND tCore_Data{suffix}.bSuspendUpdateFA <> 1 AND tCore_Header{suffix}.bSuspended = 0 AND tCore_Data{suffix}.iAuthStatus < 2 \r\n\t\t            AND cCore_Vouchers{suffix}.bPostVAT = 1 AND tCore_Data{suffix}.iType <> 5 AND bInventory = 1 AND (iBookNo = {preferenceValue4} OR iCode = {preferenceValue4}) \r\n\t            )Temp\r\n                JOIN tCore_Refrn{suffix} b ON Temp.iMainBodyId = b.iBodyId AND iRefType = 2\r\n                GROUP BY Temp.iBodyId,(CASE WHEN Temp.iCode = {preferenceValue} THEN Amt ELSE 0.0 END)\r\n            )v_Vat ON v_Vat.iBodyId = tCore_Data{suffix}.iBodyId \r\n            GROUP BY v_Vat.iBodyId";
	}

	public string getVatOrderBy(CountryVAT oCountry)
	{
		string text = null;
		return oCountry switch
		{
			CountryVAT.UAE => string.Format("CASE WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280,5120) AND lower(vmCore_Jurisdiction.sName) like '%dhabi%' AND vmCore_TaxCode.sCode ='SR' THEN '1.a Standard rated supplies in Abu Dhabi' \r\n\t            WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280,5120) AND lower(vmCore_Jurisdiction.sName) like '%dubai%' AND vmCore_TaxCode.sCode ='SR' THEN '1.b Standard rated supplies in Dubai'\r\n\t            WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280,5120) AND lower(vmCore_Jurisdiction.sName) like '%sharjah%' AND vmCore_TaxCode.sCode ='SR' THEN '1.c Standard rated supplies in Sharjah'\r\n\t            WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280,5120) AND lower(vmCore_Jurisdiction.sName) like '%ajman%' AND vmCore_TaxCode.sCode ='SR' THEN '1.d Standard rated supplies in Ajman'\r\n\t            WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280,5120) AND lower(vmCore_Jurisdiction.sName) like '%quwain%' AND vmCore_TaxCode.sCode ='SR' THEN '1.e Standard rated supplies in Umm Al Quwain'\r\n\t            WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280,5120) AND (lower(vmCore_Jurisdiction.sCode) like '%rak%' OR lower(vmCore_Jurisdiction.sName) like '%khaima%') AND vmCore_TaxCode.sCode ='SR' THEN '1.f Standard rated supplies in Ras Al Khaimah'\r\n\t            WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280,5120) AND lower(vmCore_Jurisdiction.sName) like '%fujair%' AND vmCore_TaxCode.sCode ='SR' THEN '1.g Standard rated supplies in Fujairah'\r\n\t            WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='TT' THEN '2. The Refunds provided to Tourists under the Tax Refunds for Tourists Scheme'\r\n\t            WHEN vmCore_TaxCode.sCode IN('RC','RCMS') THEN '3. Supplies subject to the reverse charge provisions'\r\n\t            WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='ZR' THEN '4. Zero rated Supplies'\r\n\t            WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='EX' THEN '5. Exempt Supplies'\r\n\t            WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode ='IC' THEN '6. Goods Imported into the UAE'\r\n\t            WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode ='AM' THEN '7. Adjustments to goods imported into the UAE'\r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode IN('SR','SR-REC') THEN '9. Standard rated Expenses'\r\n\t\t\t\tWHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode IN('RC','RCMS') THEN '10. Supplies subject to the reverse charge provisions'\r\n\t\t\t\tELSE 'Others' END", Suffix), 
			CountryVAT.KSA => string.Format("CASE WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280,5120) AND vmCore_TaxCode.sCode IN('SR','OA') THEN '1. Standard rated sales (15%)' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280,5120) AND vmCore_TaxCode.sCode = 'SR5' THEN '1.1 Sales subject to VAT (5%)' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='IG' THEN '2. Sales to customers in VAT implementing GCC countries'\r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='ZR' THEN '3. Zero rated domestic sales'\r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='ZE' THEN '4. Exports'\r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='EX' THEN '5. Exempt sales'\r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode IN('SR','SR-REC','SREC-FA') THEN '7. Standard rated domestic purchases (15%)' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode IN('SR5', 'SR-REC5') THEN '7.1 Standard rated domestic purchases (5%)' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode IN('IC','IV', 'IC-REC') THEN '8. Import subject to VAT paid at customs (15%)' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode = 'IC5' THEN '8.1 Import subject to VAT paid at customs (5%)' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode = 'RC' THEN '9. Import subject to VAT accounted for through reverse change machenism (15%)' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode IN('RC5','RCM5') THEN '9.1 Import subject to VAT accounted for through reverse change machenism (5%)' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode = 'ZRP' THEN '10. Zero rated purchases' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode = 'EXP' THEN '11. Exempt purchases' \r\n                ELSE 'Others' END", Suffix), 
			CountryVAT.OM => string.Format("CASE WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280,5120) AND vmCore_TaxCode.sCode = 'SR' THEN '1 a. Supplies of goods / services taxed at 5%' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='ZR' THEN '1 b. Supplies of goods / services taxed at 0%'\r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='EX' THEN '1 c. Supplies of goods / services tax exempt'\r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode = 'RC' THEN '2. Purchases from the GCC subject to Reverse Charge Mechanism:' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='ZE' THEN '3 a. Exports'\r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode = 'IC' AND InnerTable.[VATAmt] <> 0 THEN '4 a. Import of Goods (Postponed payment)' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='SR-ADJ' THEN '5 b. Adjustment of VAT due'\r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode IN('SREC','SREC-NON','SR-REC','ZRP','EXP','SR-NON','OS') THEN '6 a. Purchases (except import of goods)' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode IN('IC','IC-REC') THEN '6 b. Import of goods' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode = 'SREC-FA' THEN '6 c. VAT on acquisition of fixed assets' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode = 'SR-RADJ' THEN '6 d. Adjustment of input VAT credit' \r\n                ELSE 'Others' END", Suffix), 
			CountryVAT.BH => string.Format("CASE WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode IN('SR','OA') THEN '1. Standard rated sales' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='IG' THEN '2. Sales to registered customers in other GCC States'\r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='IG' THEN '3. Sales subject to domestic reverse charge mechanism'\r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode = 'ZR' THEN '4. Zero rated domestic sales' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='ZE' THEN '5. Exports'\r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='EX' THEN '6. Exempt sales'\r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode IN('SR','SR-REC') THEN '8. Standard rated domestic purchases' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode = 'IC' THEN '9. Imports subject to VAT either paid at customs or deferred' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode = 'RC' THEN '10. Imports subject to VAT accounted for through reverse charge mechanism' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode = 'ZRP' THEN '11. Purchases subject to domestic reverse charge mechanism' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode = 'EXP' THEN '12. Purchases from non-registered taxpayers, zero-rated/ exempt purchases' \r\n                ELSE 'Others' END", Suffix), 
			CountryVAT.NPL => string.Format("CASE WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280,5120) AND vmCore_TaxCode.sCode IN('SR') THEN '1.1 Taxable Sales' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='ZR' THEN '1.2 Export'\r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(768,6400,2560,1280) AND vmCore_TaxCode.sCode ='EX' THEN '1.3 Exempt Sales'\r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode IN('SR-REC') AND vmCore_PlaceOfSupply.sName <> 'Import' THEN '2.1 Taxable Purchase' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode IN('IC') AND vmCore_PlaceOfSupply.sName = 'Import' THEN '2.2 Taxable Import' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode = 'EX' AND vmCore_PlaceOfSupply.sName <> 'Import' THEN '2.3 Exempted Purchase' \r\n                WHEN tCore_Header{0}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode = 'EX' AND vmCore_PlaceOfSupply.sName = 'Import' THEN '2.4 Exempted Import' \r\n                WHEN tCore_Header{0}.iVoucherClass IN(4098,8704,1792) AND vmCore_TaxCode.sCode = 'SR-ADJ' THEN '3.1 Other Adjustments/Sales Returned/Cr. Note' \r\n                WHEN tCore_Header{0}.iVoucherClass IN(3840,8704,6400) AND vmCore_TaxCode.sCode = 'SR-RADJ' THEN '3.2 Other Adjustment/Purchase Returned/Dr. Note' \r\n                ELSE 'Others' END", Suffix), 
			_ => $"CASE WHEN tCore_Header{Suffix}.iVoucherClass NOT IN(3328,1792,5632,6144) AND vmCore_TaxCode.sCode IN('SR','SR-REC') THEN 'Purchases' ELSE 'Sales' END ", 
		};
	}

	private string DefaultFixAssetQuery(RepRecord objRec, Database objDb)
