			break;
		case FocusReport.FATransferOfAssets:
		{
			int preferenceValue3 = _focus.company(m_iCompId).getPreferenceValue(PreferenceCategories.FixedAssets, 18);
			string viewName = _focus.company(m_iCompId).master(preferenceValue3).viewName;
			preferenceValue3 = _focus.company(m_iCompId).getPreferenceValue(PreferenceCategories.FixedAssets, 2);
			string viewName2 = _focus.company(m_iCompId).master(preferenceValue3).viewName;
			preferenceValue3 = _focus.company(m_iCompId).getPreferenceValue(PreferenceCategories.FixedAssets, 3);
			string viewName3 = _focus.company(m_iCompId).master(preferenceValue3).viewName;
			preferenceValue3 = _focus.company(m_iCompId).getPreferenceValue(PreferenceCategories.FixedAssets, 29);
			string viewName4 = _focus.company(m_iCompId).master(preferenceValue3).viewName;
			preferenceValue3 = _focus.company(m_iCompId).getPreferenceValue(PreferenceCategories.FixedAssets, 30);
			string viewName5 = _focus.company(m_iCompId).master(preferenceValue3).viewName;
			string text5 = "";
			string text6 = "";
			string text7 = "";
			string text8 = "";
			string text9 = "";
			string text10 = "";
			string text11 = "";
			string text12 = "";
			string text13 = "";
			string text14 = "";
			if (string.IsNullOrEmpty(viewName) && string.IsNullOrEmpty(viewName2) && string.IsNullOrEmpty(viewName3) && string.IsNullOrEmpty(viewName2) && string.IsNullOrEmpty(viewName3))
			{
				result = string.Format("SELECT distinct mFixA_AssetTransfer_0.iTransferId,mFixA_AssetTransfer_0.sVoucherNo,vrFixA_FixedAsset.sName, vrFixA_FixedAsset.sCode, iTransferDate, \r\n                        ''[ftag1.sName],''[ftag1.sCode], ''[ttag1.sName], ''[ttag1.sCode],\r\n                        ''[ftag2.sName],''[ftag2.sCode], ''[ttag2.sName], ''[ttag2.sCode],\r\n                        ''[ftag3.sName],''[ftag3.sCode], ''[ttag3.sName], ''[ttag3.sCode],\r\n                        ''[ftag4.sName],''[ftag4.sCode], ''[ttag4.sName], ''[ttag4.sCode],\r\n                        ''[ftag5.sName],''[ftag5.sCode], ''[ttag5.sName], ''[ttag5.sCode],\r\n                        femp.sName,femp.sCode, temp.sName,temp.sCode,mFixA_AssetTransfer_0.dValueAfterDepreciation,mFixA_AssetTransfer_0.dValueChanged, tCore_Header{0}.SvoucherNo TransVoucher\r\n                        from mFixA_AssetTransfer_0\r\n                        Inner Join vrFixA_FixedAsset on vrFixA_FixedAsset.iMasterId = mFixA_AssetTransfer_0.iAssetId and vrFixA_FixedAsset.iTreeId=0\r\n                        inner join mPay_Employee femp on femp.iMasterId = iFAllotedTo \r\n                        inner join mPay_Employee temp on temp.iMasterId = iTAllotedTo \r\n                        left join tCore_Data{0}  on tCore_Data{0}.iTransactionId= mFixA_AssetTransfer_0.iTransactionId\r\n\t\t\t\t\t    left join tCore_Header{0}  on tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n                        left join [tCore_FixAssetAuth] ON [tCore_FixAssetAuth].iDocumentId=mFixA_AssetTransfer_0.iTransferId and [tCore_FixAssetAuth].iFixAssetScreenTypeId=3\r\n                        left JOIN tCore_FixAssetAuthUser  on tCore_FixAssetAuthUser.iAuthId = [tCore_FixAssetAuth].iAuthId", Suffix);
			}
