ars  else vrFixA_FixedAsset.fITDepreciationRate end)\r\n                    ELSE 0 END [DepreciationWithoutAR]\r\n                    , ISNULL(AddYrs.iNoOfYears,0) TotYrs, ISNULL(AddYrs.iNoOfMonths,0) iNoOfMonths --ISNULL(vrFixA_FixedAsset.iDepreciationInYears,0) +\r\n\r\n                    FROM vrFixA_FixedAsset \r\n                    JOIN muFixA_FixedAsset_Depreciation ON vrFixA_FixedAsset.iMasterId=muFixA_FixedAsset_Depreciation.iMasterId\r\n                    JOIN mFixA_FixedAsset ON vrFixA_FixedAsset.iMasterId=mFixA_FixedAsset.iMasterId\r\n                    LEFT JOIN mFixA_AssetChgValHeader_0 AddValue WITH (READUNCOMMITTED) ON AddValue.iAssetId = vrFixA_FixedAsset.iMasterId and AddValue.iStatus<>5 and AddValue.iCommencementdate <= {2}\r\n                    LEFT JOIN mFixA_AssetDisposalHeader_0 Disposal WITH (READUNCOMMITTED) ON Disposal.iAssetId = vrFixA_FixedAsset.iMasterId and Disposal.iStatus<>5 --and Disposal.iDisposalDate <= {2}\r\n                    LEFT JOIN  vrFixA_FixedAsset FixA  ON FixA.iMasterId= vrFixA_FixedAsset.iParentId\r\n                    left join mFixA_ChangeDepValue AddYrs on AddYrs.iFixAssetId=vrFixA_FixedAsset.iMasterId {7}{12} {9} ", Suffix, (objRec.StartingDate == 0) ? accountingDate : objRec.StartingDate, objRec.EndingDate, FConvert.GetInputValue(objRec.Inputs, 4), accountingDate, value, noOfDecimal, objRec.ExtraColumns.Any((FieldData p) => p.FieldName.ToString().Contains("vrCore_Product")) ? " left join vrCore_Product on vrCore_Product.sCode=vrFixA_FixedAsset.iProductsCode " : "", num, text2, text4, strRoleIdFilterJoin, text3, empty);
