	public string GetMasterIdsXML(string strMasterIds)
	{
		string[] array = strMasterIds.Split(',');
		StringBuilder stringBuilder = new StringBuilder("");
		string empty = string.Empty;
		string empty2 = string.Empty;
		if (array == null)
		{
			empty = " ID=\"0\"";
			empty2 = " iR=\"0\"";
			stringBuilder.Append("<R " + empty + "/>");
		}
		else
		{
			for (int i = 0; i < array.Length; i++)
			{
				empty = $" ID=\"{array[i]}\"";
				empty2 = $" iR=\"{i.ToString()}\"";
				stringBuilder.Append("<R " + empty2 + empty + "/>");
			}
		}
		return stringBuilder.ToString();
	}

	public List<IdNamePair> GetMonthWiseStartEndDates(int iStartDate, int iEndDate)
	{
		int accountingDate = _focus.company(m_iCompId).accountingDate;
		iStartDate = ((iStartDate == 0) ? accountingDate : iStartDate);
		List<IdNamePair> list = new List<IdNamePair>();
		try
		{
			int iD = iStartDate;
			int num = 0;
			IdNamePair idNamePair = new IdNamePair();
			Date date = new Date(iStartDate, m_objCalType);
			new Date(iStartDate, m_objCalType);
			num = date.Add(1, DateAdd.Months).Add(-date.Day, DateAdd.Days).Value;
			idNamePair.ID = iD;
			if (num > iEndDate)
			{
				num = iEndDate;
			}
			idNamePair.Tag = num;
			list.Add(idNamePair);
			iD = new Date(num, m_objCalType).Add(1, DateAdd.Days).Value;
			while (num < iEndDate)
			{
				date = new Date(iD, m_objCalType);
				idNamePair = new IdNamePair();
				idNamePair.ID = iD;
				num = date.Add(1, DateAdd.Months).Add(-1, DateAdd.Days).Value;
				if (num > iEndDate)
				{
					num = iEndDate;
				}
				idNamePair.Tag = num;
				list.Add(idNamePair);
				iD = new Date(num, m_objCalType).Add(1, DateAdd.Days).Value;
			}
		}
		catch (Exception ex)
		{
			m_sError = ex.Message;
		}
		return list;
	}

