				text4 += string.Format(" LEFT JOIN\r\n                            (\r\n                                SELECT tCore_Links{0}.iTransactionId,iRefId,tCore_Links{0}.iUserId, tCore_Links{0}.bClosed\r\n                                FROM tCore_Links{0} JOIN tCore_Data{0} ON tCore_Links{0}.iTransactionId = tCore_Data{0}.iTransactionId\r\n                                JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                                WHERE tCore_Data{0}.bSuspendUpdateStocks <> 1 AND tCore_Header{0}.bSuspended = 0 \r\n                                AND tCore_Links{0}.iLinkId IN ({5}) AND bBase=1\r\n                            )tCore_LinksFinalBase{0} ON tCore_Links{4}{3}.iTransactionId = tCore_LinksFinalBase{0}.iRefId", Suffix, list[num2], num2 + ((num2 > 0) ? num3 : 0), (num2 > 0) ? list[num2 - 1].ToString() : string.Empty, Suffix, (!string.IsNullOrEmpty(text3)) ? text3 : list[num2].ToString());
			}
			if (bPreviousYear)
			{
				text5 = ((m_iLinkCount > 0) ? ("tCore_LinksFinalBase" + Suffix) : ("tCore_Links" + Suffix));
				text3 = ((iLinkPathId > 0) ? $" AND tCore_LinksOb{m_sCurrentSuffix}.iLinkId = {iLinkPathId} " : "");
				text = $"SELECT tCore_Links{Suffix}.iBodyId[iHeaderId], [DocNo-b],[iDate-b],AVG([fValue-b])[fValue-b] {text2}\r\n                        ,CASE WHEN ISNULL({text5}.iUserId,0) > 0 THEN 'Manually Closed' WHEN ISNULL({text5}.bClosed, 0) > 0 THEN 'Closed' ELSE 'Pending' END[Linktatus]\r\n                        FROM \r\n                        (\r\n\t                        SELECT 0[iUserId], 0[bClosed],tCore_Data{Suffix}.iBodyId,tCore_LinksOb{m_sCurrentSuffix}.iTransactionId, iRefId,tCore_Header{Suffix}.iDate[iDate-b], sAbbr+':'+sVoucherNo[DocNo-b],fValue[fValue-b]\r\n\t                        FROM tCore_LinksOb{m_sCurrentSuffix} \r\n\t                        JOIN tCore_Data{Suffix} ON tCore_LinksOb{m_sCurrentSuffix}.iTransactionId = tCore_Data{Suffix}.iTransactionId\r\n\t                        JOIN tCore_Header{Suffix} ON tCore_Data{Suffix}.iHeaderId = tCore_Header{Suffix}.iHeaderId\r\n\t                        JOIN cCore_Vouchers{Suffix} WITH (READUNCOMMITTED) ON cCore_Vouchers{Suffix}.iVoucherType = tCore_Header{Suffix}.iVoucherType\r\n\t                        WHERE tCore_Data{Suffix}.bSuspendUpdateStocks <> 1 AND tCore_Header{Suffix}.bSuspended = 0 \r\n                            AND tCore_Header{Suffix}.iDate BETWEEN {objRec.StartingDate} AND {objRec.EndingDate} AND bBase = 1 {text3}\r\n                        )tCore_Links{Suffix} \r\n                        LEFT JOIN tCore_Data{Suffix} ON tCore_Links{Suffix}.iTransactionId = tCore_Data{Suffix}.iTransactionId\r\n\t\t\t\t\t    JOIN tCore_Header{Suffix} ON tCore_Data{Suffix}.iHeaderId = tCore_Header{Suffix}.iHeaderId\r\n\t                    JOIN cCore_Vouchers{Suffix} WITH (READUNCOMMITTED) ON cCore_Vouchers{Suffix}.iVoucherType = tCore_Header{Suffix}.iVoucherType\r\n                        LEFT JOIN tCore_Indta{Suffix} ON tCore_Indta{Suffix}.iBodyId = tCore_Data{Suffix}.iBodyId\r\n                        LEFT JOIN vrCore_Product ON vrCore_Product.iMasterId = tCore_Indta{Suffix}.iProduct AND vrCore_Product.iTreeId = 0\r\n                        {text4}";
			}
			else
			{
				text = string.Format("SELECT tCore_Links{0}.iBodyId[iHeaderId], [DocNo-b],[iDate-b],AVG([fValue-b])[fValue-b]\r\n                        {1}, CASE WHEN ISNULL(tCore_Links{0}.iUserId,0) > 0 AND tCore_Links{0}.LinkStatus <> 'Pending' THEN 'Manually Closed' WHEN ISNULL({6}{0}.bClosed, 0) > 0 THEN 'Closed' ELSE 'Pending' END[LinkStatus]\r\n                        FROM \r\n                        (\r\n\t                        SELECT tCore_Links{0}.iUserId, bClosed,tCore_Data{0}.iBodyId,tCore_Links{0}.iTransactionId, iRefId,tCore_Header{0}.iDate[iDate-b], sAbbr+':'+sVoucherNo[DocNo-b],fValue[fValue-b]\r\n                            ,CASE WHEN tCore_Links{0}.bClosed IS NULL OR tCore_Links{0}.bClosed = 0 THEN 'Pending' ELSE 'Closed' END[LinkStatus]\r\n\t                        FROM tCore_Links{0} \r\n\t                        JOIN tCore_Data{0} ON tCore_Links{0}.iTransactionId = tCore_Data{0}.iTransactionId\r\n\t                        JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t                        JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType = tCore_Header{0}.iVoucherType\r\n\t                        WHERE tCore_Data{0}.bSuspendUpdateStocks <> 1 AND tCore_Header{0}.bSuspended = 0 AND tCore_Data{0}.iAuthStatus < 2\r\n                            AND tCore_Header{0}.iDate BETWEEN {3} AND {4} AND bBase = 1 {5}\r\n                        )tCore_Links{0} \r\n                        LEFT JOIN tCore_Data{0} ON tCore_Links{0}.iTransactionId = tCore_Data{0}.iTransactionId\r\n\t\t\t\t\t    JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n\t                    JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType = tCore_Header{0}.iVoucherType\r\n                        LEFT JOIN tCore_Indta{0} ON tCore_Indta{0}.iBodyId = tCore_Data{0}.iBodyId\r\n                        LEFT JOIN vrCore_Product ON vrCore_Product.iMasterId = tCore_Indta{0}.iProduct AND vrCore_Product.iTreeId = 0\r\n                        {2}", Suffix, text2, text4, objRec.StartingDate, objRec.EndingDate, (iLinkPathId > 0) ? $" AND tCore_Links{Suffix}.iLinkId = {iLinkPathId} " : "", (m_iLinkCount > 0) ? "tCore_LinksFinalBase" : "tCore_Links");
			}
			break;
		}
		case FocusReport.BestSellingItems:
			num2 = FConvert.GetInputValue(objRec.Inputs, 1);
			num2 = ((num2 >= 0) ? num2 : 0);
			text = $"SELECT TOP {num2} vrCore_Product.iMasterId, vrCore_Product.sName,\r\n                    SUM(CASE WHEN tCore_Indta{Suffix}.fQuantityInBase < 0 OR tCore_Header{Suffix}.iVoucherClass = {1792} THEN tCore_Indta{Suffix}.fQuantityInBase ELSE 0 END) [Balance Quantity] ,sum(mAmount2)\r\n                    FROM tCore_Header{Suffix}\r\n                    JOIN tCore_Data{Suffix} ON tCore_Header{Suffix}.iHeaderId = tCore_Data{Suffix}.iHeaderId\r\n                    JOIN tCore_Indta{Suffix} ON tCore_Indta{Suffix}.iBodyId = tCore_Data{Suffix}.iBodyId \r\n                    JOIN vrCore_Product ON vrCore_Product.iMasterId = tCore_Indta{Suffix}.iProduct AND vrCore_Product.iTreeId = 0\r\n                    JOIN cCore_Vouchers{Suffix} WITH (READUNCOMMITTED) ON cCore_Vouchers{Suffix}.iVoucherType = tCore_Header{Suffix}.iVoucherType  \r\n                    ";
			break;
		case FocusReport.StockTransferSummary:
			text3 = "''";
			if (FConvert.GetInputValue(objRec.Inputs, 3) == 1)
			{
				text3 = "sAbbr + ':' + sVoucherNo";
			}
			num2 = FConvert.GetInputValue(objRec.Inputs, 1);
			text4 = ((num2 <= 0) ? (",CASE WHEN tCore_Indta" + Suffix + ".fQuantityInBase < 0 THEN " + text7 + ".sName ELSE null END[From Warehouse]") : $",CASE WHEN tCore_Indta{Suffix}.fQuantityInBase < 0 AND tCore_Data{Suffix}.iInvTag = {num2} THEN {text7}.sName ELSE null END[From Warehouse]");
			array2 = GetWarehouseList(m_iCompId);
			num2 = FConvert.GetInputValue(objRec.Inputs, 2);
			for (num = 0; num < array2.Length && num < 255; num++)
			{
				if (num2 <= 0)
				{
					text4 += $",CASE WHEN tCore_Indta{Suffix}.fQuantityInBase > 0 and tCore_Data{Suffix}.iInvTag = {array2[num].ID} THEN tCore_Indta{Suffix}.fQuantityInBase ELSE 0 END[To {array2[num].Name}]";
				}
				else
				{
					text4 = ((num2 != array2[num].ID) ? (text4 + ",0[To " + array2[num].Name + "]") : (text4 + $",CASE WHEN tCore_Indta{Suffix}.fQuantityInBase > 0 and tCore_Data{Suffix}.iInvTag = {array2[num].ID} THEN tCore_Indta{Suffix}.fQuantityInBase ELSE 0 END[To {array2[num].Name}]"));
				}
				text2 = text2 + ",SUM([To " + array2[num].Name + "])[To " + array2[num].Name + "]";
			}
			text = $"SELECT vrCore_Product.iMasterId,vrCore_Product.iMasterId,Temp.iDate,Temp.[sVoucherNo],MAX([From Warehouse])[From Warehouse]{text2}\r\n                    FROM\r\n                    (\r\n\t                    SELECT DISTINCT tCore_Data{Suffix}.iBodyId,tCore_Header{Suffix}.iDate,{text3}[sVoucherNo]\r\n                        {text4}\r\n\t                    FROM tCore_Header{Suffix}\r\n\t                    JOIN tCore_Data{Suffix} ON tCore_Header{Suffix}.iHeaderId = tCore_Data{Suffix}.iHeaderId\r\n\t                    JOIN tCore_Indta{Suffix} ON tCore_Indta{Suffix}.iBodyId = tCore_Data{Suffix}.iBodyId\r\n\t                    JOIN cCore_Vouchers{Suffix} WITH (READUNCOMMITTED) ON cCore_Vouchers{Suffix}.iVoucherType=tCore_Header{Suffix}.iVoucherType \r\n\t                    JOIN vrCore_Product ON tCore_Indta{Suffix}.iProduct = vrCore_Product.iMasterId AND vrCore_Product.iTreeId = 0\r\n\t                    JOIN {text7} ON {text7}.iMasterId = tCore_Data{Suffix}.iInvTag\r\n\t                    WHERE tCore_Header{Suffix}.bUpdateStocks = 1 AND tCore_Data{Suffix}.bSuspendUpdateStocks <> 1 \r\n\t                    AND tCore_Data{Suffix}.iAuthStatus < 2 AND tCore_Header{Suffix}.bSuspended = 0 \r\n\t                    AND tCore_Header{Suffix}.iDate BETWEEN {objRec.StartingDate} AND {objRec.EndingDate} AND cCore_Vouchers{Suffix}.bInventory  = 1\r\n\t                    AND tCore_Header{Suffix}.iVoucherClass = {3072}\r\n                    )Temp\r\n                    JOIN tCore_Data{Suffix} ON Temp.iBodyId = tCore_Data{Suffix}.iBodyId \r\n                    JOIN tCore_Header{Suffix} ON tCore_Header{Suffix}.iHeaderId = tCore_Data{Suffix}.iHeaderId\r\n                    JOIN tCore_Indta{Suffix} ON tCore_Indta{Suffix}.iBodyId = tCore_Data{Suffix}.iBodyId\r\n                    JOIN @XML.nodes('/Master/r') T(c) ON tCore_Indta{Suffix}.iProduct = T.c.value('./@id', 'int') \r\n                    JOIN vrCore_Product ON tCore_Indta{Suffix}.iProduct = vrCore_Product.iMasterId AND vrCore_Product.iTreeId = 0";
			if (!string.IsNullOrEmpty(_focus.company(m_iCompId).invTagName))
			{
				text = text + " LEFT JOIN " + _focus.company(m_iCompId).invTagName + " ON " + _focus.company(m_iCompId).invTagName + ".iMasterId = tCore_Data" + Suffix + ".iInvTag AND " + _focus.company(m_iCompId).invTagName + ".iTreeId = 0";
			}
			break;
		case FocusReport.StockReservationReport:
			text = string.Format("SELECT tCore_Data{0}.iBodyId,tCore_Header{0}.iDate,cCore_Vouchers{0}.sName, tCore_Header{0}.sVoucherNo,vrCore_Product.sName\r\n                    ,(CASE WHEN bReserveOrRelease = 0 THEN -tCore_ReservedStock{0}.fQuantity ELSE 0 END) + (CASE WHEN bReserveOrRelease = 1 THEN tCore_ReservedStock{0}.fQuantity ELSE 0 END)[Reserved Qty] \r\n                    ,tCore_Indta{0}.mRate\r\n                    ,CASE WHEN tCore_Indta{0}.fQuantityInBase < 0 THEN BookNo.sName ELSE Code.sName END[Customer],tCore_Indta{0}.iProduct\r\n                    FROM tCore_Header{0} \r\n                    JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n                    JOIN tCore_ReservedStock{0} ON tCore_Data{0}.iTransactionId = tCore_ReservedStock{0}.iTransactionId\r\n                    JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId\r\n                    JOIN @XML.nodes('/Master/r') T(c) ON tCore_Indta{0}.iProduct = T.c.value('./@id', 'int') \r\n                    JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iVoucherType = cCore_Vouchers{0}.iVoucherType\r\n                    JOIN vrCore_Product ON vrCore_Product.iMasterId = tCore_Indta{0}.iProduct AND vrCore_Product.iTreeId = 0\r\n                    JOIN vrCore_Account BookNo ON BookNo.iMasterId = tCore_Data{0}.iBookNo AND BookNo.iTreeId = 0\r\n                    JOIN vrCore_Account Code ON Code.iMasterId = tCore_Data{0}.iCode AND Code.iTreeId = 0 ", Suffix);
			text += JoinItemTree(objRec.ReportId, objRec.Inputs);
			break;
		case FocusReport.TransactionWiseStockReport:
			array = GetVouchers(bInventoryType: true);
			text = "SELECT vrCore_Product.iMasterId[iProduct],vrCore_Product.sName[Product]";
			for (num = 0; num < array.Length; num++)
			{
				text += string.Format(",CASE WHEN tCore_Header{0}.iVoucherType = {1} THEN SUM(fQuantityInBase) ELSE 0 END[{2} Qty]\r\n                        ,CASE WHEN tCore_Header{0}.iVoucherType = {1} THEN SUM(mStockValue) ELSE 0 END[{2} Value]", Suffix, array[num].ID, array[num].Name);
			}
			text += string.Format(" FROM tCore_Header{0} \r\n                            JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n                            JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId\r\n                            JOIN @XML.nodes('/Master/r') T(c) ON tCore_Indta{0}.iProduct = T.c.value('./@id', 'int') \r\n                            JOIN vrCore_Product ON vrCore_Product.iMasterId = tCore_Indta{0}.iProduct AND vrCore_Product.iTreeId = 0\r\n                            JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType = tCore_Header{0}.iVoucherType ", Suffix);
			break;
		case FocusReport.ActualConsumptionReport:
			text = string.Format("SELECT vrCore_Product.iMasterId[iProduct],vrCore_Product.sName[Product]\r\n                    ,CASE WHEN tCore_Header{0}.iVoucherClass = 512 THEN SUM(fQuantityInBase) ELSE 0 END[Opening Qty]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherClass = 512 THEN SUM(mStockValue) ELSE 0 END[Opening Value]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherClass = 1280 THEN SUM(fQuantityInBase) ELSE 0 END[MRN Qty]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherClass = 1280 THEN SUM(mStockValue) ELSE 0 END[MRN Value]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherClass = 768 THEN SUM(fQuantityInBase) ELSE 0 END[Purchase Qty]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherClass = 768 THEN SUM(mStockValue) ELSE 0 END[Purchase Value]\r\n                    ,CASE WHEN tCore_Header{0}.iVoucherClass = 9216 THEN SUM(fQuantityInBase) ELSE 0 END[RTS Qty]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherClass = 9216 THEN SUM(mStockValue) ELSE 0 END[RTS Value]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherClass = 2048 THEN SUM(fQuantityInBase) ELSE 0 END[Transfer in Qty]\r\n                    ,CASE WHEN tCore_Header{0}.iVoucherClass = 2048 THEN SUM(mStockValue) ELSE 0 END[Transfer in Value]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherClass = 1792 THEN SUM(fQuantityInBase) ELSE 0 END[Sales Return Qty]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherClass = 1792 THEN SUM(mStockValue) ELSE 0 END[Sales Return Value]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherType = 5380 THEN -SUM(fQuantityInBase) ELSE 0 END[Transfer out Qty]\r\n                    ,CASE WHEN tCore_Header{0}.iVoucherType = 5380 THEN SUM(mStockValue) ELSE 0 END[Transfer out Value]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherClass = 3328 THEN -SUM(fQuantityInBase) ELSE 0 END[Sales Qty]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherClass = 3328 THEN SUM(mStockValue) ELSE 0 END[Sales Value]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherType = 5378 THEN SUM(fQuantityInBase) ELSE 0 END[Wastage Qty]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherType = 5378 THEN SUM(mStockValue) ELSE 0 END[Wastage Value]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherClass = 6400 THEN -SUM(fQuantityInBase) ELSE 0 END[Purchase Return Qty]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherClass = 6400 THEN SUM(mStockValue) ELSE 0 END[Purchase Return Value]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherType = 7938 THEN SUM(fQuantityInBase) ELSE 0 END[Closing Qty]\r\n\t                ,CASE WHEN tCore_Header{0}.iVoucherType = 7938 THEN SUM(mStockValue) ELSE 0 END[Closing Value]\r\n\t                FROM tCore_Header{0} \r\n\t                JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n\t                JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId\r\n                    JOIN @XML.nodes('/Master/r') T(c) ON tCore_Indta{0}.iProduct = T.c.value('./@id', 'int') \r\n\t                JOIN vrCore_Product ON vrCore_Product.iMasterId = tCore_Indta{0}.iProduct AND vrCore_Product.iTreeId = 0\r\n\t                JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON cCore_Vouchers{0}.iVoucherType = tCore_Header{0}.iVoucherType", Suffix);
			break;
		case FocusReport.GLAndInvMismatchReport:
			text = "SELECT 0[iBodyId]";
			break;
		}
		return text;
	}

	private IdNamePair[] GetWarehouseList(int iCompanyId)
	{
		string text = null;
		string text2 = null;
		IDataReader dataReader = null;
		List<IdNamePair> list = null;
		list = new List<IdNamePair>();
		text2 = _focus.company(iCompanyId).invTagName;
		if (!string.IsNullOrEmpty(text2))
		{
			text = $"SELECT iMasterId,sName,bGroup FROM {text2} WHERE iMasterId>0 and iStatus<>5 ORDER BY iMasterId";
			dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			while (dataReader.Read())
			{
				list.Add(new IdNamePair(Convert.ToInt32(dataReader["iMasterId"]), Convert.ToString(dataReader["sName"]), Convert.ToBoolean(dataReader["bGroup"])));
			}
			dataReader.Close();
			List<int> list2 = new List<int>();
			for (int i = 0; i < list.Count; i++)
			{
				if (Convert.ToBoolean(list[i].Tag))
				{
					list2.Clear();
					text = string.Format("WITH RecursionCTE (iMasterId, iParentId, bGroup)  AS  \r\n                        (   SELECT iMasterId, iParentId, bGroup\r\n                            FROM {0} \r\n                            WHERE iMasterId = {1} AND iTreeId = 0\r\n                            UNION ALL  \r\n                            SELECT R1.iMasterId, R1.iParentId, R1.bGroup\r\n                            FROM {0} AS R1\r\n                            JOIN RecursionCTE AS R2 ON R1.iParentId = R2.iMasterId\r\n                        )SELECT iMasterId  FROM RecursionCTE WHERE bGroup = 0", text2, list[i].ID);
					dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
					while (dataReader.Read())
					{
						list2.Add(Convert.ToInt32(dataReader["iMasterId"]));
					}
					dataReader.Close();
					list[i].Tag = list2.ToArray();
				}
				else
				{
					list[i].Tag = null;
				}
			}
		}
		return list.ToArray();
	}

	private List<int> GetWorkflowLinks(RepRecord oRec, ref int iLinkPathId, Database objDb)
	{
		string strErrorMessage = null;
		List<int> list = new List<int>();
		int inputValue = FConvert.GetInputValue(oRec.Inputs, 2);
		int inputValue2 = FConvert.GetInputValue(oRec.Inputs, 6);
		LinkChain[] linkChainAnalysisFlows = new WorkFlow().GetLinkChainAnalysisFlows(oRec.Code, ref strErrorMessage, m_iCompId);
		if (linkChainAnalysisFlows != null)
		{
			for (int i = 0; i < linkChainAnalysisFlows.Length; i++)
			{
				if (linkChainAnalysisFlows[i].Sequence != inputValue2)
				{
					continue;
				}
				for (int j = ((inputValue >= 0) ? inputValue : 0); j < linkChainAnalysisFlows[i].Flows.Length; j++)
				{
					if (iLinkPathId <= 0)
					{
						iLinkPathId = (linkChainAnalysisFlows[i].Flows[j].ToFrom * 65536) | linkChainAnalysisFlows[i].Flows[j].ToLink;
					}
					list.Add((linkChainAnalysisFlows[i].Flows[j].ToFrom * 65536) | linkChainAnalysisFlows[i].Flows[j].ToLink);
				}
				break;
			}
		}
		return list;
	}

	private string ExcludeVouchersFromAgeing(_Filter[] arrFilter)
	{
		List<int> list = new List<int>();
		list.AddRange(_focus.company(m_iCompId).getPreferenceValues(PreferenceCategories.Inventory, 100, 110));
		if (list.Count == 0)
		{
			return $" AND tCore_Header{Suffix}.iVoucherClass <> {3072}";
		}
		if (list.Count > 0)
		{
			return string.Format(" AND tCore_Header{0}.iVoucherType NOT IN({1})", Suffix, string.Join(",", list.Select((int p) =>
			{
				int num = p;
				return num.ToString();
			})));
		}
		return string.Empty;
	}

	private string GetDontoclubLinks(string sLinkPathId, int iCompanyId)
	{
		List<string> list = new List<string>();
		string text = string.Format("select distinct iLinkPathId from \r\n            mCore_LinkPath{0} a  with (ReadUncommitted) \r\n            join mCore_LinkNodes{0} b  with (ReadUncommitted) on a.iFromLinkId = b.iLinkId\r\n            where b.iVoucherType in \r\n            (\r\n\t            select iVoucherType from  mCore_LinkNodes{0} n with (ReadUncommitted) \r\n\t            join mCore_LinkPath{0} p  with (ReadUncommitted) on p.iFromLinkId = n.iLinkId\r\n\t            where iLinkPathId IN ({1}) AND bDoNotClubCommonBase=0\r\n            )", Suffix, sLinkPathId);
		IDataReader dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		while (dataReader.Read())
		{
			list.Add(Convert.ToString(dataReader[0]));
		}
		dataReader.Close();
		if (list.Count == 0)
		{
			list.Add(sLinkPathId);
		}
		return string.Join(",", list);
	}

	private void GetVouchersFromLinkId(int iLinkPathId, int iCompanyId, ref int iBaseVoucher, ref int iLinkVoucher)
	{
		string suffix = FConvert.GetSuffix(iCompanyId);
		string text = string.Format("select b.iVoucherType[Base], c.iVoucherType[Link] from mCore_LinkPath{0} a  with (ReadUncommitted) \r\njoin mCore_LinkNodes{0} b  with (ReadUncommitted) on a.iFromLinkId = b.iLinkId\r\njoin mCore_LinkNodes{0} c  with (ReadUncommitted) on a.iToLinkId = c.iLinkId\r\nwhere a.iLinkPathId = {1}", suffix, iLinkPathId);
		IDataReader dataReader = m_objDatabase.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
		if (dataReader.Read())
		{
			iBaseVoucher = Convert.ToInt32(dataReader[0]);
			iLinkVoucher = Convert.ToInt32(dataReader[1]);
		}
		dataReader.Close();
	}

	private string getPendingView(Database objDb, bool bTagWise, string sSuffix)
	{
		string text = null;
		string text2 = null;
		string text3 = null;
		string text4 = "@ORDERED";
		bool flag = false;
		try
		{
