	private string JoinItemTree(uint ReportId, IdValuePair[] arrInputs)
	{
		string sortingOnItem = General.GetSortingOnItem(ReportId, arrInputs);
		if (sortingOnItem != null && sortingOnItem.Contains("ATree.iSeq"))
		{
			return " JOIN dbo.fCore_GetProductTreeSequenceByLangId(0, 0, 0) ATree ON ATree.iMasterId = vrCore_Product.iMasterId";
