	public string GetMasterQuery(RepRecord objRec, ref string strViewName, ref StandardQuery oQuery)
	{
		DbCommand dbCommand = null;
		int languageId = objRec.LanguageId;
		string strJoinQuery = string.Empty;
		string text = string.Empty;
		string text2 = string.Empty;
		string text3 = string.Empty;
		string[] array = null;
		IDataReader dataReader = null;
		FieldData[] array2 = null;
		GlobalReport globalReport = new GlobalReport();
		FieldData[] arrFilterFields = null;
		m_strExtraColumns = (m_strExtraColumnsAlias = string.Empty);
		try
		{
			if (m_objDatabase == null)
			{
				m_objDatabase = DatabaseWrapper.GetDatabase2(m_iCompId);
			}
			text = $"SELECT sModule, sMasterName \r\n                FROM cCore_MasterDef WITH (ReadUnCommitted) WHERE iMasterTypeId={objRec.Code}";
			dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dataReader = m_objDatabase.ExecuteReader(dbCommand);
			if (dataReader.Read())
			{
				text3 = Convert.ToString(dataReader[0]);
				text2 = Convert.ToString(dataReader[1]);
				strViewName = $"vr{dataReader[0]}_{dataReader[1]}";
			}
			dataReader.Close();
			array2 = GetExtraFields(ref objRec, ref arrFilterFields, m_objDatabase);
			oQuery = globalReport.vFirstLine(objRec, bPreviousYear: false, ref m_arrDefualtTables, m_iCompId);
			if (!string.IsNullOrEmpty(strViewName))
			{
				m_arrDefualtTables.AddRange(new string[3]
				{
					strViewName,
					"m" + strViewName.Substring(2) + "Language",
					"acc"
				});
			}
			array = JoinQuery(objRec, array2, arrFilterFields, ref strJoinQuery, m_objDatabase, m_iYearId > 0);
			if (oQuery != null)
			{
				oQuery.Query = ReplaceGlobalValues(objRec, oQuery.Query, array, null, strJoinQuery, m_iCompId);
			}
			else
			{
				m_strExtraColumns = GetColumnsName(array2, array, ref m_strExtraColumnsAlias);
				text = GetDefaultMasterQuery(objRec, strViewName, m_strExtraColumnsAlias, strJoinQuery, languageId);
				if (!NonMaster(objRec.ReportId))
				{
					text = text + " JOIN dbo.f" + text3 + "_Get" + text2 + "TreeSequence(0,0) acc ON acc.iMasterId = " + strViewName + ".iMasterId ";
				}
				text += GetMasterFilter(objRec, strViewName, languageId);
				text += GroupOrOrderBy(objRec, m_strExtraColumns, m_objDatabase);
				text = AppendSubQuery(objRec, text, m_strExtraColumns, m_strExtraColumnsAlias, array2, m_objDatabase);
				objRec.ExtraColumns = General.GetAllColumns(objRec.Columns, array2);
			}
		}
		catch (Exception ex)
		{
			text = ex.Message;
			text = string.Empty;
		}
		finally
		{
			if (dbCommand != null && dbCommand.Connection != null && dbCommand.Connection.State != ConnectionState.Closed)
			{
				dbCommand.Connection.Close();
			}
		}
		return text;
	}

	public bool IsClosedCompanyReport(RepRecord objRec)
	{
		if (objRec.Module != Module.None || (objRec.SubReportId != 2 && objRec.SubReportId != 3 && objRec.SubReportId != 5))
		{
			if (objRec.Module == Module.Inventory)
			{
				if (objRec.ReportId != 657)
				{
					return objRec.ReportId == 581;
				}
				return true;
			}
			return false;
		}
		return true;
	}

	private bool NonMaster(uint iReportId)
	{
		switch ((FocusReport)iReportId)
		{
		case FocusReport.MasterAuthorizationReport:
		case FocusReport.AuditMasters:
		case FocusReport.AuditPricebook:
		case FocusReport.AuthorizationMatrix:
		case FocusReport.AuditTrailAuthorization:
		case FocusReport.FormReport:
		case FocusReport.PricebookAuthorizationReport:
		case FocusReport.MembershipRecruitment:
		case FocusReport.MembershipRecruitmentByDate:
		case FocusReport.MemberPoints:
		case FocusReport.MemberPointsExpiry:
		case FocusReport.MemberMaximumPoints:
		case FocusReport.MemberMinimumPoints:
		case FocusReport.POSMemberBalance:
			return true;
		default:
			return false;
		}
	}

