	private string GetColumnsName(FieldData[] arrFields, string[] arrColumnName, ref string strColumnAlias)
	{
		string text = string.Empty;
		string text2 = null;
		for (int i = 0; i < arrFields.Length; i++)
		{
			text2 = ((i < arrColumnName.Length) ? arrColumnName[i] : arrFields[i].FieldName);
			if (!string.IsNullOrEmpty(text2))
			{
				if (text2 == arrFields[i].FieldName)
				{
					strColumnAlias += $",{arrFields[i].FieldName}[Field{i}]";
					text += $",{arrFields[i].FieldName}";
				}
				else
				{
					strColumnAlias += $",{text2}[Field{i}]";
					text += $",{text2}";
				}
			}
			else
			{
				strColumnAlias += string.Format(",0[Field{1}]", text2, i);
				text += string.Format(",''", text2);
			}
		}
		return text;
	}

	private string GetMasterFilter(RepRecord objRec, string strMaster, int iLanguageId)
	{
		string text = string.Empty;
		int num = 0;
		if (objRec.ReportId != 734 && objRec.ReportId != 8532 && objRec.ReportId != 736 && objRec.ReportId != 742 && objRec.ReportId != 743 && objRec.ReportId != 711 && objRec.ReportId != 754 && objRec.ReportId != 757)
		{
			text = $" WHERE {strMaster}.iTreeId = 0 AND iLanguageId = {iLanguageId}";
		}
		if (objRec.Module == Module.CoreMasters)
		{
			switch ((FocusReport)objRec.ReportId)
			{
			case FocusReport.MemberPoints:
				text = $" WHERE vrPos_Member.iTreeId = 0 AND iLanguageId = {iLanguageId} AND dbo.DateToInt(dbo.fCore_IntToDateTime(vPos_MemberPoints.iCreatedDate)) BETWEEN {objRec.StartingDate} AND {objRec.EndingDate} ";
				if (objRec.Masters != null && !objRec.IsSelectAll)
				{
					text += $" AND vrPos_Member.iMasterId IN ({General.GetMasters(objRec.Masters)})";
				}
				break;
			case FocusReport.POSMemberBalance:
				text = $" WHERE vrPos_Member.iTreeId = 0 AND iLanguageId = {iLanguageId}";
				if (objRec.Masters != null && !objRec.IsSelectAll)
				{
					text += $" AND vrPos_Member.iMasterId IN ({General.GetMasters(objRec.Masters)})";
				}
				break;
			case FocusReport.MemberBirthdayReport:
				if (objRec.Masters != null)
				{
					text += $" AND mPos_Outlet.iMasterId IN ({General.GetMasters(objRec.Masters)})";
				}
				num = FConvert.GetInputValue(objRec.Inputs, 1);
				text += string.Format(" AND (vrPos_Member.iDOB & 0xff00)/256 = {1} ", strMaster, num + 1);
