			case FocusReport.MasterAuthorizationReport:
			{
				text = string.Format(" where dbo.DateToInt(dbo.fCore_IntToDateTime(M.iCreatedDate)) BETWEEN {1} AND {2} AND M.iStatus<>5 and  A.iMasterTypeId={4}  ", Suffix, objRec.StartingDate, objRec.EndingDate, 4, objRec.Code);
				int inputValue = FConvert.GetInputValue(objRec.Inputs, 0);
				if (inputValue != 5)
				{
					text += string.Format(" AND U.iStatus in({1} {2})", Suffix, inputValue switch
					{
						3 => 3, 
						2 => 2, 
						1 => 1, 
						0 => 0, 
						_ => 5, 
					}, (inputValue == 4) ? ",7" : string.Empty);
				}
				break;
			}
			}
		}
		else
		{
			switch ((FocusReport)objRec.ReportId)
			{
			case FocusReport.FixedAssetRegister:
				text = $" WHERE vrFixA_FixedAsset.iPurchaseDate BETWEEN {objRec.StartingDate} AND {objRec.EndingDate} AND vrFixA_FixedAsset.iMasterId > 0 AND vrFixA_FixedAsset.iTreeId = 0";
				break;
			case FocusReport.ConsumptionRegister:
			case FocusReport.ProductionRegister:
			case FocusReport.ProductionSummary:
			case FocusReport.ConsumptionSummary:
				text = " And " + strMaster + ".iTreeId = 0 ";
				if (objRec.Masters != null && objRec.Masters != null && objRec.Masters != null && !objRec.IsSelectAll)
				{
					text += $" AND {strMaster}.iMasterId IN ({General.GetMasters(objRec.Masters)})";
				}
				break;
			case FocusReport.NegitiveBatchList:
				text = "";
				if (objRec.Masters != null && objRec.Masters != null && objRec.Masters != null)
				{
					text += $" AND iProduct IN ({General.GetMasters(objRec.Masters)})";
				}
				break;
			case FocusReport.BOMListReport:
				text = "";
				if (objRec.Masters != null && objRec.Masters != null && objRec.Masters != null)
				{
					text += $" AND Product.iMasterId IN ({General.GetMasters(objRec.Masters)})";
				}
				break;
			case FocusReport.BOMRoutingStatusReport:
				text = "";
				if (objRec.Masters != null && objRec.Masters != null && objRec.Masters != null)
				{
					text += $" and Product.MasterId IN ({General.GetMasters(objRec.Masters)})";
				}
				break;
			}
		}
		if (objRec.ReportId == 711 || objRec.ReportId == 757)
		{
			return text;
		}
		return text + ((objRec.ReportId == 734 || objRec.ReportId == 736 || objRec.ReportId == 742 || objRec.ReportId == 743 || objRec.ReportId == 754) ? "" : filter_string(objRec.FilterSource, m_objDatabase, m_iCompId, bCubeReport: false, objRec.ReportId, objRec.Module));
	}

	private string DefaultPOSQuery(RepRecord objRec, Database objDb)
	{
		int num = 0;
		IdNamePair[] array = null;
		string text = string.Empty;
		string text2 = string.Empty;
		string empty = string.Empty;
		empty = "select Case when  CHARINDEX('2019',@@version) > 0 Then '2019' When CHARINDEX('2017',@@version) > 0 Then '2017' Else '2014' End  as version";
		int num2 = Convert.ToInt32(objDb.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty));
		empty = string.Empty;
		switch ((FocusReport)objRec.ReportId)
