			break;
		case FocusReport.PaymentWiseSales:
			if (FConvert.GetInputValue(objRec.Inputs, 1) > 0 && FConvert.GetInputValue(objRec.Inputs, 2) > 0)
			{
				text = $" AND iModifiedTime BETWEEN {FConvert.GetInputValue(objRec.Inputs, 1)} AND {FConvert.GetInputValue(objRec.Inputs, 2)}";
			}
			if (FConvert.GetInputValue(objRec.Inputs, 3) == 1)
			{
				text2 = string.Format(" OR tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSR)", Suffix, 4096);
			}
			empty = string.Format("Declare @PosSales varchar(10) = '', @PosSO varchar(10) = '', @PosSR varchar(10) = ''\r\n                    select @PosSales = sAbbr + '%' from cCore_Vouchers{0} where iVoucherType = 3331\r\n                    select @PosSO = sAbbr + '%' from cCore_Vouchers{0} where iVoucherType = 5632\r\n                    select @PosSR = sAbbr + '%' from cCore_Vouchers{0} where iVoucherType = 1792\r\n                    SELECT tCore_Header{0}.iDate[iDate],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSales) {5} THEN CASE WHEN iPaymentType=1 THEN mAmount2 ELSE CASE WHEN iPaymentType = 9 THEN -mAmount2 ELSE 0 END END ELSE 0 END[Cash Amount],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSO) {5} THEN CASE WHEN iPaymentType=1 THEN mAmount2 ELSE 0 END ELSE 0 END[P_Cash Amount],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSales) {5} THEN CASE WHEN iPaymentType=2 THEN mAmount2 ELSE 0 END ELSE 0 END[Credit Card Amount],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSO) {5} THEN CASE WHEN iPaymentType=2 THEN mAmount2 ELSE 0 END ELSE 0 END[P_Credit Card Amount],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSales) {5} THEN CASE WHEN iPaymentType=3 THEN mAmount2 ELSE 0 END ELSE 0 END[Debit Card Amount],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSO) {5} THEN CASE WHEN iPaymentType=3 THEN mAmount2 ELSE 0 END ELSE 0 END[P_Debit Card Amount],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSales) {5} THEN CASE WHEN iPaymentType=4 THEN mAmount2 ELSE 0 END ELSE 0 END[Cheque Value],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSO) {5} THEN CASE WHEN iPaymentType=4 THEN mAmount2 ELSE 0 END ELSE 0 END[P_Cheque Value],\r\n                    0[GV1],0[GV2],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSO) {5} THEN CASE WHEN iPaymentType=5 THEN mAmount2 ELSE 0 END ELSE 0 END[Coupon Amount],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSO) {5} THEN CASE WHEN iPaymentType=5 THEN mAmount2 ELSE 0 END ELSE 0 END[P_Coupon Amount],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSales) {5} THEN CASE WHEN iPaymentType=7 THEN mAmount2 ELSE 0 END ELSE 0 END[Points Redemption],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSO) {5} THEN CASE WHEN iPaymentType=7 THEN mAmount2 ELSE 0 END ELSE 0 END[P_Points Redemption],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSales) {5} THEN CASE WHEN iPaymentType=6 THEN mAmount2 ELSE 0 END ELSE 0 END[Credit Notes],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSO) {5} THEN CASE WHEN iPaymentType=6 THEN mAmount2 ELSE 0 END ELSE 0 END[P_Credit Notes],\r\n                    0[DV1],0[DV2],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSales) {5} THEN CASE WHEN iPaymentType=8 THEN mAmount2 ELSE 0 END ELSE 0 END[Discount Coupon],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSO) {5} THEN CASE WHEN iPaymentType=8 THEN mAmount2 ELSE 0 END ELSE 0 END[P_Discount Coupon],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSales) {5} THEN CASE WHEN iPaymentType=10 THEN fCreditSaleAmount ELSE 0 END ELSE 0 END[Credit sales],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSO) {5} THEN CASE WHEN iPaymentType=10 THEN fCreditSaleAmount ELSE 0 END ELSE 0 END[P_Credit sales],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSales) {5} THEN CASE WHEN iPaymentType=11 THEN mAmount2 ELSE 0 END ELSE 0 END[Credit charges],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSO) {5} THEN CASE WHEN iPaymentType=11 THEN mAmount2 ELSE 0 END ELSE 0 END[P_Credit charges],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSales) {5} THEN CASE WHEN iPaymentType=12 THEN mAmount2 ELSE 0 END ELSE 0 END[Debit charges],\r\n                    CASE WHEN tCore_HeaderData{1}{0}.sBillReferenceNo LIKE (@PosSO) {5} THEN CASE WHEN iPaymentType=12 THEN mAmount2 ELSE 0 END ELSE 0 END[P_Debit charges],\r\n                    CASE WHEN tCore_HeaderData4096{0}.sBillReferenceNo LIKE (@PosSales)  OR tCore_HeaderData4096{0}.sBillReferenceNo LIKE (@PosSR) THEN CASE WHEN iPaymentType=14 THEN mAmount2 ELSE 0 END ELSE 0 END[EPayment Type],\r\n                    CASE WHEN tCore_HeaderData4096{0}.sBillReferenceNo LIKE (@PosSO)  OR tCore_HeaderData4096{0}.sBillReferenceNo LIKE (@PosSR) THEN CASE WHEN iPaymentType=14 THEN mAmount2 ELSE 0 END ELSE 0 END[P_EPayment Type],\r\n                    tCore_Data{0}.iInvTag[OutletId]\r\n                    FROM tCore_Header{0} \r\n                    JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n                    JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iVoucherType = cCore_Vouchers{0}.iVoucherType\r\n                    JOIN tCore_HeaderData{1}{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n                    JOIN tCore_Data{1}{0} WITH (READUNCOMMITTED) ON tCore_Data{0}.iBodyId = tCore_Data{1}{0}.iBodyId\r\n                    WHERE tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA <> 1 \r\n                    AND tCore_Header{0}.bSuspended = 0 \r\n                    AND tCore_Header{0}.iDate BETWEEN {2} AND {3}\r\n                    UNION ALL\r\n                    SELECT tCore_Header{0}.iDate[iDate],\r\n                    CASE WHEN iPaymentType= 9 OR iPaymentType= 16 THEN mAmount2 ELSE 0 END ELSE 0 END [Cash Amount], 0 [P_Cash Amount],\r\n                    CASE WHEN iPaymentType= 2 THEN mAmount2 ELSE 0 END ELSE 0 END [Credit Card Amount], 0 [P_Credit Card Amount],\r\n                    CASE WHEN iPaymentType= 3 THEN mAmount2 ELSE 0 END ELSE 0 END [Debit Card Amount], 0 [P_Debit Card Amount],\r\n                    0[Cheque Value],0[P_Cheque Value],\r\n                    CASE WHEN iPaymentType= 5 OR iPaymentType= 17 THEN mAmount2 ELSE 0 END ELSE 0 END [GV1],0[GV2],\r\n                    0[Coupon Amount],0[P_Coupon Amount],0[Points Redemption],0[P_Points Redemption],\r\n                    CASE WHEN iPaymentType= 6 OR iPaymentType= 18 THEN mAmount2 ELSE 0 END ELSE 0 END [Credit Notes],0[P_Credit Notes],\r\n                    0[DV1],0[DV2],\r\n                    0[Discount Coupon],0[P_Discount Coupon],0[Credit sales],0[P_Credit sales],0[Credit charges],0[P_Credit charges],0[Debit charges],0[P_Debit charges],\r\n                    CASE WHEN iPaymentType= 14 THEN mAmount2 ELSE 0 END ELSE 0 END [EPayment Type],0 [P_EPayment Type],\r\n                    tCore_Data{0}.iInvTag[OutletId]\r\n                    FROM tCore_Header{0} \r\n                    JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n                    JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iVoucherType = cCore_Vouchers{0}.iVoucherType\r\n                    JOIN tCore_HeaderData{6}{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iHeaderId = tCore_HeaderData{6}{0}.iHeaderId\r\n                    JOIN tCore_Data{6}{0} WITH (READUNCOMMITTED) ON tCore_Data{0}.iBodyId = tCore_Data{6}{0}.iBodyId\r\n                    WHERE tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA <> 1 \r\n                    AND tCore_Header{0}.bSuspended = 0 \r\n                    AND tCore_Header{0}.iDate BETWEEN {2} AND {3}\r\n                    UNION ALL\r\n                    SELECT\r\n                    tCore_Header{0}.iDate[iDate],0[Cash Amount],0[P_Cash Amount],0[Credit Card Amount],0[P_Credit Card Amount],0[Debit Card Amount],\r\n                    0[P_Debit Card Amount],0[Cheque Value],0[P_Cheque Value],\r\n                    sum(fGVInternal)[GV1],SUM(fGVExternal)[GV2],\r\n                    0[Coupon Amount],0[P_Coupon Amount],0[Points Redemption],0[P_Points Redemption],0[Credit Notes],0[P_Credit Notes],\r\n                    SUM(fDVInternal)[DV1],SUM(fDVExternal)[DV2],\r\n                    0[Discount Coupon],0[P_Discount Coupon],0[Credit sales],0[P_Credit sales],0[Credit charges],0[P_Credit charges],0[Debit charges],0[P_Debit charges],\r\n                    0 [EPayment Type],0 [P_EPayment Type],tCore_Data{0}.iInvTag[OutletId]\r\n                    FROM tCore_Header{0} \r\n                    JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n                    JOIN cCore_Vouchers{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iVoucherType = cCore_Vouchers{0}.iVoucherType\r\n                    LEFT JOIN vPos_GVDVValues WITH (READUNCOMMITTED) ON vPos_GVDVValues.iHeaderId  = tCore_Header{0}.iHeaderId \r\n                    WHERE tCore_Data{0}.bUpdateFA = 1 AND tCore_Data{0}.bSuspendUpdateFA <> 1 \r\n                    AND tCore_Header{0}.bSuspended = 0 \r\n                    AND tCore_Header{0}.iDate BETWEEN {2} AND {3} {4}\r\n                    AND (fGVInternal <> 0 or fGVExternal<>0 or fDVInternal <> 0 or fDVExternal <> 0) and tCore_Data{0}.iSerialNo=0\r\n                    group by tCore_Header{0}.iDate, tCore_Data{0}.iInvTag\r\n                    ", Suffix, 4096, objRec.StartingDate, objRec.EndingDate, text, text2, 8704);
			break;
		case FocusReport.PaymentModeWiseSalesSummary:
		{
			if (FConvert.GetInputValue(objRec.Inputs, 1) > 0 && FConvert.GetInputValue(objRec.Inputs, 2) > 0 && FConvert.GetInputValue(objRec.Inputs, 1) != FConvert.GetInputValue(objRec.Inputs, 2))
			{
				text = $" AND iModifiedTime BETWEEN {FConvert.GetInputValue(objRec.Inputs, 1)} AND {FConvert.GetInputValue(objRec.Inputs, 2)}";
			}
			string text3 = string.Empty;
			string text4 = string.Empty;
			text2 = " AND (sBillReferenceNo LIKE @PosSales OR sBillReferenceNo LIKE @PosSO ";
			if (FConvert.GetInputValue(objRec.Inputs, 3) == 1)
			{
				text3 = " WHEN Name LIKE ('Sale Return') then -Amount ";
				text2 += " OR sBillReferenceNo LIKE (@PosSR) ";
				text4 = string.Format("UNION\r\n\t                    ----sales return \r\n\t                    SELECT iInvTag,tCore_Header{0}.iHeaderId[HeaderId],iDate,iModifiedTime,tCore_HeaderData{1}{0}.sBillReferenceNo,0[MasterId],'Sale Return'[Name], abs(mAmount1)[Amount], 0 [Points Redeemed]\r\n\t                    FROM tCore_Header{0} \r\n\t                    JOIN tCore_HeaderData{1}{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n                        JOIN tCore_Data{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId where mAmount2 > 0 ", Suffix, 3584);
			}
			text2 += ")";
			if (objRec.Masters != null && objRec.Masters.Length != 0)
			{
				text2 += $" AND vrPos_Outlet.iMasterId IN({General.GetMasters(objRec.Masters)})";
			}
			empty = string.Format("\r\n                    SELECT MasterId, Name, \r\n                        CASE {10} WHEN sBillReferenceNo LIKE (@PosSales) then Amount else 0 end[SalesAmount],\r\n\t                    CASE WHEN sBillReferenceNo LIKE (@PosSO) then Amount else 0 end[PreorderAmount],[Points Redeemed],\r\n                        iInvTag\r\n                    From\r\n                    (\r\n\t                    --CASH sales\r\n\t                    SELECT iInvTag,tCore_Header{0}.iHeaderId[HeaderId],iDate,iModifiedTime,tCore_HeaderData{1}{0}.sBillReferenceNo,0[MasterId],'Cash'[Name], fCashPaid[Amount], 0 [Points Redeemed]\r\n\t                    FROM tCore_Header{0} \r\n\t                    JOIN tCore_HeaderData{1}{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n                        JOIN tCore_Data{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId AND tCore_Data{0}.iSerialNo = 0\r\n\t                    UNION\r\n\t                    ----sales Credit card\r\n\t                    SELECT iInvTag,tCore_Header{0}.iHeaderId[HeaderId],iDate,iModifiedTime,tCore_HeaderData{1}{0}.sBillReferenceNo,CreditCard.iMasterId[MasterId], CreditCard.sName[Name], PayCard.fAmount[Amount], 0 [Points Redeemed]\r\n\t\t                FROM tPos_PaymentCardDetails PayCard WITH (READUNCOMMITTED)\r\n\t\t                INNER JOIN tPos_PaymentHeader PosPayHeader WITH (READUNCOMMITTED) ON PosPayHeader.iId = PayCard.iPaymentHeaderId\r\n\t\t                INNER JOIN tCore_Data{0} ERPBody ON ERPBody.iTransactionId = PosPayHeader.iTransactionId \r\n\t\t                JOIN tCore_Header{0} ON tCore_Header{0}.iHeaderId = ERPBody.iHeaderId\r\n\t\t                JOIN tCore_HeaderData{1}{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId \r\n\t\t                LEFT JOIN mPos_BankCardType CreditCard WITH (READUNCOMMITTED) ON CreditCard.iMasterId = PayCard.iBankType  \r\n\t\t                WHERE PayCard.iType = 2\r\n\t\t                UNION\r\n\t\t                ----sales Debit card\t                   \r\n\t\t                SELECT iInvTag,tCore_Header{0}.iHeaderId[HeaderId],iDate,iModifiedTime,tCore_HeaderData{1}{0}.sBillReferenceNo,CreditCard.iMasterId[MasterId], CreditCard.sName[Name], PayCard.fAmount[Amount], 0 [Points Redeemed]\r\n\t\t                FROM tPos_PaymentCardDetails PayCard WITH (READUNCOMMITTED)\r\n\t\t                INNER JOIN tPos_PaymentHeader PosPayHeader WITH (READUNCOMMITTED) ON PosPayHeader.iId = PayCard.iPaymentHeaderId\r\n\t\t                INNER JOIN tCore_Data{0} ERPBody ON ERPBody.iTransactionId = PosPayHeader.iTransactionId \r\n\t\t                JOIN tCore_Header{0} ON tCore_Header{0}.iHeaderId = ERPBody.iHeaderId\r\n\t\t                JOIN tCore_HeaderData{1}{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId \r\n\t\t                LEFT JOIN mPos_BankCardType CreditCard WITH (READUNCOMMITTED) ON CreditCard.iMasterId = PayCard.iBankType  \r\n\t\t                WHERE PayCard.iType = 3\r\n                        ----Sales EPaymentType\r\n\t\t\t\t\t\tUNION\t                   \r\n\t\t                SELECT iInvTag,tCore_Header{0}.iHeaderId[HeaderId],iDate,iModifiedTime,tCore_HeaderData4096{0}.sBillReferenceNo,EPayment.iMasterId[MasterId], EPayment.sName[Name], PayCard.fAmount[Amount], 0 [Points Redeemed]\r\n\t\t                FROM tPos_PaymentCardDetails PayCard WITH (READUNCOMMITTED)\r\n\t\t                INNER JOIN tPos_PaymentHeader PosPayHeader WITH (READUNCOMMITTED) ON PosPayHeader.iId = PayCard.iPaymentHeaderId\r\n\t\t                INNER JOIN tCore_Data{0} ERPBody ON ERPBody.iTransactionId = PosPayHeader.iTransactionId \r\n\t\t                JOIN tCore_Header{0} ON tCore_Header{0}.iHeaderId = ERPBody.iHeaderId\r\n\t\t                JOIN tCore_HeaderData4096{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iHeaderId = tCore_HeaderData4096{0}.iHeaderId \r\n\t\t                LEFT JOIN mPos_EPayment EPayment WITH (READUNCOMMITTED) ON EPayment.iMasterId = PayCard.iEPaymentType  \r\n\t\t                WHERE PayCard.iType = 14\r\n\t                    UNION\r\n\t                    --DiscountVoucher\r\n\t                    SELECT iInvTag,tCore_Header{0}.iHeaderId[HeaderId],iDate,iModifiedTime,tCore_HeaderData{1}{0}.sBillReferenceNo,0[MasterId], 'Disc Voucher', fDVTotRedeemedValue[Amount], 0 [Points Redeemed]\r\n\t                    FROM tCore_Header{0} \r\n\t                    JOIN tCore_HeaderData{1}{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n                        Join tCore_Data{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId AND tCore_Data{0}.iSerialNo = 0\r\n\t                    WHERE fDVTotRedeemedValue is not null\r\n\t                    UNION \r\n\t                    --Gift voucher\r\n\t                    SELECT iInvTag,tCore_Header{0}.iHeaderId[HeaderId],iDate,iModifiedTime,tCore_HeaderData{1}{0}.sBillReferenceNo,0[MasterId],'Gift voucher', fGVTotalValue[Amount], 0 [Points Redeemed]\r\n\t                    FROM tCore_Header{0} \r\n\t                    JOIN tCore_HeaderData{1}{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n                        Join tCore_Data{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId AND tCore_Data{0}.iSerialNo = 0\r\n\t                    UNION\r\n\t                    --Cheque payment\r\n\t                    SELECT iInvTag,tCore_Header{0}.iHeaderId[HeaderId],iDate,iModifiedTime,tCore_HeaderData{1}{0}.sBillReferenceNo,0[MasterId],'Cheque payment', fChqValue[Amount], 0 [Points Redeemed]\r\n\t                    FROM tCore_Header{0} \r\n\t                    JOIN tCore_HeaderData{1}{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n                        Join tCore_Data{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId AND tCore_Data{0}.iSerialNo = 0\r\n                        UNION\r\n                        --Member Points\r\n\t                    SELECT iInvTag,tCore_Header{0}.iHeaderId[HeaderId],iDate,iModifiedTime,tCore_HeaderData{1}{0}.sBillReferenceNo,0[MasterId],'Member Points', fTotalValue[Amount], fPointsRedempted [Points Redeemed]\r\n\t                    FROM tCore_Header{0} \r\n\t                    JOIN tCore_HeaderData{1}{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n\t                    JOIN tCore_Data{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId and tCore_Data{0}.iSerialNo = 0\r\n\t                    where fPointValue is not null\r\n                        UNION\r\n                        --Credit Sale\r\n\t                    SELECT iInvTag,tCore_Header{0}.iHeaderId[HeaderId],iDate,iModifiedTime,tCore_HeaderData{1}{0}.sBillReferenceNo,0[MasterId],'Credit Sale'[Name], [fCreditSaleAmount], 0 [Points Redeemed]\r\n\t                    FROM tCore_Header{0} \r\n\t                    JOIN tCore_HeaderData{1}{0} WITH (READUNCOMMITTED) ON tCore_Header{0}.iHeaderId = tCore_HeaderData{1}{0}.iHeaderId\r\n                        JOIN tCore_Data{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId and tCore_Data{0}.iSerialNo = 0\r\n                        {11}\r\n                    )SubTable\r\n                    LEFT JOIN {7} ON {7}.iMasterId = iInvTag\r\n                    WHERE Amount > 0 AND iDate BETWEEN {4} AND {5} {6} {9}", Suffix, 4096, 3331, 5632, objRec.StartingDate, objRec.EndingDate, text, _focus.company(m_iCompId).invTagName, 3584, text2, text3, text4);
			break;
