			return "Select vrCore_Product.iMasterId,mMRP_BomHeader.sName  + ' - ' +mMRP_BomVariantHeader.sName BOM,Case when mMRP_BOMBody.bInput = 1 then (Space(4)) + PL.sName else PL.sName END ProductName\r\n                    ,vrCore_Product.sCode ProductCode, vrCore_Units.sCode UnitCode, vrCore_Units.sName UnitName, \r\n                    Case when bMainOutPut = 1 or bInput = 0 then 0 else fQty End InputQty,\r\n\t\t\t\t\tCase when bMainOutPut = 1 or bInput = 0 then 0 else fRate End InputRate,\r\n\t\t\t\t\tCase when bMainOutPut = 1 or bInput = 0 then 0 Else (fQty*fRate) End Gross, \r\n\t\t\t\t\tCase when bMainOutPut = 1 or bInput = 0 then fQty else 0 End OutPutQty,\r\n\t\t\t\t\tCase when bMainOutPut = 1 or bInput = 0 then ((Select Sum(Case when mMRP_BOMBody.bInput = 1 then (fRate * fQty) else 0 End) ProdRate From mMRP_BOMBody where iVariantId = mMRP_BomVariantHeader.iVariantId)/fQty) * Case when dCostPercentage=0 then 100 Else dCostPercentage End/100\r\n\t\t\t\t\telse 0 End OutputRate,\r\n\t\t\t\t\tCase when bMainOutPut = 1 or bInput = 0 then \r\n\t\t\t\t\t((Select Sum(Case when mMRP_BOMBody.bInput = 1 or bInput = 0 then (fRate * fQty) else 0 End)  ProdRate From mMRP_BOMBody where iVariantId = mMRP_BomVariantHeader.iVariantId) ) * Case when dCostPercentage=0 then 100 Else dCostPercentage End/100\r\n\t\t\t\t\tElse 0 End OutputGross,\r\n                    Case when mMRP_BOMBody.iScrapType = 0 Then 'Percentage' Else 'Value' End ScrapType, dScrapPerc, \r\n                    dTrailScrapPerc, bFixedQty, bRoundOff,bInput,iProductId,0 CostPrice,0 SellingPrice,0 NetProfit,mMRP_BOMBody.iUnit,vmCore_InvTag.sName,bMainOutPut,Case when dCostPercentage=0 then 100 Else dCostPercentage End dCostPercentage,\r\n                    Case when isnull(mMRP_BomVariantHeader.iAuthStatus,0)=0 then 'Authorise Pending' when mMRP_BomVariantHeader.iAuthStatus=1 then 'Authorised' when mMRP_BomVariantHeader.iAuthStatus=2 then 'Rejected' else '' end as AuthStatus,\r\n                    Case when isnull(mMRP_BomVariantHeader.iStatus,0)= 0 then 'InActive' when mMRP_BomVariantHeader.iStatus= 1 then 'Active' else '' end as BOMStatus\r\n                    " + text17 + "\r\n                    FROM mMRP_BomHeader\r\n                    Inner Join mMRP_BomVariantHeader on mMRP_BomHeader.iBomId = mMRP_BomVariantHeader.iBomId\r\n                    Inner Join mMRP_BOMBody On mMRP_BOMBody.iVariantId = mMRP_BomVariantHeader.iVariantId\r\n                    Inner Join vrCore_Product on vrCore_Product.iMasterId = iProductId And vrCore_Product.iTreeId = 0\r\n                    JOIN mCore_ProductLanguage PL ON vrCore_Product.iMasterId = PL.iMasterId And  PL.iLanguageId=0\r\n                    Inner Join vrCore_Units On vrCore_Units.iMasterId = mMRP_BOMBody.iUnit AND vrCore_Units.iTreeId = 0\r\n                    Join vmCore_InvTag on vmCore_InvTag.iMasterId = iInvTagValue\r\n                    left join mMRP_BomExtraHeader on mMRP_BomExtraHeader.iBomId = mMRP_BomHeader.iBomId\r\n                    left join mMRP_BomExtraBody on mMRP_BomExtraBody.iBomBodyId = mMRP_BOMBody.iBomBodyId \r\n                    " + text16 + "\r\n                    " + empty + " ";
		}
		case FocusReport.ProductionOrderStatusReport:
		{
			int preferenceValue = _focus.company(m_iCompId).getPreferenceValue(PreferenceCategories.MRP, 14);
			string text3 = string.Empty;
