			if (_focus.company(m_iCompId).isModuleImplemented(ModulesImplemented.MRP1) || _focus.company(m_iCompId).isModuleImplemented(ModulesImplemented.MRP2))
			{
				text7 = $"Left Join (Select iFullfillTransId,iHeaderId From tCore_ReservedStock_{yearId} WITH (READUNCOMMITTED)\r\n                            Join tCore_Data_{yearId} on tCore_Data_{yearId}.iTransactionId = tCore_ReservedStock_{yearId}.iReqTransactionId\r\n                            Where iResDocType = 0 And tCore_ReservedStock_{yearId}.iType = 11 ) tCore_Header_{yearId} On iFullfillTransId = iProdOrderBodyId\r\n\t                        Left Join (Select iFullfillTransId,iBodyId From tCore_ReservedStock_{yearId} WITH (READUNCOMMITTED)\r\n                            Join tCore_Data_{yearId} on tCore_Data_{yearId}.iTransactionId = tCore_ReservedStock_{yearId}.iReqTransactionId\r\n                            Where iResDocType = 0 And tCore_ReservedStock_{yearId}.iType = 11 ) tCore_Data_{yearId} On tCore_Data_{yearId}.iFullfillTransId = iProdOrderBodyId";
			}
			string text8 = " And iProduct = iItem ";
