			{
				for (int num = 0; num < yearId; num++)
				{
					text10 += $"\r\n                                Union All \r\n                                SELECT tCore_Header_2_{num}.iProdOrderId,SUM(Case when tCore_Indta_{num}.fQuantityInBase < 0 Then 0 Else tCore_Indta_{num}.fQuantityInBase End)[Received Qty] ,iProcessId\r\n\t                            FROM tCore_Header_2_{num} \r\n\t                            JOIN tCore_Header_{num} ON tCore_Header_2_{num}.iHeaderId = tCore_Header_{num}.iHeaderId\r\n                                JOIN tCore_Data_{num} ON tCore_Data_{num}.iHeaderId = tCore_Header_{num}.iHeaderId\r\n\t                            JOIN tCore_Indta_{num} ON tCore_Data_{num}.iBodyId = tCore_Indta_{num}.iBodyId\r\n                                Join vMrp_ProdOrder_{num} On vMrp_ProdOrder_{num}.iProdOrderId = tCore_Header_2_{num}.iProdOrderId And iProduct = iItem And bMainProduct =1\r\n\t                            WHERE tCore_Header_{num}.bSuspended = 0 AND tCore_Header_{num}.iDate < {objRec.EndingDate}\r\n\t                            AND tCore_Header_{num}.iVoucherType & {65280} IN({1024},{1536},{2816}) \r\n                                And iVoucherType not in({1056}) \r\n\t                            GROUP BY tCore_Header_2_{num}.iProdOrderId,iProcessId";
					text9 += $"\r\n                                Union All\r\n                                SELECT tCore_Header_2_{num}.iProdOrderId,SUM(tCore_Header_2_{num}.fProdSize)[Issue Qty] ,iProcessId\r\n\t                            FROM tCore_Header_2_{num} \r\n\t                            JOIN tCore_Header_{num} ON tCore_Header_2_{num}.iHeaderId = tCore_Header_{num}.iHeaderId\r\n\t                            WHERE tCore_Header_{num}.bSuspended = 0 AND tCore_Header_{num}.iDate <= {objRec.EndingDate} \r\n\t                            AND tCore_Header_{num}.iVoucherType & {65280} IN({6656},{6912},{2816}) And bUpdateStocks = 1\r\n\t                            GROUP BY tCore_Header_2_{num}.iProdOrderId,iProcessId";
					text11 += $"\r\n                                Union All\r\n                                SELECT tCore_Header_2_{num}.iProdOrderId,SUM(tCore_Header_2_{num}.fProdSize)[Qty Returned] ,iProcessId\r\n\t                            FROM tCore_Header_2_{num} \r\n\t                            JOIN tCore_Header_{num} ON tCore_Header_2_{num}.iHeaderId = tCore_Header_{num}.iHeaderId\r\n\t                            WHERE tCore_Header_{num}.bSuspended = 0 AND tCore_Header_{num}.iDate <= {objRec.EndingDate}\r\n\t                            And iVoucherType in (1056)\r\n\t                            GROUP BY tCore_Header_2_{num}.iProdOrderId,iProcessId\r\n                                \r\n                                ";
