				text8 = "";
			}
			return $"SELECT distinct tMrp_ProdOrder{Suffix}.iProdOrderId,tMrp_ProdOrder{Suffix}.sProdOrderNo,{text4} ProcessName, case when  isnull(tMrp_ProdOrder{Suffix}.bMRPOrder,0)=0 then B.sName else A.sName end [Customer], case when  isnull(tMrp_ProdOrder{Suffix}.bMRPOrder,0)=0 then tMrp_ProdOrder{Suffix}.sSONO else tMrp_ProdOrder{Suffix}.sRefOrderNo end sSONO,tMrp_ProdOrder{Suffix}.iDueDate,\r\n                        vmCore_Warehouse.sName[Warehouse], mMRP_BomHeader.sName[BOM], PL.sName[Item Name],vrCore_Product.sCode[Item Code], vmCore_Units.sName[Unit],\r\n                        fQuantity[PO Qty],IssueTable.[Issue Qty], ReturnFromSF.[Qty Returned],\r\n                        fQuantity-isnull(IssueTable.[Issue Qty],0)[Balance Issue Qty],\r\n                        ReceiptTable.[Received Qty] , \r\n                        CASE WHEN fQuantity-isnull(ReceiptTable.[Received Qty],0) <0 THEN 0 ELSE fQuantity-isnull(ReceiptTable.[Received Qty],0) END [Balance Receipt Qty],\r\n                        CASE WHEN (IssueTable.[Issue Qty] - (isnull(ReceiptTable.[Received Qty],0) + isnull(ReturnFromSF.[Qty Returned],0))) < 0 THEN 0 ELSE (isnull(IssueTable.[Issue Qty],0) - (isnull(ReceiptTable.[Received Qty],0)+isnull(ReturnFromSF.[Qty Returned],0))) END [WIP Qty],\r\n                        CASE WHEN  isnull(tMrp_ProdOrder{Suffix}.iOrderStatus,0) in (0,1) then 'Not Released' WHEN tMrp_ProdOrder{Suffix}.iOrderStatus = 2 THEN 'Released' \r\n                        WHEN tMrp_ProdOrder{Suffix}.iOrderStatus = 3 THEN \r\n                        Case when {preferenceValue} > 0 And \r\n                        (CASE WHEN fQuantity-isnull(ReceiptTable.[Received Qty],0) <0 THEN 0 ELSE fQuantity-isnull(ReceiptTable.[Received Qty],0) END) = 0 Then 'Process Completed'\r\n                        Else 'Work in progress' End\r\n                        WHEN tMrp_ProdOrder{Suffix}.iOrderStatus = 4 THEN 'Finished' ELSE 'Closed' END[Status],\r\n                        CASE WHEN tMrp_ProdOrder{Suffix}.iIssueType = 0 THEN 'Single level' ELSE 'Heirarchy level' END[Issue type], tMrp_ProdOrder{Suffix}.sSpecialInstruction, tMrp_ProdOrder{Suffix}.sRemarks,\r\n                        tMrp_ProdOrder{Suffix}.iCreatedDate,tMrp_ProdOrder{Suffix}.iCreatedTime,tMrp_ProdOrder{Suffix}.iDate [Prod Order Date]\r\n                        FROM vMrp_ProdOrder{Suffix} tMrp_ProdOrder{Suffix}\r\n                        --JOIN tMrp_ProdOrderBody{Suffix} WITH (READUNCOMMITTED) ON tMrp_ProdOrder{Suffix}.iProdOrderId = iProdOrderId\r\n                        JOIN mMRP_BomVariantHeader WITH (READUNCOMMITTED) ON mMRP_BomVariantHeader.iVariantId = tMrp_ProdOrder{Suffix}.iVaraintId\r\n                        JOIN mMRP_BomHeader WITH (READUNCOMMITTED) ON mMRP_BomHeader.iBomId = mMRP_BomVariantHeader.iBomId\r\n                        {text3}\r\n                        JOIN vrCore_Product ON vrCore_Product.iMasterId = iItem AND vrCore_Product.iTreeId = 0\r\n                        JOIN mCore_ProductLanguage PL ON vrCore_Product.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                        LEFT JOIN vmCore_Account A ON A.iMasterId = tMrp_ProdOrder{Suffix}.iVendorId  And A.iTreeId = 0  \r\n                        LEFT JOIN vmCore_Account B ON B.iMasterId = tMrp_ProdOrder{Suffix}.iCustomer  And B.iTreeId = 0  \r\n                        LEFT JOIN vmCore_Warehouse  ON vmCore_Warehouse.iMasterId =  tMrp_ProdOrder{Suffix}.iWareHouseId And vmCore_Warehouse.iTreeId = 0\r\n                        LEFT JOIN vmCore_Units  ON vmCore_Units.iMasterId =  iUnit And vmCore_Units.iTreeId = 0\r\n                        {text7}\r\n                        LEFT JOIN\r\n                        (\r\n                            Select iProdOrderId,iProcessId,Sum([Issue Qty])[Issue Qty] From (\r\n\t                        SELECT tCore_Header_2{Suffix}.iProdOrderId,SUM(tCore_Header_2{Suffix}.fProdSize)[Issue Qty] ,iProcessId\r\n\t                        FROM tCore_Header_2{Suffix} \r\n\t                        JOIN tCore_Header{Suffix} ON tCore_Header_2{Suffix}.iHeaderId = tCore_Header{Suffix}.iHeaderId\r\n\t                        WHERE tCore_Header{Suffix}.bSuspended = 0 --AND tCore_Header{Suffix}.iDate BETWEEN {objRec.StartingDate} AND {objRec.EndingDate}\r\n\t                        AND tCore_Header{Suffix}.iVoucherType & {65280} IN({6656},{6912},{2816}) And bUpdateStocks = 1\r\n\t                        GROUP BY tCore_Header_2{Suffix}.iProdOrderId,iProcessId\r\n                            {text9}\r\n                            ) IssueTableInternal Group By iProdOrderId,iProcessId\r\n                        )IssueTable ON IssueTable.iProdOrderId = tMrp_ProdOrder{Suffix}.iProdOrderId {text5}\r\n                        LEFT JOIN\r\n                        (\r\n                            Select iProdOrderId,iProcessId,Sum([Qty Returned])[Qty Returned] From (\r\n                            SELECT tCore_Header_2{Suffix}.iProdOrderId,SUM(tCore_Header_2{Suffix}.fProdSize)[Qty Returned] ,iProcessId\r\n\t                        FROM tCore_Header_2{Suffix} \r\n\t                        JOIN tCore_Header{Suffix} ON tCore_Header_2{Suffix}.iHeaderId = tCore_Header{Suffix}.iHeaderId\r\n\t                        WHERE tCore_Header{Suffix}.bSuspended = 0 --AND tCore_Header{Suffix}.iDate BETWEEN {objRec.StartingDate} AND {objRec.EndingDate}\r\n\t                        And iVoucherType in (1056)\r\n\t                        GROUP BY tCore_Header_2{Suffix}.iProdOrderId,iProcessId\r\n                            {text11}\r\n                            ) ReturnFromSFIntrnal Group By iProdOrderId,iProcessId\r\n                        )ReturnFromSF ON ReturnFromSF.iProdOrderId = tMrp_ProdOrder{Suffix}.iProdOrderId{text5}\r\n                        LEFT JOIN\r\n                        (\r\n                            Select iProdOrderId,iProcessId,Sum([Received Qty])[Received Qty] From (\r\n\t                        SELECT tCore_Header_2{Suffix}.iProdOrderId,SUM(Case when tCore_Indta{Suffix}.fQuantityInBase < 0 Then 0 Else\r\n                            tCore_Indta{Suffix}.fQuantityInBase End)[Received Qty] ,iProcessId\r\n\t                        FROM tCore_Header_2{Suffix} \r\n\t                        JOIN tCore_Header{Suffix} ON tCore_Header_2{Suffix}.iHeaderId = tCore_Header{Suffix}.iHeaderId\r\n                            JOIN tCore_Data{Suffix} ON tCore_Data{Suffix}.iHeaderId = tCore_Header{Suffix}.iHeaderId\r\n\t                        JOIN tCore_Indta{Suffix} ON tCore_Data{Suffix}.iBodyId = tCore_Indta{Suffix}.iBodyId\r\n                            Join vMrp_ProdOrder{Suffix} On vMrp_ProdOrder{Suffix}.iProdOrderId = tCore_Header_2{Suffix}.iProdOrderId And isnull(bMainProduct,1) =1 {text8}\r\n\t                        WHERE tCore_Header{Suffix}.bSuspended = 0 --AND tCore_Header{Suffix}.iDate BETWEEN {objRec.StartingDate} AND {objRec.EndingDate}\r\n\t                        AND tCore_Header{Suffix}.iVoucherType & {65280} IN({1024},{1536},{2816}) \r\n                            And iVoucherType not in({1056}) \r\n\t                        GROUP BY tCore_Header_2{Suffix}.iProdOrderId,iProcessId\r\n                            {text10}\r\n                            ) ReceiptTableIntrnal Group By iProdOrderId,iProcessId\r\n                        )ReceiptTable ON ReceiptTable.iProdOrderId = tMrp_ProdOrder{Suffix}.iProdOrderId {text6}";
		}
		case FocusReport.BOMRevisionHistoryReport:
		{
			int preferenceValue2 = _focus.company(m_iCompId).getPreferenceValue(PreferenceCategories.MRP, 28);
			string empty2 = string.Empty;
			string text14 = string.Empty;
			string text15 = ",'' BomTagName ";
			if (preferenceValue2 > 0)
			{
				text = $"Select 'm' + sModule + '_' + sMasterName as BOMTagName From cCore_MasterDef where iMasterTypeId = {preferenceValue2}";
				empty2 = Convert.ToString(objDb.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
				text14 = " Left Join " + empty2 + " BTT On BTT.iMasterId = c.iTagValue ";
				text15 = " ,BTT.sName BomTagName";
			}
			return $"DECLARE @Variants table (id int identity(0,1), iVariantId int,iVersion int,sRemarks nvarchar(max),ModifiedDate int,CreatedDate int,BomTagName nvarchar(50), ModifiedBy Varchar(200))\r\n                            DECLARE @iRowCount int=0\r\n                            DECLARE @iLoop int =0\r\n                            DECLARE @iVariantId int={objRec.Code}\r\n                            DECLARE @iVariantId0 int=0\r\n                            DECLARE @iVariantId1 int=0  \r\n                            DECLARE @iVersion int = 0\r\n                            DECLARE @BOMName  Varchar(500) = ''\r\n                            DECLARE @ModifiedBy  Varchar(500) = ''\r\n                            DECLARE @sRemarks  nvarchar(max) = ''\r\n                            DECLARE @ModifiedDate  int = 0\r\n                            DECLARE @CreatedDate  int = 0\r\n                            DECLARE @BomTagName Varchar(50) = ''\r\n                            Select  @BOMName =a.sName From mMRP_BomHeader a\r\n                            Join mMRP_BomVariantHeader b on a.iBomId = b.iBomId where a.iBomId =@iVariantId\r\n\r\n                            --Select * From mSec_Users\r\n\r\n\r\n                            insert into @Variants \r\n                            select iVariantId,iVersion,ISNULL(c.sRemarks,'') sRemarks,\r\n                            dbo.DateToInt(dbo.IntToGregDateTime(c.iModifiedDate)),dbo.DateToInt(dbo.IntToGregDateTime(c.iCreatedDate))\r\n                            {text15}\r\n                            ,Isnull(d.sUserName,'SU') sUserName from  mMRP_BomVariantHeader b\r\n                            Join mMRP_BomHeader c on c.iBomId = b.iBomId\r\n                            Join mSec_Users d on c.iCreatedBy = d.iUserId\r\n                            {text14}\r\n                            Where c.sName = @BOMName Order by iVersion\r\n                            set @iRowCount=@@ROWCOUNT\r\n                            Declare @BOMDefSet table (sBomName Varchar(500), iVersion int, sReason Varchar(100),sFieldName Varchar(100),sOrignalValue nvarchar(max),sChangedValue nvarchar(max),sType Varchar(100),sRemarks nvarchar(max),ModifiedDate int,CreatedDate int, BomTagName varchar(50), ModifiedBy Varchar(200))\r\n                            if(@iRowCount >1)\r\n                            Begin\r\n                            while @iLoop<@iRowCount\r\n                            begin\r\n\t                            select @iVariantId0 =iVariantId,@ModifiedBy=ModifiedBy,@ModifiedDate = ModifiedDate,@CreatedDate = CreatedDate,@BomTagName = BomTagName,@sRemarks = sRemarks from @Variants where id=@iLoop\r\n\t                            select @iVariantId1 =iVariantId,@iVersion = iVersion from @Variants where id=@iLoop +1\r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Output Product Changed ','Product', v1.sName, v2.sName, 'BOM Output',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product P on P.iMasterId = a.iProductId\r\n                                    JOIN mCore_ProductLanguage PL ON P.iMasterId = PL.iMasterId And  PL.iLanguageId=0\r\n\t\t                            Where b.iVariantId=@iVariantId0 And bInput = 0) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,sName From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n                                    Where b.iVariantId=@iVariantId1 And bInput = 0) V2 on V1.iProductId= v2.iProductId where v1.iProductId <> v2.iProductId\r\n\t\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Added New Product And Quantity',  v1.sName, '', V1.fQty,'BOM Output',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,c.sName,fQty From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n                                    JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 0) V1 \r\n\t\t                            Left join (\r\n\t\t                            Select iProductId,c.sName From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Where b.iVariantId=@iVariantId0 And bInput = 0) V2 on V1.iProductId= v2.iProductId where v1.iProductId <> Isnull(v2.iProductId,0)\r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Removed Product And Quantity',  v1.sName, '', V1.fQty,'BOM Output',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName,fQty From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 0) V1 \r\n\t\t                            Left join (\r\n\t\t                            Select iProductId,c.sName From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 0) V2 on V1.iProductId= v2.iProductId where v1.iProductId <> Isnull(V2.iProductId,0)\r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Unit Changed for Product ' , v2.PName, v1.UName, v2.UName, 'BOM Output',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName PName,d.sName UName,bMainOutPut From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Join mCore_Units d on d.iMasterId = a.iUnit\r\n\t\t                            Where b.iVariantId=@iVariantId0 And bInput = 0) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName PName,d.sName UName,bMainOutPut From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Join mCore_Units d on d.iMasterId = a.iUnit\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 0) V2 on V1.iProductId= v2.iProductId where v1.UName <> v2.UName\r\n\r\n\t\t\t                        Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Changed Costing Percentage for Product' , v1.PName, v1.dCostPercentage, v2.dCostPercentage, 'BOM Output',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName PName,dCostPercentage From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 0) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,dCostPercentage From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 0) V2 on V1.iProductId= v2.iProductId where v1.dCostPercentage <> v2.dCostPercentage\r\n\t\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Output Quantity Changed for Product' , v2.sName , v1.fQty, v2.fQty, 'BOM Output',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName,fQty From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 0) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName,fQty From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 0) V2 on V1.iProductId= v2.iProductId where v1.fQty <> v2.fQty\r\n\r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Main Output Changed from Product','Product' , v1.sName, v2.sName, 'BOM Output',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName,bMainOutPut From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 0) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName,bMainOutPut From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 0) V2 on V1.iProductId= v2.iProductId where v1.bMainOutPut <> v2.bMainOutPut\r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Input Product Changed From ','Product', v1.sName, v2.sName, 'BOM Input',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 1) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 1) V2 on V1.iProductId= v2.iProductId where v1.iProductId <> v2.iProductId\r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Added New Product And Quantity',  v1.sName, '', V1.fQty,'BOM Input',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName,fQty From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId1 And bInput = 1) V1 \r\n\t\t                            Left join (\r\n\t\t                            Select iProductId,c.sName From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Where b.iVariantId=@iVariantId0 And bInput = 1) V2 on V1.iProductId= v2.iProductId where v1.iProductId <> Isnull(v2.iProductId,0)\r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Removed Product And Quantity',  v1.sName, '', V1.fQty,'BOM Output',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName,fQty From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 1) V1 \r\n\t\t                            Left join (\r\n\t\t                            Select iProductId,c.sName From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 1) V2 on V1.iProductId= v2.iProductId where v1.iProductId <> Isnull(V2.iProductId,0)\r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Quantity Changed for Product ' , v2.sName , v1.fQty, v2.fQty, 'BOM Input',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName,fQty From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 1) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName,fQty From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 1) V2 on V1.iProductId= v2.iProductId where v1.fQty <> v2.fQty\r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Unit Changed for Product ' , v2.PName, v1.UName, v2.UName, 'BOM Input',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName PName,d.sName UName From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Join mCore_Units d on d.iMasterId = a.iUnit\r\n\t\t                            Where b.iVariantId=@iVariantId0 And bInput = 1) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName PName,d.sName UName From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Join mCore_Units d on d.iMasterId = a.iUnit\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 1) V2 on V1.iProductId= v2.iProductId where v1.UName <> v2.UName\r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Rate Changed for Product ' , v2.PName, v1.fRate, v2.fRate, 'BOM Input',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName PName,fRate From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 1) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName PName,fRate From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Join mCore_Units d on d.iMasterId = a.iUnit\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 1) V2 on V1.iProductId= v2.iProductId where v1.fRate <> v2.fRate\r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Procure Type Changed for Product ' , v2.PName, v1.iProcureType, v2.iProcureType, 'BOM Input',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName PName,iProcureType From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 0) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName PName,iProcureType From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Join mCore_Units d on d.iMasterId = a.iUnit\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 1) V2 on V1.iProductId= v2.iProductId where v1.iProcureType <> v2.iProcureType\r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Scrap Type Changed for Product ' , v2.PName, v1.iScrapType, v2.iScrapType, 'BOM Input',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName PName,iScrapType From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 0) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName PName,iScrapType From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Join mCore_Units d on d.iMasterId = a.iUnit\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 1) V2 on V1.iProductId= v2.iProductId where v1.iScrapType <> v2.iScrapType\r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Scrap Value Changed for Product ' , v2.PName, v1.dScrapPerc, v2.dScrapPerc, 'BOM Input',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName PName,dScrapPerc From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 0) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName PName,dScrapPerc From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Join mCore_Units d on d.iMasterId = a.iUnit\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 1) V2 on V1.iProductId= v2.iProductId where v1.dScrapPerc <> v2.dScrapPerc\r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Trail Scrap Value Changed for Product ' , v2.PName, v1.dTrailScrapPerc, v2.dTrailScrapPerc, 'BOM Input',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName PName,dTrailScrapPerc From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 0) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName PName,dTrailScrapPerc From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Join mCore_Units d on d.iMasterId = a.iUnit\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 1) V2 on V1.iProductId= v2.iProductId where v1.dTrailScrapPerc <> v2.dTrailScrapPerc\r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Priority Value Changed for Product ' , v2.PName, v1.iPriority , v2.iPriority , 'BOM Input',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName PName,iPriority From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 0) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName PName,iPriority  From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Join mCore_Units d on d.iMasterId = a.iUnit\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 1) V2 on V1.iProductId= v2.iProductId where v1.iPriority  <> v2.iPriority \r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Description Changed for Product ' , v2.PName, v1.sDescription , v2.sDescription , 'BOM Input',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName PName,sDescription From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 0) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName PName,sDescription  From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Join mCore_Units d on d.iMasterId = a.iUnit\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 1) V2 on V1.iProductId= v2.iProductId where v1.sDescription  <> v2.sDescription \r\n\t\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Is Fixed Quantity Changed for Product ' , v2.PName, Case When v1.bFixedQty = 0 then 'False' Else 'True' End , Case When v2.bFixedQty = 0 then 'False' Else 'True' End ,  'BOM Input',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName PName,bFixedQty From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 0) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName PName,bFixedQty  From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Join mCore_Units d on d.iMasterId = a.iUnit\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 1) V2 on V1.iProductId= v2.iProductId where v1.bFixedQty  <> v2.bFixedQty \r\n\r\n\t\t                            Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Round Of Changed for Product ' , v2.PName, Case When v1.bRoundOff = 0 then 'False' Else 'True' End , Case When v2.bRoundOff = 0 then 'False' Else 'True' End , 'BOM Input',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName PName,bRoundOff From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 0) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName PName,bRoundOff  From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Join mCore_Units d on d.iMasterId = a.iUnit\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 1) V2 on V1.iProductId= v2.iProductId where v1.bRoundOff  <> v2.bRoundOff \r\n\r\n\t\t\t                        Insert Into @BOMDefSet \r\n\t\t                            select  @BOMName,@iVersion,'Tolerance Changed for Product ' , v2.PName,v1.dTolerancePerc , v2.dTolerancePerc  , 'BOM Input',@sRemarks,@ModifiedDate,@CreatedDate,@BomTagName,@ModifiedBy from(\r\n\t\t                            Select iProductId,PL.sName PName,dTolerancePerc From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            JOIN mCore_ProductLanguage PL ON c.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                    Where b.iVariantId=@iVariantId0 And bInput = 0) V1 \r\n\t\t                            inner join (\r\n\t\t                            Select iProductId,c.sName PName,dTolerancePerc  From mMRP_BOMBody a\r\n\t\t                            Join mMRP_BomVariantHeader b on a.iVariantId = b.iVariantId \r\n\t\t                            Join mCore_Product c on c.iMasterId = a.iProductId\r\n\t\t                            Join mCore_Units d on d.iMasterId = a.iUnit\r\n\t\t                            Where b.iVariantId=@iVariantId1 And bInput = 1) V2 on V1.iProductId= v2.iProductId where v1.dTolerancePerc  <> v2.dTolerancePerc \r\n\t\t\r\n\t\t                            set @iLoop +=1\r\n\r\n                            End\r\n\r\n                            Select @iVariantId iHeaderId,sBomName + ' BOM Changes in Version From  Version: ' + Cast(iVersion-1 as varchar(5))  + ' To Version:' + Cast(iVersion as varchar(5)) iVersion,sType,sReason,sFieldName sFieldData,sOrignalValue,sChangedValue,sRemarks,ModifiedBy,ModifiedDate,CreatedDate,BomTagName From @BOMDefSet\r\n                            End\r\n                            Else\r\n                            Begin\r\n\t                            Select 0 iHeaderId,'No Versions Found' iVersion,'' sType,'' sReason,'' sFieldData,'' sOrignalValue,'' sChangedValue,'' sRemarks,'' ModifiedBy,0 ModifiedDate ,0 CreatedDate ,''BomTagName\r\n                            End ";
		}
		case FocusReport.NegitiveBatchList:
			return $"Select iProduct,w.sCode InvTag, PL.sName ItemName, p.sCode ItemCode, u.sName Unit,CEILING((Sum(fQuantityInBase)))   fQuantity,sBatchNo Batch ,Max(iExpiryDate) ExpiryDate,Max(iMfDate) MFDate,iBatchId,iInvTag\r\n                        From tCore_Batch{Suffix} bat\r\n                        join tCore_Data{Suffix} a on a.iBodyId = bat.iBodyId\r\n                        join tCore_Indta{Suffix} i on a.iBodyId = i.iBodyId\r\n                        join tCore_Header{Suffix} b on a.iHeaderId = b.iHeaderId\r\n                        join cCore_Vouchers{Suffix} c on c.iVoucherType = b.iVoucherType\r\n                        join vmCore_Product p on p.iMasterId = i.iProduct\r\n                        JOIN mCore_ProductLanguage PL ON p.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                        join mCore_Units u on u.iMasterId = p.iDefaultBaseUnit\r\n                        Join vmCore_InvTag w on w.iMasterId = iInvTag ";
		case FocusReport.MRPReservationDetailsReport:
			return $"\r\n                                DECLARE @iPIOSOId Bigint={FConvert.GetInputValue(objRec.Inputs, 2)}\r\n                                Select iReqTransactionId,ItemName,ItemCode,ItemType,sUnit, Max(QtyRequired) QtyRequired,Sum(QtyPlanned) QtyPlanned\r\n                                ,Sum(QtyAdjusted) QtyAdjusted,Sum(QtyRaised) QtyRaised\r\n                                From (\r\n                                Select iReqTransactionId,PL.sName ItemName,vmCore_Product.sCode ItemCode,vmCore_Product.iProductTypeName ItemType,vmCore_Product.iDefaultBaseUnitName sUnit, PIODet.fQuantity QtyRequired,\r\n                                Sum(POB.fQuantity) QtyPlanned,0 QtyAdjusted,Sum(Res.fQuantity) QtyRaised\r\n                                  From tCore_ReservedStock{Suffix} Res\t\r\n                                Join tMrp_PIODetails{Suffix} PIODet with(readuncommitted) on Res.iReqTransactionId = PIODet.iId\r\n                                Join tMrp_ProdOrderBody{Suffix} POB with(readuncommitted) on POB.iMasterID= Res.iFullfillTransId\r\n                                Join vmCore_Product On vmCore_Product.iMasterId = PIODet.iProductId And vmCore_Product.iTreeId = 0\r\n                                JOIN mCore_ProductLanguage PL ON vmCore_Product.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                Where iResDocType = 1 and Res.iType = 11 And bReserveOrRelease = 0 And iReqTransactionId = case when  @iPIOSOId >0 then @iPIOSOId else iReqTransactionId end\r\n                                Group by iReqTransactionId,PL.sName ,vmCore_Product.sCode ,vmCore_Product.iProductTypeName , PIODet.fQuantity ,vmCore_Product.iDefaultBaseUnitName\r\n                                Union All\r\n                                Select iReqTransactionId,PL.sName ItemName,vmCore_Product.sCode ItemCode,vmCore_Product.iProductTypeName ItemType,vmCore_Product.iDefaultBaseUnitName sUnit, PIODet.fQuantity QtyRequired,\r\n                                0 QtyPlanned,Sum(Res.fQuantity) QtyAdjusted, 0 QtyRaised\r\n                                  From tCore_ReservedStock{Suffix} Res\r\n                                Join tMrp_PIODetails{Suffix} PIODet on Res.iReqTransactionId = PIODet.iId\r\n                                Join vmCore_Product On vmCore_Product.iMasterId = PIODet.iProductId And vmCore_Product.iTreeId = 0\r\n                                JOIN mCore_ProductLanguage PL ON vmCore_Product.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                Where iResDocType = 1 and Res.iType = 0 And bReserveOrRelease = 0 And iReqTransactionId = case when  @iPIOSOId >0 then @iPIOSOId else iReqTransactionId end\r\n                                Group by iReqTransactionId,PL.sName ,vmCore_Product.sCode ,vmCore_Product.iProductTypeName , PIODet.fQuantity ,vmCore_Product.iDefaultBaseUnitName\r\n                                Union All\r\n                                --Sales Order \r\n                                Select iReqTransactionId,PL.sName ItemName,vmCore_Product.sCode ItemCode,vmCore_Product.iProductTypeName ItemType,vmCore_Product.iDefaultBaseUnitName sUnit, SORIn.fQuantityInBase QtyRequired,\r\n                                Sum(POB.fQuantity) QtyPlanned,0 QtyAdjusted,Sum(Res.fQuantity) QtyRaised\r\n                                  From tCore_ReservedStock{Suffix} Res\r\n                                Join tCore_Data{Suffix} SORDet on Res.iReqTransactionId = SORDet.iTransactionId\r\n                                Join tCore_Indta{Suffix} SORIn on SORIn.iBodyId = SORDet.iBodyId\r\n                                Join tMrp_ProdOrderBody{Suffix} POB with(readuncommitted) on POB.iMasterID= Res.iFullfillTransId\r\n                                Join vmCore_Product On vmCore_Product.iMasterId = SORIn.iProduct And vmCore_Product.iTreeId = 0\r\n                                JOIN mCore_ProductLanguage PL ON vmCore_Product.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                Where iResDocType = 0 and Res.iType = 11 And bReserveOrRelease = 0 And iReqTransactionId = case when  @iPIOSOId >0 then @iPIOSOId else iReqTransactionId end\r\n                                Group by iReqTransactionId,PL.sName ,vmCore_Product.sCode ,vmCore_Product.iProductTypeName , SORIn.fQuantityInBase,vmCore_Product.iDefaultBaseUnitName\r\n                                Union All\r\n                                Select iReqTransactionId,PL.sName ItemName,vmCore_Product.sCode ItemCode,vmCore_Product.iProductTypeName ItemType,vmCore_Product.iDefaultBaseUnitName sUnit, SORIn.fQuantityInBase QtyRequired,\r\n                                0 QtyPlanned,Sum(Res.fQuantity) QtyAdjusted,0 QtyRaised\r\n                                From tCore_ReservedStock{Suffix} Res\r\n                                Join tCore_Data{Suffix} SORDet on Res.iReqTransactionId = SORDet.iTransactionId\r\n                                Join tCore_Indta{Suffix} SORIn on SORIn.iBodyId = SORDet.iBodyId\r\n                                Join vmCore_Product On vmCore_Product.iMasterId = SORIn.iProduct And vmCore_Product.iTreeId = 0\r\n                                JOIN mCore_ProductLanguage PL ON vmCore_Product.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                Where iResDocType = 0 and Res.iType = 0 And bReserveOrRelease = 0 And iReqTransactionId = case when  @iPIOSOId >0 then @iPIOSOId else iReqTransactionId end\r\n                                Group by iReqTransactionId,PL.sName ,vmCore_Product.sCode ,vmCore_Product.iProductTypeName , SORIn.fQuantityInBase,vmCore_Product.iDefaultBaseUnitName\r\n                                ) as SOPIO  Group by iReqTransactionId,ItemName,ItemCode,ItemType,sUnit\r\n                                Union All\r\n                                Select Min(iPDRId)iPDRId,ItemName,ItemCode,ItemType,sUnit,0 QtyRequired,\r\n\r\n                                sum(QtyRequired) QtyPlanned,SUm(QtyAdjusted) QtyAdjusted, Sum(QtyRaised) QtyRaised\r\n                                FRom (\r\n\t                                Select PDR.iPDRId,PL.sName ItemName,vmCore_Product.sCode ItemCode,vmCore_Product.iProductTypeName ItemType,U.sName sUnit,\r\n\t                                (PDR.fQuantity) QtyRequired, QtyAdjusted, QtyRaised\r\n\t                                From tMRP_PlannedDependentRequirement{Suffix} PDR\r\n\t                                Join vmCore_Product On vmCore_Product.iMasterId = PDR.iProductId And vmCore_Product.iTreeId = 0\r\n                                    JOIN mCore_ProductLanguage PL ON vmCore_Product.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n\t                                Join vmCore_Units U On U.iMasterId = PDR.iUnitId And U.iTreeId = 0\r\n\t                                Left Join (Select PDRL.iPDRId,Sum(Case When Res.iType = 0 then Res.fQuantity Else 0 End) QtyAdjusted\r\n\t\t                                ,Sum(Case When Res.iType > 0 then Res.fQuantity Else 0 End) QtyRaised\r\n\t\t                                From tMRP_PDRStockReservationLink{Suffix} PDRl\r\n\t\t                                Join tCore_ReservedStock{Suffix} Res on Res.iReqTransactionId = PDRl.iPDRSTRId\r\n\t\t                                Where iResDocType = 3 And bReserveOrRelease = 0 and case when iType = 0 and iTransactionId > 0 then 1 else 0 end =0 Group by PDRL.iPDRId) as PDRL on PDRL.iPDRId = PDR.iPDRId\r\n\t                                Where PDR.iProdOrderId  in (select iProdOrderId from tCore_ReservedStock{Suffix} Res\r\n\t                                Join tMrp_ProdOrderBody{Suffix} POB  with(readuncommitted) on POB.iMasterID = Res.iFullfillTransId\r\n\t                                Where Res.iType = 11 and Res.iResDocType in (0,1) And POB.bMainProduct = 1\r\n\t                                And iReqTransactionId in (case when  @iPIOSOId >0 then @iPIOSOId else iReqTransactionId end) And bReserveOrRelease = 0) \r\n                                ) as PDR \r\n                                Group by ItemName,ItemCode,ItemType,sUnit";
		case FocusReport.MaterialRequisitionByProductionOrderReport:
		{
			int num4 = ((FConvert.GetInputValue(objRec.Inputs, 1) != -1) ? FConvert.GetInputValue(objRec.Inputs, 1) : 0);
			int num5 = ((FConvert.GetInputValue(objRec.Inputs, 0) != -1) ? FConvert.GetInputValue(objRec.Inputs, 0) : 0);
			string text18 = ((objRec.UserId > 1) ? " And isnull(bPhantom, 0) <> 1 " : "");
			return $"declare @iProductionOrderId int = {num4}\r\n                                declare @ProductId int = {num5}\r\n                                declare @Startdate int = {objRec.StartingDate}\r\n                                declare @EndDate int = {objRec.EndingDate}\r\n                                 SELECT    \r\n                                ProdOrder.iProdOrderId,ProdOrder.sProdOrderNo,PL.sName AS ProductName,vrCore_Product.sCode AS ProductCode,  \r\n                                ISP.fQuantity AS Quantity,  iDefaultBaseUnit UnitName, iDefaultBaseUnitsCode UnitCode,\r\n                                isnull(ISP.fIssuedQuantity,0) fIssuedQuantity,ProdOrder.iDueDate\r\n                                FROM  tMrp_ProdOrder{Suffix} ProdOrder  with(readuncommitted)\r\n                                INNER JOIN tMRP_IssueToProduction{Suffix} ISP  ON ProdOrder.iProdOrderId = ISP.iProdOrderId \r\n                                INNER JOIN vrCore_Product ON ISP.iProductId = vrCore_Product.iMasterId\r\n                                JOIN mCore_ProductLanguage PL ON vrCore_Product.iMasterId = PL.iMasterId And  PL.iLanguageId=0\r\n                                --inner join mCore_Units on mCore_Units.iMasterId = vrCore_Product.iDefaultBaseUnit\r\n                                where ISP.iProductID= case @ProductId when 0 then ISP.iProductId else @ProductId end\r\n                                and  ProdOrder.iProdOrderId= case @iProductionOrderId when 0 then ProdOrder.iProdOrderId else @iProductionOrderId end\r\n                                and  ProdOrder.iDueDate >= case when @Startdate  = 0 then  ProdOrder.iDueDate else @Startdate end\r\n                                and  ProdOrder.iDueDate <= case when @EndDate  = 0 then  ProdOrder.iDueDate else @EndDate end\r\n                                and  ProdOrder.iDueDate <= case when @EndDate  = 0 then  ProdOrder.iDueDate else @EndDate end\r\n                                {text18}\r\n                                group by ProdOrder.iProdOrderId,ProdOrder.sProdOrderNo,PL.sName,vrCore_Product.sCode,ISP.fQuantity, iDefaultBaseUnit, iDefaultBaseUnitsCode,\r\n                                ISP.fIssuedQuantity,ProdOrder.iDueDate";
		}
		case FocusReport.BOMRoutingStatusReport:
			return $"Select Product.MasterId ProductId,PL.sName ProductName,Product.Code ProductCode,case isnull(Product.sDefaultReplenishment,0) when 0 then 'Purchase' ELSE 'Production' END as  [ReplenishmentType],\r\n                                Case when isnull(Product.Bom,0) > 0 then 'Yes' Else 'No' End IsBOMCreated,\r\n                                Case when isnull(Product.Bom,0) > 0 then Case when(Select COUNT(*) From mMRP_RoutingHeader RH where RH.iBomId = Product.Bom) > 0 then 'Yes' Else 'No' End   Else 'No' End IsRoutingCreated\r\n                                From vMRP_Products Product\r\n                                JOIN mCore_ProductLanguage PL ON Product.MasterId = PL.iMasterId And  PL.iLanguageId={inputValue}";
		case FocusReport.BOMExplosionDetailsReport:
		{
			int num3 = ((FConvert.GetInputValue(objRec.Inputs, 1) != -1) ? FConvert.GetInputValue(objRec.Inputs, 1) : 0);
			empty = string.Empty;
			if (num3 == 0)
			{
				empty = "--";
			}
			return $"WITH cte_BOM (\r\n                                    iVarientId, BOMName, BOMCode, ProductName, ProductCode, ProductType, BomType,\r\n                                    fQty, UnitName, dScrapPerc, Replenishment, bRoundOff, bFixedQty, inputType,\r\n                                    iVersion, iRowIndex, iBomId, iLevel, Warehouse, bPhantom, ChildId, Path\r\n                                ) AS\r\n                                (     \r\n                                    -- Anchor part\r\n                                    SELECT \r\n                                        iVarientId, BOMName, BOMCode, ProductName, ProductCode, ProductType, BomType,\r\n                                        CAST(fQty AS DECIMAL(20,9)) AS fQty, UnitName, dScrapPerc, Replenishment,\r\n                                        bRoundOff, bFixedQty, inputType, iVersion, iRowIndex, iBomId, iLevel,\r\n                                        Warehouse, bPhantom, ChildId, Path\r\n                                    FROM (\r\n                                        SELECT \r\n                                            bv.iVariantId iVarientId, bh.sName BOMName, bh.sCode BOMCode,\r\n                                            PL.sName ProductName, f_Product.sCode ProductCode, f_Product.iProductTypeName ProductType,\r\n                                            CASE iType  \r\n                                                WHEN 0 THEN 'Production' WHEN 1 THEN 'Assembly' WHEN 2 THEN 'Engineering'\r\n                                                WHEN 3 THEN 'Universal' WHEN 4 THEN 'Plant Maintenance'\r\n                                                WHEN 5 THEN 'Sales Distribution' ELSE '' END BomType,\r\n                                            CAST(bb.fQty AS DECIMAL(20,9)) AS fQty,\r\n                                            mCore_Units.sName UnitName, bb.dScrapPerc,\r\n                                            f_Product.iDefaultReplenishmentName Replenishment,\r\n                                            ISNULL(bb.bRoundOff,0) bRoundOff, ISNULL(bb.bFixedQty,0) bFixedQty,\r\n                                            bb.bMainOutPut inputType, bh.iVersion, bb.iRowIndex, 0 iBomId, 0 iLevel,\r\n                                            vmCore_InvTag.sName Warehouse, ISNULL(bh.bPhantom,0) bPhantom,\r\n                                            f_Product.iBOM ChildId,\r\n                                            CAST(RIGHT('0000'+CAST(bb.iRowIndex AS VARCHAR(4)),4) AS VARCHAR(MAX)) AS Path\r\n                                        FROM mMRP_BomHeader bh\r\n                                        INNER JOIN mMRP_BomVariantHeader bv ON bv.iBomId = bh.iBomId\r\n                                        INNER JOIN mMRP_BOMBody bb ON bb.iVariantId = bv.iVariantId AND bInput = 0\r\n                                        JOIN vmCore_InvTag ON iMasterId = iInvTagValue\r\n                                        JOIN vmCore_Product f_Product ON f_Product.iMasterId = iProductId\r\n                                        JOIN mCore_ProductLanguage PL ON f_Product.iMasterId = PL.iMasterId AND PL.iLanguageId={inputValue}\r\n                                        INNER JOIN mCore_Units ON mCore_Units.iMasterId = bb.iUnit                                        \r\n                                        WHERE bv.iVariantId = {num3} \r\n\r\n                                        UNION ALL\r\n\r\n                                        SELECT vh.iVariantId iVarientId, bomheader.sName BOMName, bomheader.sCode BOMCode, PL.sName ProductName, \r\n                                        f_Product.sCode ProductCode, f_Product.iProductTypeName ProductType,\r\n                                            CASE iType  \r\n                                                WHEN 0 THEN 'Production' WHEN 1 THEN 'Assembly' WHEN 2 THEN 'Engineering'\r\n                                                WHEN 3 THEN 'Universal' WHEN 4 THEN 'Plant Maintenance'\r\n                                                WHEN 5 THEN 'Sales Distribution' ELSE '' END BomType,\r\n                                            CAST(BomBody.fQty AS DECIMAL(20,9)) AS fQty,\r\n                                            mCore_Units.sName UnitName, BomBody.dScrapPerc,\r\n                                            f_Product.iDefaultReplenishmentName Replenishment,\r\n                                            ISNULL(BomBody.bRoundOff,0) bRoundOff, ISNULL(BomBody.bFixedQty,0) bFixedQty,\r\n                                            BomBody.bInput inputType, bomheader.iVersion, BomBody.iRowIndex,\r\n                                            f_Product.iBOM, 1 iLevel, vmCore_InvTag.sName Warehouse,\r\n                                            ISNULL(bomheader.bPhantom,0) bPhantom,\r\n                                            f_Product.iBOM ChildId,\r\n                                            RIGHT('0000'+CAST(BomBody.iRowIndex AS VARCHAR(4)),4) AS Path\r\n                                        FROM mMRP_BomHeader bomheader\r\n                                        INNER JOIN mMRP_BomVariantHeader VH ON VH.iBomId = bomheader.iBomId \r\n                                        INNER JOIN mMRP_BOMBody BomBody ON VH.iVariantId = BomBody.iVariantId\r\n                                        JOIN vmCore_InvTag ON iMasterId = iInvTagValue\r\n                                        JOIN vmCore_Product f_Product ON f_Product.iMasterId = iProductId\r\n                                        JOIN mCore_ProductLanguage PL ON f_Product.iMasterId = PL.iMasterId AND PL.iLanguageId={inputValue}\r\n                                        INNER JOIN mCore_Units ON mCore_Units.iMasterId = BomBody.iUnit                                        \r\n                                        WHERE vH.iVariantId = {num3} AND bInput=1 AND bMainOutPut=0 \r\n                                    ) a\r\n\r\n                                    UNION ALL\r\n\r\n                                    -- Recursive part\r\n                                    SELECT \r\n                                        vh.iVariantId iVarientId, bomheader.sName BOMName, bomheader.sCode BOMCode,\r\n                                        PL.sName ProductName, f_Product.sCode ProductCode, f_Product.iProductTypeName ProductType,\r\n                                        CASE iType  \r\n                                            WHEN 0 THEN 'Production' WHEN 1 THEN 'Assembly' WHEN 2 THEN 'Engineering'\r\n                                            WHEN 3 THEN 'Universal' WHEN 4 THEN 'Plant Maintenance'\r\n                                            WHEN 5 THEN 'Sales Distribution' ELSE '' END BomType,\r\n                                        CAST(((BomBody.fQty/ProductBOM.OutQty) * cte_BOM.fQty) AS DECIMAL(20,9)) AS fQty,\r\n                                        mCore_Units.sName UnitName, BomBody.dScrapPerc,\r\n                                        f_Product.iDefaultReplenishmentName Replenishment,\r\n                                        ISNULL(BomBody.bRoundOff,0) bRoundOff, ISNULL(BomBody.bFixedQty,0) bFixedQty,\r\n                                        BomBody.bInput inputType, bomheader.iVersion, BomBody.iRowIndex,\r\n                                        f_Product.iBOM, cte_BOM.iLevel+1, cte_BOM.Warehouse,\r\n                                        ISNULL(bomheader.bPhantom,0) bPhantom,\r\n                                        f_Product.iBOM ChildId,\r\n                                        cte_BOM.Path + '-' + RIGHT('0000'+CAST(BomBody.iRowIndex AS VARCHAR(4)),4) AS Path\r\n                                    FROM mMRP_BOMBody BomBody\r\n                                    JOIN vmCore_Product f_Product ON f_Product.iMasterId = BomBody.iProductId \r\n                                    JOIN mCore_ProductLanguage PL ON f_Product.iMasterId = PL.iMasterId AND PL.iLanguageId={inputValue}\r\n                                    INNER JOIN (\r\n                                        SELECT iBOM, P.iMasterId, fQty OutQty \r\n                                        FROM mCore_Product P\r\n                                        JOIN muCore_Product_Replenishment PR ON P.iMasterId = PR.iMasterId\r\n                                        INNER JOIN mMRP_BOMBody Body ON PR.iBOM = Body.iVariantId AND bMainOutPut=1 AND bInput=0 AND P.iMasterId=Body.iProductId\r\n                                    ) ProductBOM ON ProductBOM.iBOM = BomBody.iVariantId\r\n                                    INNER JOIN mMRP_BomVariantHeader VH ON VH.iVariantId = ProductBOM.iBOM \r\n                                    INNER JOIN mMRP_BomHeader bomheader ON bomheader.iBomId = vh.iBomId\r\n                                    INNER JOIN mCore_Units ON mCore_Units.iMasterId = BomBody.iUnit AND BomBody.bInput=1\r\n                                    INNER JOIN cte_BOM ON cte_BOM.iBomId = BomBody.iVariantId AND cte_BOM.iVarientId <> BomBody.iVariantId                                        \r\n                                    WHERE CHARINDEX(CAST(VH.iVariantId AS VARCHAR(MAX)), cte_BOM.Path) = 0 AND cte_BOM.iLevel > 0\r\n                                )\r\n                                SELECT iVarientId, BOMName, BOMCode, REPLICATE('   ', iLevel) + ProductName AS ProductName,\r\n                                       ProductCode, ProductType, BomType, fQty, UnitName, dScrapPerc, Replenishment,\r\n                                       bRoundOff, bFixedQty, inputType, iVersion, iRowIndex, iBomId, iLevel, Warehouse, bPhantom\r\n                                FROM cte_BOM\r\n                                ORDER BY Path\r\n                                OPTION (MAXRECURSION 1000)";
		}
		case FocusReport.BOMListReport:
			empty = string.Empty;
			return "Select Product.iMasterId ProductId,PL.sName ProductName,Product.szCode ProductCode,\r\n                                case when Product.Type=2 then 'Inter Mediate Product' else 'Finished good' end [Type],\r\n                                isnull(BOM.BOMName,'') BOMName,CONVERT(nvarchar(max),BOM.iVersion) iVersion, isnull(BOM.sDescription,'') sDescription, isnull(BOM.sAuthStatus,'') sAuthStatus,  \r\n                                Case when isnull(BOM.AuthorizedUser,'')='' then '' else BOM.AuthorizedUser end as AuthorizedUser,Case when isnull(BOM.AuthRemarks,'')='' then '' else BOM.AuthRemarks end as AuthRemarks,\r\n                                isnull(ROU.RoutingCode,'') RoutingCode ,isnull(ROU.IsDefaultRouting,0) IsDefaultRouting From fMRP_Product(0) Product\r\n                                JOIN mCore_ProductLanguage PL ON Product.iMasterId = PL.iMasterId And  PL.iLanguageId=0\r\n                                Left Join (Select bv.iVariantId iVarientId,Case when bv.sName = 'Default' then bh.sName Else bv.sName End BOMName,bh.sDescription sDescription, \r\n\t\t                                   bb.iProductId iProductId, bh.bDefault IsDefaultBOM,ISNULL(bh.iVersion,0) iVersion,\r\n\t\t                                   Case when isnull(bv.iAuthStatus,0)=0 then 'Authorise Pending' when bv.iAuthStatus=1 then 'Authorised' when bv.iAuthStatus=2 then 'Rejected' else '' end as sAuthStatus,\r\n\t\t                                   Case when isnull(sUser.sUserName,'')='' then '' else sUser.sUserName end as AuthorizedUser,\r\n\t\t                                   Case when isnull(sUser.AuthRemarks,'')='' then '' else sUser.AuthRemarks end as AuthRemarks\r\n\t\t                                   From mMRP_BomHeader bh\r\n\t\t\t                               Inner Join mMRP_BomVariantHeader bv On bv.iBomId = bh.iBomId and bh.iStatus != 5\r\n\t\t\t                               Inner Join mMRP_BOMBody bb on bb.iVariantId = bv.iVariantId And bInput = 0\r\n\t\t\t                               LEFT Join (Select iDocumentId,STRING_AGG( 'L' + convert(varchar,iLevel+1) + ' : ' + sUserName ,', ') sUserName, \r\n\t\t\t\t\t\t                                Case when isnull(AU.sReason,'')='' then '' else AU.sReason end as AuthRemarks\r\n\t\t\t\t\t\t                                from mCore_AuthorizationDetails" + Suffix + " AD\r\n\t\t\t\t\t\t                                JOIN  tCore_ProductionAuth PA on AD.iAuthorizationDetailId = PA.iAuthNodeId\r\n\t\t\t\t\t\t                                JOIN tCore_productionAuthUser AU on AU.iAuthId = PA.iAuthId\r\n\t\t\t\t\t\t                                JOIN mSec_Users sUser ON AU.iRoleOrUserId = sUser.iUserId\r\n\t\t\t\t\t\t                                WHERE AU.iStatus = 1\r\n\t\t\t\t\t\t                                GROUP BY iDocumentId, AU.sReason\r\n\t\t\t\t\t\t                             ) sUser On sUser.iDocumentId  = bv.iVariantId\r\n\t\t                                   )\r\n                                BOM on BOM.iProductId=Product.iMasterId\r\n                                Left Join (Select iRoutingId RoutingId,sCode RoutingCode,iBomId,bSetAsDefault IsDefaultRouting From mMRP_RoutingHeader) \r\n                                ROU on ROU.iBomId=BOM.iVarientId ";
		case FocusReport.PIODetailsReport:
			return $"declare  @itemId int = {objRec.Code}  \r\n                                declare  @iStartDate int = {objRec.StartingDate} \r\n                                declare @iEndDate int = {objRec.EndingDate}\r\n                                SELECT pio.iPIOId,pio.sDocNo as DocumentNo,PL.sName as Item,  pio.iDate as Date,PIODet.iDueDate as DueDate,  \r\n                                PIODet.fQuantity as Quantity from tMrp_PIO{Suffix} PIO   \r\n                                inner join tMrp_PIODetails{Suffix} PIODet on PIO.iPIOId=PIODet.iPIOId   \r\n                                Inner Join vrCore_Product on PIODet.iproductID = vrCore_Product.iMasterId  And vrCore_Product.iTreeId = 0\r\n                                JOIN mCore_ProductLanguage PL ON vrCore_Product.iMasterId = PL.iMasterId And  PL.iLanguageId={inputValue}\r\n                                Where pio.iDate >= case when @iStartDate = 0 then pio.iDate else  Cast(@iStartDate as VarChar(12)) end    \r\n                                AND vrCore_Product.iMasterId = case @itemID  when 0 then vrCore_Product.iMasterId else Cast(@itemID as VarChar(10)) end";
		case FocusReport.BOMProcessReport:
		{
			string text2 = string.Empty;
			empty = "--";
			object inputObject = FConvert.GetInputObject(objRec.Inputs, 0);
			List<LongIdNamePair> list = new List<LongIdNamePair>();
			if (inputObject != null)
			{
				list = ((LongIdNamePair[])inputObject).ToList();
				text2 = string.Join(",", list.Select((LongIdNamePair p) => p.ID));
				if (text2.Length > 0)
				{
					empty = string.Empty;
				}
			}
			return "SELECT mMRP_RoutingHeader.iRoutingId iHeaderId,mMRP_RoutingHeader.sCode BOMCode,'Output' AS 'In/Out',PL.sName sProductName,P.sCode sProductCode,\r\n                                    mMrp_Process.sName sProcessName,mMrp_Process.sCode sProcessCode,\r\n                                    fQuantity fActualQty,fQuantity fProcessQty,mCore_Units.sName sUnitName,mCore_Units.sCode sUnitCode,\r\n                                    CASE WHEN iType=0 THEN 1 ELSE 0 END bMainOutput,mMRP_RoutingNodes.iBodyId,mMRP_RoutingOutput.iProcessId,0 RowId\r\n                                    FROM mMRP_RoutingOutput WITH (READUNCOMMITTED) \r\n                                    INNER JOIN mCore_Product P ON mMRP_RoutingOutput.iProductId = P.iMasterId  \r\n                                    INNER JOIN mCore_ProductLanguage PL ON P.iMasterId = PL.iMasterId And  PL.iLanguageId=0\r\n\t\t\t\t\t\t\t\t\tINNER JOIN muCore_Product_Units PU ON PU.iMasterId = P.iMasterId\r\n                                    INNER JOIN mMRP_RoutingNodes ON mMRP_RoutingNodes.iBodyId = mMRP_RoutingOutput.iBodyId\r\n                                    INNER JOIN mMRP_RoutingHeader ON mMRP_RoutingHeader.iRoutingId = mMRP_RoutingNodes.iHeaderId AND bBOMProcess = 1\r\n                                    INNER JOIN mCore_Units ON mCore_Units.iMasterId = PU.iDefaultBaseUnit\r\n                                    INNER JOIN mMrp_Process ON mMrp_Process.iMasterId = mMRP_RoutingOutput.iProcessId\r\n                                    WHERE mMRP_RoutingOutput.iBodyId IN( SELECT iBodyId FROM mMRP_RoutingNodes WITH (READUNCOMMITTED) " + empty + " WHERE iHeaderId in (" + text2 + ")\r\n                                    )\r\n                                    UNION ALL\r\n                                    SELECT mMRP_RoutingHeader.iRoutingId iHeaderId,mMRP_RoutingHeader.sCode BOMCode,'Input' as 'In/Out',PL.sName sProductName,P.sCode sProductCode,\r\n                                    mMrp_Process.sName sProcessName,mMrp_Process.sCode sProcessCode,CASE WHEN ISNULL(BomBody.fQty,0) > 0 THEN BomBody.fQty ELSE fQuantity END fActualQty,\r\n                                    fQuantity fProcessQty,mCore_Units.sName sUnitName, mCore_Units.sCode sUnitCode,0 bMainOutput,mMRP_RoutingNodes.iBodyId,iProcessId,1 RowId\r\n                                    FROM mMRP_RoutingBOMProduct WITH (READUNCOMMITTED)\r\n                                    INNER JOIN mMRP_RoutingNodes WITH (READUNCOMMITTED) ON mMRP_RoutingNodes.iBodyId=mMRP_RoutingBOMProduct.iBodyId\r\n                                    INNER JOIN mMRP_RoutingHeader WITH (READUNCOMMITTED) ON mMRP_RoutingHeader.iRoutingId=mMRP_RoutingNodes.iHeaderId AND bBOMProcess = 1\r\n                                    INNER JOIN mMRP_BomVariantHeader WITH (READUNCOMMITTED) ON mMRP_BomVariantHeader.iVariantId=mMRP_RoutingHeader.iBomId\r\n                                    INNER JOIN mMrp_Process ON mMrp_Process.iMasterId = mMRP_RoutingNodes.iProcessId \r\n\t\t\t\t\t\t\t\t\tINNER JOIN mCore_Product P  ON mMRP_RoutingBOMProduct.iProductId = P.iMasterId  \r\n\t\t\t\t\t\t\t\t\tINNER JOIN mCore_ProductLanguage PL ON P.iMasterId = PL.iMasterId And  PL.iLanguageId=0\r\n\t\t\t\t\t\t\t\t\tINNER JOIN muCore_Product_Units PU ON PU.iMasterId = P.iMasterId\r\n\t\t\t\t\t\t\t\t\tLEFT JOIN mMrp_bombody BomBody WITH (READUNCOMMITTED) ON  mMRP_RoutingBOMProduct.iProductId =BomBody.iProductId AND BomBody.iVariantId=mMRP_BomVariantHeader.iVariantId\r\n                                    LEFT JOIN mCore_Units ON mCore_Units.iMasterId = CASE WHEN isnull(BomBody.iUnit,0) > 0 THEN BomBody.iUnit ELSE PU.iDefaultBaseUnit END\r\n                                    WHERE  mMRP_RoutingBOMProduct.iBodyId IN( SELECT iBodyId FROM mMRP_RoutingNodes " + empty + " WHERE iHeaderId IN(" + text2 + ")\r\n                                    ) AND fQuantity > 0";
		}
		default:
			return null;
		}
	}

	private string DefaultQCQuery(RepRecord objRec, Database objDb)
	{
		string result = null;
