			break;
		case FocusReport.QCRequsition:
			result = $"Select tQC_RequisitionHeader{Suffix}.iReqHeaderId,PL.sName + '----' + P.sCode Item,sRequisitionNo,tQC_RequisitionHeader{Suffix}.iDate,dQtyAvailable,sVoucherNo,ISNULL(sProdOrderNo,'')sProdOrderNo,ISNULL(mMrp_Process.sName,'') ProcessName,sTestName,\r\n                        case when bClose = 1 then 'Closed' Else 'Pending' End ReqStatus\r\n                        ,Case when isnull(iFinalResult,10) =10 then 'Pending' when isnull(iFinalResult,10) =1 then 'Passed' else 'Failed' End FinalResult \r\n                        ,mPay_Employee.sName AllocatedTo FROM tQC_RequisitionHeader{Suffix}  \r\n                        Join tQC_RequisitionBody{Suffix}  on tQC_RequisitionHeader{Suffix}.iReqHeaderId = tQC_RequisitionBody{Suffix}.iReqHeaderId\r\n                        Join mQC_TestDefinitionHeader  on mQC_TestDefinitionHeader.iTestDefHeaderId = tQC_RequisitionBody{Suffix}.iTestDefHeaderId\r\n                        Join mCore_Product P on tQC_RequisitionHeader{Suffix}.iProductId = P.iMasterId\r\n                        JOIN mCore_ProductLanguage PL ON P.iMasterId = PL.iMasterId And  PL.iLanguageId={objRec.LanguageId}\r\n                        join tCore_Data{Suffix} on tQC_RequisitionHeader{Suffix}.iTransactionId = tCore_Data{Suffix}.iTransactionId\r\n                        Join tCore_Header{Suffix} on tCore_Data{Suffix}.iHeaderId = tCore_Header{Suffix}.iHeaderId\r\n                        Left Join tCore_Header_2{Suffix}  on tCore_Header{Suffix}.iHeaderId = tCore_Header_2{Suffix}.iHeaderId\r\n                        Left join tMrp_ProdOrder{Suffix} with(readuncommitted) on isnull(tCore_Header_2{Suffix}.iProdOrderId,0) = tMrp_ProdOrder{Suffix}.iProdOrderId\r\n                        Left join mMrp_Process  on isnull(tCore_Header_2{Suffix}.iProcessId,0) = mMrp_Process.iMasterId\r\n                        Left join  mPay_Employee  on mPay_Employee.iMasterId = tQC_RequisitionHeader{Suffix}.iFinalResultUser";
			break;
		case FocusReport.QCSampleTesting:
		{
			empty = string.Empty;
			int[] arrIds = (from p in objRec.ReportCustomize.Layout.Columns
				where p.FieldId > 25
				select p.FieldId).ToArray();
			empty = GetProductionExtraFeildsColumnNames(arrIds, 684, objDb);
			result = $"Select  tQC_TestingHeader{Suffix}.iTestHeaderId,PL.sName + '----' + P.sCode Item,sRequisitionNo,tQC_RequisitionHeader{Suffix}.iDate RequsitionDate,AllocatedTo.sName AllocatedTo\r\n                                    ,tQC_TestingHeader{Suffix}.sDocNo,tQC_TestingHeader{Suffix}.iDate TestingDate,dQtyAvailable,sVoucherNo,ISNULL(sProdOrderNo,'')sProdOrderNo,\r\n                                    ISNULL(mMrp_Process.sName,'') ProcessName,sTestName,Case when isnull(tQC_TestingHeader{Suffix}.iFinalResult,10) =10 then 'Pending' when isnull(tQC_TestingHeader{Suffix}.iFinalResult,10) =1 then 'Passed' else 'Failed' End \r\n                                    FinalResult, mQC_QCParameters.sName ParameterName, mQC_TestDefinitionBody.dMinSpec,mQC_TestDefinitionBody.dMaxSpec,mQC_TestDefinitionBody.sPassedFrom,mQC_TestDefinitionBody.sPassedTo,tQC_TestingBody{Suffix}.sValue \r\n                                    ,TestedBy.sName Testedby,ApprovedBy.sName ApprovedBy,case when bClose = 1 then 'Closed' Else 'Pending' End ReqStatus,\r\n                                   \ttCore_Header{Suffix}.iDate iVoucherDate,sVoucherNo VoucherNumber,acc.sName iVendor,vrCore_Account.sName iAccount,tQC_TestingHeader{Suffix}.sNarration Narration \r\n                                    FROM tQC_TestingHeader{Suffix}  \r\n                                    Join tQC_TestingBody{Suffix}   on tQC_TestingHeader{Suffix}.iTestHeaderId = tQC_TestingBody{Suffix}.iTestHeaderId\r\n                                    Join tQC_RequisitionBody{Suffix}  on tQC_RequisitionBody{Suffix}.iReqBodyId = tQC_TestingHeader{Suffix}.iReqBodyId\r\n                                    Join mCore_Product P on tQC_TestingHeader{Suffix}.iProductId = P.iMasterId\r\n                                    JOIN mCore_ProductLanguage PL ON P.iMasterId = PL.iMasterId And  PL.iLanguageId={objRec.LanguageId}\r\n                                    Join tQC_RequisitionHeader{Suffix}  on tQC_RequisitionHeader{Suffix}.iReqHeaderId = tQC_RequisitionBody{Suffix}.iReqHeaderId\r\n                                    Join mQC_TestDefinitionHeader  on mQC_TestDefinitionHeader.iTestDefHeaderId = tQC_RequisitionBody{Suffix}.iTestDefHeaderId\r\n                                    Join mQC_TestDefinitionBody  on mQC_TestDefinitionBody.iTestDefHeaderId = mQC_TestDefinitionHeader.iTestDefHeaderId \r\n                                    And mQC_TestDefinitionBody.iParameterId = tQC_TestingBody{Suffix}.iParameterId\r\n                                    Join mPay_Employee TestedBy  on TestedBy.iMasterId = tQC_TestingBody{Suffix}.iTestedBy\r\n                                    Join mPay_Employee ApprovedBy  on ApprovedBy.iMasterId = tQC_TestingHeader{Suffix}.iApprovedBy\r\n                                    Join mPay_Employee AllocatedTo  on AllocatedTo.iMasterId = tQC_RequisitionBody{Suffix}.iAllotedTo\r\n                                    Join mQC_QCParameters   on mQC_QCParameters.iMasterId = tQC_TestingBody{Suffix}.iParameterId\r\n                                    left join tQC_TestingExtraHeader{Suffix} on tQC_TestingExtraHeader{Suffix}.iTestHeaderId = tQC_TestingHeader{Suffix}.iTestHeaderId\r\n                                    left join tQC_TestingExtraBody{Suffix} on tQC_TestingExtraBody{Suffix}.iTestBodyId = tQC_TestingBody{Suffix}.iTestBodyId\r\n                                    join tCore_Data{Suffix} on tQC_RequisitionHeader{Suffix}.iTransactionId = tCore_Data{Suffix}.iTransactionId\r\n                                    Join tCore_Header{Suffix} on tCore_Data{Suffix}.iHeaderId = tCore_Header{Suffix}.iHeaderId\r\n                                    Left Join tCore_Header_2{Suffix}  on tCore_Header{Suffix}.iHeaderId = tCore_Header_2{Suffix}.iHeaderId\r\n                                    Left join tMrp_ProdOrder{Suffix} with(readuncommitted)  on isnull(tCore_Header_2{Suffix}.iProdOrderId,0) = tMrp_ProdOrder{Suffix}.iProdOrderId\r\n                                    Left join mMrp_Process  on isnull(tCore_Header_2{Suffix}.iProcessId,0) = mMrp_Process.iMasterId\r\n                                    left join mCore_Account acc on acc.iMasterId = tCore_Data{Suffix}.iBookNo\r\n\t\t\t\t\t\t\t\t\tleft  JOIN vrCore_Account ON vrCore_Account.iMasterId = tCore_Data{Suffix}.iCode  And vrCore_Account.iTreeId = 0 \r\n                                    {empty} ";
			break;
		}
		case FocusReport.QCProductMapping:
			result = $"Select b.iTestDefHeaderId,sTestName,PL.sName ProductName,P.sCode ProductCode,InvF.sName FailedWarehouse,InvP.sName PassedWarehouse,Emp.sName AllocatedTo\r\n                                    From mQC_TestDefinitionHeader a \r\n                                    Join mQC_ProductTestMapping b  on a.iTestDefHeaderId = b.iTestDefHeaderId\r\n                                    Join mCore_Product P on b.iProductId= P.iMasterId\r\n                                    JOIN mCore_ProductLanguage PL ON P.iMasterId = PL.iMasterId And  PL.iLanguageId={objRec.LanguageId}\r\n                                    join vmCore_InvTag InvF  on  a.iFailedWarehouse = InvF.iMasterId\r\n                                    join vmCore_InvTag InvP  on  a.iPassedWarehouse = InvP.iMasterId\r\n                                    Join mPay_Employee Emp on  a.iAllottedTo = Emp.iMasterId\r\n                                ";
			break;
		}
		return result;
	}

	private string GetProductionExtraFeildsColumnNames(int[] arrIds, int iReportId, Database objDb)
	{
		try
		{
			string empty = string.Empty;
			string text = string.Empty;
			DbCommand dbCommand = null;
			IDataReader dataReader = null;
			List<ExtraFieldsDetails> list = new List<ExtraFieldsDetails>();
			new Focus.Transactions.BL.Transactions();
			int num = 0;
			switch (iReportId)
			{
			case 650:
				num = 2;
				break;
			case 684:
				num = 12;
				break;
			}
			if (arrIds != null && arrIds.Length != 0)
			{
				empty = $"select id,bHeader,isnull(sName,'') sName,sCaption,iFieldType,iMasterId,sVariableName from mMRP_ExtraFields where iScreenId = {num}";
				dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
				dbCommand.CommandTimeout = 0;
				dataReader = objDb.ExecuteReader(dbCommand);
				while (dataReader.Read())
				{
					ExtraFieldsDetails extraFieldsDetails = new ExtraFieldsDetails();
					extraFieldsDetails.iFieldId = Convert.ToInt32(dataReader["id"]);
					extraFieldsDetails.IsHeader = Convert.ToBoolean(dataReader["bHeader"]);
					extraFieldsDetails.sFieldName = Convert.ToString(dataReader["sName"]);
					extraFieldsDetails.sCaption = Convert.ToString(dataReader["sCaption"]);
					extraFieldsDetails.iFieldType = Convert.ToInt32(dataReader["iFieldType"]);
					extraFieldsDetails.iMasterId = Convert.ToInt32(dataReader["iMasterId"]);
					list.Add(extraFieldsDetails);
				}
				dataReader.Close();
				for (int i = 0; i < list.Count; i++)
				{
					string empty2 = string.Empty;
					if (Convert.ToInt32(list[i].iFieldType) == 12)
					{
						int num2 = Convert.ToInt32(list[i].iMasterId);
						empty = $"select 'vr' + sModule + '_' + sMasterName as ViewName from cCore_MasterDef where iMasterTypeId = {num2}";
						string text2 = Convert.ToString(objDb.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty));
						string text3 = "tbl" + text2;
						if (Convert.ToBoolean(list[i].IsHeader))
						{
							empty2 = ((iReportId != 650) ? "tQC_TestingExtraHeader_0." : "mMRP_BomExtraHeader.");
						}
						else
						{
							empty2 = ((iReportId != 650) ? "tQC_TestingExtraBody_0." : "mMRP_BomExtraBody.");
						}
						text = text + " Left Join " + text2 + " " + text3 + " on " + text3 + ".iMasterId  = " + empty2 + list[i].sFieldName;
					}
				}
			}
			return text;
		}
		catch (Exception ex)
		{
			m_sError = ex.Message;
			return "";
		}
	}

	private void SetFAInvTag(RepRecord objRec)
	{
		m_iStartDate = objRec.StartingDate;
		Dictionary<string, string> dictionary = null;
		if (FConvert.GetInputObject(objRec.Inputs, -11) != null)
		{
			dictionary = (Dictionary<string, string>)FConvert.GetInputObject(objRec.Inputs, -11);
			m_strAuthorized = FConvert.GetNameFromResource(m_strAuthorized, dictionary);
			m_strPending = FConvert.GetNameFromResource(m_strPending, dictionary);
			m_strRejected = FConvert.GetNameFromResource(m_strRejected, dictionary);
			m_strStopped = FConvert.GetNameFromResource(m_strStopped, dictionary);
		}
		string text = null;
		int num = 0;
		int num2 = 0;
		for (int i = 0; i < objRec.ReportCustomize.Layout.Columns.Length; i++)
		{
			if (objRec.ReportCustomize.Layout.Columns[i].DataTypeId == MasterDataType.Fraction && objRec.ReportCustomize.Layout.Columns[i].FieldId != -2)
			{
				if (objRec.ReportCustomize.Layout.Columns[i].ColumnFilter != null && objRec.ReportCustomize.Layout.Columns[i].ColumnFilter.Length != 0)
				{
					if (objRec.ReportCustomize.Layout.Columns[i].ColumnFilter[0].DataType == MasterDataType.Master || objRec.ReportCustomize.Layout.Columns[i].ColumnFilter[0].DataType == MasterDataType.NumberList)
					{
						objRec.ReportCustomize.AdvancedEngine = false;
						break;
					}
					text = filter_string(objRec.ReportCustomize.Layout.Columns[i].ColumnFilter, null, IsUseExactField: false, null, m_iCompId, bCubeReport: true, objRec.ReportId, objRec.Module, (int)objRec.SubReportId);
					if (text.Contains(".iMasterId"))
					{
						if (!text.Contains("Code.iMasterId") && !text.Contains("BookNo.iMasterId"))
						{
							objRec.ReportCustomize.AdvancedEngine = false;
							break;
						}
					}
					else if (text.Contains(".sCode") && (text.Contains("Code.sCode") || text.Contains("BookNo.sCode")))
					{
						objRec.ReportCustomize.AdvancedEngine = false;
						break;
					}
				}
				else if (objRec.ReportCustomize.Layout.Columns[i].SubParentId > 0 && objRec.ReportCustomize.Groupings != null && objRec.ReportCustomize.Groupings.Length != 0)
				{
					objRec.ReportCustomize.AdvancedEngine = false;
					break;
				}
			}
			else
			{
				if (objRec.ReportCustomize.Layout.Columns[i].DataTypeId == MasterDataType.Master && objRec.ReportCustomize.Groupings != null && objRec.ReportCustomize.Groupings.Length != 0)
				{
					objRec.ReportCustomize.AdvancedEngine = false;
					break;
				}
				if (objRec.ReportCustomize.Layout.Columns[i].DataTypeId == MasterDataType.Text && objRec.ReportCustomize.Groupings != null && objRec.ReportCustomize.Groupings.Length != 0)
				{
					num = objRec.ReportCustomize.Layout.Columns[i].FieldId;
					num2 = RDCommon.GetSubFieldId(ref num);
					if (num == 2 && num2 >= 1 && num2 <= 7)
					{
						objRec.ReportCustomize.AdvancedEngine = false;
						break;
					}
				}
			}
			if ((objRec.ReportCustomize.Layout.Columns[i].FieldId & 0xFF0000) >> 16 == 128 || (objRec.ReportCustomize.Layout.Columns[i].FieldId & 0xFF0000) >> 16 == 131 || (objRec.ReportCustomize.Layout.Columns[i].FieldId & 0xFF0000) >> 16 == 132)
			{
				objRec.ReportCustomize.AdvancedEngine = false;
				break;
			}
		}
	}

	public string GetQueryFromReportId(ref RepRecord objRec, Database objDb, int iCompId, ref StandardQuery oQuery, string sUniqueId, bool bPreviousYear = false)
	{
		int num = 0;
