				if (objRec.ReportId == 8502)
				{
					for (int i = 0; i < arrMasters?.Count; i++)
					{
						int iD = arrMasters[i].ID;
						if (iD != 800 && (uint)(iD - 1100) > 1u && iD != 1106)
						{
							arrMasters.RemoveAt(i);
							i--;
						}
					}
					for (int j = 0; j < arrMasterField?.Count; j++)
					{
						int iD = arrMasterField[j].SubParentId;
						if (iD != 800 && (uint)(iD - 1100) > 1u && iD != 1106)
						{
							arrMasterField.RemoveAt(j);
							j--;
