			if (FConvert.IsItSales((int)objRec.ReportId) && objRec.Module != Module.CoreMasters)
			{
				m_arrDefualtTables.Add($"tCore_Indta{suffix}");
			}
			break;
		}
		if (objRec.ReportId >= RDCommon.RD_STARTID)
		{
			bool bPendingLink = false;
			int iTagId = 0;
			string text2 = primary_key(objRec.ReportCustomize.ReportType, objRec.ReportCustomize.DataSourceType, objRec.ReportCustomize.Layout.Columns, objRec.ReportCustomize.Groupings);
			m_arrDefualtTables.AddRange(string.Format("tCore_Header{0},tCore_Data{0},tCore_Indta{0},cCore_Vouchers{0},vrCore_Product", suffix).Split(','));
