		if (bPreviousYear && (objRec.Module != Module.None || (objRec.SubReportId != 3 && objRec.SubReportId != 2)) && objRec.ReportId != 601 && objRec.ReportId != 624)
		{
			for (num = 0; num < arrColumns.Count; num++)
			{
