			}
			strJoinQuery = strJoinQuery.Replace(suffix, m_strPrevYearSuffix);
		}
		if (IsAccountItemParam(objRec))
		{
			strJoinQuery += "--@EXTRA_TABLES";
		}
		(from p in arrColumns.Distinct()
			where p.Length > 0
			select p).ToArray();
		if (objRec.ExtraColumns != null)
		{
			List<IdNamePair> arrTransactionFormula = null;
			RDConversion rDConversion = new RDConversion();
			EXTRAFORMULACOLUMNS = 0;
			for (num = 0; num < objRec.ExtraColumns.Length; num++)
