				{
					if (arrColumns.Where((string p) => p == Convert.ToString(arrTransactionFormula[i].Tag)).Count() == 0)
					{
						arrColumns.Add(Convert.ToString(arrTransactionFormula[i].Tag));
						EXTRAFORMULACOLUMNS++;
					}
				}
			}
		}
		return arrColumns.ToArray();
	}

