				strTranHeaderDocsColumns = ((objRec.ReportId != 500 && objRec.ReportId != 501) ? ("LEFT JOIN \r\n                            (\r\n                                " + text + "\r\n                            )vCore_TranHeaderDocs" + Suffix + " ON vCore_TranHeaderDocs" + Suffix + ".iHeaderId = tCore_Header" + Suffix + ".iHeaderId") : ("LEFT JOIN \r\n                            (\r\n                                " + text + "\r\n                            )vCore_TranHeaderDocs" + Suffix + " ON vCore_TranHeaderDocs" + Suffix + ".iHeaderId = tCore_Data" + Suffix + ".iHeaderId"));
				strJoinQuery = strJoinQuery.Replace("@TRAN_HEADERDOCS_COLUMNS", strTranHeaderDocsColumns);
			}
		}
		if (!string.IsNullOrEmpty(strTranBodyDocsColumns) && strJoinQuery.Contains("@TRAN_DATADOCS_COLUMNS"))
		{
			list2.Clear();
			array = strTranBodyDocsColumns.Split(',');
			for (num4 = 0; num4 < array.Length; num4++)
			{
				if (!string.IsNullOrEmpty(array[num4]))
				{
					list2.Add(array[num4]);
				}
			}
			if (arrFilterFields != null)
			{
				for (num4 = 0; num4 < arrFilterFields.Length; num4++)
				{
					if (arrFilterFields[num4].FieldName != null && arrFilterFields[num4].FieldName.StartsWith("vCore_TranData" + Suffix))
					{
						array = arrFilterFields[num4].FieldName.Split('.');
						list2.Add(array[1]);
					}
				}
			}
			text = CreateTranDocsViewHeader(objRec, voucherTypeForReport, bClassType, list2.Distinct().ToList(), objDb, bHeader: false, m_iCompId);
			if (!string.IsNullOrEmpty(text))
			{
				strTranBodyDocsColumns = "LEFT JOIN \r\n                        (\r\n                            " + text + "\r\n                        )vCore_TranDataDocs" + Suffix + " ON vCore_TranDataDocs" + Suffix + ".iBodyId = tCore_Data" + Suffix + ".iBodyId";
				strJoinQuery = strJoinQuery.Replace("@TRAN_DATADOCS_COLUMNS", strTranBodyDocsColumns);
			}
		}
		if (!string.IsNullOrEmpty(strTranAllDataColumns) && strJoinQuery.Contains("@TRAN_ALLDATA_COLUMNS"))
		{
			list2.Clear();
			array = strTranAllDataColumns.Split(',');
			for (num4 = 0; num4 < array.Length; num4++)
			{
				if (!string.IsNullOrEmpty(array[num4]))
				{
					list2.Add(array[num4]);
				}
			}
			if (arrFilterFields != null)
			{
				for (num4 = 0; num4 < arrFilterFields.Length; num4++)
				{
					if (arrFilterFields[num4].FieldName != null && arrFilterFields[num4].FieldName.StartsWith("vCore_TranData" + Suffix))
					{
						array = arrFilterFields[num4].FieldName.Split('.');
						list2.Add(array[1]);
					}
				}
			}
			text = CreateTranDataViewOriginal(objRec, voucherTypeForReport, bClassType, list2.Distinct().ToList(), objDb, m_iCompId);
			if (!string.IsNullOrEmpty(text))
			{
				strTranAllDataColumns = "LEFT JOIN \r\n                        (\r\n                            " + text + "\r\n                        )vCore_TranAllData" + Suffix + " ON vCore_TranAllData" + Suffix + ".iBodyId = tCore_Data" + Suffix + ".iBodyId";
				strJoinQuery = strJoinQuery.Replace("@TRAN_ALLDATA_COLUMNS", strTranAllDataColumns);
			}
		}
		if (string.IsNullOrEmpty(strScreenDataColumns) || !strJoinQuery.Contains("@SCREEN_DATA_COLUMNS"))
		{
			return;
		}
		list2.Clear();
		strScreenDataColumns = strScreenDataColumns.Replace("[", "");
		strScreenDataColumns = strScreenDataColumns.Replace("]", "");
		array = strScreenDataColumns.Split(',');
		for (num4 = 0; num4 < array.Length; num4++)
		{
			if (!string.IsNullOrEmpty(array[num4]))
			{
				list2.Add(array[num4]);
			}
		}
		if (arrFilterFields != null)
		{
			for (num4 = 0; num4 < arrFilterFields.Length; num4++)
			{
				if (arrFilterFields[num4].FieldName != null && arrFilterFields[num4].FieldName.StartsWith("vCore_BodyScreenData" + Suffix))
				{
					array = arrFilterFields[num4].FieldName.Split('.');
					list2.Add(array[1]);
					flag2 = true;
				}
			}
		}
		if (!m_bCallingFromBI && !flag2)
		{
			string[] arrScreenColumns = CreateScreenDataViewColumnOnly(objRec.Module, voucherTypeForReport, voucherTypeForReport2, list2.Distinct().ToList(), objDb, objRec, m_iCompId);
			updateScreenDataColumns(arrScreenColumns, ref arrColumns);
			strJoinQuery = strJoinQuery.Replace("@SCREEN_DATA_COLUMNS", string.Format("LEFT JOIN tCore_IndtaBodyScreenData{0} ON tCore_IndtaBodyScreenData{0}.iBodyId = tCore_Data{0}.iBodyId", Suffix));
			return;
		}
		text = CreateScreenDataView(objRec.Module, voucherTypeForReport, voucherTypeForReport2, list2.Distinct().ToList(), objDb, objRec, m_iCompId);
		if (!string.IsNullOrEmpty(text))
		{
			strScreenDataColumns = "LEFT JOIN \r\n                            (\r\n                                " + text + "\r\n                            )vCore_BodyScreenData" + Suffix + " ON vCore_BodyScreenData" + Suffix + ".iBodyId = tCore_Data" + Suffix + ".iBodyId";
			strJoinQuery = strJoinQuery.Replace("@SCREEN_DATA_COLUMNS", strScreenDataColumns);
		}
	}

	private void updateScreenDataColumns(string[] arrScreenColumns, ref List<string> arrColumns)
	{
		string[] array = null;
		int num = 0;
		int num2 = 0;
		for (num2 = 0; num2 < arrColumns.Count; num2++)
		{
			if (!arrColumns[num2].StartsWith($"vCore_BodyScreenData{Suffix}."))
			{
				continue;
			}
			for (num = 0; num < arrScreenColumns.Length; num++)
			{
				array = arrColumns[num2].Split(new char[1] { '.' }, 2);
				if (array.Length >= 2 && arrScreenColumns[num].Contains(array[1]))
				{
					arrColumns[num2] = arrScreenColumns[num].Replace(array[1], string.Empty);
					break;
				}
			}
		}
	}

	public string UnionSubQuery(RepRecord objRec, string strQuery, string strExtraColumnAlias, string strExtraColumnFormula)
	{
		switch ((FocusReport)objRec.ReportId)
		{
		case FocusReport.StockAnalysisbyBatch:
			if (!string.IsNullOrEmpty(strExtraColumnFormula) && strExtraColumnFormula != strExtraColumnAlias)
			{
				strQuery = strQuery.Insert(0, "SELECT [iHeaderId],[sBatchNo], SUM([fQuantity])[fQuantity], \r\n                        AVG(mRate)[mRate], SUM([StockValue])[StockValue], [iExpiryDate], [iMfDate],SUM([fAlternateQty])[fAlternateQty]\r\n                        ,AVG([OrigRate])[OrigRate],SUM([ReservedQty])[ReservedQty]" + strExtraColumnFormula + " FROM(");
				strQuery = strQuery + ")TempTable GROUP BY [iHeaderId],[sBatchNo],[iExpiryDate], [iMfDate]" + strExtraColumnAlias + " HAVING SUM([fQuantity]) <> 0";
			}
			else
			{
				strQuery = strQuery.Insert(0, "SELECT [iHeaderId],[sBatchNo], SUM([fQuantity])[fQuantity], \r\n                        AVG(mRate)[mRate], SUM([StockValue])[StockValue], [iExpiryDate], [iMfDate],SUM([fAlternateQty])[fAlternateQty]\r\n                        ,AVG([OrigRate])[OrigRate],SUM([ReservedQty])[ReservedQty] " + strExtraColumnAlias + " FROM(");
				strQuery = strQuery + ")TempTable GROUP BY [iHeaderId],[sBatchNo],[iExpiryDate], [iMfDate]" + strExtraColumnAlias + " HAVING SUM([fQuantity]) <> 0";
			}
			break;
		case FocusReport.StockBalanceByWarehouse:
			strQuery = strQuery.Insert(0, "SELECT [iMasterId], [Particular], SUM([Quantity])[Quantity], \r\n                    AVG([Reserved Quantity])[Reserved Quantity], SUM([Net Quantity])[Net Quantity],[Product],[Warehouse] " + strExtraColumnAlias + " FROM(");
			strQuery = strQuery + ")TempTable GROUP BY [iMasterId], [Particular], [Product],[Warehouse] " + strExtraColumnAlias + " HAVING SUM([Quantity]) <> 0";
			break;
		case FocusReport.StockBalanceByBins:
			strQuery = strQuery.Insert(0, "SELECT iMasterId, [Particular], [Expiry Date], [Manufacturing Date], \r\n                    SUM ([Quantity])[Quantity], AVG([Reserved Quantity])[Reserved Quantity], SUM([Net Quantity])[Net Quantity],[Product] " + strExtraColumnAlias + " FROM(");
			strQuery = strQuery + ")TempTable GROUP BY iMasterId, [Particular], [Expiry Date], [Manufacturing Date], [Product] " + strExtraColumnAlias + " HAVING SUM([Quantity]) <> 0";
			break;
		case FocusReport.StockBalanceByProductByBins:
			strQuery = strQuery.Insert(0, "SELECT TempTable.iMasterId, [Item Name], [Expiry Date], [Manufacturing Date], SUM ([Quantity])[Quantity], \r\n                    AVG([Reserved Quantity])[Reserved Quantity], 0[On-Hold Quantity], SUM([Net Quantity])[Net Quantity], [Product] " + strExtraColumnAlias + " FROM(");
			strQuery = strQuery + ")TempTable GROUP BY TempTable.iMasterId, [Item Name], [Expiry Date], [Manufacturing Date], [Product] " + strExtraColumnAlias + " HAVING SUM([Quantity]) <> 0";
			break;
		case FocusReport.StockBalanceByProduct:
			strQuery = strQuery.Insert(0, "SELECT TempTable.iMasterId, [Particular], [Expiry Date], [Manufacturing Date], \r\n                    SUM ([Quantity])[Quantity], AVG([Reserved Quantity])[Reserved Quantity], SUM([Net Quantity])[Net Quantity],[Product] " + strExtraColumnAlias + " FROM(");
			strQuery = strQuery + ")TempTable GROUP BY TempTable.iMasterId, [Particular], [Expiry Date], [Manufacturing Date], [Product] " + strExtraColumnAlias + " HAVING SUM([Quantity]) <> 0";
			break;
		case FocusReport.ExpiredStockByBins:
			strQuery = strQuery.Insert(0, "SELECT TempTable.iMasterId, [Item Name], [Expiry Date], [Manufacturing Date],\r\n                        SUM([Quantity])[Quantity], AVG([Reserved Quantity])[Reserved Quantity], 0[On-Hold Quantity], SUM([Net Quantity])[Net Quantity],[Product] " + strExtraColumnAlias + " FROM(");
			strQuery = strQuery + ")TempTable GROUP BY TempTable.iMasterId, [Item Name], [Expiry Date], [Manufacturing Date], [Product] " + strExtraColumnAlias + " HAVING SUM([Quantity]) <> 0";
			break;
		case FocusReport.VirtualStockAnalysis:
			strQuery = strQuery.Insert(0, "SELECT TempTable.iMasterId, [Item Name],SUM([Stock Balance])[Stock Balance],SUM([Pending sales orders])[Pending sales orders],SUM([Pending purchases orders])[Pending purchases orders],SUM([Reserved stock])[Reserved stock],SUM([Virtual stock])[Virtual stock] " + strExtraColumnAlias + " FROM(");
			strQuery = strQuery + ")TempTable GROUP BY TempTable.iMasterId, [Item Name] " + strExtraColumnAlias + " ";
			break;
		case FocusReport.StockAnalysisbyRMA:
			strQuery = strQuery.Insert(0, "SELECT [iHeaderId],sRmaNo,SUM(fQuantity)[fQuantity],AVG(mRate)[mRate],AVG([StockValue])[StockValue] " + strExtraColumnAlias + " FROM(");
			strQuery = strQuery + ")TempTable GROUP BY [iHeaderId],sRmaNo " + strExtraColumnAlias + " HAVING SUM(fQuantity) <> 0 ";
			break;
		}
		return strQuery;
	}

	private string DefualtQuery(RepRecord objRec, FieldData[] arrFields, Database objDb, ref string strSecurityFilter, ref string strJoinQuery, bool bPreviousYear, string[] arrExtraColumns, FieldData[] arrFilterFields, int iCompanyId, string sUniqueId)
	{
		string text = string.Empty;
		string text2 = null;
		if (objRec.ReportId >= RDCommon.RD_STARTID)
		{
			bool flag = General.IsAccountingTransaction(objRec.ReportCustomize.TransactionSets, objRec.Module, objRec.ReportId) > 0;
			bool bPendingLink = false;
			int iTagId = 0;
			string text3 = primary_key(objRec.ReportCustomize.ReportType, objRec.ReportCustomize.DataSourceType, objRec.ReportCustomize.Layout.Columns, objRec.ReportCustomize.Groupings);
			string text4 = (IsInventorySet((m_arrBaseTranSet != null && m_arrBaseTranSet.Length != 0) ? m_arrBaseTranSet : objRec.ReportCustomize.TransactionSets) ? "" : " LEFT");
			applyDetailRowGrouping(objRec.ReportCustomize, text3);
			if (objRec.ReportCustomize.ReportType == ReportType.Cubes && (text3.Contains(".iMasterId") || text3 == "-1[iHeaderId]") && objRec.ReportCustomize.AdvancedEngine && !flag)
			{
				text = ApplyGroupByonCube(objRec, objDb, arrFields, text3, text4, ref strJoinQuery, ref arrExtraColumns);
			}
			if (string.IsNullOrEmpty(text))
			{
				if (flag)
				{
					string text5 = null;
					_Filter[] filterSource = objRec.FilterSource;
					_Filter[] filters = objRec.ReportCustomize.Filters;
					objRec.FilterSource = null;
					objRec.ReportCustomize.Filters = null;
					text5 = GetRD_filter_condition(objRec, objDb, m_iCompId);
					text5 = text5.Replace("--@EXTRA_TABLES", "");
					objRec.FilterSource = filterSource;
					objRec.ReportCustomize.Filters = filters;
					text = string.Format("SELECT {2}\r\n                        FROM tCore_Header{0} \r\n                        JOIN {1} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                        JOIN cCore_Vouchers{0} ON cCore_Vouchers{0}.iVoucherType = tCore_Header{0}.iVoucherType\r\n                        {3} JOIN tCore_Indta{0} ON tCore_Indta{0}.iBodyId = tCore_Data{0}.iBodyId", Suffix, GetDataFATable(text5, m_iCompId), text3, text4);
				}
				else
				{
					text = "SELECT " + text3 + " FROM tCore_Header" + Suffix + " \r\n                        JOIN tCore_Data" + Suffix + " ON tCore_Data" + Suffix + ".iHeaderId = tCore_Header" + Suffix + ".iHeaderId\r\n                        JOIN cCore_Vouchers" + Suffix + " ON cCore_Vouchers" + Suffix + ".iVoucherType = tCore_Header" + Suffix + ".iVoucherType\r\n                        " + text4 + " JOIN tCore_Indta" + Suffix + " ON tCore_Indta" + Suffix + ".iBodyId = tCore_Data" + Suffix + ".iBodyId";
				}
				if (objRec.ReportCustomize.AdvancedEngine)
				{
					text2 = getMasterInnerQuery(2, "vrCore_Product");
					text = (string.IsNullOrEmpty(text2) ? (text + getMasterJoin(2, "vrCore_Product", $"tCore_Indta{Suffix}.iProduct", text4)) : (text + string.Format(" {2} JOIN ({1}) vrCore_Product ON vrCore_Product.iMasterId = tCore_Indta{0}.iProduct ", Suffix, text2, text4)));
				}
				else
				{
					text += getMasterJoin(2, "vrCore_Product", $"tCore_Indta{Suffix}.iProduct", text4);
				}
			}
			if (text3.Contains("Code."))
			{
				if (objRec.ReportCustomize.AdvancedEngine)
				{
					text2 = getMasterInnerQuery(1, "vrCore_Account");
					if (!string.IsNullOrEmpty(text2))
					{
						text += string.Format(" JOIN ({1}) Code ON Code.iMasterId = tCore_Data{0}.iCode AND Code.iTreeId = 0 ", Suffix, text2);
					}
				}
				else
				{
					text += $" JOIN vrCore_Account Code ON Code.iMasterId = tCore_Data{Suffix}.iCode AND Code.iTreeId = 0";
				}
			}
			else if (text3.Contains("BookNo."))
			{
				if (objRec.ReportCustomize.AdvancedEngine)
				{
					text2 = getMasterInnerQuery(1, "vrCore_Account");
					if (!string.IsNullOrEmpty(text2))
					{
						text += string.Format(" JOIN ({1}) BookNo ON BookNo.iMasterId = tCore_Data{0}.iBookNo AND BookNo.iTreeId = 0 ", Suffix, text2);
					}
				}
				else
				{
					text += $" JOIN vrCore_Account BookNo ON BookNo.iMasterId = tCore_Data{Suffix}.iBookNo AND BookNo.iTreeId = 0";
				}
			}
			if (IsTagwiseTransaction(objRec, ref bPendingLink, ref iTagId) && iTagId > 0)
			{
				text = text + " LEFT JOIN tCore_Data_Tags" + Suffix + " ON tCore_Data_Tags" + Suffix + ".iBodyId = tCore_Data" + Suffix + ".iBodyId ";
			}
			if (bPendingLink)
			{
				text = text + " LEFT JOIN tCore_Links" + Suffix + " ON tCore_Links" + Suffix + ".iTransactionId = tCore_Data" + Suffix + ".iTransactionId";
			}
			return text;
		}
		if (objRec.ReportId == 657)
		{
			objRec.Module = Module.None;
			objRec.SubReportId = 2u;
			TranHomeFilterData tranHomeFilterData = new TranHomeFilterData();
			tranHomeFilterData.Date = new Date().GetToday(_focus.company(m_iCompId).calType).Value;
			tranHomeFilterData.VoucherType = objRec.Code & 0xFFFF;
			tranHomeFilterData.BaseVoucherType = objRec.Code / 65535;
			tranHomeFilterData.KeyField = 3;
			tranHomeFilterData.UserId = objRec.UserId;
			List<IdValuePair> list = new List<IdValuePair>();
			if (objRec.Inputs != null && objRec.Inputs.Length != 0)
			{
				list.AddRange(objRec.Inputs);
			}
			list.Insert(0, new IdValuePair(0, tranHomeFilterData));
			objRec.Inputs = list.ToArray();
		}
		return objRec.Module switch
		{
			Module.CoreTransactions => DefaultFAQuery(objRec, arrFields, objDb, ref strSecurityFilter, strJoinQuery, iCompanyId, sUniqueId, bPreviousYear, arrExtraColumns), 
			Module.Inventory => DefaultInventoryQuery(objRec, objDb, strSecurityFilter, bPreviousYear), 
			Module.POS => DefaultPOSQuery(objRec, objDb), 
			Module.FixAssets => DefaultFixAssetQuery(objRec, objDb), 
			Module.Production => DefaultProductionQuery(objRec, objDb), 
			Module.Quality => DefaultQCQuery(objRec, objDb), 
			_ => DefaultTranQuery(objRec, objDb, bPreviousYear, arrFields, arrExtraColumns, strSecurityFilter, arrFilterFields), 
		};
	}

	private string InsertExtraColumn(string strQuery, ref string[] arrColumns, FieldData[] arrExtraFields, RepRecord objRec, ref string strExtraColumnAlias)
	{
		int num = -1;
		int num2 = 0;
		List<string> list = null;
		string text = null;
		string text2 = null;
		string text3 = null;
		bool flag = false;
		bool flag2 = false;
		bool bClassType = false;
		bool bSummary = true;
		if (objRec.Module == Module.None)
		{
			CustomizeColumn customizeColumn = (CustomizeColumn)objRec.SubReportId;
			if (customizeColumn == CustomizeColumn.HomePage || customizeColumn == CustomizeColumn.PendingBills || customizeColumn == CustomizeColumn.Drafts)
			{
				if ((byte)objRec.SubReportId == 1)
				{
					m_arrLinkId = IsLinkField(objRec);
				}
				bSummary = (m_arrLinkId != null && m_arrLinkId.Length != 0) || IsFractionBodyFieldCustomize(objRec, arrExtraFields);
			}
		}
		GetVoucherTypeForReport(objRec, bDontFetchVoucher: false, ref bClassType);
		num = strQuery.IndexOf("FROM ");
		if (num > 0)
		{
			if (m_bDetailRowGrouping)
			{
				string text4 = primary_key(objRec.ReportCustomize.ReportType, objRec.ReportCustomize.DataSourceType, objRec.ReportCustomize.Layout.Columns, objRec.ReportCustomize.Groupings);
				if (text4 != "-1[iHeaderId]")
				{
					strExtraColumnAlias = text4;
				}
			}
			flag = objRec.ReportCustomize.ReportType == ReportType.Cubes;
			flag2 = objRec.ReportId >= RDCommon.RD_STARTID;
			list = new List<string>();
			for (num2 = 0; num2 < arrColumns.Length; num2++)
			{
				if (arrColumns[num2].Length <= 0)
				{
					continue;
				}
				if (num2 < arrExtraFields.Length)
				{
					if (!flag)
					{
						text2 = GetColumnFunction(objRec, arrExtraFields[num2]);
					}
					else if (m_bDetailRowGrouping)
					{
						text2 = GetColumnFunction(objRec, arrExtraFields[num2], bSummary: true);
					}
					text3 = arrColumns[num2].Replace("[", "");
					text3 = text3.Replace("]", "");
					text3 = ((text3.Contains("dbo.") || text3.Contains("CASE WHEN") || text3.Contains("ISNULL")) ? $"ColumnId{num2}" : text3);
					if ((!string.IsNullOrEmpty(text2) || IsSummarizeReport(objRec)) && num2 < arrExtraFields.Length && (arrExtraFields[num2].DataType == MasterDataType.Fraction || text2 == "MAX"))
					{
						if ((m_bDetailRowGrouping && arrColumns[num2] == "'0'") || (arrExtraFields[num2].FieldId == -2 && arrColumns[num2].Length < 5))
						{
							text = string.Format(",0[FORMULA-{1}] ", arrColumns[num2], num2);
							if (m_bClosed)
							{
								m_strExtraColumnsWithFormula += text;
							}
							if (flag2)
							{
								list.Add(arrColumns[num2]);
							}
						}
						else
						{
							if (string.IsNullOrEmpty(text2))
							{
								text2 = GetColumnFunction(objRec, arrExtraFields[num2], bSummary);
							}
							if (objRec.Module == Module.None && arrExtraFields.Length == 1 && arrExtraFields[0].FieldId == 171)
							{
								text2 = null;
							}
							text = string.Format(",{3}({0})[{1}{2}] ", arrColumns[num2], text3, num2, text2);
							if (flag2)
							{
								list.Add(arrColumns[num2]);
							}
						}
					}
					else
					{
						if (m_bDetailRowGrouping)
						{
							if (arrColumns[num2] == "tCore_Header" + Suffix + ".sVoucherNo" && bClassType && objRec.ReportId >= RDCommon.RD_STARTID)
							{
								strExtraColumnAlias += string.Format("{0}{1}, cCore_Vouchers{2}.sAbbr ", string.IsNullOrEmpty(strExtraColumnAlias) ? string.Empty : ",", arrColumns[num2], Suffix);
							}
							else if (arrColumns[num2] != "'0'" && !arrColumns[num2].Contains("ROW_NUMBER()"))
							{
								strExtraColumnAlias += string.Format("{0}{1} ", string.IsNullOrEmpty(strExtraColumnAlias) ? string.Empty : ",", arrColumns[num2]);
							}
						}
						else
						{
							strExtraColumnAlias += $",[{text3}{num2}] ";
						}
						if (m_bClosed)
						{
							m_strExtraColumnsWithFormula += $",[{text3}{num2}] ";
						}
						if (objRec.ReportId == 581 && (arrColumns[num2].Contains($"tCore_Header{Suffix}") || arrColumns[num2].Contains($"tCore_Data{Suffix}")))
						{
							text = ((arrExtraFields[num2].DataType != MasterDataType.Boolean) ? $",MAX({arrColumns[num2]})[{text3}{num2}] " : $",MAX(CASE WHEN {arrColumns[num2]} = 1 THEN 1 ELSE 0 END)[{text3}{num2}] ");
						}
						else
						{
							text = ((!(arrColumns[num2] == "tCore_Header" + Suffix + ".sVoucherNo") || !bClassType || objRec.ReportId < RDCommon.RD_STARTID) ? $",{arrColumns[num2]}[{text3}{num2}] " : string.Format(",cCore_Vouchers{3}.sAbbr+':'+{0}[{1}{2}] ", arrColumns[num2], text3, num2, Suffix));
							list.Add(arrColumns[num2]);
						}
					}
				}
				else
				{
					text3 = $"{arrColumns[num2]}";
					if (m_bDetailRowGrouping)
					{
						strExtraColumnAlias += string.Format("{0}{1} ", string.IsNullOrEmpty(strExtraColumnAlias) ? string.Empty : ",", arrColumns[num2]);
					}
					else
					{
						strExtraColumnAlias += $",[{text3}{num2}] ";
					}
					if (m_bClosed)
					{
						m_strExtraColumnsWithFormula += $",[{text3}{num2}] ";
					}
					text = $",{arrColumns[num2]}[{text3}{num2}] ";
					list.Add(arrColumns[num2]);
				}
				strQuery = strQuery.Insert(num, text);
				num += text.Length;
			}
			arrColumns = list.ToArray();
			if (!string.IsNullOrEmpty(m_sLinkColumns))
			{
				strQuery = strQuery.Insert(num, m_sLinkColumns);
			}
		}
		return strQuery;
	}

	private bool IsCustomerReport(RepRecord objRec)
	{
		switch ((FocusReport)objRec.ReportId)
		{
		case FocusReport.CustomerBillwiseSummary:
		case FocusReport.CustomerListingofOutstandingBills:
		case FocusReport.CustomerStatements:
		case FocusReport.CustomerDueDateAnalysis:
		case FocusReport.CustomerAgeingSummaryBillwise:
		case FocusReport.CustomerAgeingDetailsBillwise:
		case FocusReport.CustomerDetailAgeingByDueDate:
		case FocusReport.CustomerSummaryAgeingByDueDate:
		case FocusReport.CustomerOverdueAnalysis:
		case FocusReport.CustomerOverdueSummary:
			return true;
		case FocusReport.VendorListingofOutstandingBills:
		case FocusReport.VendorStatements:
		case FocusReport.VendorDueDateAnalysis:
		case FocusReport.VendorAgeingSummaryBillwise:
		case FocusReport.VendorAgeingDetailsBillwise:
		case FocusReport.VendorDetailAgeingByDueDate:
		case FocusReport.VendorSummaryAgeingByDueDate:
		case FocusReport.VendorOverdueAnalysis:
		case FocusReport.VendorOverdueSummary:
		case FocusReport.VendorBillwiseSummary:
			return false;
		default:
			return false;
		}
	}

