		string result = $" AND tCore_Data{Suffix}.bSuspendUpdateStocks <> 1";
		if (FConvert.GetInputValue(arrInputs, 4) == 1)
		{
			result = string.Format(" AND (tCore_Data{0}.bSuspendUpdateStocks <> 1 OR (tCore_Indta{0}.iQCStatus = 1 AND tCore_Data{0}.iAuthStatus = 1))", Suffix);
		}
		return result;
	}

