	private void applyDetailRowGrouping(_Reports oData, string strPK)
	{
		m_bDetailRowGrouping = !strPK.Contains(".iBodyId");
		if (!m_bDetailRowGrouping)
		{
			return;
		}
		int num = 0;
		for (num = 0; num < oData.Layout.Columns.Length; num++)
		{
			if (oData.Layout.Columns[num].ColumnFilter != null && oData.Layout.Columns[num].ColumnFilter.Length != 0)
			{
				m_bDetailRowGrouping = false;
				break;
			}
		}
		for (num = 0; num < oData.Groupings.Length; num++)
		{
			if (oData.Groupings[num].FieldId == 1 || oData.Groupings[num].FieldId == 175)
			{
				m_bVoucherSequence = true;
			}
		}
	}

	private string getUserVoucherFilter(int iUserId, int iCompanyId)
	{
		string text = null;
		IDataReader dataReader = null;
		List<string> list = null;
		text = string.Format("SELECT mCore_Menu.iTypeId FROM\r\n            ( \r\n                SELECT iMenuId FROM mSec_ProfileDetails WITH (READUNCOMMITTED)\r\n                WHERE iProfileId IN \r\n                (\r\n                    SELECT iProfileId FROM mSec_RolesProfiles WITH (READUNCOMMITTED) \r\n                    JOIN mSec_Users_Roles WITH (READUNCOMMITTED) ON mSec_Users_Roles.iERPRole = mSec_RolesProfiles.iRoleId \r\n                    WHERE mSec_Users_Roles.iUserId = {0} and mSec_Users_Roles.iYearId = {1}\r\n                )\r\n                UNION \r\n                SELECT iMenuId FROM mSec_RolesExtraRights WITH (READUNCOMMITTED) \r\n                JOIN mSec_Users_Roles WITH (READUNCOMMITTED) ON mSec_Users_Roles.iERPRole = mSec_RolesExtraRights.iRoleId \r\n                WHERE mSec_Users_Roles.iUserId = {0} AND mSec_Users_Roles.iYearId = {1} AND bAdd = 1 \r\n                EXCEPT \r\n                SELECT iMenuId FROM mSec_RolesExtraRights WITH (READUNCOMMITTED)  \r\n                JOIN mSec_Users_Roles WITH (READUNCOMMITTED) ON mSec_Users_Roles.iERPRole = mSec_RolesExtraRights.iRoleId \r\n                WHERE mSec_Users_Roles.iUserId = {0} AND mSec_Users_Roles.iYearId = {1} AND bAdd = 0\r\n            ) AS RightsTable\r\n            JOIN mCore_Menu WITH (READUNCOMMITTED) ON mCore_Menu.iMenuId = RightsTable.iMenuId\r\n            WHERE mCore_Menu.iType = 1 AND mCore_Menu.iMenuId > 255", iUserId, FConvert.GetYearId(iCompanyId));
		list = new List<string>();
		using (DbCommand command = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text))
		{
			dataReader = m_objDatabase.ExecuteReader(command);
			while (dataReader.Read())
			{
				list.Add(Convert.ToString(dataReader[0]));
			}
			dataReader.Close();
		}
		if (list.Count <= 0)
		{
			return string.Empty;
		}
		return string.Join(",", list);
	}

	private string GetDataFATable(string sBaseFilter, int iCompanyId)
	{
		string text = string.Empty;
		string suffix = FConvert.GetSuffix(iCompanyId);
		if (!string.IsNullOrEmpty(sBaseFilter))
		{
			text += string.Format(" JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId {1}", suffix, sBaseFilter);
		}
		return string.Format("\r\n            (\r\n                SELECT iBodyId, tCore_Data{0}.iHeaderId, iTransactionId, iSerialNo, iCode, iBookNo, iFaTag, iInvTag, mAmount1[mAmount2],\r\n                mOriginalAmount, iDueDate, bSuspendUpdateStocks, bSuspendUpdateFA, bSuspendLinkSaved, bSuspendBaseSaved,\r\n                bSuspendReservation, bChecked, bSpecialMeaning, bBrs, bPdc, bCOGS, bForexFlux, iType, iAuthStatus, bVoid,\r\n                bPnL, iMainBodyId, iLocationId, bFreeQty, bPDCDisc, iInvSettingTag, mAmount3, tCore_Data{0}.bUpdateFA, iCurrencyId\r\n                FROM tCore_Data{0} \r\n                {1}\r\n                UNION ALL\r\n                SELECT iBodyId, tCore_Data{0}.iHeaderId, iTransactionId, iSerialNo, iBookNo[iCode],iCode, iFaTag, iInvTag, mAmount2,\r\n                mOriginalAmount, iDueDate, bSuspendUpdateStocks, bSuspendUpdateFA, bSuspendLinkSaved, bSuspendBaseSaved,\r\n                bSuspendReservation, bChecked, bSpecialMeaning, bBrs, bPdc, bCOGS, bForexFlux, iType, iAuthStatus, bVoid,\r\n                bPnL, iMainBodyId, iLocationId, bFreeQty, bPDCDisc, iInvSettingTag, mAmount3, tCore_Data{0}.bUpdateFA, iCurrencyId\r\n                FROM tCore_Data{0} \r\n                {1}\r\n            )tCore_Data{0}", suffix, text);
	}

	private string ReplaceGlobalValues(RepRecord objRec, string strQuery, string[] arrExtraColumns, List<MasterRights> arrRestrictMasters, string strJoinQuery, int iCompanyId)
	{
		string text = null;
		if (strQuery.Contains("--@EXTRA_GROUPBY"))
		{
			List<string> list = new List<string>();
			for (int i = 0; i < arrExtraColumns.Length; i++)
			{
				if (!(arrExtraColumns[i] == "'0'"))
				{
					list.Add(arrExtraColumns[i]);
				}
			}
			text = string.Empty;
			if (list != null && list.Count > 0)
			{
				text = string.Join(",", list.Select((string p) => p));
			}
			if (text.Length > 0)
			{
				text = "," + text;
			}
			strQuery = strQuery.Replace("--@EXTRA_GROUPBY", text);
		}
		if (strQuery.Contains("--@EXTRA_COLUMNS"))
		{
			text = string.Empty;
			if (arrExtraColumns != null && arrExtraColumns.Length != 0)
			{
				text = string.Join(",", arrExtraColumns.Select((string p) => p));
			}
			if (text.Length > 0)
			{
				text = "," + text;
			}
			strQuery = strQuery.Replace("--@EXTRA_COLUMNS", text);
		}
		if (strQuery.Contains("--@EXTRA_TABLES"))
		{
			text = string.Empty;
			if (!string.IsNullOrEmpty(strJoinQuery))
			{
				text = strJoinQuery;
			}
			strQuery = strQuery.Replace("--@EXTRA_TABLES", text);
		}
		if (strQuery.Contains("--@EXTRA_FILTER"))
		{
			text = string.Empty;
			if (objRec.FilterSource != null && objRec.FilterSource.Length != 0)
			{
				text = filter_string(objRec.FilterSource, m_objDatabase, iCompanyId);
			}
			strQuery = strQuery.Replace("--@EXTRA_FILTER", text);
		}
		if (strQuery.Contains("--@ROLES_FILTER"))
		{
			text = string.Empty;
			if (arrRestrictMasters != null && arrRestrictMasters.Count > 0)
			{
				text = AddSecurityPermission(strQuery, arrRestrictMasters, objRec, iCompanyId);
			}
			strQuery = strQuery.Replace("--@ROLES_FILTER", text);
		}
		return strQuery;
	}

	private void UpdateRestrictMaster(RepRecord objRec, ref List<MasterRights> arrMasters, ref List<FieldData> arrSecurityField)
	{
		if (arrMasters == null || arrMasters.Count <= 0)
		{
			return;
		}
		int num = 0;
		int num2 = -1;
		string value = string.Empty;
		switch ((FocusReport)objRec.ReportId)
		{
		case FocusReport.AgeingStockByBins:
		case FocusReport.AgeingStockByProductByBins:
			num2 = 2;
			value = "vrCore_Product";
			break;
		case FocusReport.TransactionsTypeAnalysis:
			num2 = 1;
			value = "vrCore_Account";
			break;
		case FocusReport.ReorderReport:
			num2 = _focus.company(m_iCompId).invTagId;
			value = _focus.company(m_iCompId).invTagName;
			break;
		default:
			if (objRec.ReportId < RDCommon.RD_STARTID && objRec.Module != Module.None)
			{
				if (objRec.Module == Module.CoreTransactions && _focus.company(m_iCompId).getPreferenceValue(PreferenceCategories.Print, 49) == 1)
				{
					num2 = _focus.company(m_iCompId).faTagId;
					value = _focus.company(m_iCompId).faTagName;
				}
				else if (objRec.Module == Module.Inventory && _focus.company(m_iCompId).getPreferenceValue(PreferenceCategories.Print, 50) == 1)
				{
					num2 = _focus.company(m_iCompId).invTagId;
					value = _focus.company(m_iCompId).invTagName;
				}
			}
			else
			{
				ApplyRestrictionOnVoucherMasters(objRec, ref arrMasters);
				if (arrSecurityField != null && arrSecurityField.Count > 0 && arrMasters.Count == 0)
				{
					arrSecurityField.Clear();
				}
			}
			break;
		}
		if (num2 <= 0 || string.IsNullOrEmpty(value))
		{
			return;
		}
		for (num = 0; num < arrMasters.Count; num++)
		{
			if (arrMasters[num].ID != num2)
			{
				arrMasters.RemoveAt(num);
				num--;
			}
		}
		if (arrSecurityField == null)
		{
			return;
		}
		for (num = 0; num < arrSecurityField.Count; num++)
		{
			if (!arrSecurityField[num].FieldName.StartsWith(value))
			{
				arrSecurityField.RemoveAt(num);
				num--;
			}
		}
	}

	private void ClearRestrictMaster(uint iReportId, int iUserId)
	{
		if (iReportId == 583 || iReportId == 591 || iReportId == 646)
		{
			_focus.company(m_iCompId).user(iUserId).RoleMasters = null;
		}
	}

	private void ApplyRestrictionOnVoucherMasters(RepRecord objRec, ref List<MasterRights> arrMasters)
	{
		List<int> list = new List<int>();
		List<string> list2 = new List<string>();
		if (objRec.ReportId >= RDCommon.RD_STARTID)
		{
			if (objRec.ReportCustomize.TransactionSets != null)
			{
				for (int i = 0; i < objRec.ReportCustomize.TransactionSets.Length; i++)
				{
					if (objRec.ReportCustomize.TransactionSets[i].TransactionSetId == TransactionSetType.AllTransactionsOfDocumentType)
					{
						list2.Add(objRec.ReportCustomize.TransactionSets[i].VoucherType.ToString());
					}
				}
			}
			if (list2.Count == 0)
			{
				if (IsInventorySet((m_arrBaseTranSet != null && m_arrBaseTranSet.Length != 0) ? m_arrBaseTranSet : objRec.ReportCustomize.TransactionSets) && objRec.Module == Module.Inventory)
				{
					list.AddRange(new int[2]
					{
						2,
						_focus.company(m_iCompId).invTagId
					});
				}
				if (list.Count > 0)
				{
					arrMasters = (from p in list
						join q in arrMasters on p equals q.ID
						select q).ToList();
				}
			}
		}
		else if (objRec.Module == Module.None)
		{
			list2.Add(objRec.ReportId.ToString());
		}
		if (list2.Count <= 0)
		{
			return;
		}
		list.Add(1);
		list.Add(2);
		if (objRec.Module == Module.None && list2.Count == 1 && FConvert.IsItTransfer(Convert.ToInt32(list2[0])))
		{
			list.Add(_focus.company(m_iCompId).invTagId);
		}
		string text = string.Format("SELECT DISTINCT iMasterType FROM cCore_VoucherMasters{0} WHERE iVoucherType IN ({1})", Suffix, string.Join(",", list2));
		using (DbCommand command = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text))
		{
			IDataReader dataReader = m_objDatabase.ExecuteReader(command);
			while (dataReader.Read())
			{
				list.Add(Convert.ToInt32(dataReader["iMasterType"]));
			}
			dataReader.Close();
		}
		arrMasters = (from p in list
			join q in arrMasters on p equals q.ID
			select q).ToList();
	}

	public string AddSecurityPermission(string sQuery, List<MasterRights> arrRestrictMasters, RepRecord oRec, int iCompId)
	{
		int num = 0;
		string text = string.Empty;
		string text2 = null;
		if (arrRestrictMasters != null)
		{
			for (num = 0; num < arrRestrictMasters.Count; num++)
			{
				if ((arrRestrictMasters[num].ID == 601 && oRec.Module != Module.FixAssets) || IsSecurityFilterApply(oRec.ReportId, oRec.Module, arrRestrictMasters[num].ID) || arrRestrictMasters[num].ID == 1 || arrRestrictMasters[num].ID == 2 || !sQuery.Contains(arrRestrictMasters[num].Name))
				{
					continue;
				}
				if (arrRestrictMasters[num].Name == "vrCore_Account")
				{
					if (!IsAccountMasterReport(oRec.ReportId))
					{
						text2 = arrRestrictMasters[num].Tag;
						if (oRec.Module != Module.None)
						{
							getAccountWithTransaction(ref text2, m_objDatabase);
						}
						arrRestrictMasters[num].Tag = text2;
						if (sQuery.Contains(" BookNo ") && sQuery.Contains(" Code "))
						{
							text += string.Format(" AND (BookNo.iMasterId {0} IN ({1}) OR Code.iMasterId {0} IN ({1})) ", arrRestrictMasters[num].Exclude ? "NOT" : "", arrRestrictMasters[num].Tag);
						}
						else if (sQuery.Contains(" BookNo "))
						{
							text += string.Format(" AND BookNo.iMasterId {0} IN ({1})", arrRestrictMasters[num].Exclude ? "NOT" : "", arrRestrictMasters[num].Tag);
						}
						else if (sQuery.Contains(" Code "))
						{
							text += string.Format(" AND Code.iMasterId {0} IN ({1})", arrRestrictMasters[num].Exclude ? "NOT" : "", arrRestrictMasters[num].Tag);
						}
					}
				}
				else if ((oRec.ReportId >= RDCommon.RD_STARTID || oRec.Module != Module.CoreTransactions || arrRestrictMasters[num].ID != 2) && ((byte)oRec.SubReportId != 3 || !Convert.ToBoolean(oRec.Inputs[9].Value)))
				{
					if (arrRestrictMasters[num].Name == "vrCore_Product")
					{
						text2 = arrRestrictMasters[num].Tag;
						getItemWithTransaction(ref text2, m_objDatabase);
						arrRestrictMasters[num].Tag = text2;
					}
					text += string.Format(" AND ISNULL({0}.iMasterId,0) {2} IN ({1})", arrRestrictMasters[num].Name, arrRestrictMasters[num].Tag, arrRestrictMasters[num].Exclude ? "NOT" : "");
				}
			}
		}
		return text;
	}

