	private string AddSecurityFilter(List<MasterRights> arrRestrictMasters, RepRecord oRec)
	{
		int num = 0;
		string text = string.Empty;
		if ((byte)oRec.SubReportId == 3 && Convert.ToBoolean(oRec.Inputs[9].Value))
		{
			return text;
		}
		if (arrRestrictMasters != null)
		{
			for (num = 0; num < arrRestrictMasters.Count; num++)
			{
				if (!string.IsNullOrEmpty(_focus.company(m_iCompId).faTagName) && MatchTable(_focus.company(m_iCompId).faTagName, arrRestrictMasters[num].Name))
				{
					text += string.Format(" AND iFaTag{0} IN ({1} )", arrRestrictMasters[num].Exclude ? " NOT" : "", arrRestrictMasters[num].Tag);
				}
				else if (!string.IsNullOrEmpty(_focus.company(m_iCompId).invTagName) && MatchTable(_focus.company(m_iCompId).invTagName, arrRestrictMasters[num].Name))
				{
					text += string.Format(" AND iInvTag{0} IN ({1} )", arrRestrictMasters[num].Exclude ? " NOT" : "", arrRestrictMasters[num].Tag);
