	private bool IsSecurityFilterApply(uint iReportId, Module oModule, int iMasterTypeId)
	{
		switch ((FocusReport)iReportId)
		{
		case FocusReport.StockLedger:
		case FocusReport.StockStatement:
		case FocusReport.StockMovement:
		case FocusReport.MultiLevelStockMovement:
		case FocusReport.VirtualStockAnalysis:
		case FocusReport.ABCAnalysisProdcut:
		case FocusReport.StockAnalysisbyBatch:
		case FocusReport.StockAnalysisbyRMA:
			if (iMasterTypeId == _focus.company(m_iCompId).invTagId || iMasterTypeId == _focus.company(m_iCompId).faTagId || (iMasterTypeId != 1 && iMasterTypeId != 2))
			{
				return false;
			}
			return true;
		case FocusReport.StockBalanceByWarehouse:
			if (iMasterTypeId == _focus.company(m_iCompId).invTagId || iMasterTypeId == _focus.company(m_iCompId).faTagId || iMasterTypeId == 2)
			{
				return false;
			}
			return true;
		case FocusReport.StockValuation:
			if (iMasterTypeId == 2 || iMasterTypeId == _focus.company(m_iCompId).invTagId)
			{
				return false;
			}
			return true;
		case FocusReport.VATDetailedReport:
			if (iMasterTypeId == 1 || iMasterTypeId == _focus.company(m_iCompId).faTagId)
			{
				return false;
			}
			return true;
		default:
			return false;
		}
	}

