					for (int i = 0; i < objRec.ReportCustomize.Layout.Columns[num].ColumnFilter.Length; i++)
					{
						fieldData = new FieldData();
						fieldData.FieldId = objRec.ReportCustomize.Layout.Columns[num].ColumnFilter[i].FieldId;
						fieldData.SubParentId = objRec.ReportCustomize.Layout.Columns[num].ColumnFilter[i].SubParentId;
						fieldData.ParentId = objRec.ReportCustomize.Layout.Columns[num].ColumnFilter[i].ParentId;
						fieldData.DataType = objRec.ReportCustomize.Layout.Columns[num].ColumnFilter[i].DataType;
						list.Add(fieldData);
					}
				}
			}
		}
		if (objRec.SourceType == DataSourceType.Reports && objRec.ReportCustomize.TransactionSets != null && objRec.ReportCustomize.TransactionSets.Length != 0 && objRec.ReportCustomize.TransactionSets[0].TransactionSetId == TransactionSetType.None && objRec.ReportCustomize.TransactionSets[0].VoucherType > 0)
		{
			array2 = LoadBaseFilter((uint)objRec.ReportCustomize.TransactionSets[0].VoucherType, objDb, m_iCompId);
			if (array2 != null && array2.Length != 0)
			{
				for (num = 0; num < array2.Length; num++)
				{
					fieldData = new FieldData();
					fieldData.FieldId = array2[num].FieldId;
					fieldData.SubParentId = array2[num].SubParentId;
					fieldData.ParentId = array2[num].ParentId;
					fieldData.DataType = array2[num].DataType;
					list.Add(fieldData);
				}
			}
		}
		invoiceLayout = new InvoiceLayout();
		invoiceLayout.VouchersValue = arrVoucherTypesValue;
		if (m_bClosed)
		{
			invoiceLayout.CurrentSuffix = Suffix;
		}
		array = ((!bPreviousYear || !m_bClosed) ? invoiceLayout.GetExtraFieldNames(list.ToArray(), m_iVoucherType, m_bVoucherClass, m_iCompId, bCallingFromFilter: true) : invoiceLayout.GetExtraFieldNames(list.ToArray(), m_iVoucherType, m_bVoucherClass, m_iCompId - 1, bCallingFromFilter: true));
		for (num = 0; num < array.Length && num < list.Count; num++)
		{
			list[num].FieldName = array[num];
		}
		return list.ToArray();
	}

	private bool IsInventorySet(_TransactionSet[] arrSet)
	{
		bool flag = false;
		bool flag2 = false;
		for (int i = 0; i < arrSet.Length; i++)
		{
			switch (arrSet[i].TransactionSetId)
			{
			case TransactionSetType.AccountingTransactions:
			case TransactionSetType.AccountingTransactionsOfanAccount:
			case TransactionSetType.AccountingTransactionsOfAccountingTag:
			case TransactionSetType.AccountingTransactionsOfInventoryTag:
			case TransactionSetType.AccountingTransactionsOfaTag:
			case TransactionSetType.AccountingTransactionsOfSelectedAccounts:
			case TransactionSetType.AllAccountingTransactions:
			case TransactionSetType.AllAccounts:
			case TransactionSetType.AllAccountsTagwise:
			case TransactionSetType.AllFixedAssets:
			case TransactionSetType.BillReference:
				flag2 = true;
				break;
			case TransactionSetType.InventoryTransactions:
			case TransactionSetType.InventoryTransactionsOfaProduct:
			case TransactionSetType.InventoryTransactionsOfAccountingTag:
			case TransactionSetType.InventoryTransactionsOfInventoryTag:
			case TransactionSetType.InventoryTransactionsOfaTag:
			case TransactionSetType.InventoryTransactionsOfSelectedProducts:
			case TransactionSetType.AllProductsWithOpeningStock:
				flag = true;
				break;
			case TransactionSetType.AllTransactionsOfDocumentClass:
			case TransactionSetType.AllTransactionsOfDocumentType:
				flag = FConvert.IsItSales(arrSet[i].VoucherType);
				if (!flag)
				{
					return false;
				}
				break;
			}
		}
		if (flag)
		{
			return !flag2;
		}
		return false;
	}

