	private bool IsTagwiseTransaction(RepRecord objRec, ref bool bPendingLink, ref int iTagId)
	{
		bool result = false;
		for (int i = 0; i < objRec.ReportCustomize.TransactionSets.Length; i++)
		{
			if (objRec.ReportCustomize.TransactionSets[i].TransactionSetId == TransactionSetType.AccountingTransactionsOfaTag || objRec.ReportCustomize.TransactionSets[i].TransactionSetId == TransactionSetType.InventoryTransactionsOfaTag || objRec.ReportCustomize.TransactionSets[i].TransactionSetId == TransactionSetType.AllAccountsTagwise || objRec.ReportCustomize.TransactionSets[i].TransactionSetId == TransactionSetType.AllProductsTagwise)
			{
				iTagId = objRec.ReportCustomize.TransactionSets[i].VoucherType;
				result = true;
			}
			else if (objRec.ReportCustomize.TransactionSets[i].TransactionSetId == TransactionSetType.PendingLinks)
			{
				bPendingLink = true;
			}
		}
		return result;
	}

	private bool IsAllAccountingTransaction(RepRecord objRec)
	{
		if (objRec.ReportCustomize != null && objRec.ReportCustomize.TransactionSets != null)
		{
			for (int i = 0; i < objRec.ReportCustomize.TransactionSets.Length; i++)
			{
				if (objRec.ReportCustomize.TransactionSets[i].TransactionSetId == TransactionSetType.AllAccountingTransactions)
				{
					return true;
				}
			}
		}
		return false;
	}

	private string primary_key(ReportType objReportType, DataSourceType objSource, _Column[] arrColumns, _Grouping[] arrGrouping)
	{
		string text = "-1[iHeaderId]";
		if (ReportType.Detail == objReportType && objSource == DataSourceType.Default)
		{
			text = $"tCore_Data{Suffix}.iBodyId";
			_Column[] array = arrColumns;
			foreach (_Column column in array)
			{
				if (column.ColumnFunction != null && column.ColumnFunction.Function != AggregateFunction.None)
				{
					text = "-1[iHeaderId]";
					break;
				}
			}
		}
		else if (objReportType == ReportType.Cubes)
		{
			if (objSource == DataSourceType.Reports)
			{
				text = $"tCore_Data{Suffix}.iBodyId";
				_Column[] array = arrColumns;
				foreach (_Column column2 in array)
				{
					if (column2.ColumnFunction != null && column2.ColumnFunction.Function != AggregateFunction.None)
					{
						text = "-1[iHeaderId]";
						break;
					}
				}
			}
			if (text == "-1[iHeaderId]")
			{
				_Column[] array = arrColumns;
				foreach (_Column column3 in array)
				{
					if (column3.FieldId == 1 || column3.FieldId == 175)
					{
						text = $"tCore_Header{Suffix}.iHeaderId";
						break;
					}
					if (column3.FieldId == 187)
					{
						text = $"tCore_Data{Suffix}.iBodyId";
						break;
					}
				}
			}
			if (text == "-1[iHeaderId]")
			{
				if (arrColumns.Length != 0 && arrColumns[0].SubParentId == 23)
				{
					text = "vrCore_Product.iMasterId";
				}
				else if (arrColumns.Length != 0 && (arrColumns[0].SubParentId == 39 || arrColumns[0].SubParentId == 4))
				{
					text = "BookNo.iMasterId";
				}
				else if (arrColumns.Length != 0 && (arrColumns[0].SubParentId == 12 || arrColumns[0].SubParentId == 3))
				{
					text = "Code.iMasterId";
				}
				else if (arrGrouping != null && arrGrouping.Length != 0)
				{
					switch (new RDDefault().GetBackTrackType(objReportType, objSource, arrGrouping, arrColumns))
					{
					case BackTrackType.Transaction:
						text = $"tCore_Data{Suffix}.iBodyId";
						break;
					case BackTrackType.TransactionHeaderId:
						text = $"tCore_Header{Suffix}.iHeaderId";
						break;
					case BackTrackType.AccountDetail:
					{
						for (int j = 0; j < arrGrouping.Length; j++)
						{
							if (arrGrouping[j].GroupingType == _GroupingType.Row)
							{
								if (arrGrouping[j].SubParentId == 4 || arrGrouping[j].SubParentId == 39)
								{
									text = "BookNo.iMasterId";
									break;
								}
								if (arrGrouping[j].SubParentId == 3 || arrGrouping[j].SubParentId == 12)
								{
									text = "Code.iMasterId";
									break;
								}
							}
						}
						break;
					}
					case BackTrackType.ProductDetail:
						text = "vrCore_Product.iMasterId";
						break;
					}
				}
			}
			if (text == "-1[iHeaderId]")
			{
				_Column[] array = arrColumns;
				foreach (_Column column4 in array)
				{
					if (column4.FieldId == 1 || column4.FieldId == 175)
					{
						text = $"tCore_Header{Suffix}.iHeaderId";
						break;
					}
					if (column4.FieldId == 187)
					{
						text = $"tCore_Data{Suffix}.iBodyId";
						break;
					}
				}
			}
		}
		return text;
	}

	private string GetViewSettings(int iReportId, IdValuePair[] arrInputs)
	{
		string text = "";
