		int num2 = 0;
		int num3 = 0;
		int num4 = 0;
		int num5 = 0;
		num = FConvert.GetInputValue(arrInputs, 1);
		num2 = FConvert.GetInputValue(arrInputs, 2);
		num3 = FConvert.GetInputValue(arrInputs, 3);
		num5 = FConvert.GetInputValue(arrInputs, 4);
		num4 = FConvert.GetInputValue(arrInputs, 5);
		bool flag = FConvert.IsItSales(Convert.ToInt32(iReportId));
		if (num3 < 2 && num3 > -1 && !flag)
		{
			text += $" AND tCore_Indta{Suffix}.bQCDone = {num3}";
		}
		if (num2 < 2 && num2 > -1)
