						{
							advanceFilterQuery.CompareValue = GetMastersInGroup(extraFieldName.Split('.')[0], Convert.ToInt32(arrFilter[b].CompareValue), objDb, iCompId);
							if (!string.IsNullOrEmpty(advanceFilterQuery.CompareValue) && advanceFilterQuery.CompareValue.Split(',').Length >= 10000)
							{
								m_strParamValues = advanceFilterQuery.CompareValue;
								FieldData fieldData = new FieldData();
								fieldData.FieldId = arrFilter[b].FieldId;
								fieldData.SubParentId = arrFilter[b].SubParentId;
								fieldData.ParentId = arrFilter[b].ParentId;
								string[] extraFieldNames = invoiceLayout.GetExtraFieldNames(new FieldData[1] { fieldData }, -1, bVoucherClass: false, iCompId, bCallingFromFilter: true);
								m_strParamFilter = ((extraFieldNames != null && extraFieldNames.Length != 0) ? extraFieldNames[0] : null);
								if (!string.IsNullOrEmpty(m_strParamFilter) && m_strParamFilter.Contains(".sName"))
								{
									m_strParamFilter = m_strParamFilter.Replace(".sName", ".iMasterId");
								}
								flag = true;
							}
						}
						if (Convert.ToString(advanceFilterQuery.CompareValue).Contains(','))
						{
							arrFilter[b].CompareText = null;
						}
					}
					advanceFilterQuery.TreeData = new TreeHierarchyDetails();
					advanceFilterQuery.TreeData.IsGroup = true;
					advanceFilterQuery.TreeData.FieldId = arrFilter[b].FieldId;
					advanceFilterQuery.TreeData.SubParentId = arrFilter[b].SubParentId;
				}
				if (arrFilter[b].DataType == MasterDataType.Date && arrFilter[b].CompareWith == Focus.Common.DataStructs.CompareWith.DateRange)
				{
					advanceFilterQuery.iValueType = arrFilter[b].DataType;
				}
				if (flag)
				{
					flag = false;
				}
				else
				{
					if (!string.IsNullOrEmpty(arrFilter[b].CompareText) && (arrFilter[b].DataType == MasterDataType.Master || arrFilter[b].DataType == MasterDataType.NumberList || (arrFilter[b].DataType == MasterDataType.ExternalTable && arrFilter[b].FieldId == 8)))
					{
						advanceFilterQuery.CompareValue = arrFilter[b].CompareText;
					}
					advanceFilterQuery.FieldId = arrFilter[b].FieldId;
					list.Add(advanceFilterQuery);
					FieldData fieldData2 = new FieldData();
					fieldData2.FieldId = advanceFilterQuery.FieldId;
					fieldData2.SubParentId = arrFilter[b].SubParentId;
					fieldData2.ParentId = arrFilter[b].ParentId;
					if (!string.IsNullOrEmpty(advanceFilterQuery.CompareValue) || advanceFilterQuery.Operator == 6 || advanceFilterQuery.Operator == 7)
					{
						list2.Add(fieldData2);
					}
					if (oModule != Module.None && iReportId != 658 && fieldData2.FieldId != 127 && (fieldData2.SubParentId == 4 || fieldData2.SubParentId == 39 || fieldData2.SubParentId == 3 || fieldData2.SubParentId == 12))
					{
						flag2 = true;
						flag3 = arrFilter[b].Operator == Operator.NotEqualTo;
					}
				}
			}
			array = ((arrColumnAlias == null || arrColumnAlias.Length == 0 || !IsUseExactField) ? invoiceLayout.GetExtraFieldNames(list2.ToArray(), m_iVoucherType, m_bVoucherClass, iCompId, bCallingFromFilter: true) : arrColumnAlias);
			if (array.Length != 0)
			{
				for (b = 0; b < list.Count; b++)
				{
					string text4 = ((b < array.Length) ? array[b] : string.Empty);
					list[b].Name = text4;
					if (b < arrFilter.Length && !IsUseExactField)
					{
						list[b].Name = GetSpecialName(text4, list[b].FieldId, arrFilter[b].SubParentId, arrFilter[b].IsGroup, iReportId, SubReportId, oModule);
						if (arrFilter[b].SubParentId == 87 && list[b].Name.Contains(_focus.company(m_iCompId).invTagName) && IsItTransferTypeSet())
						{
							list[b].Name = list[b].Name.Replace($"{_focus.company(m_iCompId).invTagName}.", "InvTag2.");
						}
						if (iReportId == 538 && (list[b].Name.Contains("Code") || list[b].Name.Contains("BookNo")))
						{
							list[b].Name = list[b].Name.Replace("Code.", "vrCore_Account.");
							list[b].Name = list[b].Name.Replace("BookNo.", "vrCore_Account.");
							flag2 = false;
						}
						if (list[b].Name.EndsWith("YH") && !string.IsNullOrEmpty(arrFilter[b].CompareText))
						{
							list[b].CompareValue = arrFilter[b].CompareText;
						}
						else if (list[b].FieldId == 95 && !string.IsNullOrEmpty(arrFilter[b].CompareText))
						{
							switch (arrFilter[b].CompareText.ToLower())
							{
							case "pending":
								list[b].CompareValue = "0";
								break;
							case "rejected":
								list[b].CompareValue = "2";
								break;
							case "stopped":
								list[b].CompareValue = "3";
								break;
							case "partial":
								list[b].CompareValue = "4";
								break;
							default:
								list[b].CompareValue = "1";
								break;
							}
						}
						else if (list[b].FieldId == 186 && !string.IsNullOrEmpty(arrFilter[b].CompareText))
						{
							if (arrFilter[b].CompareText.ToLower() == "converted")
							{
								list[b].CompareValue = "1";
							}
							else
							{
								list[b].CompareValue = "0";
							}
						}
						if (iReportId == 500 || iReportId == 501)
						{
							if (list[b].Name == $"tCore_Header{Suffix}.iAuth")
							{
								list[b].Name = $"tCore_Data{Suffix}.iAuth";
							}
							else if (list[b].Name == $"tCore_Header{Suffix}.iVoucherType")
							{
								list[b].Name = $"tCore_Data{Suffix}.iVoucherType";
							}
						}
						if (list[b].iValueType == MasterDataType.Date && list[b].CompareWith == 3)
						{
							num++;
						}
					}
				}
				if (num > 0)
				{
					text3 = GetDateRangeFilterString(ref list);
				}
				if (list.Count == 0)
				{
					text = text3;
				}
				else
				{
					text = FConvert.GetFilterString(list.ToArray());
					if (!string.IsNullOrEmpty(text3))
					{
						text += text3;
					}
				}
				if (text.StartsWith("AND "))
				{
					text = text.Substring(4);
				}
				else
				{
					text = ((!text.StartsWith("OR ")) ? text.Substring(5) : text.Substring(3));
				}
				if (flag2 && !bCubeReport)
				{
					string text5 = text.Replace(" BookNo", " Code");
					string text6 = text.Replace(" Code", " BookNo");
					text = ((!flag3) ? ("(" + text5 + " OR " + text6 + ")") : ("(" + text5 + " AND " + text6 + ")"));
				}
				if (list.Count > 1)
				{
					text = "(" + text + ")";
				}
				text = text.Insert(0, " AND ");
			}
			else if (!string.IsNullOrEmpty(m_strParamFilter) && !string.IsNullOrEmpty(m_strParamValues))
			{
				text = "--@EXTRA_TABLES";
			}
		}
		return text2 + text;
	}

	private string GetDateRangeFilterString(ref List<AdvanceFilterQuery> arrAdvFilter)
	{
		int iStartDate = 0;
		int iEndDate = 0;
		int accountingDate = _focus.company(m_iCompId).accountingDate;
		decimal result = 0m;
		string text = string.Empty;
		for (int i = 0; i < arrAdvFilter.Count; i++)
		{
			if (arrAdvFilter[i].iValueType == MasterDataType.Date && arrAdvFilter[i].CompareWith == 3)
			{
				decimal.TryParse(arrAdvFilter[i].CompareValue, out result);
				switch ((DateRangesAll)(int)result)
				{
				case DateRangesAll.CurrentFY:
					RDCommon.ApplyDateSetting(DateOptions.ForThisYear, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					break;
				case DateRangesAll.PrevoiusFY:
					RDCommon.ApplyDateSetting(DateOptions.LastYear, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					break;
				case DateRangesAll.NextFY:
					RDCommon.ApplyDateSetting(DateOptions.ForThisYear, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iStartDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iStartDate).AddYears(1));
					iEndDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iEndDate).AddYears(1));
					break;
				case DateRangesAll.CurrentAndNextFY:
					RDCommon.ApplyDateSetting(DateOptions.ForThisYear, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iEndDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iEndDate).AddYears(1));
					break;
				case DateRangesAll.CurrentAndPrevoiusFY:
					RDCommon.ApplyDateSetting(DateOptions.ForThisYear, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iStartDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iStartDate).AddYears(-1));
					break;
				case DateRangesAll.CurrentFQ:
					RDCommon.ApplyDateSetting(DateOptions.CurrentQuarter, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					break;
				case DateRangesAll.PrevoiusFQ:
					RDCommon.ApplyDateSetting(DateOptions.PreviousQuarter, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					break;
				case DateRangesAll.NextFQ:
					RDCommon.ApplyDateSetting(DateOptions.CurrentQuarter, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iStartDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iStartDate).AddMonths(3));
					iEndDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iEndDate).AddMonths(3));
					break;
				case DateRangesAll.CurrentAndNextFQ:
					RDCommon.ApplyDateSetting(DateOptions.CurrentQuarter, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iEndDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iEndDate).AddMonths(3));
					break;
				case DateRangesAll.CurrentAndPrevoiusFQ:
					RDCommon.ApplyDateSetting(DateOptions.CurrentQuarter, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iStartDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iStartDate).AddMonths(-3));
					break;
				case DateRangesAll.CurrentMonth:
					RDCommon.ApplyDateSetting(DateOptions.ForThisMonth, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					break;
				case DateRangesAll.PrevoiusMonth:
					RDCommon.ApplyDateSetting(DateOptions.ForLastMonth, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					break;
				case DateRangesAll.NextMonth:
					RDCommon.ApplyDateSetting(DateOptions.ForThisMonth, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iStartDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iStartDate).AddMonths(1));
					iEndDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iEndDate).AddMonths(1));
					break;
				case DateRangesAll.CurrentAndNextMonth:
					RDCommon.ApplyDateSetting(DateOptions.ForThisMonth, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iEndDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iEndDate).AddMonths(1));
					break;
				case DateRangesAll.CurrentAndPrevoiusMonth:
					RDCommon.ApplyDateSetting(DateOptions.ForThisMonth, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iStartDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iStartDate).AddMonths(-1));
					break;
				case DateRangesAll.CurrentWeek:
					RDCommon.ApplyDateSetting(DateOptions.ForThisWeek, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					break;
				case DateRangesAll.PrevoiusWeek:
					RDCommon.ApplyDateSetting(DateOptions.ForLastWeek, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					break;
				case DateRangesAll.NextWeek:
					RDCommon.ApplyDateSetting(DateOptions.ForThisWeek, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iStartDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iStartDate).AddDays(7.0));
					iEndDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iEndDate).AddDays(7.0));
					break;
				case DateRangesAll.CurrentAndNextWeek:
					RDCommon.ApplyDateSetting(DateOptions.ForThisWeek, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iEndDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iEndDate).AddDays(7.0));
					break;
				case DateRangesAll.CurrentAndPrevoiusWeek:
					RDCommon.ApplyDateSetting(DateOptions.ForThisWeek, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iStartDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iStartDate).AddDays(-7.0));
					break;
				case DateRangesAll.Today:
					RDCommon.ApplyDateSetting(DateOptions.ForToday, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					break;
				case DateRangesAll.Yesterday:
					RDCommon.ApplyDateSetting(DateOptions.Yesterday, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					break;
				case DateRangesAll.Tomorrow:
					RDCommon.ApplyDateSetting(DateOptions.ForToday, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iEndDate = (iStartDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iStartDate).AddDays(1.0)));
					break;
				case DateRangesAll.Previous7Days:
					RDCommon.ApplyDateSetting(DateOptions.ForToday, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iStartDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iStartDate).AddDays(-7.0));
					break;
				case DateRangesAll.Previous30Days:
					RDCommon.ApplyDateSetting(DateOptions.ForToday, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iStartDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iStartDate).AddDays(-30.0));
					break;
				case DateRangesAll.Previous60Days:
					RDCommon.ApplyDateSetting(DateOptions.ForToday, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iStartDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iStartDate).AddDays(-60.0));
					break;
				case DateRangesAll.Previous90Days:
					RDCommon.ApplyDateSetting(DateOptions.ForToday, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iStartDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iStartDate).AddDays(-90.0));
					break;
				case DateRangesAll.Next7Days:
					RDCommon.ApplyDateSetting(DateOptions.ForToday, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iEndDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iEndDate).AddDays(7.0));
					break;
				case DateRangesAll.Next30Days:
					RDCommon.ApplyDateSetting(DateOptions.ForToday, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iEndDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iEndDate).AddDays(30.0));
					break;
				case DateRangesAll.Next60Days:
					RDCommon.ApplyDateSetting(DateOptions.ForToday, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iEndDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iEndDate).AddDays(60.0));
					break;
				case DateRangesAll.Next90Days:
					RDCommon.ApplyDateSetting(DateOptions.ForToday, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					iEndDate = Date.DateToInt(new Date(m_objCalType).IntToDate(iEndDate).AddDays(90.0));
					break;
				case DateRangesAll.MonthToDate:
					RDCommon.ApplyDateSetting(DateOptions.ForThisMonth, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					break;
				case DateRangesAll.YearToDate:
					RDCommon.ApplyDateSetting(DateOptions.ForThisYear, m_objCalType, accountingDate, 0, ref iStartDate, ref iEndDate);
					break;
				default:
					iEndDate = m_iStartDate;
					break;
				}
				text += $"AND {arrAdvFilter[i].Name} BETWEEN {iStartDate} AND {iEndDate} ";
				iStartDate = (iEndDate = 0);
				arrAdvFilter.RemoveAt(i);
				i--;
			}
		}
		return text;
	}

	private bool IsItTransferTypeSet()
	{
		if (m_iVoucherType > 0 && FConvert.IsItTransfer(m_iVoucherType))
		{
			return true;
		}
		if (m_arrVoucherTypesValue != null && m_arrVoucherTypesValue.Count > 0)
		{
			for (int i = 0; i < m_arrVoucherTypesValue.Count; i++)
			{
				if (m_arrVoucherTypesValue[i].ID > 0 && FConvert.IsItTransfer(m_arrVoucherTypesValue[i].ID))
				{
					return true;
				}
			}
		}
		return false;
	}

	private string getDocRangeFilter(ref _Filter[] arrFilter, Module oModule, uint iReportId, Database objDb, int iCompId)
	{
		int num = 0;
		int num2 = 0;
		string text = null;
		string text2 = null;
		string text3 = null;
		string suffix = FConvert.GetSuffix(iCompId);
		List<_Filter> list = null;
		if (arrFilter != null && arrFilter.Length >= 2)
		{
			list = new List<_Filter>();
			for (num2 = 0; num2 < arrFilter.Length; num2++)
			{
				if (arrFilter[num2].FieldId == 1 && num < 2)
				{
					if (num == 0)
					{
						text = arrFilter[num2].CompareValue;
					}
					else
					{
						text2 = arrFilter[num2].CompareValue;
					}
					num++;
				}
				else
				{
					list.Add(arrFilter[num2]);
				}
			}
			if (!string.IsNullOrEmpty(text) && !string.IsNullOrEmpty(text2))
			{
				arrFilter = list.ToArray();
				if (FConvert.IsNumeric(text) && FConvert.IsNumeric(text2))
				{
					text3 = string.Format(" AND (CASE WHEN ISNUMERIC(tCore_Header{0}.sVoucherNo) = 1 THEN CAST(tCore_Header{0}.sVoucherNo AS BIGINT) END) BETWEEN {1} AND {2}", suffix, text, text2);
				}
				else if (oModule == Module.None || (m_arrVoucherTypesValue != null && m_arrVoucherTypesValue.Count > 0))
				{
					string serieFromDocNo = getSerieFromDocNo(text);
					string arg = $" iVoucherType = {iReportId}";
					if (oModule != Module.None && m_arrVoucherTypesValue != null && m_arrVoucherTypesValue.Count > 1)
					{
						string text4 = string.Join(",", from p in m_arrVoucherTypesValue
							where Convert.ToBoolean(p.Value)
							select p.ID.ToString());
						string text5 = string.Join(",", from p in m_arrVoucherTypesValue
							where !Convert.ToBoolean(p.Value)
							select p.ID.ToString());
						if (!string.IsNullOrEmpty(text4) && !string.IsNullOrEmpty(text5))
						{
							arg = $" (iVoucherClass IN ({text4}) OR iVoucherType IN ({text5}))";
						}
						else
						{
							if (!string.IsNullOrEmpty(text4))
							{
								arg = $" iVoucherClass IN ({text4})";
							}
							if (!string.IsNullOrEmpty(text5))
							{
								arg = $" iVoucherType IN ({text5})";
							}
						}
					}
					text3 = $"SELECT TOP 1 iHeaderId FROM tCore_Header{suffix} \r\n                            WHERE {arg} AND sVoucherNo >= N'{text}'\r\n                            ORDER BY sVoucherNo ";
					text = Convert.ToString(objDb.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text3) : text3));
					text3 = $"SELECT TOP 1 iHeaderId FROM tCore_Header{suffix} \r\n                            WHERE {arg} AND sVoucherNo <= N'{text2}'\r\n                            ORDER BY sVoucherNo DESC";
					text2 = Convert.ToString(objDb.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text3) : text3));
					text3 = string.Empty;
					if (FConvert.IsNumeric(text) && FConvert.IsNumeric(text2))
					{
						text3 = $" AND tCore_Header{suffix}.iHeaderId BETWEEN {text} AND {text2}";
						if (!string.IsNullOrEmpty(serieFromDocNo))
						{
							text3 += $" AND sVoucherNo LIKE N'{serieFromDocNo}%'";
						}
					}
				}
			}
		}
		return text3;
	}

	private string getSerieFromDocNo(string sDocNo)
	{
		int num = 0;
		num = sDocNo.Length - 1;
		while (num >= 0 && char.IsDigit(sDocNo[num]))
		{
			num--;
		}
		if (num < sDocNo.Length - 1 && num > 0)
		{
			sDocNo = sDocNo.Substring(0, num + 1);
		}
		return sDocNo;
	}

	private bool IsAccountItemParam(RepRecord objRec)
	{
		bool result = false;
		if (objRec.ReportCustomize != null && objRec.ReportCustomize.TransactionSets != null && objRec.Masters != null && objRec.Masters.Length > 1)
		{
			for (int i = 0; i < objRec.ReportCustomize.TransactionSets.Length; i++)
			{
				if (objRec.ReportCustomize.Filters == null || objRec.ReportCustomize.Filters.Length == 0)
				{
					continue;
				}
				for (int j = 0; j < objRec.ReportCustomize.Filters.Length; j++)
				{
					if (!string.IsNullOrEmpty(objRec.ReportCustomize.Filters[j].CompareValue) && objRec.ReportCustomize.Filters[j].CompareValue.StartsWith("@") && (objRec.ReportCustomize.Filters[j].SubParentId == 4 || objRec.ReportCustomize.Filters[j].SubParentId == 39 || objRec.ReportCustomize.Filters[j].SubParentId == 3 || objRec.ReportCustomize.Filters[j].SubParentId == 12 || objRec.ReportCustomize.Filters[j].SubParentId == 23))
					{
						result = true;
						break;
					}
				}
			}
		}
		return result;
	}

	private string GetRD_filter_condition(RepRecord objRec, Database objDb, int iCompId, bool bBacktrackFilter = false)
	{
		int num = 0;
		bool bCubeReport = true;
		bool bPending = false;
		bool bMultiMaster = false;
		bool flag = IsAccountItemParam(objRec);
		string text = null;
		_Filter[] array = null;
		_Filter[] arrBaseFilter = null;
		_TransactionSet[] array2 = null;
		List<string> list = null;
		List<string> list2 = null;
		m_iStartDate = objRec.StartingDate;
		list = new List<string>();
		list2 = new List<string>();
		if (objRec.StartingDate > 0)
		{
			for (num = 0; num < objRec.ReportCustomize.TransactionSets.Length; num++)
			{
				if (objRec.ReportCustomize.TransactionSets[num].TransactionSetId == TransactionSetType.AllAccounts || objRec.ReportCustomize.TransactionSets[num].TransactionSetId == TransactionSetType.AllAccountsWithOpeningBalance)
				{
					if (objRec.ReportCustomize.TransactionSets[num].TransactionSetId == TransactionSetType.AllAccountsWithOpeningBalance)
					{
						list.Add($" WHERE tCore_Header{Suffix}.iDate <= {objRec.EndingDate}");
					}
					else
					{
						list.Add($" WHERE ((tCore_Header{Suffix}.iDate BETWEEN {objRec.StartingDate} AND {objRec.EndingDate}) OR iVoucherClass = 256)");
					}
				}
				else if (objRec.ReportCustomize.TransactionSets[num].TransactionSetId == TransactionSetType.AllProducts || objRec.ReportCustomize.TransactionSets[num].TransactionSetId == TransactionSetType.AllProductsWithOpeningStock)
				{
					list.Add($" WHERE ((tCore_Header{Suffix}.iDate BETWEEN {objRec.StartingDate} AND {objRec.EndingDate}) OR iVoucherClass = 512)");
				}
				if (list.Count > 0)
				{
					break;
				}
			}
		}
		if (list.Count == 0)
		{
			list.Add($" WHERE tCore_Header{Suffix}.iDate BETWEEN {objRec.StartingDate} AND {objRec.EndingDate}");
		}
		if (objRec.ReportCustomize.TransactionSets.Length != 0 && objRec.ReportCustomize.TransactionSets[0].TransactionSetId == TransactionSetType.None && objRec.ReportCustomize.TransactionSets[0].VoucherType > 0)
		{
			array2 = LoadTransactionSet((uint)objRec.ReportCustomize.TransactionSets[0].VoucherType, ref arrBaseFilter, objDb, iCompId);
		}
		else
		{
			array2 = objRec.ReportCustomize.TransactionSets;
			arrBaseFilter = objRec.ReportCustomize.Filters;
		}
		if (!flag && arrBaseFilter != null && arrBaseFilter.Length != 0)
		{
			num = 0;
			if (arrBaseFilter[num].IsGroup && arrBaseFilter[num].SubParentId > 0 && (arrBaseFilter[num].DataType == MasterDataType.Master || arrBaseFilter[num].DataType == MasterDataType.Number || arrBaseFilter[num].DataType == MasterDataType.NumberList || arrBaseFilter[num].DataType == MasterDataType.StringList))
			{
				flag = true;
			}
		}
		for (num = 0; num < array2.Length; num++)
		{
			list2.Add(FilterOfTransactionSet(objRec, array2[num].TransactionSetId, array2[num].VoucherType, objDb, iCompId, ref bMultiMaster));
			list.Add(document_type_filter(array2[num], ref bPending));
			if (arrBaseFilter != null && arrBaseFilter.Length != 0)
			{
				array = arrBaseFilter;
				UpdateFilterInputValue(objRec.ReportCustomize.Parameters, objRec, objDb, ref array);
				text = filter_string(array, objDb, iCompId, bCubeReport);
				if (flag && !string.IsNullOrEmpty(m_strParamValues))
				{
					m_strParamFilter = text;
				}
				else
				{
					list.Add(text);
				}
				text = string.Empty;
			}
			if (num == 0)
			{
				string strParamValues = m_strParamValues;
				string strParamFilter = m_strParamFilter;
				m_strParamValues = (m_strParamFilter = null);
				if (!bBacktrackFilter)
				{
					list.Add(filter_string(objRec.FilterSource, objDb, iCompId, bCubeReport));
				}
				if (!string.IsNullOrEmpty(strParamValues))
				{
					m_strParamValues = strParamValues;
				}
				if (!string.IsNullOrEmpty(strParamFilter))
				{
					m_strParamFilter = strParamFilter;
				}
			}
		}
		if (!bPending)
		{
			list.Add(" tCore_Data" + Suffix + ".bSuspendUpdateFA <> 1 ");
		}
		text = "(";
		for (num = 0; num < list2.Count; num++)
		{
			if (num > 0)
			{
				text += " OR";
			}
			text += list2[num];
		}
		text += ")";
		if (list2.Count > 0)
		{
			list.Add(text);
		}
		text = string.Empty;
		for (num = 0; num < list.Count; num++)
		{
			if (!string.IsNullOrEmpty(list[num]) && !list[num].Contains(" = @"))
			{
				if (text != null && text.Length > 0 && !list[num].StartsWith(" AND") && list[num] != "--@EXTRA_TABLES")
				{
					text += " AND";
				}
				text += list[num];
			}
		}
		if (!string.IsNullOrEmpty(m_strMasterFilter) && objRec.UserId > 1)
		{
			text += m_strMasterFilter;
			m_strMasterFilter = string.Empty;
		}
		if (bMultiMaster)
		{
			text += "--@EXTRA_TABLES";
		}
		return text;
	}

	private _TransactionSet[] LoadTransactionSet(uint iReportId, ref _Filter[] arrBaseFilter, Database objDb, int iCompId)
	{
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		_TransactionSet transactionSet = null;
		string text = null;
		List<_TransactionSet> list = null;
		list = new List<_TransactionSet>();
		if (iReportId >= RDCommon.RD_STARTID)
		{
			text = $"SELECT iTranId, iTranSetId, iBRS, iDocumentOption, iVoucherType \r\n                FROM cCore_ReportTransactionSet{FConvert.GetSuffix(iCompId)} WHERE iReportId = {iReportId}";
			dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dbCommand.CommandTimeout = 0;
			dataReader = objDb.ExecuteReader(dbCommand);
			while (dataReader.Read())
			{
				transactionSet = new _TransactionSet();
				transactionSet.TransactionId = dataReader.GetInt32(0);
				transactionSet.TransactionSetId = (TransactionSetType)dataReader.GetInt32(1);
				transactionSet.BRS = dataReader.GetByte(2);
				transactionSet.DocumentOption = dataReader.GetInt32(3);
				transactionSet.VoucherType = dataReader.GetInt32(4);
				list.Add(transactionSet);
			}
			dataReader.Close();
			arrBaseFilter = LoadBaseFilter(iReportId, objDb, iCompId);
		}
		return list.ToArray();
	}

	private _Filter[] LoadBaseFilter(uint iReportId, Database objDb, int iCompId)
	{
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		string text = null;
		_Filter filter = null;
		List<_Filter> list = new List<_Filter>();
		if (iReportId >= RDCommon.RD_STARTID)
		{
			text = $"SELECT iFieldId, iOperator, sValue, ISNULL(sCompareText,'')[sCompareText], iConjunction, ISNULL(iCompareWith,0)[iCompareWith], iType, ISNULL(iDataType,0)[iDataType], ISNULL(iSubParentId, 0)iSubParentId, ISNULL(bGroup,0) [bGroup]\r\n                            FROM cCore_ReportFilter{FConvert.GetSuffix(iCompId)} WHERE iFilterGroupId = {iReportId} AND iType = {0}";
			dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dbCommand.CommandTimeout = 0;
			dataReader = objDb.ExecuteReader(dbCommand);
			while (dataReader.Read())
			{
				filter = new _Filter();
				filter.FieldId = dataReader.GetInt32(0);
				filter.Operator = (Operator)dataReader.GetByte(1);
				filter.CompareValue = dataReader.GetString(2);
				filter.CompareText = dataReader.GetString(3);
				filter.Conjuction = (Conjuction)dataReader.GetByte(4);
				filter.CompareWith = (Focus.Common.DataStructs.CompareWith)dataReader.GetByte(5);
				filter.FilterType = (_FilterType)dataReader.GetByte(6);
				filter.DataType = (MasterDataType)dataReader.GetByte(7);
				filter.SubParentId = dataReader.GetInt32(8);
				filter.IsGroup = dataReader.GetBoolean(9);
				list.Add(filter);
			}
			dataReader.Close();
		}
		return list.ToArray();
	}

	private string FilterOfTransactionSet(RepRecord objRec, TransactionSetType objTransactionSetType, int iVoucherType, Database objDb, int iCompId, ref bool bMultiMaster)
	{
		string text = null;
		string text2 = " 1=1";
		switch (objTransactionSetType)
		{
		case TransactionSetType.AccountingTransactions:
		case TransactionSetType.AllAccountingTransactions:
		case TransactionSetType.AllAccounts:
			text2 = " tCore_Data" + Suffix + ".bUpdateFA = 1 ";
			break;
		case TransactionSetType.AccountingTransactionsOfanAccount:
			if (objRec.Code > 0)
			{
				bMultiMaster = true;
				text = GetMastersInGroup("vmCore_Account", objRec.Code, objDb, iCompId);
				m_strParamValues = text;
				m_strParamFilter = "Code.sName";
				text2 = " tCore_Data" + Suffix + ".bUpdateFA = 1 ";
			}
			else
			{
				text2 = " tCore_Data" + Suffix + ".bUpdateFA = 1 ";
			}
			break;
		case TransactionSetType.AccountingTransactionsOfSelectedAccounts:
		case TransactionSetType.AllAccountsWithOpeningBalance:
			if (objRec.Masters != null)
			{
				text = General.GetMasters(objRec.Masters);
				bMultiMaster = true;
				m_strParamValues = text;
				m_strParamFilter = "Code.sName";
				text2 = " tCore_Data" + Suffix + ".bUpdateFA = 1";
			}
			else
			{
				text2 = " tCore_Data" + Suffix + ".bUpdateFA = 1";
			}
			break;
		case TransactionSetType.AllProducts:
		case TransactionSetType.InventoryTransactions:
			text2 = " (tCore_Header" + Suffix + ".bUpdateStocks = 1 AND tCore_Data" + Suffix + ".bSuspendUpdateStocks <> 1)";
			break;
		case TransactionSetType.InventoryTransactionsOfaProduct:
			if (objRec.Code > 0)
			{
				text = GetMastersInGroup("vmCore_Product", objRec.Code, objDb, iCompId);
				bMultiMaster = true;
				m_strParamValues = text;
				m_strParamFilter = "vrCore_Product.sName";
				text2 = " (tCore_Header" + Suffix + ".bUpdateStocks = 1 AND tCore_Data" + Suffix + ".bSuspendUpdateStocks <> 1)";
			}
			else
			{
				text2 = " (tCore_Header" + Suffix + ".bUpdateStocks = 1 AND tCore_Data" + Suffix + ".bSuspendUpdateStocks <> 1)";
			}
			break;
		case TransactionSetType.InventoryTransactionsOfSelectedProducts:
		case TransactionSetType.AllProductsWithOpeningStock:
			if (objRec.Masters != null)
			{
				text = General.GetMasters(objRec.Masters);
				bMultiMaster = true;
				m_strParamValues = text;
				m_strParamFilter = "vrCore_Product.sName";
				text2 = " (tCore_Header" + Suffix + ".bUpdateStocks = 1 AND tCore_Data" + Suffix + ".bSuspendUpdateStocks <> 1)";
			}
			else
			{
				text2 = " (tCore_Header" + Suffix + ".bUpdateStocks = 1 AND tCore_Data" + Suffix + ".bSuspendUpdateStocks <> 1)";
			}
			break;
		case TransactionSetType.AllTransactionsOfDocumentClass:
			if (iVoucherType > 0)
			{
				text2 = $" tCore_Header{Suffix}.iVoucherClass = {iVoucherType}";
				if (FConvert.IsItTransfer(iVoucherType))
				{
					text2 = text2 + " AND tCore_Data" + Suffix + ".iMainBodyId = 0";
				}
			}
			break;
		case TransactionSetType.AllTransactionsOfDocumentType:
			if (iVoucherType > 0)
			{
				text2 = $" tCore_Header{Suffix}.iVoucherType = {iVoucherType}";
				if (FConvert.IsItTransfer(iVoucherType))
				{
					text2 = text2 + " AND tCore_Data" + Suffix + ".iMainBodyId = 0";
				}
			}
			break;
		case TransactionSetType.AccountingTransactionsOfAccountingTag:
			text2 = ((objRec.Code <= 0) ? (" tCore_Data" + Suffix + ".bUpdateFA = 1") : $" tCore_Data{Suffix}.iFaTag = {objRec.Code} AND tCore_Data{Suffix}.bUpdateFA = 1");
			break;
		case TransactionSetType.InventoryTransactionsOfAccountingTag:
			text2 = ((objRec.Code <= 0) ? (" tCore_Header" + Suffix + ".bUpdateStocks = 1 AND tCore_Data" + Suffix + ".bSuspendUpdateStocks <> 1") : $" tCore_Data{Suffix}.iFaTag = {objRec.Code}\r\nAND tCore_Header{Suffix}.bUpdateStocks = 1 AND tCore_Data{Suffix}.bSuspendUpdateStocks <> 1");
			break;
		case TransactionSetType.AccountingTransactionsOfInventoryTag:
			text2 = ((objRec.Code <= 0) ? (" tCore_Data" + Suffix + ".bUpdateFA = 1") : $" tCore_Data{Suffix}.iInvTag = {objRec.Code} AND tCore_Data{Suffix}.bUpdateFA = 1");
			break;
		case TransactionSetType.InventoryTransactionsOfInventoryTag:
			if (objRec.Code > 0)
			{
				text2 = $" tCore_Data{Suffix}.iInvTag IN {GetMastersInGroup(_focus.company(iCompId).invTagName, objRec.Code, objDb, iCompId)}";
				text2 = text2 + " AND tCore_Header" + Suffix + ".bUpdateStocks = 1 AND tCore_Data" + Suffix + ".bSuspendUpdateStocks <> 1";
			}
			else
			{
				text2 = " tCore_Header" + Suffix + ".bUpdateStocks = 1 AND tCore_Data" + Suffix + ".bSuspendUpdateStocks <> 1";
			}
			break;
		case TransactionSetType.AccountingTransactionsOfaTag:
			if (iVoucherType <= 0 || objRec.Code <= 0)
			{
				text2 = " tCore_Data" + Suffix + ".bUpdateFA = 1";
			}
			else if (iVoucherType != _focus.company(m_iCompId).faTagId)
			{
				text2 = ((iVoucherType != _focus.company(m_iCompId).invTagId) ? string.Format(" tCore_Data_Tags{0}.iTag{1} = {2} AND tCore_Data{0}.bUpdateFA = 1", Suffix, iVoucherType, objRec.Code) : string.Format(" tCore_Data{0}.iInvTag = {2} AND tCore_Data{0}.bUpdateFA = 1", Suffix, iVoucherType, objRec.Code));
			}
			else
			{
				text2 = string.Format(" tCore_Data{0}.iFaTag = {2} AND tCore_Data{0}.bUpdateFA = 1", Suffix, iVoucherType, objRec.Code);
			}
			break;
		case TransactionSetType.InventoryTransactionsOfaTag:
			text2 = ((iVoucherType <= 0 || objRec.Code <= 0) ? (" tCore_Header" + Suffix + ".bUpdateStocks = 1 AND tCore_Data" + Suffix + ".bSuspendUpdateStocks <> 1") : string.Format(" tCore_Data_Tags{0}.iTag{1} = {2} AND tCore_Header{0}.bUpdateStocks = 1 AND tCore_Data{0}.bSuspendUpdateStocks <> 1", Suffix, iVoucherType, objRec.Code));
			break;
		case TransactionSetType.AllAccountsTagwise:
		case TransactionSetType.AllProductsTagwise:
			if (iVoucherType > 0 && objRec.Code > 0)
			{
				text2 = string.Format(" tags{1}.iTag{1} = {2})", Suffix, iVoucherType, objRec.Code);
			}
			break;
		case TransactionSetType.PendingLinks:
			if (iVoucherType > 0)
			{
				text2 = $" tCore_Links{Suffix}.iLinkId = {iVoucherType} AND tCore_Links{Suffix}.bClosed = 0";
			}
			break;
		}
		return text2;
	}

	private void UpdateFilterInputValue(_Parameter[] arrParams, RepRecord objRec, Database objDb, ref _Filter[] arrFilterSource)
	{
		DbCommand dbCommand = null;
		int num = 0;
		int num2 = 0;
		bool bNextRangeField = false;
		string text = null;
		for (int i = 0; i < arrFilterSource.Length; i++)
		{
			if (string.IsNullOrEmpty(arrFilterSource[i].CompareValue) || !arrFilterSource[i].CompareValue.StartsWith("@"))
			{
				continue;
			}
			string specificInputField = GetSpecificInputField(arrFilterSource[i].CompareValue, ref bNextRangeField);
			text = $"SELECT ISNULL(iFieldId,0)[iFieldId] FROM cCore_ReportParameter{Suffix} \r\n                        WHERE sFieldVariable='{specificInputField}' AND iReportId = {objRec.ReportId}";
			dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			num = Convert.ToInt32(objDb.ExecuteScalar(dbCommand));
			if (bNextRangeField && num != 0)
			{
				num--;
			}
			if (arrParams != null && arrParams.Length != 0)
			{
				for (num2 = 0; num2 < arrParams.Length; num2++)
				{
					if (arrParams[num2].FieldId != num || arrParams[num2].FieldType != _FieldType.Master)
					{
						continue;
					}
					if (arrParams[num2].SelectionMode == _SelectionMode.Multiple)
					{
						if (objRec.Masters.Length > 1)
						{
							arrFilterSource[i].CompareValue = $"({General.GetMasters(objRec.Masters)})";
							arrFilterSource[i].IsGroup = true;
						}
						else
						{
							arrFilterSource[i].CompareValue = General.GetMasters(objRec.Masters);
						}
						num = -1;
					}
					else
					{
						arrFilterSource[i].CompareValue = GetMasterUnderGroup(objRec.Code, arrParams[num2].ControlId, objDb, m_iCompId);
					}
				}
			}
			if (num > 0 && objRec.Inputs != null)
			{
				num = FConvert.GetInputValue(objRec.Inputs, num);
				arrFilterSource[i].CompareValue = ((num < 0) ? string.Empty : num.ToString());
			}
		}
	}

	private string GetSpecificInputField(string strField, ref bool bNextRangeField)
	{
		if (strField.Contains("@ Start "))
		{
			strField = strField.Replace(" Start ", "");
		}
		else if (strField.Contains("@ End "))
		{
			strField = strField.Replace(" End ", "");
			bNextRangeField = true;
		}
		return strField;
	}

	public string GetMasterUnderGroup(int iMasterId, int iMasterTypeId, Database objDb, int iCompId)
	{
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		List<string> list = null;
		string text = null;
		string text2 = null;
		list = new List<string>();
		try
		{
			switch (iMasterTypeId)
			{
			case 1:
				text2 = "vmCore_Account";
				break;
			case 2:
				text2 = "vmCore_Product";
				break;
			default:
				text = $"select 'vm'+sModule+'_'+sMasterName from cCore_MasterDef where iMasterTypeId = {iMasterTypeId}";
				dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
				text2 = objDb.ExecuteScalar(dbCommand).ToString();
				break;
			}
			text = string.Format("WITH RecursionCTE (iMasterId, iParentId, bGroup)  AS  \r\n                            (   SELECT iMasterId, iParentId, bGroup\r\n                                FROM {1}\r\n                                WHERE iMasterId = {2} AND iTreeId = 0\r\n                                UNION ALL  \r\n                                SELECT R1.iMasterId, R1.iParentId, R1.bGroup\r\n                                FROM {1} AS R1\r\n                                JOIN RecursionCTE AS R2 ON R1.iParentId = R2.iMasterId\r\n                            )SELECT iMasterId  FROM RecursionCTE WHERE bGroup = 0", FConvert.GetSuffix(iCompId), text2, iMasterId);
			dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dbCommand.CommandTimeout = 0;
			dataReader = objDb.ExecuteReader(dbCommand);
			while (dataReader.Read())
			{
				list.Add(Convert.ToString(dataReader[0]));
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			FConvert.LogFile("FQuery.log", "Exception QueryGenerator->GetMasterUnderGroup : " + ex.Message + " \r\n " + ex.StackTrace);
		}
		if (list.Count <= 0)
		{
			return $"({iMasterId})";
		}
		return string.Format("({0})", string.Join(",", list.ToArray()));
	}

	private string document_type_filter(_TransactionSet objTransactionSet, ref bool bPending)
	{
		string text = string.Empty;
		string text2 = string.Empty;
		string text3 = string.Empty;
		string text4 = string.Empty;
		StringBuilder stringBuilder = new StringBuilder();
		if (!Convert.ToBoolean((objTransactionSet.BRS == 2) ? 1 : 0) || !Convert.ToBoolean((objTransactionSet.BRS == 1) ? 1 : 0))
		{
			if (Convert.ToBoolean((objTransactionSet.BRS == 2) ? 1 : 0))
			{
				text += string.Format(" ({1}{0}.bBrs = 1", Suffix, EnumUtils.DescriptionOf(TranTable.Body));
			}
			if (Convert.ToBoolean((objTransactionSet.BRS == 1) ? 1 : 0))
			{
				text = ((text.Length <= 0) ? (text + " (") : (text + EnumUtils.DescriptionOf(SQLKey.OR)));
				text += string.Format(" {1}{0}.bBrs = 0", Suffix, EnumUtils.DescriptionOf(TranTable.Body));
			}
			if (text.Length > 0)
			{
				text += ")";
			}
		}
		if ((objTransactionSet.DocumentOption & (int)Math.Pow(2.0, 0.0)) != 1 || (objTransactionSet.DocumentOption & (int)Math.Pow(2.0, Convert.ToInt32(1))) >> Convert.ToInt32(1) != 1)
		{
			if ((objTransactionSet.DocumentOption & (int)Math.Pow(2.0, 0.0)) == 1)
			{
				bPending = true;
				text2 += string.Format(" ({1}{0}.bSuspended = 1", Suffix, EnumUtils.DescriptionOf(TranTable.Header));
			}
			if ((objTransactionSet.DocumentOption & (int)Math.Pow(2.0, Convert.ToInt32(1))) >> Convert.ToInt32(1) == 1)
			{
				bPending = true;
				text2 = ((text2.Length <= 0) ? (text2 + " (") : (text2 + EnumUtils.DescriptionOf(SQLKey.OR)));
				text2 += string.Format(" {1}{0}.bSuspended = 0", Suffix, EnumUtils.DescriptionOf(TranTable.Header));
			}
			text2 = ((text2.Length <= 0) ? string.Format(" {1}{0}.bSuspended = 0", Suffix, EnumUtils.DescriptionOf(TranTable.Header)) : (text2 + ")"));
		}
		else
		{
			bPending = true;
		}
		if ((objTransactionSet.DocumentOption & (int)Math.Pow(2.0, Convert.ToInt32(2))) >> Convert.ToInt32(2) != 1 || (objTransactionSet.DocumentOption & (int)Math.Pow(2.0, Convert.ToInt32(3))) >> Convert.ToInt32(3) != 1)
		{
			if ((objTransactionSet.DocumentOption & (int)Math.Pow(2.0, Convert.ToInt32(2))) >> Convert.ToInt32(2) == 1)
			{
				text3 += string.Format(" ({1}{0}.bChecked = 1", Suffix, EnumUtils.DescriptionOf(TranTable.Body));
			}
			if ((objTransactionSet.DocumentOption & (int)Math.Pow(2.0, Convert.ToInt32(3))) >> Convert.ToInt32(3) == 1)
			{
				text3 = ((text3.Length <= 0) ? (text3 + " (") : (text3 + EnumUtils.DescriptionOf(SQLKey.OR)));
				text3 += string.Format(" {1}{0}.bChecked = 0", Suffix, EnumUtils.DescriptionOf(TranTable.Body));
			}
			if (text3.Length > 0)
			{
				text3 += ")";
			}
		}
		if ((objTransactionSet.DocumentOption & (int)Math.Pow(2.0, Convert.ToInt32(4))) >> Convert.ToInt32(4) != 1 || (objTransactionSet.DocumentOption & (int)Math.Pow(2.0, Convert.ToInt32(5))) >> Convert.ToInt32(5) != 1)
		{
			if ((objTransactionSet.DocumentOption & (int)Math.Pow(2.0, Convert.ToInt32(4))) >> Convert.ToInt32(4) == 1)
			{
				if (IsInventorySet(new _TransactionSet[1] { objTransactionSet }))
				{
					text4 += string.Format(" ({1}{0}.iAuthStatus = 1 AND {1}{0}.bSuspendUpdateStocks = 0", Suffix, EnumUtils.DescriptionOf(TranTable.Body));
				}
				else
				{
					text4 = ((!IsAccountingSet(new _TransactionSet[1] { objTransactionSet })) ? (text4 + string.Format(" ({1}{0}.iAuthStatus = 1", Suffix, EnumUtils.DescriptionOf(TranTable.Body))) : (text4 + string.Format(" ({1}{0}.iAuthStatus = 1 AND {1}{0}.bSuspendUpdateFA = 0", Suffix, EnumUtils.DescriptionOf(TranTable.Body))));
				}
			}
			if ((objTransactionSet.DocumentOption & (int)Math.Pow(2.0, Convert.ToInt32(5))) >> Convert.ToInt32(5) == 1)
			{
				text4 = ((text4.Length <= 0) ? (text4 + " (") : (text4 + EnumUtils.DescriptionOf(SQLKey.OR)));
				text4 += string.Format(" {1}{0}.iAuthStatus = 0", Suffix, EnumUtils.DescriptionOf(TranTable.Body));
			}
			if (text4.Length > 0)
			{
				text4 += ")";
			}
		}
		if (text.Length > 0)
		{
			stringBuilder.Append(text);
		}
		if (text2.Length > 0)
		{
			if (stringBuilder.Length > 0)
			{
				stringBuilder.Append(EnumUtils.DescriptionOf(SQLKey.AND));
			}
			stringBuilder.Append(text2);
		}
		if (text3.Length > 0)
		{
			if (stringBuilder.Length > 0)
			{
				stringBuilder.Append(EnumUtils.DescriptionOf(SQLKey.AND));
			}
			stringBuilder.Append(text3);
		}
		if (text4.Length > 0)
		{
			if (stringBuilder.Length > 0)
			{
				stringBuilder.Append(EnumUtils.DescriptionOf(SQLKey.AND));
			}
			stringBuilder.Append(text4);
		}
		return stringBuilder.ToString();
	}

	public string GetMastersInGroup(string strMasterType, int iMasterGroupId, Database objDb, int iCompanyId)
	{
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		List<int> list = new List<int>();
		List<int> list2 = null;
		string empty = string.Empty;
		try
		{
			if (!string.IsNullOrEmpty(strMasterType) && iMasterGroupId > 0)
			{
				if (objDb == null)
				{
					objDb = DatabaseWrapper.GetDatabase2(iCompanyId, -1, bReplicationServer: true);
				}
				if (strMasterType == "Code" || strMasterType == "BookNo")
				{
					strMasterType = "vrCore_Account";
					empty = $"WITH RecursionCTE (iMasterId, iParentId, bGroup)  AS  \r\n                        (   SELECT iMasterId, iParentId, bGroup\r\n                            FROM \r\n                            (\r\n\t\t                        SELECT mCore_AccountTreeDetails.iMasterId, iParentId, bGroup\r\n                                FROM mCore_Account \r\n\t\t                        JOIN mCore_AccountTreeDetails WITH(READUNCOMMITTED) ON mCore_Account.iMasterId = mCore_AccountTreeDetails.iMasterId \r\n                                WHERE iTreeId = 0 AND iStatus <> 5\r\n                            )\r\n                            vmCore_Account \r\n                            WHERE iMasterId = {iMasterGroupId} \r\n                            UNION ALL  \r\n                            SELECT R1.iMasterId, R1.iParentId, R1.bGroup\r\n                            FROM \r\n                            (\r\n\t\t                        SELECT mCore_AccountTreeDetails.iMasterId, iParentId, bGroup \r\n                                FROM mCore_Account \r\n\t\t                        JOIN mCore_AccountTreeDetails WITH(READUNCOMMITTED) ON mCore_Account.iMasterId = mCore_AccountTreeDetails.iMasterId \r\n                                WHERE iTreeId = 0 AND iStatus <> 5\r\n\t                        )R1\r\n                            JOIN RecursionCTE AS R2 ON R1.iParentId = R2.iMasterId\r\n                        )SELECT iMasterId  FROM RecursionCTE --WHERE bGroup = 0";
				}
				else
				{
					empty = string.Format("WITH RecursionCTE (iMasterId, iParentId, bGroup)  AS  \r\n                                (   SELECT iMasterId, iParentId, bGroup\r\n                                    FROM {0} \r\n                                    WHERE iMasterId = {1} AND iTreeId = 0\r\n                                    UNION ALL  \r\n                                    SELECT R1.iMasterId, R1.iParentId, R1.bGroup\r\n                                    FROM {0} AS R1\r\n                                    JOIN RecursionCTE AS R2 ON R1.iParentId = R2.iMasterId WHERE R1.iTreeId = 0\r\n                                )SELECT iMasterId  FROM RecursionCTE WHERE bGroup = 0 ", strMasterType, iMasterGroupId);
				}
				dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
				dbCommand.CommandTimeout = 0;
				dataReader = objDb.ExecuteReader(dbCommand);
				while (dataReader.Read())
				{
					list.Add(Convert.ToInt32(dataReader[0]));
				}
				dataReader.Close();
				if (list.Count > 100 && (strMasterType == "vrCore_Account" || strMasterType == "vrCore_Product"))
				{
					empty = ((!(strMasterType == "vrCore_Account")) ? $"SELECT DISTINCT iProduct FROM tCore_Indta{FConvert.GetSuffix(iCompanyId)}" : string.Format("SELECT DISTINCT iBookNo FROM tCore_Data{0} UNION SELECT DISTINCT iCode FROM tCore_Data{0} ", FConvert.GetSuffix(iCompanyId)));
					list2 = new List<int>();
					dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
					dbCommand.CommandTimeout = 0;
					dataReader = objDb.ExecuteReader(dbCommand);
					while (dataReader.Read())
					{
						list2.Add(Convert.ToInt32(dataReader[0]));
					}
					dataReader.Close();
					list = (from p in list2
						join m in list on p equals m
						select m).ToList();
				}
			}
		}
		catch (Exception ex)
		{
			FConvert.LogFile("FQuery.log", "Exception QueryGenerator->GetMastersInGroup : " + ex.Message + " \r\n " + ex.StackTrace);
		}
		if (list.Count == 0 || list.Where((int p) => p == iMasterGroupId).Count() == 0)
		{
			if (list.Count == 0)
			{
				list.Add(0);
			}
			list.Add(iMasterGroupId);
		}
		return string.Format("({0})", string.Join(",", list.ToArray()));
	}

	private string DateTimeFilter(RepRecord objRec)
	{
		return DateTimeFilter(objRec, 2, 3);
	}

	private string DateTimeFilter(RepRecord objRec, int Field1, int Field2)
	{
		_ = string.Empty;
		long num = 0L;
		long num2 = 0L;
		Date date = new Date(objRec.StartingDate, _focus.company(m_iCompId).calType);
		Time time = new Time(FConvert.GetInputValue(objRec.Inputs, Field1));
		num = new FDateTime(date.Year, date.Month, date.Day, time.Hours, time.Minutes, time.Seconds, _focus.company(m_iCompId).calType).Value;
		date = new Date(objRec.EndingDate, _focus.company(m_iCompId).calType);
		time = new Time(FConvert.GetInputValue(objRec.Inputs, Field2));
		num2 = new FDateTime(date.Year, date.Month, date.Day, time.Hours, time.Minutes, time.Seconds, _focus.company(m_iCompId).calType).Value;
		return string.Format(" AND dbo.fCore_DateTimeToInt(dbo.IntToDate(tCore_Header{0}.iModifiedDate) + dbo.fCore_IntToTime(tCore_Header{0}.iModifiedTime)) BETWEEN {1} AND {2}", Suffix, num, num2);
	}

	private string GetSpecialName(string sName, int iFieldId, int iSubParentId, bool bMasterId, uint iReportId, int SubReportId, Module oModule)
	{
		bool flag = false;
		string[] array = null;
		switch ((VTFIELDID)iFieldId)
		{
		case VTFIELDID.FDF_MODIFIED_BY:
			sName = sName.Replace("mSec_Users", "MUser");
			break;
		case VTFIELDID.FDF_USER_ID:
			sName = sName.Replace("mSec_Users", "EUser");
			break;
		case VTFIELDID.FDF_PMTTERMS:
			sName = sName.Replace($"tCore_Header_2{Suffix}.iPaymentTerms", "mCore_PaymentTerms.sPaymentDescription");
			break;
		case VTFIELDID.FDF_BODYJRNDEBIT:
		case VTFIELDID.FDF_BODYJRNCREDIT:
			if ((iReportId == 500 || iReportId == 501) && sName.StartsWith("vtCore_DrCr"))
			{
				sName = ((!sName.Contains(".Dr")) ? sName.Replace($"vtCore_DrCr{Suffix}.Cr", "TranCr") : sName.Replace($"vtCore_DrCr{Suffix}.Dr", "-TranDr"));
			}
			break;
		default:
			if ((iFieldId & 0xFFFF) == 101 || (iFieldId & 0xFFFF) == 102)
			{
				array = sName.Split('.');
				switch ((VTFIELDID)iSubParentId)
				{
				case VTFIELDID.FDF_CODE:
					sName = string.Format("CodeParent.{0}", (array.Length <= 1) ? "iMasterId" : array[1]);
					flag = true;
					break;
				case VTFIELDID.FDF_BOOKNO:
					sName = string.Format("BookParent.{0}", (array.Length <= 1) ? "iMasterId" : array[1]);
					flag = true;
					break;
				case VTFIELDID.FDF_BODYPRODUCT:
					sName = string.Format("ItemParent.{0}", (array.Length <= 1) ? "iMasterId" : array[1]);
					flag = true;
					break;
				}
			}
			if ((iSubParentId & Convert.ToInt32(VTFIELDFLAG.SCR_FTR)) == Convert.ToInt32(VTFIELDFLAG.SCR_FTR) && sName.Contains("vrCore_Account"))
			{
				if ((iSubParentId & 0xFFFFFF) - 1001 >= 0)
				{
					sName = $"FooterDrAc{(iSubParentId & 0xFFFFFF) - 1001}.iMasterId";
					flag = true;
				}
				else if ((iSubParentId & 0xFFFFFF) - 2001 >= 0)
				{
					sName = $"FooterCrAc{(iSubParentId & 0xFFFFFF) - 2001}.iMasterId";
					flag = true;
				}
			}
			if (flag)
			{
				break;
			}
			if (sName.Contains(".sName") && !sName.Contains("Language"))
			{
				sName = ((oModule != Module.None || (byte)SubReportId != 7 || !sName.StartsWith("Code.")) ? sName.Replace(".sName", ".iMasterId") : "mCore_Account.iMasterId");
				break;
			}
			if (sName.Contains(".iMasterId"))
			{
				if (sName.Contains(_focus.company(m_iCompId).faTagName))
				{
					sName = $"tCore_Data{Suffix}.iFaTag";
				}
				else if (sName.Contains(_focus.company(m_iCompId).invTagName))
				{
					sName = $"tCore_Data{Suffix}.iInvTag";
				}
				break;
			}
			array = sName.Split('.');
			switch ((VTFIELDID)iSubParentId)
			{
			case VTFIELDID.FDF_CODE:
				sName = ((!sName.Contains("Language")) ? string.Format("Code.{0}", (array.Length <= 1) ? "iMasterId" : array[1]) : sName.Replace("mCore_AccountLanguage", "CodeLanguage"));
				break;
			case VTFIELDID.FDF_BOOKNO:
				sName = ((!sName.Contains("Language")) ? string.Format("BookNo.{0}", (array.Length <= 1) ? "iMasterId" : array[1]) : sName.Replace("mCore_AccountLanguage", "BookNoLanguage"));
				break;
			}
			break;
		case VTFIELDID.FDF_VOUCHERNAME:
		case VTFIELDID.FDF_PROD_PROCESS:
			break;
		}
		if ((iReportId == 500 || iReportId == 501) && sName.StartsWith("tCore_Header"))
		{
			sName = sName.Replace($"tCore_Header{Suffix}", $"tCore_Data{Suffix}");
		}
		return sName;
	}

	private string AppendSubQuery(RepRecord objRec, string strQuery, string strExtraColumn, string strExtraColumnAlias, FieldData[] arrFields, Database objDb)
	{
		int num = 0;
		int iDisplayTotal = 0;
		int num2 = 0;
		string text = null;
		string text2 = string.Empty;
		string text3 = string.Empty;
		_ = string.Empty;
		string empty = string.Empty;
		bool bClosed = m_bClosed;
		ComboData[] array = null;
		IdNamePair[] array2 = null;
		if (objRec.Module == Module.None)
		{
			return strQuery;
		}
		switch ((FocusReport)objRec.ReportId)
		{
		case FocusReport.Ledger:
		case FocusReport.SubLedger:
			if (objRec.ReportId == 500 && FConvert.GetInputValue(objRec.Inputs, -12) == 1)
			{
				num = 2;
			}
			else
			{
				iDisplayTotal = 0;
				num = IsAccountPropertyEnable(objRec.Inputs, objRec.Masters, (FocusReport)objRec.ReportId, objRec.Code, ref iDisplayTotal);
			}
			if (iDisplayTotal >= 2 && iDisplayTotal <= 4)
			{
				strQuery = iDisplayTotal switch
				{
					2 => strQuery + $" GROUP BY dbo.GetDatePart('y',iDate), dbo.GetDatePart('m',iDate), dbo.GetDateName('m',iDate)+ ' '+CAST(dbo.GetDatePart('y',iDate) as varchar),tCore_Data{Suffix}.iMasterId", 
					3 => strQuery + $" GROUP BY dbo.IntToDate( iDate),tCore_Data{Suffix}.iMasterId", 
					_ => strQuery + $" GROUP BY tCore_Data{Suffix}.iMasterId,ContrAccount.sName", 
				};
				strQuery += string.Format(" HAVING((SUM(Debit) + SUM(Credit) <> 0) OR(SUM(TranDr) + SUM(TranCr) <> 0) OR(SUM(LocalDr) + SUM(LocalCr) <> 0))", Suffix);
				break;
			}
			if (num > 0 && !string.IsNullOrEmpty(strExtraColumnAlias))
			{
				string[] array3 = strExtraColumnAlias.Split(',');
				for (iDisplayTotal = 1; iDisplayTotal < array3.Length; iDisplayTotal++)
				{
					if (!string.IsNullOrEmpty(array3[iDisplayTotal]))
					{
						if (iDisplayTotal - 1 < arrFields.Length && arrFields[iDisplayTotal - 1].DataType == MasterDataType.Boolean)
						{
							text3 = text3 + ",MIN(CASE WHEN " + array3[iDisplayTotal] + " = '1' THEN 1 ELSE 0 END)" + array3[iDisplayTotal];
						}
						else if (iDisplayTotal - 1 < arrFields.Length && arrFields[iDisplayTotal - 1].FieldId != -2 && arrFields[iDisplayTotal - 1].DataType == MasterDataType.Fraction)
						{
							empty = GetColumnFunction(objRec, arrFields[iDisplayTotal - 1], bSummary: true);
							empty = (string.IsNullOrEmpty(empty) ? "SUM" : empty);
							text3 = text3 + "," + empty + "(" + array3[iDisplayTotal] + ")" + array3[iDisplayTotal];
						}
						else
						{
							text3 = text3 + ",MIN(" + array3[iDisplayTotal] + ")" + array3[iDisplayTotal];
						}
					}
				}
			}
			empty = string.Empty;
			if (_focus.company(m_iCompId).isModuleImplemented(ModulesImplemented.SubLedger) && num > 0)
			{
				empty = ",[SubLedgerName]";
			}
			switch (num)
			{
			case 1:
				strQuery = strQuery.Insert(0, $"SELECT iHeaderId,[iMasterId],iDate,[Voucher],[Account], \r\n                        SUM(TranDr)[TranDr], SUM(TranCr)[TranCr],0[TranBal],                        \r\n                        SUM(LocalDr)[LocalDr], SUM(LocalCr)[LocalCr],0[LocalBal],                        \r\n                        SUM(Debit)[Debit], SUM(Credit)[Credit],0[Balance],\r\n                        MIN([Currency])[Currency],[bHeader],[iVoucherType] {empty}{text3} FROM(");
				strQuery += string.Format(") TempTable GROUP BY iHeaderId,iDate,[Voucher],[Account],[iMasterId],[bHeader],[iVoucherType]{3}", objRec.StartingDate, objRec.EndingDate, text2, empty);
				strQuery += " HAVING ((SUM(Debit) + SUM(Credit) <> 0) OR (SUM(TranDr) + SUM(TranCr) <> 0) OR (SUM(LocalDr) + SUM(LocalCr) <> 0))";
				break;
			case 2:
				if (objRec.ReportId == 500 && FConvert.GetInputValue(objRec.Inputs, -12) == 1)
				{
					strQuery = strQuery.Insert(0, $"SELECT iHeaderId,TempTable.[iMasterId],iDate,[Voucher],MAX([Account])[AccountName], \r\n                                CASE WHEN SUM(TranDr)+SUM(TranCr) < 0 THEN SUM(TranDr) + SUM(TranCr) ELSE 0 END[TranDr], \r\n                                CASE WHEN SUM(TranDr)+SUM(TranCr) > 0 THEN SUM(TranDr) + SUM(TranCr) ELSE 0 END[TranCr],0[TranBal],                        \r\n                                CASE WHEN SUM(LocalDr)+SUM(LocalCr) < 0 THEN SUM(LocalDr) + SUM(LocalCr) ELSE 0 END[LocalDr], \r\n                                CASE WHEN SUM(LocalDr)+SUM(LocalCr) > 0 THEN SUM(LocalDr) + SUM(LocalCr) ELSE 0 END[LocalCr],0[LocalBal],                        \r\n                                CASE WHEN SUM(Debit)+SUM(Credit) < 0 THEN SUM(Debit) + SUM(Credit) ELSE 0 END[Debit], \r\n                                CASE WHEN SUM(Debit)+SUM(Credit) > 0 THEN SUM(Debit) + SUM(Credit) ELSE 0 END[Credit],0[Balance],\r\n                                MIN([Currency])[Currency],[bHeader],[iVoucherType] {empty}{text3} FROM(");
					strQuery += string.Format(") TempTable \r\n                                JOIN dbo.fCore_GetAccountTreeSequence(0,0) ATree ON ATree.iMasterId = TempTable.iMasterId\r\n                                GROUP BY iHeaderId,iDate,[Voucher],TempTable.[iMasterId],[bHeader],[iVoucherType],ATree.iSeq{3}", objRec.StartingDate, objRec.EndingDate, text2, empty);
				}
				else
				{
					strQuery = strQuery.Insert(0, $"SELECT iHeaderId,[iMasterId],iDate,[Voucher],MAX([Account])[AccountName], \r\n                                CASE WHEN SUM(TranDr)+SUM(TranCr) < 0 THEN SUM(TranDr) + SUM(TranCr) ELSE 0 END[TranDr], \r\n                                CASE WHEN SUM(TranDr)+SUM(TranCr) > 0 THEN SUM(TranDr) + SUM(TranCr) ELSE 0 END[TranCr],0[TranBal],                        \r\n                                CASE WHEN SUM(LocalDr)+SUM(LocalCr) < 0 THEN SUM(LocalDr) + SUM(LocalCr) ELSE 0 END[LocalDr], \r\n                                CASE WHEN SUM(LocalDr)+SUM(LocalCr) > 0 THEN SUM(LocalDr) + SUM(LocalCr) ELSE 0 END[LocalCr],0[LocalBal],                        \r\n                                CASE WHEN SUM(Debit)+SUM(Credit) < 0 THEN SUM(Debit) + SUM(Credit) ELSE 0 END[Debit], \r\n                                CASE WHEN SUM(Debit)+SUM(Credit) > 0 THEN SUM(Debit) + SUM(Credit) ELSE 0 END[Credit],0[Balance],\r\n                                MIN([Currency])[Currency],[bHeader],[iVoucherType] {empty}{text3} FROM(");
					strQuery += string.Format(") TempTable GROUP BY iHeaderId,iDate,[Voucher],[iMasterId],[bHeader],[iVoucherType]{3}", objRec.StartingDate, objRec.EndingDate, text2, empty);
				}
				strQuery += " HAVING CASE WHEN SUM(TranDr) + SUM(TranCr) < 0 THEN SUM(TranDr) + SUM(TranCr) ELSE 0 END <> 0 OR\r\nCASE WHEN SUM(TranDr) + SUM(TranCr) > 0 THEN SUM(TranDr) + SUM(TranCr) ELSE 0 END <> 0 OR\r\nCASE WHEN SUM(LocalDr) + SUM(LocalCr) < 0 THEN SUM(LocalDr) + SUM(LocalCr) ELSE 0 END <> 0 OR\r\nCASE WHEN SUM(LocalDr) + SUM(LocalCr) > 0 THEN SUM(LocalDr) + SUM(LocalCr) ELSE 0 END <> 0 OR\r\nCASE WHEN SUM(Debit) + SUM(Credit) < 0 THEN SUM(Debit) + SUM(Credit) ELSE 0 END <> 0 OR\r\nCASE WHEN SUM(Debit) + SUM(Credit) > 0 THEN SUM(Debit) + SUM(Credit) ELSE 0 END <> 0";
				break;
			case 3:
				if (objRec.ReportId == 500 && FConvert.GetInputValue(objRec.Inputs, -12) == 1)
				{
					strQuery = strQuery.Insert(0, $"SELECT iHeaderId,TempTable.[iMasterId],iDate,[Voucher],[Account][AccountName], \r\n                                CASE WHEN SUM(TranDr)+SUM(TranCr) < 0 THEN SUM(TranDr) + SUM(TranCr) ELSE 0 END[TranDr], \r\n                                CASE WHEN SUM(TranDr)+SUM(TranCr) > 0 THEN SUM(TranDr) + SUM(TranCr) ELSE 0 END[TranCr],0[TranBal],                        \r\n                                CASE WHEN SUM(LocalDr)+SUM(LocalCr) < 0 THEN SUM(LocalDr) + SUM(LocalCr) ELSE 0 END[LocalDr], \r\n                                CASE WHEN SUM(LocalDr)+SUM(LocalCr) > 0 THEN SUM(LocalDr) + SUM(LocalCr) ELSE 0 END[LocalCr],0[LocalBal],                        \r\n                                CASE WHEN SUM(Debit)+SUM(Credit) < 0 THEN SUM(Debit) + SUM(Credit) ELSE 0 END[Debit], \r\n                                CASE WHEN SUM(Debit)+SUM(Credit) > 0 THEN SUM(Debit) + SUM(Credit) ELSE 0 END[Credit],0[Balance],\r\n                                MIN([Currency])[Currency],[bHeader],[iVoucherType] {empty}{text3} FROM(");
					strQuery += string.Format(") TempTable \r\n                                JOIN dbo.fCore_GetAccountTreeSequence(0,0) ATree ON ATree.iMasterId = TempTable.iMasterId\r\n                                GROUP BY iHeaderId,iDate,[Voucher],TempTable.[iMasterId],[bHeader],[iVoucherType],ATree.iSeq,[Account]{3}", objRec.StartingDate, objRec.EndingDate, text2, empty);
				}
				else
				{
					strQuery = strQuery.Insert(0, $"SELECT iHeaderId,[iMasterId],iDate,[Voucher],[Account][AccountName], \r\n                                CASE WHEN SUM(TranDr)+SUM(TranCr) < 0 THEN SUM(TranDr) + SUM(TranCr) ELSE 0 END[TranDr], \r\n                                CASE WHEN SUM(TranDr)+SUM(TranCr) > 0 THEN SUM(TranDr) + SUM(TranCr) ELSE 0 END[TranCr],0[TranBal],                        \r\n                                CASE WHEN SUM(LocalDr)+SUM(LocalCr) < 0 THEN SUM(LocalDr) + SUM(LocalCr) ELSE 0 END[LocalDr], \r\n                                CASE WHEN SUM(LocalDr)+SUM(LocalCr) > 0 THEN SUM(LocalDr) + SUM(LocalCr) ELSE 0 END[LocalCr],0[LocalBal],                        \r\n                                CASE WHEN SUM(Debit)+SUM(Credit) < 0 THEN SUM(Debit) + SUM(Credit) ELSE 0 END[Debit], \r\n                                CASE WHEN SUM(Debit)+SUM(Credit) > 0 THEN SUM(Debit) + SUM(Credit) ELSE 0 END[Credit],0[Balance],\r\n                                MIN([Currency])[Currency],[bHeader],[iVoucherType] {empty}{text3} FROM(");
					strQuery += string.Format(") TempTable GROUP BY iHeaderId,iDate,[Voucher],[iMasterId],[bHeader],[iVoucherType],[Account]{3}", objRec.StartingDate, objRec.EndingDate, text2, empty);
				}
				strQuery += " HAVING CASE WHEN SUM(TranDr) + SUM(TranCr) < 0 THEN SUM(TranDr) + SUM(TranCr) ELSE 0 END <> 0 OR\r\nCASE WHEN SUM(TranDr) + SUM(TranCr) > 0 THEN SUM(TranDr) + SUM(TranCr) ELSE 0 END <> 0 OR\r\nCASE WHEN SUM(LocalDr) + SUM(LocalCr) < 0 THEN SUM(LocalDr) + SUM(LocalCr) ELSE 0 END <> 0 OR\r\nCASE WHEN SUM(LocalDr) + SUM(LocalCr) > 0 THEN SUM(LocalDr) + SUM(LocalCr) ELSE 0 END <> 0 OR\r\nCASE WHEN SUM(Debit) + SUM(Credit) < 0 THEN SUM(Debit) + SUM(Credit) ELSE 0 END <> 0 OR\r\nCASE WHEN SUM(Debit) + SUM(Credit) > 0 THEN SUM(Debit) + SUM(Credit) ELSE 0 END <> 0";
				break;
			}
			break;
		case FocusReport.CashBook:
			strQuery = strQuery.Insert(0, $"SELECT iHeaderId,iDate,[Voucher],MAX([Account])[Account], \r\n                    SUM(Debit)[Debit], SUM(Credit)[Credit],0[Balance base],\r\n                    SUM(TranDr)[TranDr], SUM(TranCr)[TranCr],0[Balance tran],\r\n                    SUM(DebitLocal)[DebitLocal], SUM(CreditLocal)[CreditLocal],0[Balance local]\r\n                    {strExtraColumnAlias} FROM(");
			strQuery += $") TempTable WHERE iDate BETWEEN {objRec.StartingDate} AND {objRec.EndingDate} AND (Debit <> 0 OR Credit <>0) {text2} GROUP BY iHeaderId,iDate,[Voucher]{strExtraColumnAlias}\r\n                    HAVING SUM(Debit) + SUM(Credit) <> 0 OR SUM(TranDr) + SUM(TranCr) <> 0 OR SUM(DebitLocal) + SUM(CreditLocal) <> 0 ";
			break;
		case FocusReport.BankBook:
		case FocusReport.PettyCashBook:
			strQuery = strQuery.Insert(0, $"SELECT iHeaderId,iDate,[Voucher],MAX([Account])[Account], \r\n                    SUM(Debit)[Debit], SUM(Credit)[Credit],0[Balance base],\r\n                    SUM(TranDr)[TranDr], SUM(TranCr)[TranCr],0[Balance tran],\r\n                    SUM(DebitLocal)[DebitLocal], SUM(CreditLocal)[CreditLocal],0[Balance local]\r\n                    {strExtraColumnAlias} FROM(");
			strQuery += $") TempTable WHERE iDate BETWEEN {objRec.StartingDate} AND {objRec.EndingDate} AND (Debit <> 0 OR Credit <>0) {text2} GROUP BY iHeaderId,iDate,[Voucher]{strExtraColumnAlias}";
			break;
		case FocusReport.BankReconciliationStatement:
		{
			if (objRec.Code > 0)
			{
				text2 = $" AND iMasterId = {objRec.Code} ";
			}
			if (FConvert.GetInputValue(objRec.Inputs, 3) == 1)
			{
				text2 = ((objRec.Code <= 0) ? (text2 + $" or  (TempTable.iVoucherType = {256} and iDueDate > {objRec.EndingDate}  AND bBrs = 1 ) ") : (text2 + $" or  (TempTable.iVoucherType = {256} and iDueDate > {objRec.EndingDate}  AND bBrs = 1 AND iMasterId = {objRec.Code}) "));
			}
			int inputValue = FConvert.GetInputValue(objRec.Inputs, 4);
			if (inputValue > 0 && inputValue == 2)
			{
				text = string.Format(" OR (iDueDate = {1} AND iDate BETWEEN {0} AND {1} AND bBrs = 1)", objRec.StartingDate, objRec.EndingDate);
			}
			if (FConvert.GetInputValue(objRec.Inputs, 1) == 1 && !string.IsNullOrEmpty(strExtraColumnAlias) && strExtraColumnAlias.Contains("vCore_TranData" + Suffix + ".sChequeNo"))
			{
				string[] array4 = strExtraColumnAlias.Split(',');
				empty = (text3 = string.Empty);
				for (num = 0; num < array4.Length; num++)
				{
					if (!string.IsNullOrEmpty(array4[num]))
					{
						if (array4[num].Contains("vCore_TranData" + Suffix + ".sChequeNo"))
						{
							array4[num] = $"MIN({array4[num]})[sChequeNo{num}]";
						}
						else
						{
							empty = empty + "," + array4[num];
						}
						text3 = text3 + "," + array4[num];
					}
				}
				strQuery = strQuery.Insert(0, $"SELECT iHeaderId,iDate,[Voucher],[Account]\r\n                        ,CASE WHEN SUM([TranDr])+SUM([TranCr]) < 0 THEN SUM([TranDr])+SUM([TranCr]) Else 0 End [TranDr]\r\n                        ,CASE WHEN SUM([TranDr])+SUM([TranCr]) > 0 THEN SUM([TranDr])+SUM([TranCr]) Else 0 End [TranCr]\r\n                        ,0[Balance]\r\n                        ,0[CumulativeBalTran]\r\n                        ,CASE WHEN SUM([Debit])+SUM([Credit]) < 0 THEN SUM([Debit])+SUM([Credit]) Else 0 End [Debit]\r\n                        ,CASE WHEN SUM([Debit])+SUM([Credit]) > 0 THEN SUM([Debit])+SUM([Credit]) Else 0 End [Credit]\r\n                        ,0[Balance] \r\n                        ,0[CumulativeBalance]\r\n                        ,CASE WHEN SUM([LocalDr])+SUM([LocalCr]) < 0 THEN SUM([LocalDr])+SUM([LocalCr]) Else 0 End [LocalDr]\r\n                        ,CASE WHEN SUM([LocalDr])+SUM([LocalCr]) > 0 THEN SUM([LocalDr])+SUM([LocalCr]) Else 0 End [LocalCr]\r\n                        ,0[Balance]\r\n                        ,0[CumulativeBalanceLocal]\r\n                        {text3} FROM(");
				strQuery += string.Format(") TempTable \r\n                        WHERE ((iDate <= {1} AND bBrs = 0) OR (iDueDate > {1} AND iDate BETWEEN {0} AND {1} AND bBrs = 1)) {2} \r\n                        GROUP BY iHeaderId,iDate,[Voucher],[Account]{3}\r\n                        HAVING ((SUM(Debit) + SUM(Credit) <> 0) OR (SUM(TranDr) + SUM(TranCr) <> 0) OR (SUM(LocalDr) + SUM(LocalCr) <> 0))", objRec.StartingDate, objRec.EndingDate, text2, empty);
			}
			else
			{
				strQuery = strQuery.Insert(0, $"SELECT iHeaderId,iDate,[Voucher],[Account]\r\n                        ,CASE WHEN SUM([TranDr])+SUM([TranCr]) < 0 THEN SUM([TranDr])+SUM([TranCr]) Else 0 End [TranDr]\r\n                        ,CASE WHEN SUM([TranDr])+SUM([TranCr]) > 0 THEN SUM([TranDr])+SUM([TranCr]) Else 0 End [TranCr]\r\n                        ,0[BalanceTran]\r\n                        ,0[CumulativeBalTran]\r\n                        ,CASE WHEN SUM([Debit])+SUM([Credit]) < 0 THEN SUM([Debit])+SUM([Credit]) Else 0 End [Debit]\r\n                        ,CASE WHEN SUM([Debit])+SUM([Credit]) > 0 THEN SUM([Debit])+SUM([Credit]) Else 0 End [Credit]\r\n                        ,0[Balance] \r\n                        ,0[CumulativeBalance]\r\n                        ,CASE WHEN SUM([LocalDr])+SUM([LocalCr]) < 0 THEN SUM([LocalDr])+SUM([LocalCr]) Else 0 End [LocalDr]\r\n                        ,CASE WHEN SUM([LocalDr])+SUM([LocalCr]) > 0 THEN SUM([LocalDr])+SUM([LocalCr]) Else 0 End [LocalCr]\r\n                        ,0[BalanceLocal]\r\n                        ,0[CumulativeBalanceLocal]\r\n                        {strExtraColumnAlias} FROM(");
				strQuery += string.Format(") TempTable \r\n                        WHERE ((iDate <= {1} AND bBrs = 0) OR (iDueDate > {1} AND iDate BETWEEN {0} AND {1} AND bBrs = 1) {4}) {2} \r\n                        GROUP BY iHeaderId,iDate,[Voucher],[Account]{3}\r\n                        HAVING ((SUM(Debit) + SUM(Credit) <> 0) OR (SUM(TranDr) + SUM(TranCr) <> 0) OR (SUM(LocalDr) + SUM(LocalCr) <> 0))", objRec.StartingDate, objRec.EndingDate, text2, strExtraColumnAlias, text);
			}
			break;
		}
		case FocusReport.EntryJournal:
			strQuery = strQuery.Insert(0, $"SELECT iBodyId,iDate,[Voucher],[Account]\r\n                    , SUM(Debit)[Debit] , SUM(Credit)[Credit], 0[Balance],[AccountCode]\r\n                    , SUM(TranDr)[TranDr] , SUM(TranCr)[TranCr], 0[BalanceTran]\r\n                    , SUM(LocalDr)[LocalDr] , SUM(LocalCr)[LocalCr], 0[BalanceLocal] {strExtraColumnAlias} FROM(");
			strQuery += $") TempTable WHERE iDate BETWEEN {objRec.StartingDate} AND {objRec.EndingDate} AND (Debit <> 0 OR Credit <>0) {text2} GROUP BY iBodyId,iDate,[Voucher],[Account],[AccountCode]{strExtraColumnAlias}";
			break;
		case FocusReport.PeakandLowBalanceAmount:
			strQuery = strQuery.Insert(0, $"SELECT iMasterId,Account,\r\n                            ISNULL(Min(CASE WHEN Amt1 - Amt2 > 0 THEN iDate END),0)[LowDrDate],\r\n                            Min(CASE WHEN Amt1 - Amt2 > 0 THEN (Amt1 - Amt2) ELSE 0 END) [Min Debit],\r\n                            ISNULL(Max(CASE WHEN Amt1 - Amt2 > 0 THEN iDate END), 0) [High Dr Date],\r\n                            Max(CASE WHEN Amt1 - Amt2 > 0 THEN (Amt1 - Amt2) ELSE 0 END) [Max Debit],\r\n                            ISNULL(Min(CASE WHEN Amt1 - Amt2 < 0 THEN iDate END),0) [Low Cr Date],\r\n                            Min(CASE WHEN Amt1 - Amt2 < 0 THEN (Amt1 - Amt2)*-1 ELSE 0 END)[Min Credit],\r\n                            ISNULL(Max(CASE WHEN Amt1 - Amt2 < 0 THEN iDate END),0) [High Cr Date],\r\n                            Max(CASE WHEN Amt1 - Amt2 < 0 THEN (Amt1 - Amt2)*-1 ELSE 0 END) [Max Credit] {strExtraColumnAlias} FROM (");
			strQuery += ")TempTable WHERE (Amt1 <> 0 OR Amt2<>0) GROUP BY iMasterId,Account";
			strQuery += strExtraColumnAlias;
			break;
		case FocusReport.ComprativeAnalysis:
			if (FConvert.GetInputValue(objRec.Inputs, 1) == 1)
			{
				IdNamePair[] yearwiseColumns = new RDDefault
				{
					CalType = _focus.company(m_iCompId).calType
				}.GetYearwiseColumns(_focus.company(m_iCompId).accountingDate, 3);
				for (num = 0; num < yearwiseColumns.Length; num++)
				{
					text3 += string.Format(",SUM([{0}-{1}])[{0}-{1}]", yearwiseColumns[num].Name, yearwiseColumns[num].Tag);
				}
			}
			else
			{
				text3 = $",SUM(Jan)[Jan],SUM(Feb)[Feb],SUM(Mar)[Mar],SUM(Apr)[Apr],SUM(May)[May],SUM(Jun)[Jun]\r\n                        ,SUM(Jul)[Jul],SUM(Aug)[Aug],SUM(Sep)[Sep],SUM(Oct)[Oct],SUM(Nov)[Nov],SUM(Dec)[Dec]";
			}
			strQuery = strQuery.Insert(0, $"SELECT HeaderId, Account,SUM(Total)[Total],0[Opening]\r\n                     {text3} {strExtraColumnAlias} FROM (");
			strQuery += ")TempTable GROUP BY HeaderId,Account,iSeq";
			strQuery += strExtraColumnAlias;
			strQuery += " HAVING SUM(Total) <> 0";
			break;
		case FocusReport.WalkinPreorderSalesWise:
			strQuery = strQuery.Insert(0, string.Format("Declare @PosSales varchar(10) = '', @PosSO varchar(10) = ''\r\n                    select @PosSales = sAbbr + '%' from cCore_Vouchers{0} where iVoucherType = 3331\r\n                    select @PosSO = sAbbr + '%' from cCore_Vouchers{0} where iVoucherType = 5632\r\n                    Select [iHeaderId],[iDate], 0[Total Amount],SUM([WIS Amount])[WIS Amount], SUM([PROS Amount])[Pros Amount], [OutletId]{1} FROM (", Suffix, strExtraColumnAlias));
			strQuery += ")TempTable GROUP BY [iHeaderId],[iDate], [OutletId]";
			strQuery += strExtraColumnAlias;
			break;
		case FocusReport.PaymentWiseSales:
			strQuery = strQuery.Insert(0, $"Select 0[iHeaderId],[iDate], 0[Total],\r\n                    SUM([Cash Amount])[Cash Amount], SUM([P_Cash Amount])[P_Cash Amount],\r\n                    SUM([Credit Card Amount])[Credit Card Amount], SUM([P_Credit Card Amount])[P_Credit Card Amount],\r\n                    SUM([Debit Card Amount])[Debit Card Amount], SUM([P_Debit Card Amount])[P_Debit Card Amount],\r\n                    SUM([Cheque Value])[Cheque Value],SUM([P_Cheque Value])[P_Cheque Value],\r\n                    SUM([Coupon Amount])[Coupon Amount],SUM([P_Coupon Amount])[P_Coupon Amount],\r\n                    SUM([Credit Notes])[Credit Notes],SUM([P_Credit Notes])[P_Credit Notes],\r\n                    SUM([Discount Coupon])[Discount Coupon],SUM([P_Discount Coupon])[P_Discount Coupon],\r\n                    SUM([Credit sales])[Credit sales],SUM([P_Credit sales])[P_Credit sales],\r\n                    SUM([Credit charges])[Credit charges],SUM([P_Credit charges])[P_Credit charges],\r\n                    SUM([Debit charges])[Debit charges],SUM([P_Debit charges])[P_Debit charges],\r\n                    SUM([Points Redemption])[Points Redemption],SUM([P_Points Redemption])[P_Points Redemption],\r\n                    SUM([EPayment Type]) [EPayment Type],\r\n\t\t\t\t\tSUM([P_EPayment Type]) [P_EPayment Type],\r\n                    [OutletId]{strExtraColumnAlias} FROM (");
			strQuery += ")TempTable ";
			strQuery += string.Format(" WHERE iDate BETWEEN {1} AND {2} ", Suffix, objRec.StartingDate, objRec.EndingDate);
			if (objRec.Masters != null && !objRec.IsSelectAll)
			{
				strQuery += string.Format(" AND [OutletId] IN ({1})", Suffix, General.GetMasters(objRec.Masters));
			}
			strQuery += " GROUP BY [iDate], [OutletId] ";
			strQuery += strExtraColumnAlias;
			break;
		case FocusReport.PaymentModeWiseSalesSummary:
		{
			if (objRec.Masters != null && !objRec.IsSelectAll)
			{
