				for (num = 0; num < EXTRAFORMULACOLUMNS; num++)
				{
					text += $",'0'[Col{num + arrFields.Length + 1}]";
				}
			}
			strQuery = ((!flag2) ? strQuery.Insert(0, string.Format("SELECT DISTINCT tCore_Indta{0}.iProduct{1} \r\n                                    FROM vrCore_Product\r\n                                    JOIN tCore_Indta{0} ON tCore_Indta{0}.iProduct = vrCore_Product.iMasterId \r\n                                    {2} UNION ALL ", Suffix, text, (!string.IsNullOrEmpty(m_strParamValues)) ? "JOIN @XML.nodes('/Master/r') T(c) ON vrCore_Product.iMasterId = T.c.value('./@id', 'int')" : "")) : strQuery.Insert(0, string.Format("SELECT DISTINCT tCore_Indta{0}.iProduct{1} \r\n                                    FROM vrCore_Product\r\n                                    JOIN tCore_Indta{0} ON tCore_Indta{0}.iProduct = vrCore_Product.iMasterId \r\n                                    JOIN tCore_Data{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId\r\n                                    LEFT JOIN {3} ON {3}.iMasterId = tCore_Data{0}.iInvTag  \r\n                                    {2} UNION ALL ", Suffix, text, (!string.IsNullOrEmpty(m_strParamValues)) ? "JOIN @XML.nodes('/Master/r') T(c) ON vrCore_Product.iMasterId = T.c.value('./@id', 'int')" : "", _focus.company(m_iCompId).invTagName)));
			break;
		}
		}
		return strQuery;
	}

	private string GroupOrOrderBy(RepRecord objRec, string strExtraColumns, Database objDb, bool bPreviousYear = false, FieldData[] arrField = null, List<MasterRights> arrRestrictMasters = null)
	{
		string text = string.Empty;
		string text2 = null;
		strExtraColumns = strExtraColumns.Replace(",'0'", string.Empty);
		strExtraColumns = strExtraColumns.Replace(",ROW_NUMBER() over (order by (select 1))", string.Empty);
		if (strExtraColumns.Contains("tCore_Header" + Suffix + ".sVoucherNo"))
		{
			strExtraColumns = strExtraColumns + ",cCore_Vouchers" + Suffix + ".sAbbr";
		}
		switch (objRec.Module)
		{
		case Module.CoreTransactions:
			switch ((FocusReport)objRec.ReportId)
			{
			case FocusReport.SalesPredictionReport:
			case FocusReport.PurchasePredictionReport:
				text = $" GROUP BY tCore_Indta{Suffix}.iProduct";
				break;
			case FocusReport.SummarySalesRegister:
				text = string.Format(" GROUP BY tCore_Data{0}.iHeaderId, tCore_Header{0}.iDate, cCore_Vouchers{0}.sAbbr, tCore_Header{0}.sVoucherNo, BookNo.sName ", Suffix);
				text += strExtraColumns;
				break;
			case FocusReport.SummaryPurchaseRegister:
				text = string.Format(" GROUP BY tCore_Data{0}.iHeaderId, tCore_Header{0}.iDate, cCore_Vouchers{0}.sAbbr, tCore_Header{0}.sVoucherNo, BookNo.sName ", Suffix);
				text += strExtraColumns;
				break;
			case FocusReport.SalesGroupedByCustomer:
			case FocusReport.PurchasesGroupedByVendor:
				text = ((!_focus.company(m_iCompId).isModuleImplemented(ModulesImplemented.SubLedger)) ? " GROUP BY BookNo.sName,vrCore_Product.sName,BookNo.iMasterId " : " GROUP BY mCore_SubLedger.sName,vrCore_Product.sName,mCore_SubLedger.iMasterId ");
				text += strExtraColumns;
				break;
			case FocusReport.SalesGroupedByProduct:
			case FocusReport.PurchasesGroupedByProduct:
				text = ((!_focus.company(m_iCompId).isModuleImplemented(ModulesImplemented.SubLedger)) ? " GROUP BY BookNo.sName,vrCore_Product.sName,vrCore_Product.iMasterId " : " GROUP BY mCore_SubLedger.sName,vrCore_Product.sName,vrCore_Product.iMasterId ");
				text += strExtraColumns;
				break;
			case FocusReport.SalesGroupedByDepartment:
			case FocusReport.PurchasesGroupedByDepartment:
				text = string.Format(" GROUP BY {0}.sName,vrCore_Product.sName,{0}.iMasterId ", _focus.company(m_iCompId).faTagName);
				text += strExtraColumns;
				break;
			case FocusReport.ComprativeAnalysis:
				text = string.Format(" GROUP by vrCore_Account.iMasterId,vrCore_Account.sName,iDate,ATree.iSeq", Suffix);
				text += strExtraColumns;
				break;
			case FocusReport.TransactionsTypeAnalysis:
				text = $" GROUP by vrCore_Account.iMasterId,vrCore_Account.sName {strExtraColumns} ";
				break;
			case FocusReport.CustomerBillwiseSummary:
			case FocusReport.VendorBillwiseSummary:
				text = $" GROUP BY vrCore_Account.iMasterId,vrCore_Account.sName,vrCore_Account.sCode{strExtraColumns},iRowSeq";
				break;
			case FocusReport.VendorAgeingSummaryBillwise:
			case FocusReport.VendorSummaryAgeingByDueDate:
			case FocusReport.CustomerAgeingSummaryBillwise:
			case FocusReport.CustomerSummaryAgeingByDueDate:
				text += strExtraColumns;
				break;
			case FocusReport.VendorOverdueSummary:
			case FocusReport.CustomerOverdueSummary:
				text = $" GROUP BY vrCore_Account.iMasterId,vrCore_Account.sName,vrCore_Account.sCode, iRowSeq";
				text += strExtraColumns;
				text += " Having SUM(mAmount)+avg(isnull(mUnAdjAmount,0))<>0";
				break;
			case FocusReport.VATSalesByCustomer:
				text = $" GROUP BY Code.sName";
				text += strExtraColumns;
				break;
			case FocusReport.MonthlySales:
				text = string.Format(" GROUP BY dbo.GetDateName('m',iDate),\r\n                            dbo.GetDatePart('m', iDate)", Suffix);
				text += strExtraColumns;
				break;
			case FocusReport.TopCustomers:
				text = ((!_focus.company(m_iCompId).isModuleImplemented(ModulesImplemented.SubLedger)) ? " GROUP BY vrCore_Account.sName,vrCore_Account.iMasterId" : " GROUP BY mCore_SubLedger.sName,mCore_SubLedger.iMasterId");
				text += strExtraColumns;
				break;
			case FocusReport.IncomeExpenseTrend:
				text = string.Format(" GROUP BY dbo.GetDatePart('y', iDate),dbo.GetDatePart('m', iDate),\r\n                            dbo.GetDateName('m',iDate)", Suffix);
				text += strExtraColumns;
				break;
			case FocusReport.DayBook:
				text2 = $"tCore_Header{Suffix}.iHeaderId,Voucher";
				if (FConvert.GetInputValue(objRec.Inputs, 1) == 1)
				{
					text2 = string.Format("CASE WHEN AccountType = 1 AND tCore_Header{0}.iVoucherClass = {1} THEN 0 ELSE tCore_Header{0}.iHeaderId END\r\n                                ,CASE WHEN AccountType = 1 AND tCore_Header{0}.iVoucherClass = {1} THEN 'Cash Sales for the day' ELSE Voucher END", Suffix, 3328);
				}
				text = $" GROUP BY {text2},iDate,InnerTable.Account";
				text += strExtraColumns;
				text += " HAVING SUM(Debit) < 0 OR SUM(Credit) > 0";
				break;
			case FocusReport.PDCRecieptsRegisters:
			case FocusReport.PDCPaymentsRegisters:
				if (FConvert.GetInputValue(objRec.Inputs, 2) == 1)
				{
					text = string.Format(" GROUP BY tCore_Data{0}.iHeaderId,tCore_Header{0}.iDate, cCore_Vouchers{0}.sAbbr+' : '+tCore_Header{0}.sVoucherNo,\r\n                                mBookNo.sName, mCode.sName, tCore_Data{0}.iDueDate", Suffix);
					text += strExtraColumns;
				}
				break;
			case FocusReport.TransactionAuthorizationReport:
				text = string.Format(" GROUP BY tCore_Header{0}.iHeaderId,sAbbr, sVoucherNo, tCore_Header{0}.iDate, mCore_AuthorizationDetails{0}.iLevel\r\n                            , AuthUser{0}.sUserName, tCore_TransAuthUsers{0}.iAuthDate, tCore_TransAuthUsers{0}.iAuthTime, tCore_TransAuthUsers{0}.sRemarks, tCore_TransAuthUsers{0}.iStatus {1}, tCore_TransAuth{0}.iAuthNodeId, tCore_TransAuth{0}.iAuthId", Suffix, strExtraColumns);
				break;
			case FocusReport.MasterAuthorizationReport:
				text = string.Format("  ", Suffix, strExtraColumns);
				break;
			case FocusReport.VirtualBankLedger:
				text = string.Format(" GROUP BY InnerTable.iMasterId,CASE WHEN tCore_Header{0}.iVoucherClass IN(7168,5888) THEN tCore_Data{0}.iDueDate ELSE tCore_Header{0}.iDate END{1}", Suffix, strExtraColumns);
				break;
			case FocusReport.EntryStatsReport:
				text = " GROUP BY tCore_Header" + Suffix + ".iVoucherType, tCore_Header" + Suffix + ".iCreatedDate, cCore_Vouchers" + Suffix + ".sName, ISNULL(mSec_USers.sUserName, mSec_USers.sLoginName), tCore_Header" + Suffix + ".iUserId, mSec_Users.iUserId, tCore_Header" + Suffix + ".iModifiedDate";
				break;
			case FocusReport.AuthorizationDelayReport:
				text = " GROUP BY iRoleOrUserId, sUserName, sName";
				break;
			case FocusReport.AverageDaysToPayReport:
				text = " GROUP BY NewRef.iCode,vrCore_Account.sName";
				text += strExtraColumns;
				break;
			}
			break;
		case Module.Inventory:
			switch ((FocusReport)objRec.ReportId)
			{
			case FocusReport.StockStatement:
				text = string.Format(" GROUP BY tCore_Indta{0}.iProduct,tCore_Header{0}.iDate,vrCore_Product.iValuationMethod ", Suffix);
				text2 = General.GetSortingOnItem(objRec.ReportId, objRec.Inputs);
				if (!string.IsNullOrEmpty(text2))
				{
					text += $",{text2}";
				}
				text += strExtraColumns;
				if (!string.IsNullOrEmpty(strExtraColumns) && strExtraColumns.Contains("sVoucherNo"))
				{
					text += ",sAbbr";
				}
				break;
			case FocusReport.StockMovement:
				text = ((string.IsNullOrEmpty(_focus.company(m_iCompId).invTagName) || FConvert.GetInputValue(objRec.Inputs, 1) != 1) ? " GROUP BY vrCore_Product.sName,vrCore_Product.sCode,vrCore_Product.iMasterId,ATree.iSeq " : $" GROUP BY vrCore_Product.sName,vrCore_Product.sCode,vrCore_Product.iMasterId,{_focus.company(m_iCompId).invTagName}.sName,tCore_Data{Suffix}.iInvTag,ATree.iSeq ");
				text += strExtraColumns;
				break;
			case FocusReport.StockValuationByFATag:
				text = string.Format(" GROUP BY vrCore_Product.sName,vrCore_Product.sCode,vrCore_Product.iMasterId,{0}.sName,{0}.iMasterId ", _focus.company(m_iCompId).faTagName);
				text += strExtraColumns;
				break;
			case FocusReport.FastMovingStock:
			case FocusReport.SlowMovingStock:
				text = "GROUP BY vrCore_Product.sName,vrCore_Product.iMasterId,vrCore_Product.sCode,mCore_ProductLanguage.sName";
				if (!string.IsNullOrEmpty(_focus.company(m_iCompId).invTagName) && IsInventoryFieldAdded(objRec))
				{
					text += string.Format(",{0}.sName,{0}.iMasterId", _focus.company(m_iCompId).invTagName);
				}
				text += strExtraColumns;
				text += $" HAVING SUM(CASE WHEN tCore_Indta{Suffix}.fQuantityInBase < 0 THEN 1 ELSE 0 END) > 0";
				break;
			case FocusReport.VirtualStockAnalysis:
				text = " GROUP BY vrCore_Product.sName,vrCore_Product.iMasterId";
				text2 = General.GetSortingOnItem(objRec.ReportId, objRec.Inputs);
				if (!string.IsNullOrEmpty(text2))
				{
					text += $",{text2}";
				}
				text += strExtraColumns;
				break;
			case FocusReport.StockAnalysisbyBatch:
				if (bPreviousYear)
				{
					text = string.Format(" GROUP BY tCore_Indta{1}.iProduct,tCore_BatchOb{0}.sBatchNo", m_sCurrentSuffix, m_strPrevYearSuffix);
					if (_focus.company(m_iCompId).getPreferenceValue(PreferenceCategories.InventoryBatchNumber, 7) > 0)
					{
						text += string.Format(",tCore_BatchOb{0}.iExpiryDate, tCore_BatchOb{0}.iMfDate", m_sCurrentSuffix);
					}
					text += strExtraColumns;
					text += $" HAVING SUM(tCore_Indta{m_strPrevYearSuffix}.fQuantityInBase) <> 0";
				}
				else
				{
					text = string.Format(" GROUP BY tCore_Indta{0}.iProduct,tCore_Batch{0}.sBatchNo,tCore_Batch{0}.iBatchId", Suffix);
					if (_focus.company(m_iCompId).getPreferenceValue(PreferenceCategories.InventoryBatchNumber, 7) > 0)
					{
						text += string.Format(",tCore_Batch{0}.iExpiryDate, tCore_Batch{0}.iMfDate", Suffix);
					}
					text += strExtraColumns;
					text += $" HAVING SUM(tCore_Indta{Suffix}.fQuantityInBase) <> 0";
				}
				break;
			case FocusReport.StockAnalysisbyRMA:
				text = ((!bPreviousYear) ? $" GROUP BY iProduct,tCore_Rma{Suffix}.sRmaNo" : $" GROUP BY iProduct,tCore_RmaOb{m_sCurrentSuffix}.sRmaNo");
				text += strExtraColumns;
				text = text + " HAVING SUM(CASE WHEN tCore_Indta" + Suffix + ".fQuantityInBase > 0 THEN 1 ELSE -1 END) <> 0";
				break;
			case FocusReport.StockBalanceByProduct:
				text = string.Format(" GROUP BY vrCore_Product.iMasterId, vrCore_Bins.sName ", Suffix);
				text += strExtraColumns;
				text = ((!bPreviousYear) ? (text + $" HAVING SUM(tCore_Bins{Suffix}.fQuantity) <> 0") : (text + $" HAVING SUM(tCore_BinsOb{m_sCurrentSuffix}.fQuantity) <> 0"));
				break;
			case FocusReport.StockBalanceByBins:
				if (bPreviousYear)
				{
					text = string.Format(" GROUP BY vrCore_Product.iMasterId, vrCore_Bins.iMasterId, vrCore_Product.sName,tCore_BinsOb{0}.iExpDate,tCore_BinsOb{0}.iMfgDate ", m_sCurrentSuffix);
					text += strExtraColumns;
					text += $" HAVING SUM(tCore_BinsOb{m_sCurrentSuffix}.fQuantity) <> 0";
				}
				else
				{
					text = string.Format(" GROUP BY vrCore_Product.iMasterId, vrCore_Bins.iMasterId, vrCore_Product.sName,tCore_Bins{0}.iExpDate,tCore_Bins{0}.iMfgDate ", Suffix);
					text += strExtraColumns;
					text += string.Format(" HAVING SUM(tCore_Bins{0}.fQuantity) <> 0 OR AVG(tCore_ReservedStock{0}.fQuantity) <> 0", Suffix);
				}
				break;
			case FocusReport.StockBalanceByWarehouse:
				if (bPreviousYear && m_bClosed)
				{
					text = string.Format(" GROUP BY {1}.iMasterId, {1}.sName, vrCore_Product.iMasterId, vrCore_Product.sName ", m_strPrevYearSuffix, _focus.company(m_iCompId).invTagName);
					text += strExtraColumns;
					text += $" HAVING SUM(tCore_ibalsOb{m_sCurrentSuffix}.fQty) <> 0";
				}
				else
				{
					text = string.Format(" GROUP BY {1}.iMasterId, {1}.sName, vrCore_Product.iMasterId, vrCore_Product.sName ", Suffix, _focus.company(m_iCompId).invTagName);
					text += strExtraColumns;
					text += $" HAVING SUM(tCore_Indta{Suffix}.fQuantityInBase) <> 0";
				}
				break;
			case FocusReport.StockBalanceByProductByBins:
				if (bPreviousYear)
				{
					text = string.Format(" GROUP BY vrCore_Product.iMasterId, vrCore_Bins.iMasterId, vrCore_Product.sName, vrCore_Bins.sName,tCore_BinsOb{0}.iExpDate,tCore_BinsOb{0}.iMfgDate ", m_sCurrentSuffix);
					text += strExtraColumns;
					text += $" HAVING SUM(tCore_BinsOb{m_sCurrentSuffix}.fQuantity) <> 0";
				}
				else
				{
					text = string.Format(" GROUP BY vrCore_Product.iMasterId, vrCore_Bins.iMasterId, vrCore_Product.sName, vrCore_Bins.sName,tCore_Bins{0}.iExpDate,tCore_Bins{0}.iMfgDate ", Suffix);
					text += strExtraColumns;
					text += string.Format(" HAVING SUM(tCore_Bins{0}.fQuantity) <> 0 OR AVG(tCore_ReservedStock{0}.fQuantity) <> 0", Suffix);
				}
				break;
			case FocusReport.ExpiredStockByBins:
				if (bPreviousYear)
				{
					text = string.Format(" GROUP BY ISNULL(tCore_BinsOb{0}.iExpDate,0), vrCore_Product.iMasterId, vrCore_Bins.iMasterId, vrCore_Product.sName, vrCore_Bins.sName,ISNULL(tCore_BinsOb{0}.iMfgDate,0)", m_sCurrentSuffix);
					text += $" HAVING SUM(tCore_BinsOb{m_sCurrentSuffix}.fQuantity) <> 0";
				}
				else
				{
					text = string.Format(" GROUP BY ISNULL(tCore_Batch{0}.iExpiryDate,0), vrCore_Product.iMasterId, vrCore_Bins.iMasterId, vrCore_Product.sName, vrCore_Bins.sName,ISNULL(tCore_Batch{0}.iMfDate,0)", Suffix);
					text += $" HAVING SUM(tCore_Bins{Suffix}.fQuantity) <> 0";
				}
				text += strExtraColumns;
				break;
			case FocusReport.LinkChainAnalysis:
			{
				if (bPreviousYear)
				{
					text2 = ((m_iLinkCount > 0) ? ("tCore_LinksFinalBase" + Suffix) : ("tCore_Links" + Suffix));
					text = string.Format(" GROUP BY tCore_Links{0}.iBodyId, [DocNo-b],[iDate-b]\r\n                                ,CASE WHEN ISNULL({1}.iUserId,0) > 0 THEN 'Manually Closed' WHEN ISNULL({1}.bClosed, 0) > 0 THEN 'Closed' ELSE 'Pending' END", Suffix, text2);
				}
				else
				{
					text2 = ((m_iLinkCount > 0) ? "tCore_LinksFinalBase" : "tCore_Links");
					text = string.Format(" GROUP BY tCore_Links{0}.iBodyId, [DocNo-b],[iDate-b], CASE WHEN ISNULL(tCore_Links{0}.iUserId,0) > 0 AND tCore_Links{0}.LinkStatus <> 'Pending' THEN 'Manually Closed' WHEN ISNULL({1}{0}.bClosed, 0) > 0 THEN 'Closed' ELSE 'Pending' END", Suffix, text2);
				}
				int iLinkPathId = 0;
				List<int> workflowLinks = GetWorkflowLinks(objRec, ref iLinkPathId, objDb);
				if (workflowLinks.Count == 0)
				{
					text += ",[DocNo0],[iDate0]";
				}
				else
				{
					for (iLinkPathId = 0; iLinkPathId < workflowLinks.Count; iLinkPathId++)
					{
						text += string.Format(",[DocNo{0}],[iDate{0}]", iLinkPathId + ((iLinkPathId > 0) ? 10 : 0));
					}
				}
				text += strExtraColumns;
				break;
			}
			case FocusReport.ListingOfDocument:
				if (bPreviousYear)
				{
					text = string.Format(" GROUP BY tCore_Data{0}.iBodyId, tCore_LinksOb{1}.iLinkId,tCore_Header{0}.iDate, sAbbr, tCore_Header{0}.sVoucherNo,mCore_Product.sName,tCore_LinksOb{1}.iRefId,tCore_LinksOb{1}.bBase,tCore_LinksOb{1}.bClosed", Suffix, m_sCurrentSuffix);
					text2 = "tCore_Links" + m_strPrevYearSuffix;
				}
				else
				{
					text = string.Format(" GROUP BY tCore_Data{0}.iBodyId, tCore_Links{0}.iLinkId,tCore_Header{0}.iDate, sAbbr, tCore_Header{0}.sVoucherNo,mCore_Product.sName, tCore_Links{0}.iRefId,tCore_Links{0}.bBase,tCore_Links{0}.bClosed,baseHeader.iDate", Suffix);
					text2 = "tCore_Links" + Suffix;
				}
				text += strExtraColumns;
				if (bPreviousYear)
				{
					text2 = "tCore_LinksOb" + m_sCurrentSuffix;
				}
				if (FConvert.GetInputValue(objRec.Inputs, 2) != 1 || FConvert.GetInputValue(objRec.Inputs, 5) != 1)
				{
					if (bPreviousYear)
					{
						if (FConvert.GetInputValue(objRec.Inputs, 2) == 1)
						{
							text = text + " HAVING MIN(" + text2 + ".fValue)-SUM(ISNULL(BaseTable.Used,0)) > 0 AND bBase = 1";
						}
						if (FConvert.GetInputValue(objRec.Inputs, 5) == 1)
						{
							text = text + " HAVING (MIN(" + text2 + ".fValue)-SUM(ISNULL(BaseTable.Used,0)) = 0 OR " + text2 + ".bClosed = 1) OR (SUM(BaseTable.Used) IS NULL AND bBase = 0) OR (SUM(BaseTable.Used) = 0 AND bBase = 0)";
						}
					}
					else
					{
						if (FConvert.GetInputValue(objRec.Inputs, 2) == 1)
						{
							text = text + " HAVING MIN(" + text2 + ".fValue)-SUM(BaseTable.Used) > 0 AND bBase = 1";
						}
						if (FConvert.GetInputValue(objRec.Inputs, 5) == 1)
						{
							text = text + " HAVING (MIN(" + text2 + ".fValue)-SUM(BaseTable.Used) = 0 OR " + text2 + ".bClosed = 1) OR (SUM(BaseTable.Used) IS NULL AND bBase = 0) OR (SUM(BaseTable.Used) = 0 AND bBase = 0)";
						}
					}
				}
				text2 = string.Empty;
				switch (FConvert.GetInputValue(objRec.Inputs, 4))
				{
				case 1:
					text2 = "Auto Closed";
					break;
				case 2:
					text2 = "Manually Closed";
					break;
				case 3:
					text2 = "Closed";
					break;
				case 4:
					text2 = "Partial Consumed";
					break;
				case 5:
					text2 = "Pending";
					break;
				}
				if (!string.IsNullOrEmpty(text2))
				{
					text = (text.Contains(" HAVING ") ? (text + " AND ") : (text + " HAVING "));
					text = ((!bPreviousYear) ? (text + $"(CASE WHEN MAX(vCore_Links{objRec.Code}{Suffix}.iAutoClose) = 1 THEN 'Auto Closed' \r\n                                    WHEN MAX(vCore_Links{objRec.Code}{Suffix}.iStatus) = 3 THEN 'Manually Closed' \r\n                                    WHEN ISNULL(SUM(vCore_Links{objRec.Code}{Suffix}.bClosed), 0) > 0 OR (ISNULL(SUM(vCore_Links{objRec.Code}{Suffix}.Base), 0) <> 0 AND ISNULL(SUM(vCore_Links{objRec.Code}{Suffix}.Balance), 0) = 0) THEN 'Closed' \r\n                                    WHEN ISNULL(SUM(vCore_Links{objRec.Code}{Suffix}.Base), 0) <> 0 AND ISNULL(SUM(vCore_Links{objRec.Code}{Suffix}.Balance), 0) > 0 AND ISNULL(SUM(vCore_Links{objRec.Code}{Suffix}.Base), 0) > ISNULL(SUM(vCore_Links{objRec.Code}{Suffix}.Balance), 0) THEN 'Partial Consumed'\r\n                                    WHEN ISNULL(SUM(vCore_Links{objRec.Code}{Suffix}.Base), 0) <> 0 AND ISNULL(SUM(vCore_Links{objRec.Code}{Suffix}.Balance), 0) > 0 THEN 'Pending'\r\n                                    ELSE '' END) = '{text2}'") : (text + "(CASE WHEN MIN(BaseTable.iUserId) > 0 AND bBase = 1 AND tCore_LinksOb" + m_sCurrentSuffix + ".bClosed = 1 THEN 'Manual Closed' \r\n\t                                WHEN SUM(ISNULL(BaseTable.Used,0)) = 0 AND MIN(ISNULL(BaseTable.iUserId,0)) = 0 THEN 'Pending' \r\n\t                                WHEN MIN(tCore_LinksOb" + m_sCurrentSuffix + ".fValue)-SUM(ISNULL(BaseTable.Used,0)) <> 0 AND bBase = 1 THEN 'Partial Consumed'\r\n\t                                WHEN bBase = 1 THEN 'Closed'\r\n\t                                Else ''END) = '" + text2 + "'"));
				}
				break;
			case FocusReport.ListingOfDocumentByDueDate:
				if (bPreviousYear)
				{
					text = string.Format(" WHERE tCore_LinksOb{2}.iLinkId = {1} ", Suffix, objRec.Code, m_sCurrentSuffix);
					text += string.Format(" GROUP BY tCore_Data{0}.iBodyId, tCore_Header{0}.iDate, tCore_Data{0}.iDueDate, bBase, sAbbr, sVoucherNo,vrCore_Product.sName,tCore_LinksOb{1}.iRefId,tCore_LinksOb{1}.bBase,tCore_LinksOb{1}.bClosed", m_strPrevYearSuffix, m_sCurrentSuffix);
					text2 = "tCore_Links" + m_strPrevYearSuffix;
				}
				else
				{
					text = string.Format(" GROUP BY tCore_Data{0}.iBodyId, tCore_Header{0}.iDate, tCore_Data{0}.iDueDate, bBase, sAbbr, sVoucherNo,vrCore_Product.sName, tCore_Links{0}.iRefId,tCore_Links{0}.bBase,tCore_Links{0}.bClosed", Suffix);
					text2 = "tCore_Links" + Suffix;
				}
				text += strExtraColumns;
				if (bPreviousYear)
				{
					text2 = "tCore_LinksOb" + m_sCurrentSuffix;
				}
				if (FConvert.GetInputValue(objRec.Inputs, 2) != 1 || FConvert.GetInputValue(objRec.Inputs, 5) != 1)
				{
					if (bPreviousYear)
					{
						if (FConvert.GetInputValue(objRec.Inputs, 2) == 1)
						{
							text = text + " HAVING MIN(" + text2 + ".fValue)-SUM(ISNULL(BaseTable.Used,0)) > 0 AND bBase = 1";
						}
						if (FConvert.GetInputValue(objRec.Inputs, 5) == 1)
						{
							text = text + " HAVING (MIN(" + text2 + ".fValue)-SUM(ISNULL(BaseTable.Used,0)) = 0 OR " + text2 + ".bClosed = 1) OR (SUM(BaseTable.Used) IS NULL AND bBase = 0) OR (SUM(BaseTable.Used) = 0 AND bBase = 0)";
						}
					}
					else
					{
						if (FConvert.GetInputValue(objRec.Inputs, 2) == 1)
						{
							text = text + " HAVING MIN(" + text2 + ".fValue)-SUM(BaseTable.Used) > 0 AND bBase = 1";
						}
						if (FConvert.GetInputValue(objRec.Inputs, 5) == 1)
						{
							text = text + " HAVING (MIN(" + text2 + ".fValue)-SUM(BaseTable.Used) = 0 OR " + text2 + ".bClosed = 1) OR (SUM(BaseTable.Used) IS NULL AND bBase = 0) OR (SUM(BaseTable.Used) = 0 AND bBase = 0)";
						}
					}
				}
				text2 = string.Empty;
				switch (FConvert.GetInputValue(objRec.Inputs, 4))
				{
				case 1:
					text2 = "Auto Closed";
					break;
				case 2:
					text2 = "Manually Closed";
					break;
				case 3:
					text2 = "Closed";
					break;
				case 4:
					text2 = "Partial Consumed";
					break;
				case 5:
					text2 = "Pending";
					break;
				}
				if (!string.IsNullOrEmpty(text2))
				{
					text = (text.Contains(" HAVING ") ? (text + " AND ") : (text + " HAVING "));
					text = ((!bPreviousYear) ? (text + $"(CASE WHEN MAX(vCore_Links{objRec.Code}{Suffix}.iStatus) = 2 OR MAX(vCore_Links{objRec.Code}{Suffix}.iAutoClose) = 1 THEN 'Auto Closed' \r\n                                    WHEN MAX(vCore_Links{objRec.Code}{Suffix}.iStatus) = 0 THEN 'Pending' \r\n                                    WHEN MAX(vCore_Links{objRec.Code}{Suffix}.iStatus) = 1 THEN 'Partial Consumed' \r\n                                    WHEN MAX(vCore_Links{objRec.Code}{Suffix}.iStatus) = 3 THEN 'Manually Closed' \r\n                                    ELSE '' END) = '{text2}'") : (text + "(CASE WHEN MIN(BaseTable.iUserId) > 0 AND bBase = 1 AND tCore_LinksOb" + m_sCurrentSuffix + ".bClosed = 1 THEN 'Manual Closed' \r\n\t                                WHEN SUM(ISNULL(BaseTable.Used,0)) = 0 AND MIN(ISNULL(BaseTable.iUserId,0)) = 0 THEN 'Pending' \r\n\t                                WHEN MIN(tCore_LinksOb" + m_sCurrentSuffix + ".fValue)-SUM(ISNULL(BaseTable.Used,0)) <> 0 AND bBase = 1 THEN 'Partial Consumed'\r\n\t                                WHEN bBase = 1 THEN 'Closed'\r\n\t                                Else ''END) = '" + text2 + "'"));
				}
				break;
			case FocusReport.BestSellingItems:
				text = $" GROUP BY vrCore_Product.iMasterId, vrCore_Product.sName";
				text += strExtraColumns;
				text = ((FConvert.GetInputValue(objRec.Inputs, 2) != 0) ? (text + " HAVING SUM(CASE WHEN tCore_Indta" + Suffix + ".fQuantityInBase < 0 OR tCore_Header" + Suffix + ".iVoucherClass = 1792 THEN tCore_Indta" + Suffix + ".fQuantityInBase ELSE 0 END) <> 0 AND SUM(mAmount2) <> 0") : (text + " Having SUM(mAmount2) <> 0"));
				break;
			case FocusReport.StockTransferSummary:
				text = " GROUP BY vrCore_Product.iMasterId,Temp.iDate,Temp.[sVoucherNo]";
				text += strExtraColumns;
				break;
			case FocusReport.TransactionWiseStockReport:
				text = $" GROUP by vrCore_Product.iMasterId,vrCore_Product.sName, tCore_Header{Suffix}.iVoucherType {strExtraColumns} HAVING SUM(fQuantityInBase) <> 0 ";
				break;
			case FocusReport.ActualConsumptionReport:
				text = string.Format(" GROUP by vrCore_Product.iMasterId,vrCore_Product.sName, tCore_Header{0}.iVoucherType,tCore_Header{0}.iVoucherClass  {1} HAVING SUM(fQuantityInBase) <> 0 ", Suffix, strExtraColumns);
				break;
			}
			break;
		case Module.POS:
			switch ((FocusReport)objRec.ReportId)
			{
			case FocusReport.BestOutletPerformance:
			case FocusReport.WorstOutletPerformance:
			case FocusReport.SummarySalesByOutlet:
				text = string.Format(" GROUP BY mPos_Outlet.iMasterId,mPos_Outlet.sName", Suffix);
				text += strExtraColumns;
				break;
			case FocusReport.SummarySalesByDate:
			case FocusReport.PreorderSalesSummaryQtyWise:
			case FocusReport.PreorderSalesSummaryAmounttWise:
				text = $" GROUP BY tCore_Header{Suffix}.iDate ";
				text += strExtraColumns;
				break;
			case FocusReport.SummarySalesByProduct:
				text = string.Format(" GROUP BY mCore_ProductTreeDetails.iParentId,vrCore_Product.sName,SetTable.sName ", Suffix);
				text += strExtraColumns;
				break;
			case FocusReport.PreorderPaymentCollection:
				text = " GROUP BY mPos_Outlet.iMasterId,mPos_Outlet.sName";
				text += strExtraColumns;
				break;
			case FocusReport.SummarySalesByQuantityWise:
			case FocusReport.SummarySalesByQtyAndAmtWise:
				text = $" GROUP BY mCore_ProductTreeDetails.iParentId,vrCore_Product.sName,SetTable.sName, Parent.iMasterId,tCore_Data{Suffix}.iInvTag";
				text += strExtraColumns;
				break;
			case FocusReport.SummarySalesByAmountWise:
				text = string.Format(" GROUP BY mCore_ProductTreeDetails.iParentId,vrCore_Product.sName,tCore_Data{0}.iInvTag,tCore_Header{0}.iVoucherClass", Suffix);
				text += strExtraColumns;
				break;
			case FocusReport.SalesInfoByQtyCompareToLastYear:
			case FocusReport.SalesInfoByAmtCompareToLastYear:
			case FocusReport.SalesInfoByQtyAndAmtCompareToLastYear:
				text = " GROUP BY vrCore_Product.iMasterId,vrCore_Product.sName,mPos_Outlet.iMasterId";
				text += strExtraColumns;
				break;
			case FocusReport.HourlySalesByOutlet:
				text = string.Format(" GROUP BY Datepart(HH,dbo.fCore_IntToTime(tCore_Header{0}.iModifiedTime)),tCore_Data{0}.iInvTag", Suffix);
				text += m_strExtraColumns;
				break;
			case FocusReport.DailySalesByOutlet:
				text = $" GROUP BY dbo.GetDatePart('d', tCore_Header{Suffix}.iDate),mPos_Outlet.iMasterId,mPos_Outlet.sName";
				text += m_strExtraColumns;
				break;
			case FocusReport.MonthlySalesByOutlet:
				text = $" GROUP BY dbo.GetDatePart('m', tCore_Header{Suffix}.iModifiedDate),mPos_Outlet.iMasterId,mPos_Outlet.sName";
				text += m_strExtraColumns;
				break;
			case FocusReport.QuarterlySalesByOutlet:
				text = $" GROUP BY dbo.GetDatePart('q', tCore_Header{Suffix}.iModifiedDate),mPos_Outlet.iMasterId,mPos_Outlet.sName";
				text += m_strExtraColumns;
				break;
			case FocusReport.FastMovingItems:
			case FocusReport.SlowMovingItems:
				text = string.Format(" GROUP BY vrCore_Product.sName{2} HAVING SUM(CASE WHEN tCore_Header{0}.iVoucherClass = {1}\r\n                            THEN tCore_Indta{0}.fQuantity*-1 ELSE 0 END) > 0", Suffix, 3328, strExtraColumns);
				break;
			case FocusReport.FastMovingItemsOutletWise:
			case FocusReport.SlowMovingItemsOutletWise:
				text = string.Format(" GROUP BY vrCore_Product.sName,mPos_Outlet.sName,mPos_Outlet.iMasterId{2} HAVING SUM(CASE WHEN tCore_Header{0}.iVoucherClass = {1}\r\n                            THEN tCore_Indta{0}.fQuantity*-1 ELSE 0 END) > 0", Suffix, 3328, strExtraColumns);
				break;
			case FocusReport.MemberFrequency:
				text += $" GROUP BY tCore_Header{Suffix}.iHeaderId ";
				if (strExtraColumns != null && strExtraColumns.Length > 0)
				{
					text += ",";
					text += strExtraColumns.Substring(1, strExtraColumns.Length - 1);
				}
				break;
			case FocusReport.POSRestDailySales:
				text = string.Format(" GROUP BY vrCore_Product.sName", Suffix);
				text += m_strExtraColumns;
				break;
			case FocusReport.POSRestSalesByMenuCategory:
				text = string.Format(" GROUP BY cPos_RestMenu.sName,vrCore_Product.sName", Suffix);
				text += m_strExtraColumns;
				break;
			case FocusReport.POSRestDiscountByWaiter:
				text = string.Format(" GROUP BY mPay_Employee.sName,vrCore_Product.sName", Suffix);
				text += m_strExtraColumns;
				break;
			case FocusReport.POSRestClerkWiseSales:
				text = string.Format(" GROUP BY mPay_Employee.sName,OrdersCount.Qty", Suffix);
				text += m_strExtraColumns;
				break;
			case FocusReport.POSRestTableDetails:
				text = string.Format(" GROUP BY mPos_Table.sName, mPos_Section.sName,tCore_HeaderData{1}{0}.iPax,iCreatedTime", Suffix, 3331);
				text += m_strExtraColumns;
				break;
			case FocusReport.CashCollections:
				text = $" GROUP BY mPos_CashInOut{Suffix}.iOutletId,iDate,iTime,mPos_Outlet.sName,mSec_Users.sLoginName,iType,sRemarks";
				text += m_strExtraColumns;
				break;
			}
			break;
		case Module.CoreMasters:
			switch ((FocusReport)objRec.ReportId)
			{
			case FocusReport.MemberPoints:
			case FocusReport.POSMemberBalance:
				text = " GROUP BY mPos_Member.iMasterId,mPos_Member.sName,mPos_Member.sCode,mPos_Member.iCreatedDate";
				text += strExtraColumns;
				text += " HAVING (ISNULL(SUM(Points), 0) > 0 or ISNULL(SUM(RedPoints), 0)>0)";
				break;
			case FocusReport.MembershipRecruitment:
				text = " GROUP BY mPos_Outlet.sCode,mPos_Outlet.iMasterId";
				text += strExtraColumns;
				break;
			case FocusReport.MembershipRecruitmentByDate:
				text = " GROUP BY mPos_Outlet.iMasterId,dbo.DateToInt(cast(dbo.fCore_IntToDateTime(vrPos_Member.iCreatedDate) as varchar(20))) ";
				text += strExtraColumns;
				text += ")TempTable GROUP BY [CreatedDate]";
				break;
			case FocusReport.MemberPointsExpiry:
			case FocusReport.MemberMaximumPoints:
			case FocusReport.MemberMinimumPoints:
				text = " GROUP BY vrPos_Member.iMasterId,vrPos_Member.sName ";
				text += strExtraColumns;
				text += " having ISNULL(SUM(vPos_MemberPoints.Points)-SUM(vPos_MemberPoints.RedPoints), 0) > 0 ";
				break;
			default:
				if (objRec.ReportId < RDCommon.RD_STARTID)
				{
					text = " ORDER BY acc.iSeq";
				}
				break;
			case FocusReport.MasterReport:
			case FocusReport.MasterAuthorizationReport:
			case FocusReport.AuditMasters:
			case FocusReport.AuditPricebook:
			case FocusReport.AuthorizationMatrix:
			case FocusReport.AuditTrailAuthorization:
			case FocusReport.FormReport:
			case FocusReport.PricebookAuthorizationReport:
				break;
			}
			break;
		case Module.FixAssets:
			switch ((FocusReport)objRec.ReportId)
			{
			case FocusReport.FADepreciationSchedule:
				text = " Group By vrFixA_FixedAsset.iMasterId, vrFixA_FixedAsset.sName, vrFixA_FixedAsset.iDepreciationMethod, \r\n                                                     vrFixA_FixedAsset.iDepreciationInYears , vrFixA_FixedAsset.iDepreciationInMonths,\r\n                                                     vrFixA_FixedAsset.fPrice , vrFixA_FixedAsset.fCumulativeDepreciation,muFixA_FixedAsset_Depreciation.iDepreciationMethod,\r\n                                                     vrFixA_FixedAsset.iDateOfCommencement,vrFixA_FixedAsset.fScrapValue,Disposal.dTotValSold, Disposal.iDisposalDate,\r\n                                                     ISNULL(FixA.sName , ''),vrFixA_FixedAsset.fITDepreciationRate,vrFixA_FixedAsset.ITAccruedValue, vrFixA_FixedAsset.iQuantity, vrFixA_FixedAsset.fRateOfDepreciation,Case When vrFixA_FixedAsset.iStatus =4 then 'Disposed' else '' end,vrFixA_FixedAsset.iStatus\r\n                                                     ,vrFixA_FixedAsset.iDepreciationInYears,AddYrs.iNoOfYears,AddYrs.iNoOfMonths,ISNULL(vrFixA_FixedAsset.sCode , '') ";
				text += strExtraColumns;
				break;
			case FocusReport.FixAssetAuthReport:
				text = " group by D.iLevel,FixAsset.sVoucherNo, vrFixA_FixedAsset.sName , vrFixA_FixedAsset.sCode, U.iRoleOrUserId,R.sUserName,\r\n                                        U.iAuthDate,U.iStatus,U.sReason,vrFixA_FixedAsset.iMasterId";
				text += strExtraColumns;
				break;
			}
			break;
		case Module.Production:
			switch ((FocusReport)objRec.ReportId)
			{
			case FocusReport.ProductionSummary:
			case FocusReport.WorkInProcess:
			case FocusReport.ProductwiseWorkInProcess:
			case FocusReport.ConsumptionSummary:
				text = " GROUP BY vrCore_Product.iMasterId,PL.sName,vrCore_Product.sCode";
				text += strExtraColumns;
				break;
			case FocusReport.ReplenishmentReport:
				text = " GROUP BY vrCore_Product.iMasterId,PL.sName";
				text += strExtraColumns;
				break;
			case FocusReport.NegitiveBatchList:
				text = " group by iProduct,iInvTag,sBatchNo,PL.sName,p.sCode,iBatchId,w.sCode,u.sName\r\n                                            having CEILING((Sum(fQuantityInBase))) < 0\r\n                                            Order by iProduct";
				text += strExtraColumns;
				break;
			case FocusReport.BOMProcessReport:
				text = string.Empty;
				break;
			}
			break;
		default:
			switch ((CustomizeColumn)(byte)objRec.SubReportId)
			{
			case CustomizeColumn.LinkVoucher:
			{
				m_arrLinkId = IsLinkField(objRec);
				string arg = $"tCore_Header{Suffix}.iHeaderId";
				for (int i = 0; i < arrField.Length; i++)
				{
					if ((byte)objRec.SubReportId == 2 && arrField[i].SubParentId == 23)
					{
						arg = $"tCore_Data{Suffix}.iBodyId";
						break;
					}
				}
				text = string.Format(" GROUP BY {1},tCore_Header{0}.iDate, tCore_Header{0}.sVoucherNo, \r\n\t\t\t\t\t\t\tEUser.sLoginName, MUser.sLoginName, tCore_Header{0}.iCreatedDate, tCore_Header{0}.iModifiedDate, tCore_Header{0}.iCreatedTime, \r\n                            tCore_Header{0}.iModifiedTime, tCore_Header{0}.bSuspended, tCore_Header{0}.bCancelled", Suffix, arg);
				text += ",iAuth";
				text += strExtraColumns;
				if (!string.IsNullOrEmpty(strExtraColumns) && strExtraColumns.Contains("sVoucherNo"))
				{
					text += ",sAbbr";
				}
				if (m_arrLinkId != null && m_arrLinkId.Length != 0)
				{
					text += string.Format(" HAVING SUM(vCore_Links{1}{0}.Balance) > 0", Suffix, m_arrLinkId[0]);
				}
				break;
			}
			case CustomizeColumn.HomePage:
			case CustomizeColumn.PendingBills:
			case CustomizeColumn.Drafts:
				if ((byte)objRec.SubReportId == 1)
				{
					m_arrLinkId = IsLinkField(objRec);
				}
				if (((m_arrLinkId != null && m_arrLinkId.Length != 0) || IsFractionBodyFieldCustomize(objRec, arrField)) && (objRec.Module != Module.None || arrField.Length != 1 || arrField[0].FieldId != 171))
				{
					text = string.Format(" GROUP BY tCore_Header{0}.iHeaderId,tCore_Header{0}.iDate, tCore_Header{0}.sVoucherNo, \r\n\t\t\t\t\t\t\t        EUser.sLoginName, MUser.sLoginName, tCore_Header{0}.iCreatedDate, tCore_Header{0}.iModifiedDate, tCore_Header{0}.iCreatedTime, tCore_Header{0}.iModifiedTime, tCore_Header{0}.bSuspended, tCore_Header{0}.bCancelled", Suffix);
					text += ",iAuth";
					text += strExtraColumns;
					if (!string.IsNullOrEmpty(strExtraColumns) && strExtraColumns.Contains("sVoucherNo"))
					{
						text += ",sAbbr";
					}
				}
				break;
			case CustomizeColumn.LinkPopupScreen:
				if (false)
				{
					text = $" GROUP BY tCore_Header{Suffix}.iHeaderId, t.sVoucherNo, t.iDate, Suspended";
					text += strExtraColumns;
				}
				break;
			case CustomizeColumn.CustomPendingBills:
				text = string.Format(" GROUP BY tCore_Header{0}.iHeaderId, cCore_Vouchers{0}.sAbbr + ':'+tCore_Header{0}.sVoucherNo\r\n                            , tCore_Header{0}.iDate, NewRef.iDueDate, mCore_Account.sName, {1}.sName, mCore_Currency.sName", Suffix, _focus.company(m_iCompId).faTagName);
				text += strExtraColumns;
				text += " HAVING SUM(mAmount) + SUM(ISNULL(AdjAmount, 0)) <> 0";
				break;
			}
			break;
		}
		if (m_bDetailRowGrouping && !string.IsNullOrEmpty(m_strExtraColumnsAlias))
		{
			text = $" GROUP BY {m_strExtraColumnsAlias}";
			if (m_bTreeSequence)
			{
				text += ",ATree.iSeq";
			}
			if (m_bVoucherSequence)
			{
				text += $",tCore_Data{Suffix}.iType";
			}
		}
		return text;
	}

	private string GetMasterTagJoin(ref string sTableName, List<string> arrDefualtTables, FieldData objFieldData, RepRecord objRec, ref List<string> arrTableAdded, ref string strTranDataColumns, ref string strTranHeaderDataColumns, ref string strTranAllDataColumns, ref string strTranHeaderDocsColumns, ref string strTranBodyDocsColumns, List<IdValuePair> arrVoucherTypesValue, bool IsFilterField)
	{
		if ((objRec.ReportId == 538 || objRec.ReportId == 666) & IsFilterField)
		{
			if (sTableName.Contains("Code") || sTableName.Contains("BookNo"))
			{
				sTableName = "vrCore_Account";
				objFieldData.FieldName = objFieldData.FieldName.Replace("Code.", "vrCore_Account.");
				objFieldData.FieldName = objFieldData.FieldName.Replace("BookNo.", "vrCore_Account.");
			}
			return string.Empty;
		}
		if ((objRec.ReportId == 663 || objRec.ReportId == 668 || objRec.ReportId == 661) && (sTableName == "vrCore_Product" || sTableName.Contains("Code") || sTableName.Contains("BookNo")))
		{
			return string.Empty;
		}
		bool flag = false;
		bool flag2 = false;
		string strEditLayoutMaster = string.Empty;
		string text = null;
		RDDefault rDDefault = new RDDefault();
		if (!IsStockTransferField2(objRec, objFieldData.SubParentId) && (!IsTableAdded(arrTableAdded, sTableName) || (((objFieldData.SubParentId & 0x1000000) > 0 || (objFieldData.SubParentId & 0x4000000) > 0) && sTableName.StartsWith("vr"))))
		{
			if (((objFieldData.SubParentId & 0x1000000) > 0 || (objFieldData.SubParentId & 0x4000000) > 0) && sTableName.StartsWith("vr"))
			{
				InvoiceLayout invoiceLayout = new InvoiceLayout();
				if (objFieldData.FieldId == 127)
				{
					invoiceLayout.GetMasterTypeIdFromField(objFieldData.SubParentId, null);
				}
				else
				{
					GetTagFilter(m_objDatabase, objFieldData.FieldId, objFieldData.SubParentId, arrVoucherTypesValue, ref strEditLayoutMaster);
				}
				if (!string.IsNullOrEmpty(strEditLayoutMaster))
				{
					string[] array = strEditLayoutMaster.Split('.');
					string strScreenDataColumns = null;
					if (array[0] == "vCore_TranData" + Suffix)
					{
						if (!IsTableAdded(arrTableAdded, "vCore_TranData" + Suffix))
						{
							text = GetTranDataJoin(objFieldData, objRec, "vCore_TranData" + Suffix, array[1], ref strTranDataColumns, ref strTranHeaderDataColumns, ref strScreenDataColumns, ref strTranAllDataColumns, ref strTranHeaderDocsColumns, ref strTranBodyDocsColumns);
							arrTableAdded.Add("vCore_TranData" + Suffix);
						}
						if (!string.IsNullOrEmpty(strTranDataColumns) && array.Length > 1)
						{
							strTranDataColumns = strTranDataColumns + "," + array[1];
						}
					}
					else if (array[0] == "vCore_TranHeaderData" + Suffix)
					{
						if (!IsTableAdded(arrTableAdded, "vCore_TranHeaderData" + Suffix))
						{
							text = GetTranDataJoin(objFieldData, objRec, "vCore_TranHeaderData" + Suffix, array[1], ref strTranDataColumns, ref strTranHeaderDataColumns, ref strScreenDataColumns, ref strTranAllDataColumns, ref strTranHeaderDocsColumns, ref strTranBodyDocsColumns);
							arrTableAdded.Add("vCore_TranHeaderData" + Suffix);
						}
						if (!string.IsNullOrEmpty(strTranHeaderDataColumns) && array.Length > 1)
						{
							strTranHeaderDataColumns = strTranHeaderDataColumns + "," + array[1];
						}
					}
					else if (array[0] == "vCore_TranHeaderDocs" + Suffix)
					{
						if (!IsTableAdded(arrTableAdded, "vCore_TranHeaderDocs" + Suffix))
						{
							text = GetTranDataJoin(objFieldData, objRec, "vCore_TranHeaderDocs" + Suffix, array[1], ref strTranDataColumns, ref strTranHeaderDataColumns, ref strScreenDataColumns, ref strTranAllDataColumns, ref strTranHeaderDocsColumns, ref strTranBodyDocsColumns);
							arrTableAdded.Add("vCore_TranHeaderDocs" + Suffix);
						}
						if (!string.IsNullOrEmpty(strTranHeaderDataColumns) && array.Length > 1)
						{
							strTranHeaderDataColumns = strTranHeaderDataColumns + "," + array[1];
						}
					}
					else if (array[0] == "vCore_TranAllData" + Suffix)
					{
						if (!IsTableAdded(arrTableAdded, "vCore_TranAllData" + Suffix))
						{
							text = GetTranDataJoin(objFieldData, objRec, "vCore_TranAllData" + Suffix, array[1], ref strTranDataColumns, ref strTranAllDataColumns, ref strScreenDataColumns, ref strTranAllDataColumns, ref strTranHeaderDocsColumns, ref strTranBodyDocsColumns);
							arrTableAdded.Add("vCore_TranAllData" + Suffix);
						}
						if (!string.IsNullOrEmpty(strTranAllDataColumns) && array.Length > 1)
						{
							strTranAllDataColumns = strTranAllDataColumns + "," + array[1];
						}
					}
					if (!IsTableAdded(arrTableAdded, $"Tag{objFieldData.SubParentId}"))
					{
						text += string.Format(" LEFT JOIN {1} Tag{3} ON Tag{3}.iMasterId = {2} AND Tag{3}.iTreeId = 0", Suffix, sTableName, strEditLayoutMaster, objFieldData.SubParentId);
						if (!string.IsNullOrEmpty(strTranDataColumns) && array.Length > 1)
						{
							strTranDataColumns = strTranDataColumns + "," + array[1];
						}
					}
					string[] array2 = objFieldData.FieldName.Split('.');
					if (array2.Length > 1)
					{
						objFieldData.FieldName = $"Tag{objFieldData.SubParentId}.{array2[1]}";
					}
					sTableName = $"Tag{objFieldData.SubParentId}";
					flag2 = true;
				}
			}
			if (!flag2 && !IsTableAdded(arrTableAdded, sTableName))
			{
