				}
				else if (_focus.company(m_iCompId).faTagName != null && MatchTable(_focus.company(m_iCompId).faTagName, sTableName) && !rDDefault.IsNonTransactionReport(objRec.ReportId, objRec.Module))
				{
					text = getMasterJoin(objFieldData.SubParentId, sTableName, $"tCore_Data{Suffix}.iFaTag");
				}
				else if (_focus.company(m_iCompId).invTagName != null && MatchTable(_focus.company(m_iCompId).invTagName, sTableName) && !rDDefault.IsNonTransactionReport(objRec.ReportId, objRec.Module))
				{
					text = getMasterJoin(objFieldData.SubParentId, sTableName, $"tCore_Data{Suffix}.iInvTag");
				}
