					text = ((!string.IsNullOrEmpty(masterInnerQuery2)) ? string.Format(" LEFT JOIN ({1}) BookNo ON BookNo.iMasterId = tCore_Data{0}.iBookNo", Suffix, masterInnerQuery2) : $" LEFT JOIN vrCore_Account BookNo ON BookNo.iMasterId = tCore_Data{Suffix}.iBookNo AND BookNo.iTreeId = 0");
