					}
					text = ((!string.IsNullOrEmpty(masterInnerQuery3)) ? (text + string.Format(" LEFT JOIN ({1}) vrCore_Product ON vrCore_Product.iMasterId = tCore_Indta{0}.iProduct AND vrCore_Product.iTreeId = 0", Suffix, masterInnerQuery3)) : (text + $" LEFT JOIN vrCore_Product ON vrCore_Product.iMasterId = tCore_Indta{Suffix}.iProduct AND vrCore_Product.iTreeId = 0"));
					arrTableAdded.Add("vrCore_Product");
