					if (objFieldData.ParentId > 0 && objFieldData.ParentId != 12)
					{
						text2 = invoiceLayout2.GetExtraFieldName(objFieldData.SubParentId, objFieldData.ParentId, -1, bVoucherClass: false, _focus.company(m_iCompId).id);
						string[] array3 = text2.Split('.');
