	private string GetTagJoinQuery(ref string sTableName, List<string> arrDefualtTables, FieldData objFieldData, RepRecord objRec, List<IdValuePair> arrVoucherTypesValue, ref List<string> arrTableAdded)
	{
		if (objRec.Module == Module.CoreMasters)
		{
			return string.Empty;
		}
		int num = 0;
		string text = null;
		string strEditLayoutMaster = null;
		string text2 = null;
		InvoiceLayout invoiceLayout = new InvoiceLayout();
		num = ((objFieldData.FieldId != 127) ? GetTagFilter(m_objDatabase, objFieldData.FieldId, objFieldData.SubParentId, arrVoucherTypesValue, ref strEditLayoutMaster) : invoiceLayout.GetMasterTypeIdFromField(objFieldData.SubParentId, null));
		if (num > 0 || !string.IsNullOrEmpty(strEditLayoutMaster))
		{
			switch (num)
			{
			case 1:
				if (arrDefualtTables.Where((string p) => p == "vrCore_Account").Count() != 0)
				{
					break;
				}
				if (objFieldData.SubParentId > 0 && (objFieldData.SubParentId & 0x8000000) == 134217728)
				{
					if (!IsTableAdded(arrTableAdded, "tCore_IndtaFooterScreenData" + Suffix))
					{
						text2 = " LEFT JOIN tCore_IndtaFooterScreenData" + Suffix + " WITH (READUNCOMMITTED) ON tCore_IndtaFooterScreenData" + Suffix + ".iHeaderId = tCore_Header" + Suffix + ".iHeaderId";
						arrTableAdded.Add("tCore_IndtaFooterScreenData" + Suffix);
					}
					if ((objFieldData.SubParentId & 0xFFFFFF) - 1001 >= 0)
					{
						num = (objFieldData.SubParentId & 0xFFFFFF) - 1001;
						sTableName = $"FooterDrAc{num}";
						objFieldData.FieldName = objFieldData.FieldName.Replace("vrCore_Account", sTableName);
						if (!IsTableAdded(arrTableAdded, sTableName))
						{
							text2 += string.Format(" LEFT JOIN vrCore_Account {2} ON {2}.iMasterId = tCore_IndtaFooterScreenData{0}.iAccount{1} AND {2}.iTreeId = 0", Suffix, num, sTableName);
							arrTableAdded.Add(sTableName);
						}
					}
					else if ((objFieldData.SubParentId & 0xFFFFFF) - 2001 >= 0)
					{
						num = (objFieldData.SubParentId & 0xFFFFFF) - 2001;
						sTableName = $"FooterCrAc{num}";
						objFieldData.FieldName = objFieldData.FieldName.Replace("vrCore_Account", sTableName);
						if (!IsTableAdded(arrTableAdded, sTableName))
						{
							text2 += string.Format(" LEFT JOIN vrCore_Account {2} ON {2}.iMasterId = tCore_IndtaFooterScreenData{0}.iAccount{1} AND {2}.iTreeId = 0", Suffix, num, sTableName);
							arrTableAdded.Add(sTableName);
						}
					}
					break;
				}
				if (objFieldData.SubParentId == 3)
				{
					if (!IsTableAdded(arrTableAdded, "Code"))
					{
						text2 = $" JOIN vrCore_Account Code ON Code.iMasterId = tCore_Data{Suffix}.iCode AND Code.iTreeId = 0";
						arrTableAdded.Add("Code");
					}
					break;
				}
				if (!IsTableAdded(arrTableAdded, sTableName))
				{
					text = getMasterInnerQuery(objFieldData.SubParentId, sTableName);
					switch ((FocusReport)objRec.ReportId)
					{
					case FocusReport.VendorAgeingSummaryBillwise:
					case FocusReport.VendorSummaryAgeingByDueDate:
					case FocusReport.CustomerAgeingSummaryBillwise:
					case FocusReport.CustomerSummaryAgeingByDueDate:
						if (string.IsNullOrEmpty(text))
						{
							text2 += " join vrCore_Account ON mCore_Account.iMasterId = vrCore_Account.iMasterId and vrCore_Account.iTreeId=0";
							arrTableAdded.Add("vrCore_Account");
						}
						else
						{
							text2 = string.Empty;
						}
						break;
					default:
						if (string.IsNullOrEmpty(text))
						{
							text2 = string.Format(" JOIN {1} ON {1}.iMasterId = tCore_Data{0}.iBookNo AND {1}.iTreeId = 0", Suffix, sTableName);
							if (!IsTableAdded(arrTableAdded, "Code"))
							{
								text2 += $" JOIN vrCore_Account Code ON Code.iMasterId = tCore_Data{Suffix}.iCode AND Code.iTreeId = 0";
								arrTableAdded.Add("Code");
							}
						}
						else
						{
							text2 = string.Format(" JOIN ({1}){2} ON {2}.iMasterId = tCore_Data{0}.iBookNo", Suffix, text, sTableName);
						}
						break;
					}
					arrTableAdded.Add(sTableName);
				}
				if (!IsTableAdded(arrTableAdded, "BookNo"))
				{
					switch ((FocusReport)objRec.ReportId)
					{
					default:
						text2 = ((!string.IsNullOrEmpty(text)) ? (text2 + string.Format(" JOIN ({1}) BookNo ON BookNo.iMasterId = tCore_Data{0}.iBookNo ", Suffix, text)) : (text2 + $" JOIN vrCore_Account BookNo ON BookNo.iMasterId = tCore_Data{Suffix}.iBookNo AND BookNo.iTreeId = 0"));
						arrTableAdded.Add("BookNo");
						break;
					case FocusReport.VendorAgeingSummaryBillwise:
					case FocusReport.VendorSummaryAgeingByDueDate:
					case FocusReport.CustomerAgeingSummaryBillwise:
					case FocusReport.CustomerSummaryAgeingByDueDate:
						break;
					}
				}
				break;
			case 2:
				if (arrDefualtTables.Where((string p) => p == "vrCore_Product").Count() != 0)
				{
					break;
				}
				if (sTableName != "vrCore_Product")
				{
					text2 = string.Format(" JOIN vrCore_Product ON vrCore_Product.iMasterId = tCore_Indta{0}.iProduct AND vrCore_Product.iTreeId = 0\r\n                                            LEFT JOIN {1} ON {1}.iMasterId = vrCore_Product.iMasterId ", Suffix, sTableName);
					arrTableAdded.Add("vrCore_Product");
					break;
				}
				if (objRec.Module != Module.Inventory)
				{
					text2 = " LEFT";
				}
				text2 += $" JOIN vrCore_Product ON vrCore_Product.iMasterId = tCore_Indta{Suffix}.iProduct ";
				break;
			case 12:
				if (!IsTableAdded(arrTableAdded, "vrCore_Bins"))
				{
					text2 = $" LEFT JOIN tCore_Bins{Suffix} tags{num} ON tags{num}.iBodyId = tCore_Data{Suffix}.iBodyId \r\n                                    LEFT JOIN vrCore_Bins ON vrCore_Bins.iMasterId = tags{num}.iBin AND vrCore_Bins.iTreeId = 0";
					arrTableAdded.Add($"tCore_Bins{Suffix}");
					arrTableAdded.Add("vrCore_Bins");
				}
				break;
			default:
				if (!string.IsNullOrEmpty(strEditLayoutMaster))
				{
					if (!IsTableAdded(arrTableAdded, $"vCore_TranData{Suffix}"))
					{
						text2 = string.Format(" LEFT JOIN vCore_TranData{0} ON vCore_TranData{0}.iBodyId = tCore_Data{0}.iBodyId", Suffix, sTableName, strEditLayoutMaster);
					}
					text2 += string.Format(" LEFT JOIN {1} ON {1}.iMasterId = {2} AND {1}.iTreeId=0", Suffix, sTableName, strEditLayoutMaster);
				}
				else
				{
					text = getMasterInnerQuery(objFieldData.SubParentId, sTableName);
					if (!IsTableAdded(arrTableAdded, $"tCore_Data_Tags{Suffix}"))
					{
						text2 += string.Format(" LEFT JOIN tCore_Data_Tags{0} ON tCore_Data_Tags{0}.iBodyId = tCore_Data{0}.iBodyId ", Suffix);
						arrTableAdded.Add($"tCore_Data_Tags{Suffix}");
					}
					text2 = (string.IsNullOrEmpty(text) ? (text2 + string.Format(" LEFT JOIN {1} ON {1}.iMasterId = tCore_Data_Tags{0}.iTag{3} AND {1}.iTreeId=0", Suffix, sTableName, arrTableAdded.Count, num)) : (text2 + string.Format(" LEFT JOIN ({4}){1} ON {1}.iMasterId = tCore_Data_Tags{0}.iTag{3}", Suffix, sTableName, arrTableAdded.Count, num, text)));
				}
				arrTableAdded.Add(sTableName);
				break;
			}
		}
		return text2;
	}

	private bool IsStockTransferField2(RepRecord objRec, int iSubparentId)
	{
		bool result = false;
		bool bClassType = false;
		int vt = 0;
		if (objRec.ReportCustomize != null && objRec.ReportCustomize.TransactionSets != null && objRec.ReportCustomize.TransactionSets.Length != 0 && (objRec.ReportCustomize.TransactionSets[0].TransactionSetId == TransactionSetType.AllTransactionsOfDocumentClass || objRec.ReportCustomize.TransactionSets[0].TransactionSetId == TransactionSetType.AllTransactionsOfDocumentType))
		{
			vt = objRec.ReportCustomize.TransactionSets[0].VoucherType;
		}
		else
		{
			List<int> voucherTypeForReport = GetVoucherTypeForReport(objRec, bDontFetchVoucher: false, ref bClassType);
			if (voucherTypeForReport != null && voucherTypeForReport.Count > 0)
			{
				vt = voucherTypeForReport[0];
			}
		}
		if (FConvert.IsItTransfer(vt))
		{
			if (iSubparentId > 0)
			{
				if (iSubparentId == 87 || iSubparentId == 84)
				{
					result = true;
				}
			}
			else
			{
				result = true;
			}
		}
		return result;
	}

	private bool IsTableAdded(List<string> arrTableAdded, string sTable)
	{
		for (int i = 0; i < arrTableAdded.Count; i++)
		{
			if (sTable == arrTableAdded[i])
			{
				return true;
			}
		}
		return false;
	}

	private bool MatchTable(string sTable1, string sTable2)
	{
		if (sTable1.Length > 0 && (sTable1 == sTable2 || sTable1.Insert(1, "u") == sTable2))
		{
			return true;
		}
		return false;
	}

	private string CheckGroupingOption(FieldData oField, RepRecord oRec)
	{
		if (oRec.ReportCustomize != null && oRec.ReportCustomize.Groupings != null && oRec.ReportCustomize.Groupings.Length != 0 && !oRec.ReportCustomize.AdvancedEngine)
		{
			for (int i = 0; i < oRec.ReportCustomize.Groupings.Length; i++)
			{
				if (oRec.ReportCustomize.Groupings[i].GroupingType == _GroupingType.Row && (oRec.ReportCustomize.Groupings[i].MiscellaneousOptions & (int)Math.Pow(2.0, 9.0)) >> 9 == 1 && oRec.ReportCustomize.Groupings[i].FieldId == oField.FieldId && oRec.ReportCustomize.Groupings[i].SubParentId == oField.SubParentId)
				{
					if (oField.FieldName.EndsWith("sName"))
					{
						return string.Format("{0} + ' [' + {1} + ']'", oField.FieldName, oField.FieldName.Replace("sName", "sCode"));
					}
					if (oField.FieldName.EndsWith("sCode"))
					{
						return string.Format("{0} + ' [' + {1} + ']'", oField.FieldName, oField.FieldName.Replace("sCode", "sName"));
					}
					if (!oField.FieldName.Contains("fCore_GetLevelMaster"))
					{
						break;
					}
					if ((oField.FieldId & 0xFFFF) > 255)
					{
						return string.Format("{0} + ' [' + {1} + ']'", oField.FieldName, oField.FieldName.Replace(", 1)", ", 0)"));
					}
					return string.Format("{0} + ' [' + {1} + ']'", oField.FieldName, oField.FieldName.Replace(", 0)", ", 1)"));
				}
			}
		}
		return oField.FieldName;
	}

	private string VoucherFilter(uint ReportId, Module objModule, object objOption = null)
	{
		string text = string.Empty;
		switch (objModule)
		{
		case Module.CoreTransactions:
			switch ((FocusReport)ReportId)
			{
			case FocusReport.SalesRegister:
			case FocusReport.SummarySalesRegister:
			case FocusReport.SalesPredictionReport:
				text = string.Format(" AND (tCore_Header{0}.iVoucherClass = {1} OR tCore_Header{0}.iVoucherClass = {2}) ", Suffix, 3328, 6144);
				if (objOption != null && Convert.ToInt32(objOption) == 1)
				{
					text = string.Format(" AND (tCore_Header{0}.iVoucherClass = {1} OR tCore_Header{0}.iVoucherClass = {2} OR tCore_Header{0}.iVoucherClass = {3}) ", Suffix, 3328, 1792, 6144);
				}
				break;
			case FocusReport.SalesGroupedByCustomer:
			case FocusReport.SalesGroupedByProduct:
			case FocusReport.SalesGroupedByDepartment:
				text = $" AND tCore_Header{Suffix}.iVoucherClass = {3328} ";
				if (objOption != null && Convert.ToInt32(objOption) == 1)
				{
					text = string.Format(" AND (tCore_Header{0}.iVoucherClass = {1} OR tCore_Header{0}.iVoucherClass = {2}) ", Suffix, 3328, 1792);
				}
				break;
			case FocusReport.SalesReturnRegister:
				text = $" AND tCore_Header{Suffix}.iVoucherClass = {1792} ";
				break;
			case FocusReport.PurchaseRegister:
			case FocusReport.SummaryPurchaseRegister:
			case FocusReport.PurchasePredictionReport:
				text = string.Format(" AND (tCore_Header{0}.iVoucherClass = {1} OR tCore_Header{0}.iVoucherClass = {2}) ", Suffix, 768, 1280);
				if (objOption != null && Convert.ToInt32(objOption) == 1)
				{
					text = string.Format(" AND (tCore_Header{0}.iVoucherClass = {1} OR tCore_Header{0}.iVoucherClass = {2} OR tCore_Header{0}.iVoucherClass = {3}) ", Suffix, 768, 6400, 1280);
				}
				break;
			case FocusReport.PurchasesGroupedByVendor:
			case FocusReport.PurchasesGroupedByProduct:
			case FocusReport.PurchasesGroupedByDepartment:
				text = $" AND tCore_Header{Suffix}.iVoucherClass = {768} ";
				if (objOption != null && Convert.ToInt32(objOption) == 1)
				{
					text = string.Format(" AND (tCore_Header{0}.iVoucherClass = {1} OR tCore_Header{0}.iVoucherClass = {2}) ", Suffix, 768, 6400);
				}
				break;
			case FocusReport.PurchaseReturnRegister:
				text = $" AND tCore_Header{Suffix}.iVoucherClass = {6400} ";
				break;
			case FocusReport.JournalEntryRegister:
				text = string.Format(" AND (tCore_Header{0}.iVoucherClass = {1} OR tCore_Header{0}.iVoucherClass = {2}) ", Suffix, 3584, 8704);
				break;
			case FocusReport.OpeningBalanceRegister:
				text = $" AND tCore_Header{Suffix}.iVoucherClass = {256} ";
				break;
			case FocusReport.PDCPaymentsRegisters:
				text = ((objOption == null || Convert.ToInt32(objOption) != 3) ? $" AND tCore_Header{Suffix}.iVoucherClass = {7168} " : $" AND tCore_Header{Suffix}.iVoucherClass IN({7168},{4864}) ");
				break;
			case FocusReport.PDCRecieptsRegisters:
				text = ((objOption == null || Convert.ToInt32(objOption) != 3) ? $" AND tCore_Header{Suffix}.iVoucherClass = {5888} " : $" AND tCore_Header{Suffix}.iVoucherClass IN({5888},{4608}) ");
				break;
			case FocusReport.ReceipRegister:
				text = $" AND tCore_Header{Suffix}.iVoucherClass = {4608}  ";
				break;
			case FocusReport.PaymentRegister:
				text = $" AND tCore_Header{Suffix}.iVoucherClass = {4864} ";
				break;
			case FocusReport.DebitNoteRegister:
				text = $" AND tCore_Header{Suffix}.iVoucherClass = {3840}  ";
				break;
			case FocusReport.CreditNoteRegister:
				text = $" AND tCore_Header{Suffix}.iVoucherClass = {4096}  ";
				break;
			case FocusReport.ProfitAndLoss:
			case FocusReport.TradingAccount:
			case FocusReport.BalanceSheet:
			case FocusReport.CashFlow:
			case FocusReport.CashFlowAnalysis:
				text = General.GetAccountFilter(ReportId);
				if (!string.IsNullOrEmpty(text))
				{
					text = $" AND mCore_Account.iAccountType IN ({text})";
				}
				break;
			}
			break;
		case Module.Inventory:
			switch ((FocusReport)ReportId)
			{
			case FocusReport.StockLedger:
			case FocusReport.StockStatement:
				text += $" AND tCore_Header{Suffix}.iVoucherClass <> {512} ";
				break;
			case FocusReport.OpeningStockRegister:
				text += $" AND tCore_Header{Suffix}.iVoucherClass = {512} ";
				break;
			case FocusReport.PurchasesOrdersRegister:
				text += $" AND tCore_Header{Suffix}.iVoucherClass = {2560} ";
				break;
			case FocusReport.SalesOrdersRegister:
				text += $" AND tCore_Header{Suffix}.iVoucherClass = {5632} ";
				break;
			case FocusReport.QuotationAnalysis:
