			case FocusReport.LowestQuotation:
				text = (string.IsNullOrEmpty(m_strQuotationVouchers) ? (text + $" AND tCore_Header{Suffix}.iVoucherClass = {2304} ") : (text + string.Format(" AND tCore_Header" + Suffix + ".iVoucherType in (" + m_strQuotationVouchers + ") ")));
				break;
			case FocusReport.SalesQuotationRegister:
				text += $" AND tCore_Header{Suffix}.iVoucherClass = {7424} ";
