			}
			break;
		case Module.POS:
			switch ((FocusReport)ReportId)
			{
			case FocusReport.FastMovingItems:
			case FocusReport.SlowMovingItems:
			{
				string arg2 = "";
				if (objOption != null && Convert.ToInt32(objOption) == 1)
				{
					arg2 = $" OR tCore_Header{Suffix}.iVoucherClass={1792} ";
				}
				text = $" AND (tCore_Header{Suffix}.iVoucherClass = {3328}{arg2})";
				break;
			}
			case FocusReport.SummarySalesByOutlet:
				text = ((objOption == null || Convert.ToInt32(objOption) != 1) ? $" AND tCore_Header{Suffix}.iVoucherType = {3331} " : string.Format(" AND (tCore_Header{0}.iVoucherType = {1} OR tCore_Header{0}.iVoucherType = {2})", Suffix, 3331, 1792));
				break;
			case FocusReport.SummarySalesByDate:
			case FocusReport.SummarySalesByQtyAndAmtWise:
				text = ((objOption == null || Convert.ToInt32(objOption) != 1) ? $" AND tCore_Header{Suffix}.iVoucherClass = {3328} " : string.Format(" AND (tCore_Header{0}.iVoucherClass = {1} OR tCore_Header{0}.iVoucherClass = {2})", Suffix, 3328, 1792));
				break;
			case FocusReport.RetailSalesAnalysis:
			case FocusReport.RetailSalesOutletWise:
			case FocusReport.RetailSalesCounterWise:
			case FocusReport.RetailSalesProductWise:
			case FocusReport.RetailSalesTransactionAnalysis:
			case FocusReport.SummarySalesByProduct:
			case FocusReport.SummarySalesByQuantityWise:
			case FocusReport.SummarySalesByAmountWise:
			case FocusReport.MemberFrequency:
			case FocusReport.SalesInfoByMembers:
			case FocusReport.HourlySalesByOutlet:
			case FocusReport.DailySalesByOutlet:
			case FocusReport.QuarterlySalesByOutlet:
			case FocusReport.MonthlySalesByOutlet:
			case FocusReport.BestOutletPerformance:
			case FocusReport.WorstOutletPerformance:
			{
				string arg = "";
				if ((ReportId == 8502 || ReportId == 8503 || ReportId == 8504 || ReportId == 8506 || ReportId == 8552 || ReportId == 8555 || ReportId == 8509 || ReportId == 8511 || ReportId == 8510 || ReportId == 8553) && objOption != null && Convert.ToInt32(objOption) == 1)
				{
					arg = $" OR tCore_Header{Suffix}.iVoucherClass = {1792}";
				}
				text = $" AND (tCore_Header{Suffix}.iVoucherClass = {3328} {arg}) ";
				break;
			}
			case FocusReport.PreorderSalesDetailReports:
			case FocusReport.PreorderSalesDetailByOrder:
			case FocusReport.PreorderSalesSummaryQtyWise:
			case FocusReport.PreorderSalesSummaryAmounttWise:
				text = $" AND tCore_Header{Suffix}.iVoucherClass = {5632} ";
				break;
			case FocusReport.PreorderPaymentCollection:
				text = $" AND tCore_Header{Suffix}.iVoucherClass = {4096} ";
				break;
			case FocusReport.PreorderRefundOrder:
			case FocusReport.PreorderPaymentCollectionByPaymentMode:
			case FocusReport.PreorderPaymentCollectionByPaymentNo:
				text = $" AND tCore_Header{Suffix}.iVoucherClass = {3584} ";
				break;
			case FocusReport.StockInAndOut:
			case FocusReport.StockStatusByoutlet:
				text = string.Format(" AND(tCore_Header{0}.iVoucherClass = {1} OR tCore_Header{0}.iVoucherClass = {2}\r\n                                OR tCore_Header{0}.iVoucherClass = {3} OR tCore_Header{0}.iVoucherClass = {4})", Suffix, 768, 1792, 3328, 6400);
				break;
			}
			break;
		case Module.Production:
			switch ((FocusReport)ReportId)
			{
			case FocusReport.ConsumptionRegister:
			case FocusReport.WorkInProcess:
			case FocusReport.ProductwiseWorkInProcess:
			case FocusReport.ConsumptionSummary:
