			case FocusReport.ProductionSummary:
				text = string.Format(" AND tCore_Header{0}.iVoucherClass IN ({1},{2},{3}) AND tCore_Header{0}.iVoucherType Not in(1056)", Suffix, 1024, 1536, 2816);
				break;
			}
			break;
		}
		return text;
	}

	private string GetExtraColumn(string[] arrColumns, FieldData[] arrExtraFields, RepRecord objRec)
	{
		int num = 0;
		List<string> list = null;
		string text = null;
		list = new List<string>();
		for (num = 0; num < arrColumns.Length; num++)
		{
			if (arrColumns[num].Length <= 0)
			{
				continue;
			}
			if (IsSummarizeReport(objRec) && num < arrExtraFields.Length && arrExtraFields[num].DataType == MasterDataType.Fraction)
			{
				if (arrExtraFields[num].FieldId == -2)
				{
					text += $",0[{arrColumns[num]}{num}] ";
					continue;
				}
				string text2 = arrColumns[num].Replace("[", "");
				text2 = text2.Replace("]", "");
				string columnFunction = GetColumnFunction(objRec, arrExtraFields[num]);
				text = (string.IsNullOrEmpty(columnFunction) ? (text + $",{arrColumns[num]}[{text2}{num}] ") : (text + string.Format(",{3}({0})[{1}{2}] ", arrColumns[num], text2, num, columnFunction)));
			}
			else
			{
				string text3 = ((num < arrExtraFields.Length) ? arrExtraFields[num].FieldName.Replace("[", "") : string.Empty);
				text3 = text3.Replace("]", "");
				text += $",{arrColumns[num]}[{text3}{num}] ";
				list.Add(arrColumns[num]);
			}
		}
		return text;
	}

	private string GetColumnFunction(RepRecord objRec, FieldData objFieldData, bool bSummary = false)
	{
		if (objFieldData != null && objRec.ReportCustomize != null && objRec.ReportCustomize.Layout != null && objRec.ReportCustomize.Layout.Columns != null)
		{
			RDDefault rDDefault = new RDDefault();
			if ((objRec.ReportId < RDCommon.RD_STARTID && !bSummary && rDDefault.GetBackTrackType(objRec.ReportId, objRec.Module, objRec.Inputs) == BackTrackType.Transaction) || IgnoreInnerFunction(objRec.ReportId, objRec.Module))
			{
				return null;
			}
			for (int i = 0; i < objRec.ReportCustomize.Layout.Columns.Length; i++)
			{
				if (objRec.ReportCustomize.Layout.Columns[i].ColumnFunction != null && objRec.ReportCustomize.Layout.Columns[i].FieldId == objFieldData.FieldId && objRec.ReportCustomize.Layout.Columns[i].SubParentId == objFieldData.SubParentId)
				{
					return objRec.ReportCustomize.Layout.Columns[i].ColumnFunction.Function switch
					{
						AggregateFunction.Average => "AVG", 
						AggregateFunction.Count => "COUNT", 
						AggregateFunction.Maximum => "MAX", 
						AggregateFunction.Minimum => "MIN", 
						_ => "SUM", 
					};
				}
			}
		}
		if (!bSummary)
		{
			return null;
		}
		return "SUM";
	}

	private bool IsSummarizeReport(RepRecord objRec)
	{
		if (objRec.ReportId >= RDCommon.RD_STARTID)
		{
			return false;
		}
		switch ((FocusReport)objRec.ReportId)
		{
		case FocusReport.SummarySalesRegister:
		case FocusReport.SummaryPurchaseRegister:
		case FocusReport.SalesGroupedByCustomer:
		case FocusReport.SalesGroupedByProduct:
		case FocusReport.SalesGroupedByDepartment:
		case FocusReport.PurchasesGroupedByVendor:
		case FocusReport.PurchasesGroupedByProduct:
		case FocusReport.PurchasesGroupedByDepartment:
		case FocusReport.MultiLevelStockMovement:
		case FocusReport.StockAnalysisbyBatch:
		case FocusReport.BudgetReport:
		case FocusReport.AdvancedBudgetReport:
		case FocusReport.SummarySalesByDate:
		case FocusReport.SummarySalesByOutlet:
			return true;
		default:
			return objRec.IsSummary;
		}
	}

	private bool IgnoreInnerFunction(uint iReportId, Module oModule)
	{
		if (oModule != Module.None)
		{
			if (iReportId - 510 <= 2)
			{
				return true;
			}
		}
		return false;
	}

