	private void checkSpecialFilter(RepRecord objRec, ref string strQuery, ref string strFilter)
	{
		if (string.IsNullOrEmpty(m_strParamFilter))
		{
			return;
		}
		if (strQuery.Contains("--@EXTRA_TABLES"))
		{
			m_strParamValues = General.GetMasters(objRec.Masters);
			string text;
			if (m_strParamFilter.Contains("BookNo."))
			{
				text = "BookNo";
			}
			else if (m_strParamFilter.Contains("Code."))
			{
				text = "Code";
			}
			else
			{
				text = (m_strParamFilter.Contains("vrCore_Product.") ? "vrCore_Product" : "");
			}
			if (!string.IsNullOrEmpty(text))
			{
				if (text.Contains("BookNo"))
				{
					strQuery = strQuery.Replace("--@EXTRA_TABLES", $" JOIN @XML.nodes('/Master/r') T(c) ON tCore_Data{Suffix}.iBookNo = T.c.value('./@id', 'int') ");
				}
				else if (text.Contains("Code"))
				{
					strQuery = strQuery.Replace("--@EXTRA_TABLES", $" JOIN @XML.nodes('/Master/r') T(c) ON tCore_Data{Suffix}.iCode = T.c.value('./@id', 'int') ");
				}
				else
				{
					strQuery = strQuery.Replace("--@EXTRA_TABLES", $" JOIN @XML.nodes('/Master/r') T(c) ON {text}.iMasterId = T.c.value('./@id', 'int') ");
				}
			}
			else
			{
				strQuery = strQuery.Replace("--@EXTRA_TABLES", "");
			}
		}
		else if (strFilter.Contains("--@EXTRA_TABLES") && !string.IsNullOrEmpty(m_strParamValues))
		{
			string text2;
			if (m_strParamFilter.Contains("BookNo."))
			{
				text2 = "BookNo";
			}
			else if (m_strParamFilter.Contains("Code."))
			{
				text2 = "Code";
			}
			else
			{
				text2 = (m_strParamFilter.Contains("vrCore_Product.") ? "vrCore_Product" : "");
			}
			if (!string.IsNullOrEmpty(text2))
			{
				if (text2.Contains("BookNo"))
				{
					strQuery += $" JOIN @XML.nodes('/Master/r') T(c) ON tCore_Data{Suffix}.iBookNo = T.c.value('./@id', 'int') ";
				}
				else if (text2.Contains("Code"))
				{
					strQuery += $" JOIN @XML.nodes('/Master/r') T(c) ON tCore_Data{Suffix}.iCode = T.c.value('./@id', 'int') ";
				}
				else
				{
					strQuery += $" JOIN @XML.nodes('/Master/r') T(c) ON {text2}.iMasterId = T.c.value('./@id', 'int') ";
				}
			}
			strFilter = strFilter.Replace("--@EXTRA_TABLES", "");
		}
		else if (!string.IsNullOrEmpty(m_strParamValues))
		{
			if (m_strParamFilter.Contains(".iTransactionId"))
			{
				strQuery += $" JOIN @XML.nodes('/Master/r') T(c) ON {m_strParamFilter} = T.c.value('./@id', 'bigint') ";
			}
			else
			{
				strQuery += $" JOIN @XML.nodes('/Master/r') T(c) ON {m_strParamFilter} = T.c.value('./@id', 'int') ";
			}
		}
		if (!string.IsNullOrEmpty(m_strParamValues))
		{
			m_strParamValues = m_strParamValues.Replace("(", "");
			m_strParamValues = m_strParamValues.Replace(")", "");
		}
	}

	private void AppendSpecialFilter(RepRecord objRec, ref string strQuery)
	{
		if (string.IsNullOrEmpty(m_strParamFilter) || string.IsNullOrEmpty(m_strParamValues))
		{
			return;
		}
		if (IsClosedCompanyReport(objRec))
		{
			if (Suffix == "_0")
			{
				strQuery = strQuery.Insert(0, getXmlMaster(m_strParamValues));
			}
		}
		else
		{
			strQuery = strQuery.Insert(0, getXmlMaster(m_strParamValues));
		}
		m_strParamFilter = (m_strParamValues = null);
	}

	private string getXmlJoin(string strMaster)
	{
		return $" JOIN @XML.nodes('/Master/r') T(c) ON {strMaster}.iMasterId = T.c.value('./@id', 'int') ";
	}

	private string getXmlMaster(string strParamValues)
	{
		StringBuilder stringBuilder = new StringBuilder();
		if (!string.IsNullOrEmpty(strParamValues))
		{
			string[] array = strParamValues.Split(',');
			stringBuilder.Append("DECLARE @XML AS XML\r\nSET @XML = '<Master>");
			for (int i = 0; i < array.Length; i++)
			{
				stringBuilder.AppendFormat("<r id=\"{0}\"/>", array[i]);
			}
			stringBuilder.Append("</Master>'\r\n");
		}
		return stringBuilder.ToString();
	}

	private string RefreshColumn(string strColumn, ref string sAlias)
	{
		int num = strColumn.LastIndexOf('[');
		int num2 = strColumn.LastIndexOf(']');
		if (num > -1 && num < strColumn.Length && num2 > -1 && num2 < strColumn.Length && num < num2)
		{
			sAlias = strColumn.Substring(num, num2 - num + 1);
			strColumn = strColumn.Replace(sAlias, string.Empty);
		}
		return strColumn;
	}

