		if (strTableName == "vtCore_DrCr" + Suffix && objRec.Module == Module.None && objRec.ReportId == 3584)
		{
			return " LEFT JOIN \r\n(\r\n    SELECT InnerTable.iBodyId, Debit[Dr], Credit[Cr]  \r\n    FROM   \r\n    (  \r\n        SELECT tCore_Data" + Suffix + ".iBodyId,   \r\n        CASE WHEN mAmount1 < 0 THEN mAmount1 ELSE 0 END Debit,   \r\n        CASE WHEN mAmount1 > 0 THEN mAmount1 ELSE 0 END Credit  \r\n        FROM tCore_Data" + Suffix + "   \r\n        JOIN tCore_Header" + Suffix + " ON tCore_Data" + Suffix + ".iHeaderId = tCore_Header" + Suffix + ".iHeaderId AND iType = 0 AND iVoucherClass = 3584\r\n    )InnerTable\r\n) " + strTableName + " ON " + strTableName + ".iBodyId = tCore_Data" + Suffix + ".iBodyId ";
		}
		return " LEFT JOIN " + strTableName + " ON " + strTableName + ".iBodyId = tCore_Data" + Suffix + ".iBodyId \n";
	}

