	private void GenerateVoucherQuery(List<IdNamePair> lstFieldName, List<VoucherFieldInfo> lstCurrentVoucher, string strSuffix, int iVocuherType, bool bHeader, ref List<string> lstVoucherQuery, string sDateTagFilter = null, bool IsIgnoreEmptyCondition = false)
	{
		string text = string.Empty;
		string text2 = null;
		string text3 = null;
		string text4 = null;
		string text5 = string.Empty;
		string[] array = null;
		List<string> list = new List<string>();
		for (int i = 0; i < lstFieldName.Count; i++)
		{
			if (text.ToLower() == lstFieldName[i].Name.ToLower())
			{
				continue;
			}
			int fieldIndexInVoucher = GetFieldIndexInVoucher(lstCurrentVoucher, lstFieldName[i].Name, lstFieldName[i].ID);
			if (fieldIndexInVoucher > -1)
			{
				text2 = (bHeader ? "header" : "body");
				if (lstCurrentVoucher[fieldIndexInVoucher].DataType == 9)
				{
					if (!string.IsNullOrEmpty(lstCurrentVoucher[fieldIndexInVoucher].DefaultValue) && lstCurrentVoucher[fieldIndexInVoucher].DefaultValue.Length > 4)
					{
						array = lstCurrentVoucher[fieldIndexInVoucher].DefaultValue.Split(',');
						text3 = "CASE " + text2 + "." + lstFieldName[i].Name;
						for (int j = 0; j + 1 < array.Length; j += 2)
						{
							text3 = text3 + " WHEN " + array[j] + " THEN N'" + array[j + 1] + "'";
						}
						text3 = text3 + " END[" + lstFieldName[i].Name + "]";
						list.Add(text3);
					}
					else
					{
						list.Add(GetDefaultValue(lstFieldName[i].ID) + "[" + lstFieldName[i].Name + "]");
					}
				}
				else if (lstCurrentVoucher[fieldIndexInVoucher].DataType == 14 && !string.IsNullOrEmpty(lstCurrentVoucher[fieldIndexInVoucher].DefaultValue))
				{
					array = lstCurrentVoucher[fieldIndexInVoucher].DefaultValue.Split('.');
					if (array.Length >= 3)
					{
						list.Add($"{array[0]}.{array[2]}[{lstCurrentVoucher[fieldIndexInVoucher].FieldName}]");
						text4 = string.Format("JOIN {0} ON {0}.{1} = {2}.{3}", array[0], array[1], text2, lstCurrentVoucher[fieldIndexInVoucher].FieldName);
					}
				}
				else
				{
					list.Add(text2 + "." + lstCurrentVoucher[fieldIndexInVoucher].FieldName);
				}
			}
			else
			{
				list.Add(GetDefaultValue(lstFieldName[i].ID) + "[" + lstFieldName[i].Name + "]");
			}
			text = lstFieldName[i].Name;
		}
		if (string.IsNullOrEmpty(text4) && list.Where((string p) => p.Contains("CASE")).Count() == 0 && !IsIgnoreEmptyCondition)
		{
			text5 = string.Join(" OR ", from p in list
				where !p.Contains("''") && !p.Contains("0") && !p.Contains("CASE")
				select $"LEN({p}) > 0");
			if (text5.Length > 0)
			{
				text5 = text5.Insert(0, "WHERE ");
			}
		}
		if (!string.IsNullOrEmpty(sDateTagFilter))
		{
			text5 = ((text5.Length <= 0) ? $" WHERE 1=1 {sDateTagFilter}" : (text5 + sDateTagFilter));
			text4 = ((!bHeader) ? (text4 + string.Format(" JOIN tCore_Data{0} ON body.iBodyId = tCore_Data{0}.iBodyId JOIN tCore_Header{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId ", Suffix)) : (text4 + string.Format(" JOIN tCore_Header{0} ON tCore_Header{0}.iHeaderId = header.iHeaderId JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId ", Suffix)));
		}
		if (bHeader)
		{
			lstVoucherQuery.Add(string.Format(" SELECT header.iHeaderId,{0} FROM tCore_HeaderData{1}{2} header WITH (READUNCOMMITTED) {3} {4}", string.Join(",", list.ToArray()), iVocuherType, strSuffix, text4, text5));
		}
		else
		{
			lstVoucherQuery.Add(string.Format(" SELECT body.iBodyId,{0} FROM tCore_Data{1}{2} body WITH (READUNCOMMITTED) {3} {4}", string.Join(",", list.ToArray()), iVocuherType, strSuffix, text4, text5));
		}
	}

	private void GenerateVoucherDocQuery(List<IdNamePair> lstFieldName, List<VoucherFieldInfo> lstCurrentVoucher, string strSuffix, int iVocuherType, bool bHeader, ref List<string> lstVoucherQuery)
	{
		string text = string.Empty;
		string empty = string.Empty;
		List<string> list = new List<string>();
		for (int i = 0; i < lstFieldName.Count; i++)
		{
			if (text.ToLower() == lstFieldName[i].Name.ToLower())
			{
				continue;
			}
			int fieldIndexInVoucher = GetFieldIndexInVoucher(lstCurrentVoucher, lstFieldName[i].Name, lstFieldName[i].ID);
			if (fieldIndexInVoucher > -1)
			{
				if (bHeader)
				{
					if (lstFieldName[i].ID == 10)
					{
						list.Add("header." + lstCurrentVoucher[fieldIndexInVoucher].FieldName + "File[" + lstFieldName[i].Name + "]");
					}
					else
					{
						list.Add("header." + lstCurrentVoucher[fieldIndexInVoucher].FieldName + "[" + lstFieldName[i].Name + "]");
					}
				}
				else
				{
					list.Add("CASE WHEN body." + lstCurrentVoucher[fieldIndexInVoucher].FieldName + " IS NOT NULL AND LEN(body." + lstCurrentVoucher[fieldIndexInVoucher].FieldName + ") > 20 THEN 'Attachment' ELSE '' END[" + lstFieldName[i].Name + "]");
				}
			}
			else
			{
				list.Add("''[" + lstFieldName[i].Name + "]");
			}
			text = lstFieldName[i].Name;
		}
		if (bHeader)
		{
			lstVoucherQuery.Add(string.Format(" SELECT header.iHeaderId,{0} FROM tCore_Docs{1}{2} header WITH (READUNCOMMITTED) {3}", string.Join(",", list.ToArray()), iVocuherType, strSuffix, empty));
		}
		else
		{
			lstVoucherQuery.Add(string.Format(" SELECT body.iBodyId,{0} FROM tCore_Data{1}{2} body WITH (READUNCOMMITTED) {3}", string.Join(",", list.ToArray()), iVocuherType, strSuffix, empty));
		}
	}

