				}
			}
			text3 = "SELECT iDataTypeId, iVoucherType, sFieldName, iMasterLink, CASE WHEN iMasterLink > 0 THEN 'm'+sModule+'_'+sMasterName ELSE sDefaultValue END sDefaultValue, bHeader\r\n                FROM cCore_Fields WITH (READUNCOMMITTED)\r\n                JOIN cCore_VoucherFields" + Suffix + " WITH (READUNCOMMITTED) ON cCore_Fields.iFieldId = cCore_VoucherFields" + Suffix + ".iUniqueId\r\n                LEFT JOIN cCore_MasterDef WITH (READUNCOMMITTED) ON cCore_MasterDef.iMasterTypeId = cCore_VoucherFields" + Suffix + ".iMasterLink\r\n                " + text2 + "\r\n                ORDER BY iVoucherType,sFieldName";
			list3 = new List<VoucherFieldInfo>();
			using (DbCommand command = objDB.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text3) : text3))
			{
				dataReader = objDB.ExecuteReader(command);
				while (dataReader.Read())
				{
					VoucherFieldInfo voucherFieldInfo = new VoucherFieldInfo();
					voucherFieldInfo.DataType = Convert.ToInt32(dataReader["iDataTypeId"]);
					voucherFieldInfo.VoucherType = Convert.ToInt32(dataReader["iVoucherType"]);
					voucherFieldInfo.FieldName = Convert.ToString(dataReader["sFieldName"]);
					voucherFieldInfo.MasterLinkId = Convert.ToInt32(dataReader["iMasterLink"]);
					voucherFieldInfo.DefaultValue = Convert.ToString(dataReader["sDefaultValue"]);
					voucherFieldInfo.IsHeaderField = Convert.ToBoolean(dataReader["bHeader"]);
					list3.Add(voucherFieldInfo);
				}
				dataReader.Close();
			}
			if (list3.Count > 0)
			{
				list2 = (from p in list3
					group p by new { p.FieldName, p.DataType } into q
					select new IdNamePair(q.Key.DataType, q.Key.FieldName) into r
					orderby r.Name
					select r).ToList();
				for (num2 = 0; num2 < list2.Count; num2++)
				{
					arrColumns.Remove(list2[num2].Name);
				}
				if (arrColumns.Count > 0)
				{
					for (num2 = 0; num2 < arrColumns.Count; num2++)
					{
						list2.Add(new IdNamePair(0, arrColumns[num2]));
					}
				}
				list4 = new List<VoucherFieldInfo>();
				list = new List<string>();
				for (num = 0; num < list3.Count; num++)
				{
					if (num3 == -1 || num3 == list3[num].VoucherType)
					{
						list4.Add(list3[num]);
					}
					else
					{
						GenerateVoucherQuery(list2, list4, Suffix, num3, ref list);
						list4.Clear();
						list4.Add(list3[num]);
					}
					num3 = list3[num].VoucherType;
				}
				GenerateVoucherQuery(list2, list4, Suffix, num3, ref list);
				stringBuilder = new StringBuilder();
				for (num2 = 0; num2 < list.Count; num2++)
				{
					stringBuilder.AppendFormat("{0}", (num2 > 0 && stringBuilder.Length > 0) ? " UNION ALL" : string.Empty);
					stringBuilder.Append(list[num2] ?? "");
				}
				if (arrVoucherTypes != null && arrVoucherTypes.Count == 1)
				{
					text3 = stringBuilder.ToString();
				}
				else
				{
					text = GetDefaultColumns(list2);
					text3 = "SELECT iBodyId, " + text + " FROM (" + stringBuilder.ToString() + ") TempTable GROUP BY iBodyId";
				}
			}
			else
			{
				text3 = "SELECT 0[iBodyId]";
				for (num2 = 0; num2 < arrColumns.Count; num2++)
				{
					if (!string.IsNullOrEmpty(arrColumns[num2]))
					{
						text3 = text3 + ",''[" + arrColumns[num2] + "]";
					}
				}
			}
		}
		return text3;
	}

	private void GenerateVoucherQuery(List<IdNamePair> lstFieldName, List<VoucherFieldInfo> lstCurrentVoucher, string strSuffix, int iVocuherType, ref List<string> lstVoucherQuery)
	{
		string text = string.Empty;
		string text2 = null;
		string text3 = null;
		string[] array = null;
		bool flag = false;
		bool flag2 = false;
		List<string> list = new List<string>();
		for (int i = 0; i < lstFieldName.Count; i++)
		{
			if (text.ToLower() == lstFieldName[i].Name.ToLower())
			{
				continue;
			}
			int fieldIndexInVoucher = GetFieldIndexInVoucher(lstCurrentVoucher, lstFieldName[i].Name, lstFieldName[i].ID);
			if (fieldIndexInVoucher > -1)
			{
				text2 = (lstCurrentVoucher[fieldIndexInVoucher].IsHeaderField ? "header" : "body");
				if (lstCurrentVoucher[fieldIndexInVoucher].IsHeaderField)
				{
					flag = true;
				}
				if (!lstCurrentVoucher[fieldIndexInVoucher].IsHeaderField)
				{
					flag2 = true;
				}
				if (lstCurrentVoucher[fieldIndexInVoucher].DataType == 9)
				{
					if (!string.IsNullOrEmpty(lstCurrentVoucher[fieldIndexInVoucher].DefaultValue) && lstCurrentVoucher[fieldIndexInVoucher].DefaultValue.Length > 4)
					{
						array = lstCurrentVoucher[fieldIndexInVoucher].DefaultValue.Split(',');
						text3 = "CASE " + text2 + "." + lstFieldName[i].Name;
						for (int j = 0; j < array.Length; j += 2)
						{
							text3 = text3 + " WHEN " + array[j] + " THEN N'" + array[j + 1] + "'";
						}
						text3 = text3 + " END[" + lstFieldName[i].Name + "]";
						list.Add(text3);
					}
					else
					{
						list.Add(GetDefaultValue(lstFieldName[i].ID) + "[" + lstFieldName[i].Name + "]");
					}
				}
				else
				{
					list.Add(text2 + "." + lstCurrentVoucher[fieldIndexInVoucher].FieldName);
				}
			}
			else
			{
				list.Add(GetDefaultValue(lstFieldName[i].ID) + "[" + lstFieldName[i].Name + "]");
			}
			text = lstFieldName[i].Name;
		}
		string text4 = string.Empty;
		if (list.Where((string p) => p.Contains("CASE")).Count() == 0)
		{
			text4 = string.Join(" OR ", from p in list
				where !p.Contains("''") && !p.Contains("0") && !p.Contains("CASE")
				select $"LEN({p}) > 0");
			if (text4.Length > 0)
			{
				text4 = text4.Insert(0, "WHERE ");
			}
		}
		if (flag && flag2)
		{
			lstVoucherQuery.Add(string.Format(" SELECT tCore_Data{0}.iBodyId,{1} \r\n                FROM tCore_Data{2} \r\n                LEFT JOIN tCore_HeaderData{3}{4} header WITH (READUNCOMMITTED) ON header.iHeaderId = tCore_Data{5}.iHeaderId\r\n                LEFT JOIN tCore_Data{6}{7} body WITH (READUNCOMMITTED) ON body.iBodyId = tCore_Data{8}.iBodyId \r\n                {9}", strSuffix, string.Join(",", list.ToArray()), strSuffix, iVocuherType, strSuffix, strSuffix, iVocuherType, strSuffix, strSuffix, text4));
		}
		else if (flag)
		{
			lstVoucherQuery.Add(string.Format(" SELECT tCore_Data{0}.iBodyId,{1} \r\n                FROM tCore_HeaderData{2}{3} header WITH (READUNCOMMITTED) \r\n                JOIN tCore_Data{4} ON header.iHeaderId = tCore_Data{5}.iHeaderId\r\n                {6}", strSuffix, string.Join(",", list.ToArray()), iVocuherType, strSuffix, strSuffix, strSuffix, text4));
		}
		else if (flag2)
		{
			lstVoucherQuery.Add(string.Format(" SELECT body.iBodyId,{0} \r\n                FROM tCore_Data{1}{2} body WITH (READUNCOMMITTED)\r\n                {3}", string.Join(",", list.ToArray()), iVocuherType, strSuffix, text4));
		}
	}

	private string GetDefaultColumns(List<IdNamePair> lstFieldName)
	{
		string text = string.Empty;
		List<string> list = new List<string>();
		for (int i = 0; i < lstFieldName.Count; i++)
		{
			if (!(text.ToLower() == lstFieldName[i].Name.ToLower()))
			{
				list.Add(string.Format("MAX({0})[{0}]", lstFieldName[i].Name));
				text = lstFieldName[i].Name;
			}
		}
		return string.Join(",", list.ToArray());
	}

	private int GetFieldIndexInVoucher(List<VoucherFieldInfo> arrFields, string sFieldName, int iId)
	{
		for (int i = 0; i < arrFields.Count; i++)
		{
			if (arrFields[i].FieldName.ToLower() == sFieldName.ToLower() && arrFields[i].DataType == iId)
			{
				return i;
			}
		}
		return -1;
	}

	private string GetDefaultValue(int iDataType)
	{
		switch ((MasterDataType)iDataType)
		{
		case MasterDataType.Text:
		case MasterDataType.StringList:
		case MasterDataType.NumberList:
		case MasterDataType.Master:
		case MasterDataType.HyperLink:
			return "''";
		case MasterDataType.ExternalTable:
			return "'0'";
		case MasterDataType.Picture:
		case MasterDataType.DocumentViewer:
			return "0x";
		default:
			return "0";
		}
	}

	private List<int> GetVoucherTypeForReport(RepRecord objRec, bool bDontFetchVoucher, ref bool bClassType)
	{
		List<int> list = new List<int>();
		bClassType = true;
		switch (objRec.Module)
		{
		case Module.None:
			switch ((CustomizeColumn)(byte)objRec.SubReportId)
			{
			case CustomizeColumn.HomePage:
			case CustomizeColumn.LinkVoucher:
			case CustomizeColumn.PendingBills:
			case CustomizeColumn.Drafts:
				list.Add((int)objRec.ReportId);
				bClassType = false;
				break;
			case CustomizeColumn.CustomPendingBills:
				if (objRec.ReportId == 4608 || objRec.ReportId == 5888)
				{
					list.Add(3328);
				}
				else
				{
					list.Add(768);
				}
				break;
			case CustomizeColumn.LinkPopupScreen:
				list.Add(objRec.Inputs[1].ID);
				bClassType = false;
				break;
			}
			break;
		case Module.CoreTransactions:
			switch ((FocusReport)objRec.ReportId)
			{
			case FocusReport.SalesRegister:
			case FocusReport.SummarySalesRegister:
			case FocusReport.SalesPredictionReport:
				list.Add(3328);
				list.Add(6144);
				list.Add(1792);
				break;
			case FocusReport.SalesGroupedByCustomer:
			case FocusReport.SalesGroupedByProduct:
			case FocusReport.SalesGroupedByDepartment:
				list.Add(3328);
				if (FConvert.GetInputValue(objRec.Inputs, 2) == 1)
				{
					list.Add(1792);
				}
				break;
			case FocusReport.SalesReturnRegister:
				list.Add(1792);
				break;
			case FocusReport.PurchaseRegister:
			case FocusReport.SummaryPurchaseRegister:
			case FocusReport.PurchasePredictionReport:
				list.Add(768);
				list.Add(1280);
				list.Add(6400);
				break;
			case FocusReport.PurchasesGroupedByVendor:
			case FocusReport.PurchasesGroupedByProduct:
			case FocusReport.PurchasesGroupedByDepartment:
				list.Add(768);
				list.Add(6400);
				break;
			case FocusReport.PurchaseReturnRegister:
				list.Add(6400);
				break;
			case FocusReport.JournalEntryRegister:
				list.AddRange(new int[2] { 3584, 8704 });
				break;
			case FocusReport.OpeningBalanceRegister:
				list.Add(256);
				break;
			case FocusReport.PDCPaymentsRegisters:
				list.Add(7168);
				break;
			case FocusReport.PDCRecieptsRegisters:
				list.Add(5888);
				break;
			case FocusReport.ReceipRegister:
				list.Add(4608);
				break;
			case FocusReport.PaymentRegister:
				list.Add(4864);
				break;
			case FocusReport.DebitNoteRegister:
				list.Add(3840);
				break;
			case FocusReport.CreditNoteRegister:
				list.Add(4096);
				break;
			}
			break;
		case Module.Inventory:
			switch ((FocusReport)objRec.ReportId)
			{
			case FocusReport.OpeningStockRegister:
				list.Add(512);
				break;
			case FocusReport.PurchasesOrdersRegister:
				list.Add(2560);
				break;
			case FocusReport.SalesOrdersRegister:
				list.Add(5632);
				break;
			case FocusReport.QuotationAnalysis:
			case FocusReport.PurchaseQuotationRegister:
			case FocusReport.LowestQuotation:
				list.Add(2304);
				break;
			case FocusReport.SalesQuotationRegister:
				list.Add(7424);
				break;
			}
			break;
		case Module.POS:
			switch ((FocusReport)objRec.ReportId)
			{
			case FocusReport.FastMovingItems:
			case FocusReport.SlowMovingItems:
				list.AddRange(new int[2] { 3328, 6400 });
				break;
			case FocusReport.RetailSalesAnalysis:
			case FocusReport.RetailSalesOutletWise:
			case FocusReport.RetailSalesCounterWise:
			case FocusReport.RetailSalesProductWise:
			case FocusReport.RetailSalesTransactionAnalysis:
			case FocusReport.SummarySalesByDate:
			case FocusReport.SummarySalesByProduct:
			case FocusReport.SummarySalesByQuantityWise:
			case FocusReport.SummarySalesByAmountWise:
			case FocusReport.SummarySalesByQtyAndAmtWise:
			case FocusReport.MemberFrequency:
			case FocusReport.SalesInfoByMembers:
			case FocusReport.HourlySalesByOutlet:
			case FocusReport.DailySalesByOutlet:
			case FocusReport.QuarterlySalesByOutlet:
			case FocusReport.MonthlySalesByOutlet:
			case FocusReport.BestOutletPerformance:
			case FocusReport.WorstOutletPerformance:
			case FocusReport.SummarySalesByOutlet:
				list.Add(3328);
				break;
			case FocusReport.PreorderSalesDetailReports:
			case FocusReport.PreorderSalesDetailByOrder:
			case FocusReport.PreorderSalesSummaryQtyWise:
			case FocusReport.PreorderSalesSummaryAmounttWise:
				list.Add(5632);
				break;
			case FocusReport.PreorderPaymentCollection:
				list.Add(4096);
				break;
			case FocusReport.PreorderRefundOrder:
			case FocusReport.PreorderPaymentCollectionByPaymentMode:
			case FocusReport.PreorderPaymentCollectionByPaymentNo:
				list.AddRange(new int[2] { 3584, 8704 });
				break;
			case FocusReport.StockInAndOut:
			case FocusReport.StockStatusByoutlet:
				list.AddRange(new int[4] { 768, 1792, 3328, 6400 });
				break;
			}
			break;
		case Module.Production:
			switch ((FocusReport)objRec.ReportId)
			{
			case FocusReport.ConsumptionRegister:
			case FocusReport.WorkInProcess:
			case FocusReport.ProductwiseWorkInProcess:
			case FocusReport.ConsumptionSummary:
				list.Add(6656);
				break;
			case FocusReport.ProductionRegister:
			case FocusReport.ProductionSummary:
				list.Add(1024);
				break;
			case FocusReport.ProductionOrderStatusReport:
				list.Add(5632);
				break;
			}
			break;
		}
		if (objRec.ReportCustomize != null)
		{
			bDontFetchVoucher = objRec.ReportCustomize.DataSourceType == DataSourceType.Reports || bDontFetchVoucher;
		}
		if (!bDontFetchVoucher && objRec.ReportCustomize != null && objRec.ReportCustomize.TransactionSets != null && objRec.ReportCustomize.TransactionSets.Length != 0)
		{
			List<bool> list2 = new List<bool>();
			for (int i = 0; i < objRec.ReportCustomize.TransactionSets.Length; i++)
			{
				if (objRec.ReportCustomize.TransactionSets[i].TransactionSetId == TransactionSetType.AllTransactionsOfDocumentType)
				{
					list2.Add(item: false);
					list.Add(objRec.ReportCustomize.TransactionSets[i].VoucherType);
				}
				else if (objRec.ReportCustomize.TransactionSets[i].TransactionSetId == TransactionSetType.AllTransactionsOfDocumentClass)
				{
					list2.Add(item: true);
					bDontFetchVoucher = true;
					list.Add(objRec.ReportCustomize.TransactionSets[i].VoucherType);
				}
			}
			bClassType = list2.Where((bool p) => p).Count() > 0;
		}
		return list;
	}

