			break;
		}
		if (!bDontFetchVoucher && objRec.ReportCustomize != null && objRec.ReportCustomize.TransactionSets != null)
		{
			if (objRec.SourceType == DataSourceType.Reports && m_arrBaseTranSet == null)
			{
				RDReport rDReport = new RDReport();
				m_arrBaseTranSet = rDReport.LoadTransactionSet(objRec.ReportId, m_iCompId);
			}
			if (m_arrBaseTranSet != null)
			{
				for (int i = 0; i < m_arrBaseTranSet.Length; i++)
				{
					if (m_arrBaseTranSet[i].TransactionSetId == TransactionSetType.AllTransactionsOfDocumentType)
					{
						list.Add(new IdValuePair(m_arrBaseTranSet[i].VoucherType, false));
					}
					else if (m_arrBaseTranSet[i].TransactionSetId == TransactionSetType.AllTransactionsOfDocumentClass)
					{
						list.Add(new IdValuePair(m_arrBaseTranSet[i].VoucherType, true));
					}
				}
			}
			else
			{
				for (int j = 0; j < objRec.ReportCustomize.TransactionSets.Length; j++)
				{
					if (objRec.ReportCustomize.TransactionSets[j].TransactionSetId == TransactionSetType.AllTransactionsOfDocumentType)
					{
						list.Add(new IdValuePair(objRec.ReportCustomize.TransactionSets[j].VoucherType, false));
					}
					else if (objRec.ReportCustomize.TransactionSets[j].TransactionSetId == TransactionSetType.AllTransactionsOfDocumentClass)
					{
						list.Add(new IdValuePair(objRec.ReportCustomize.TransactionSets[j].VoucherType, true));
					}
				}
			}
		}
		return list;
	}

	private IdNamePair[] generateMasterView(List<IdValuePair> arrAllFields, Database objDB, int iCompId)
	{
		int num = 0;
		int num2 = -1;
		string text = null;
		string text2 = null;
		string text3 = null;
		string text4 = null;
		string text5 = null;
		string strExternalMaster = null;
		string[] array = null;
		List<string> list = null;
		List<string> list2 = null;
		List<string> list3 = null;
		IDataReader oReader = null;
		DbCommand dbCommand = null;
		List<IdNamePair> list4 = null;
		list4 = new List<IdNamePair>();
		text2 = string.Join(",", (from p in arrAllFields
			where ((FieldData)p.Value).ParentId <= 0
			select ((FieldData)p.Value).FieldId).Distinct());
		text3 = string.Join(",", (from p in arrAllFields
			where ((FieldData)p.Value).ParentId > 0
			select ((FieldData)p.Value).SubParentId).Distinct());
		if (text2.Length > 0 && !string.IsNullOrEmpty(text3))
		{
			text2 = text2 + "," + text3;
		}
		if (!string.IsNullOrEmpty(text2))
		{
			list3 = new List<string>();
			list = new List<string>();
			InvoiceLayout invoiceLayout = new InvoiceLayout();
			for (num = 0; num < arrAllFields.Count; num++)
			{
				if ((((FieldData)arrAllFields[num].Value).FieldId & 0xFF0000) >> 16 == 128)
				{
					list3.Add(invoiceLayout.GetMasterTypeIdFromField(((FieldData)arrAllFields[num].Value).FieldId & 0xFFFF, null).ToString());
				}
			}
			text = $"SELECT cCore_MasterTabs.iMasterId\r\n                FROM cCore_MasterFields WITH (READUNCOMMITTED)\r\n                JOIN cCore_Fields WITH (READUNCOMMITTED) ON cCore_MasterFields.iFieldId = cCore_Fields.iFieldId\r\n                JOIN cCore_MasterTables WITH (READUNCOMMITTED) ON cCore_MasterTables.iTableId = cCore_MasterFields.iTableId\r\n                JOIN cCore_MasterTabs WITH (READUNCOMMITTED) ON cCore_MasterTabs.iTabId = cCore_MasterTables.iTabId\r\n                WHERE cCore_MasterFields.iFieldId IN({text2}) \r\n                GROUP BY cCore_MasterTabs.iMasterId\r\n                HAVING SUM(CASE WHEN bMainTable = 1 THEN 1 ELSE 0 END) = 0";
			using (dbCommand = objDB.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text))
			{
				oReader = objDB.ExecuteReader(dbCommand);
				while (oReader.Read())
				{
					list3.Add(Convert.ToString(oReader["iMasterId"]));
				}
				oReader.Close();
			}
			if (list3.Count > 0)
			{
				text = string.Format("SELECT iFieldId FROM cCore_MasterFields WHERE iTableId IN({0}) AND sFieldName = 'sName'", string.Join(",", list3));
				using (dbCommand = objDB.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text))
				{
					oReader = objDB.ExecuteReader(dbCommand);
					while (oReader.Read())
					{
						text2 += string.Format(",{0}", oReader["iFieldId"]);
					}
					oReader.Close();
				}
			}
			text = string.Format("SELECT cCore_MasterTabs.iMasterId, cCore_MasterFields.iFieldId, iDataTypeId, sFieldName\r\n                ,CASE WHEN iDataTypeId = {1} THEN sDefaultValue ELSE sExternalDisplayMember END[sDefaultValue]\r\n                ,CASE WHEN iDataTypeId IN({2},{3}) THEN sExternalTableName ELSE sTableName END sExternalTableName, sExternalValueMember, sTableName, bMainTable\r\n                FROM cCore_MasterFields WITH (READUNCOMMITTED)\r\n                JOIN cCore_Fields WITH (READUNCOMMITTED) ON cCore_MasterFields.iFieldId = cCore_Fields.iFieldId\r\n                JOIN cCore_MasterTables WITH (READUNCOMMITTED) ON cCore_MasterTables.iTableId = cCore_MasterFields.iTableId\r\n                JOIN cCore_MasterTabs WITH (READUNCOMMITTED) ON cCore_MasterTabs.iTabId = cCore_MasterTables.iTabId\r\n                WHERE cCore_MasterFields.iFieldId IN({0}) ORDER BY cCore_MasterTabs.iMasterId, bMainTable DESC", text2, 9, 12, 14);
			list.Clear();
			list3.Clear();
			list2 = new List<string>();
			using (dbCommand = objDB.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text))
			{
				oReader = objDB.ExecuteReader(dbCommand);
				while (oReader.Read())
				{
					if (num2 > 0 && Convert.ToInt32(oReader["iMasterId"]) != num2)
					{
						text = string.Format("SELECT 0[iTreeId],{0}.iMasterId,{1} FROM {0} {3} {2} WHERE {0}.iStatus < 5", text5, string.Join(",", list3), (list.Count > 0) ? ("LEFT JOIN " + string.Join("LEFT JOIN ", list)) : string.Empty, string.Empty);
						if (text5.Length > 2)
						{
							text5 = "vr" + text5.Remove(0, 1);
						}
						list4.Add(new IdNamePair(num2, text5, text));
						list3.Clear();
						list.Clear();
						list2.Clear();
						text5 = (text4 = (text3 = null));
					}
					if (string.IsNullOrEmpty(text5))
					{
						text5 = Convert.ToString(oReader["sExternalTableName"]);
						list2.Add(text5);
					}
					switch ((MasterDataType)Convert.ToInt32(oReader["iDataTypeId"]))
					{
					case MasterDataType.NumberList:
						text3 = Convert.ToString(oReader["sDefaultValue"]);
						if (!string.IsNullOrEmpty(text3) && text3.Length > 4)
						{
							array = text3.Split(',');
							text3 = string.Format("CASE ISNULL({0}.{1},0) ", oReader["sTableName"], oReader["sFieldName"]);
							for (num = 0; num < array.Length; num += 2)
							{
								text3 += $"WHEN {array[num]} THEN '{array[num + 1]}' ";
							}
							text3 += string.Format("ELSE '' END[{0}]", oReader["sFieldName"]);
						}
						else
						{
							text3 = string.Format("''[{0}]", oReader["sFieldName"]);
						}
						if (list2.Where((string p) => p == Convert.ToString(oReader["sTableName"])).Count() == 0)
						{
							text4 = string.Format("{0} WITH (READUNCOMMITTED) ON {0}.iMasterId = {1}.iMasterId ", oReader["sTableName"], text5);
						}
						break;
					case MasterDataType.ExternalTable:
						strExternalMaster = Convert.ToString(oReader["sExternalTableName"]);
						text3 = string.Format("{0}.{1}[{2}]", strExternalMaster, oReader["sDefaultValue"], oReader["sFieldName"]);
						if (list2.Where((string p) => p == Convert.ToString(oReader["sTableName"])).Count() == 0)
						{
							string text7 = Convert.ToString(oReader["sTableName"]);
							text4 = string.Format("{0} {2} ON {0}.iMasterId = {1}.iMasterId ", text7, text5, string.Empty);
							list2.Add(text7);
						}
						if (list2.Where((string p) => p == strExternalMaster).Count() == 0)
						{
							if (!string.IsNullOrEmpty(text4))
							{
								text4 += "LEFT JOIN ";
							}
							text4 += string.Format("{0} WITH (READUNCOMMITTED) ON {0}.{1} = {2}.{3} ", strExternalMaster, oReader["sExternalValueMember"], oReader["sTableName"], oReader["sFieldName"]);
							list2.Add(strExternalMaster);
						}
						break;
					case MasterDataType.Master:
						strExternalMaster = Convert.ToString(oReader["sExternalTableName"]);
						if (strExternalMaster.StartsWith("vm"))
						{
							strExternalMaster = strExternalMaster.Remove(0, 1);
						}
						text3 = string.Format("{0}.sName[{1}],{0}.sCode[{1}sCode]", strExternalMaster, oReader["sFieldName"]);
						if (list2.Where((string p) => p == Convert.ToString(oReader["sTableName"])).Count() == 0)
						{
							string text6 = Convert.ToString(oReader["sTableName"]);
							text4 = string.Format("{0} {2} ON {0}.iMasterId = {1}.iMasterId ", text6, text5, string.Empty);
							list2.Add(text6);
						}
						if (list2.Where((string p) => p == Convert.ToString(strExternalMaster)).Count() == 0)
						{
							if (!string.IsNullOrEmpty(text4))
							{
								text4 += "LEFT JOIN ";
							}
							text4 += string.Format("{2} {4} ON {2}.iMasterId = {0}.{3} ", oReader["sTableName"], text5, strExternalMaster, oReader["sFieldName"], string.Empty);
							list2.Add(strExternalMaster);
							break;
						}
						if (!string.IsNullOrEmpty(text4))
						{
							text4 += "LEFT JOIN ";
						}
						text4 += string.Format("{2} {4} AS {3} ON {3}.iMasterId = {0}.{3} ", oReader["sTableName"], text5, strExternalMaster, oReader["sFieldName"], string.Empty);
						list2.Add(strExternalMaster);
						text3 = string.Format("{1}.sName[{1}],{1}.sCode[{1}sCode]", strExternalMaster, oReader["sFieldName"]);
						break;
					default:
						if (Convert.ToBoolean(oReader["bMainTable"]))
						{
							text3 = string.Format("{0}.{1}", text5, oReader["sFieldName"]);
							break;
						}
						text3 = string.Format("{0}.{1}", oReader["sExternalTableName"], oReader["sFieldName"]);
						if (list2.Where((string p) => p == Convert.ToString(oReader["sExternalTableName"])).Count() == 0)
						{
							Convert.ToString(oReader["sExternalTableName"]);
							text4 = string.Format("{0} {2} ON {0}.iMasterId = {1}.iMasterId ", oReader["sExternalTableName"], text5, string.Empty);
						}
						break;
					}
					list3.Add(text3);
					if (!string.IsNullOrEmpty(text4))
					{
						list.Add(text4);
						list2.Add(Convert.ToString(oReader["sExternalTableName"]));
						if (Convert.ToInt32(oReader["iDataTypeId"]) == 12)
						{
							list2.Add(Convert.ToString(oReader["sTableName"]));
						}
						text4 = null;
					}
					num2 = Convert.ToInt32(oReader["iMasterId"]);
				}
				oReader.Close();
			}
			if (num2 > 0)
			{
				text = string.Format("SELECT 0[iTreeId],{0}.iMasterId,{1} FROM {0} {3} {2} WHERE {0}.iStatus < 5", text5, string.Join(",", list3), (list.Count > 0) ? ("LEFT JOIN " + string.Join("LEFT JOIN ", list)) : string.Empty, string.Empty);
				if (text5.Length > 2)
				{
					text5 = "vr" + text5.Remove(0, 1);
				}
				list4.Add(new IdNamePair(num2, text5, text));
			}
		}
		return list4.ToArray();
	}

	private string getMasterInnerQuery(string sMasterName)
	{
		if (m_arrAllMasterViews != null && m_arrAllMasterViews.Where((IdNamePair p) => p.Name == sMasterName).Count() > 0)
		{
			return $"\r\n(\r\n    {(from p in m_arrAllMasterViews
				where p.Name == sMasterName
				select Convert.ToString(p.Tag)).FirstOrDefault()}\r\n)";
		}
		return sMasterName;
	}

	private string getMasterJoin(int iSubParentId, string sMasterName, string strJoinTable, string sLeftJoin = "LEFT")
	{
		string empty = string.Empty;
		if (m_arrAllMasterViews != null && m_arrAllMasterViews.Where((IdNamePair p) => p.Name == sMasterName).Count() > 0)
		{
			empty = $"\r\n(\r\n    {(from p in m_arrAllMasterViews
				where p.Name == sMasterName
				select Convert.ToString(p.Tag)).FirstOrDefault()}\r\n)";
			return string.Format(" {3} JOIN {2}{0} ON {0}.iMasterId = {1} ", sMasterName, strJoinTable, empty, sLeftJoin);
		}
		return string.Format(" {2} JOIN {0} {3} ON {0}.iMasterId = {1} AND {0}.iTreeId = 0", sMasterName, strJoinTable, sLeftJoin, string.Empty);
	}

	private string getMasterInnerQuery(int iSubParentId, string sMasterName)
	{
		if (m_arrAllMasterViews != null && m_arrAllMasterViews.Where((IdNamePair p) => p.Name == sMasterName).Count() > 0)
		{
			return (from p in m_arrAllMasterViews
				where p.Name == sMasterName
				select Convert.ToString(p.Tag)).FirstOrDefault();
		}
		return null;
	}

