	private int GetTagFilter(Database objDb, int iFieldId, int iSubParentId, List<IdValuePair> arrVoucherTypesValue, ref string strEditLayoutMaster)
	{
		DbCommand dbCommand = null;
		int num = 0;
		string text = null;
		try
		{
			text = string.Format("SELECT distinct CASE WHEN bHeader = 1 THEN  'vCore_TranHeaderData' + '{0}' + '.' + sFieldName ELSe 'vCore_TranData' + '{0}' + '.' + sFieldName END[sFieldName]\r\n                            FROM cCore_VoucherFields{0} WITH (READUNCOMMITTED)\r\n                WHERE iUniqueId = {1}", Suffix, iSubParentId & 0xFFFFFF);
			if (arrVoucherTypesValue.Count > 0)
			{
				text += "  AND (";
				for (int i = 0; i < arrVoucherTypesValue.Count; i++)
				{
					text = ((!Convert.ToBoolean(arrVoucherTypesValue[i].Value)) ? (text + string.Format("{0} iVoucherType = {1} ", (i > 0) ? "OR" : "", arrVoucherTypesValue[i].ID)) : (text + string.Format("{0} iVoucherType & {1} = {2} ", (i > 0) ? "OR" : "", 65280, arrVoucherTypesValue[i].ID)));
				}
				text += ")";
			}
			dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			IDataReader dataReader = objDb.ExecuteReader(dbCommand);
			if (dataReader.Read())
			{
				strEditLayoutMaster += Convert.ToString(dataReader[0]);
			}
			dataReader.Close();
			if (string.IsNullOrEmpty(strEditLayoutMaster))
			{
				dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre($"SELECT iMasterId FROM vmuCore_MasterFields WHERE iFieldId = {iFieldId}") : $"SELECT iMasterId FROM vmuCore_MasterFields WHERE iFieldId = {iFieldId}");
				num = Convert.ToInt32(objDb.ExecuteScalar(dbCommand));
				if (num == 0)
				{
					num = iSubParentId & 0xFFFFFF;
				}
			}
		}
		catch (Exception ex)
		{
			m_sError = ex.Message;
		}
		return num;
	}

	public ComboData[] GetAccountNameInGroup(int iAccountGroup, Database objDb)
	{
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		string text = null;
		List<ComboData> list = new List<ComboData>();
		try
		{
			text = $"WITH RecursionCTE (iMasterId, sName, iParentId, bGroup)  AS  \r\n                                (   SELECT iMasterId, sName, iParentId, bGroup\r\n                                    FROM vmCore_Account \r\n                                    WHERE iMasterId = {iAccountGroup} AND iTreeId = 0\r\n                                    UNION ALL  \r\n                                    SELECT R1.iMasterId, R1.sName, R1.iParentId, R1.bGroup\r\n                                    FROM vmCore_Account AS R1 \r\n                                    JOIN RecursionCTE AS R2 ON R1.iParentId = R2.iMasterId WHERE iTreeId = 0\r\n                                )SELECT iMasterId,sName  FROM RecursionCTE WHERE bGroup = 0 ";
			dbCommand = objDb.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dataReader = objDb.ExecuteReader(dbCommand);
			while (dataReader.Read())
			{
				list.Add(new ComboData(Convert.ToInt32(dataReader["iMasterId"]), Convert.ToString(dataReader["sName"])));
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			FConvert.LogFile("FQuery.log", "Exception QueryGenerator->GetAccountNameInGroup : " + ex.Message + " \r\n " + ex.StackTrace);
		}
