		string text = string.Empty;
		string empty = string.Empty;
		try
		{
			empty = $"WITH RecursionCTE (iMasterId, iParentId, bGroup)  AS  \r\n                                (   SELECT iMasterId, iParentId, bGroup\r\n                                    FROM vmCore_Account \r\n                                    WHERE iMasterId = {iAccountGroup} AND iTreeId = 0\r\n                                    UNION ALL  \r\n                                    SELECT R1.iMasterId, R1.iParentId, R1.bGroup\r\n                                    FROM vmCore_Account AS R1 \r\n                                    JOIN RecursionCTE AS R2 ON R1.iParentId = R2.iMasterId WHERE iTreeId = 0\r\n                                )SELECT iMasterId  FROM RecursionCTE WHERE bGroup = 0 ";
