	public IdValuePair[] GetQtyAndAmount(RepRecord objRec, string strCategory)
	{
		DbCommand dbCommand = null;
		IDataReader dataReader = null;
		string text = null;
		List<IdValuePair> list = new List<IdValuePair>();
		try
		{
			text = (string.IsNullOrEmpty(strCategory) ? string.Format("SELECT ISNULL(SUM(tCore_Indta{0}.fQuantity), 100)[Qty], ISNULL(SUM(tCore_Indta{0}.mGross), 100)[Amt]\r\n                    FROM tCore_Header{0} \r\n                    JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n                    JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId \r\n                    WHERE iDate BETWEEN {1} AND {2} AND tCore_Header{0}.iVoucherType = {3}", Suffix, objRec.StartingDate, objRec.EndingDate, 3331) : string.Format("SELECT ISNULL(SUM(tCore_Indta{0}.fQuantity), 100)[Qty], ISNULL(SUM(tCore_Indta{0}.mGross), 100)[Amt]\r\n                    FROM tCore_Header{0} \r\n                    JOIN tCore_Data{0} ON tCore_Header{0}.iHeaderId = tCore_Data{0}.iHeaderId\r\n                    JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId\r\n                    JOIN tCore_Data_Tags{0} ON tCore_Data_Tags{0}.iBodyId = tCore_Indta{0}.iBodyId \r\n                    JOIN muPos_Counter WITH (READUNCOMMITTED) ON muPos_Counter.iMasterId = tCore_Data_Tags{0}.iTag{5}\r\n                    JOIN cPos_RestMenuItem WITH (READUNCOMMITTED) ON tCore_Indta{0}.iProduct = cPos_RestMenuItem.iProductId\r\n                    JOIN cPos_RestMenu WITH (READUNCOMMITTED) ON cPos_RestMenu.iRestMenuId = cPos_RestMenuItem.iRestMenuId \r\n                    JOIN cPos_RestMenuTemplate WITH (READUNCOMMITTED) ON cPos_RestMenu.iMenuTemplateId = cPos_RestMenuTemplate.iMenuTemplateId\r\n\t\t\t\t\tJOIN cPos_Templates WITH (READUNCOMMITTED) ON cPos_Templates.iId = cPos_RestMenuTemplate.iTemplateId \r\n                    --JOIN cPos_Templates WITH (READUNCOMMITTED) ON cPos_Templates.iId = cPos_RestMenu.iMenuTemplateId and cPos_Templates.iId = muPos_Counter.iTemplate \r\n                    JOIN tCore_HeaderData{4}{0} WITH (READUNCOMMITTED) ON tCore_HeaderData{4}{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                    JOIN tCore_Data{4}{0} WITH (READUNCOMMITTED) ON tCore_Data{4}{0}.iBodyId = tCore_Data{0}.iBodyId\r\n                    WHERE iDate BETWEEN {1} AND {2} AND cPos_RestMenu.sName = '{3}' AND tCore_Header{0}.iVoucherType = {4} \r\n                    AND tCore_HeaderData{4}{0}.iStatus = 2 AND tCore_Data{4}{0}.iVoidRemarks = 0 \r\n                            AND ISNULL(cPos_RestMenuItem.iStatus, 0) <> 5 AND ISNULL(cPos_RestMenu.iStatus, 0) <> 5 AND ISNULL(cPos_RestMenuTemplate.iStatus, 0) <> 5 ", Suffix, objRec.StartingDate, objRec.EndingDate, strCategory, 3331, 1101));
			dbCommand = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			dataReader = m_objDatabase.ExecuteReader(dbCommand);
			if (dataReader.Read())
			{
				list.Add(new IdValuePair(0, Convert.ToDouble(dataReader["Qty"])));
				list.Add(new IdValuePair(1, Convert.ToDouble(dataReader["Amt"])));
			}
			dataReader.Close();
		}
		catch
		{
		}
		if (list.Count == 0)
		{
			list.Add(new IdValuePair(0, 100));
			list.Add(new IdValuePair(1, 100));
		}
		if (list.Count > 0 && Convert.ToDouble(list[0].Value) == 0.0)
		{
			list[0].Value = 100;
		}
		if (list.Count > 1 && Convert.ToDouble(list[1].Value) == 0.0)
		{
			list[1].Value = 100;
		}
		if (objRec.Inputs != null)
		{
			list.AddRange(objRec.Inputs);
		}
		return list.ToArray();
	}

	public List<IdNamePair> GetPurchaseColumn(bool bPurVoucher, bool bIncludeReturnVoucher)
	{
