	public string GetVoucherTypeRestriction(int iUserId, int iCompanyId)
	{
		List<string> list = new List<string>();
		if (iUserId > 1)
		{
			string text = string.Format("SELECT DISTINCT mCore_Menu.iTypeId\r\n                FROM\r\n                (\r\n                    SELECT iMenuId,iActionId FROM mSec_ProfileDetails WHERE iProfileId IN \r\n                    (\r\n                        SELECT iProfileId FROM mSec_RolesProfiles a\r\n                        JOIN mSec_Users_Roles r ON r.iERPRole = a.iRoleId WHERE r.iUserId = {0} AND r.iYearId = {1}\r\n                    )\r\n                    UNION\r\n                    SELECT iMenuId,iActionId FROM mSec_RolesExtraRights a\r\n                    JOIN mSec_Users_Roles r ON r.iERPRole = a.iRoleId WHERE r.iUserId = {0} AND r.iYearId = {1} AND bAdd = 1\r\n                    EXCEPT\r\n                    SELECT iMenuId,iActionId FROM mSec_RolesExtraRights a\r\n                    JOIN mSec_Users_Roles r ON r.iERPRole = a.iRoleId WHERE r.iUserId = {0} AND r.iYearId = {1} AND bAdd = 0\r\n                ) as RightsTable\r\n                INNER JOIN mCore_Menu ON mCore_Menu.iMenuId = RightsTable.iMenuId\r\n                WHERE mCore_Menu.iType = 1", iUserId, m_iYearId);
			using DbCommand command = m_objDatabase.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			IDataReader dataReader = m_objDatabase.ExecuteReader(command);
			while (dataReader.Read())
			{
				list.Add(Convert.ToString(dataReader[0]));
			}
			dataReader.Close();
		}
		return string.Join(",", list.ToArray());
	}

	private bool IsMultipleRMAExist(int iCompanyId)
	{
		string text = $"SELECT COUNT(1)[Num]\r\n            FROM tCore_Rma{Suffix} WITH(READUNCOMMITTED) GROUP BY iBodyId HAVING COUNT(sRmaNo)>1\r\n            ORDER BY COUNT(1) DESC";
