				}
				text2 = string.Format("SELECT DISTINCT {2}[sVoucherNo] \r\n                    FROM tCore_HeaderData{1}{0}\r\n                    JOIN tCore_Data{0} ON tCore_HeaderData{1}{0}.iHeaderId = tCore_Data{0}.iHeaderId \r\n                    JOIN tCore_Header{0} ON tCore_HeaderData{1}{0}.iHeaderId = tCore_Header{0}.iHeaderId \r\n                    JOIN tCore_Indta{0} ON tCore_Data{0}.iBodyId = tCore_Indta{0}.iBodyId\r\n                    LEFT JOIN \r\n                    (\r\n                        SELECT iTransactionId, SUM(Balance)[UsedValue] FROM\r\n                        (\r\n                            SELECT DISTINCT a.iTransactionId, ISNULL(b.fValue,0)[Balance] FROM\r\n                            (\r\n                                SELECT iRefId, tCore_Links{0}.iTransactionId, fValue, tCore_Links{0}.iUserId FROM tCore_Links{0} \r\n                                JOIN tCore_Data{0} ON tCore_Links{0}.iTransactionId = tCore_Data{0}.iTransactionId\r\n                                JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                                WHERE tCore_Links{0}.iLinkId = {5} AND bBase = 1 AND tCore_Header{0}.bSuspended = 0 \r\n                                AND tCore_Data{0}.bSuspendBaseSaved = 0 AND tCore_Header{0}.iDate <= {3}\r\n                            ) a \r\n                            LEFT JOIN\r\n                            (\r\n                                SELECT iRefId, sum(fValue)[fValue] FROM tCore_Links{0} \r\n                                JOIN tCore_Data{0} ON tCore_Links{0}.iTransactionId = tCore_Data{0}.iTransactionId\r\n                                JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId\r\n                                WHERE tCore_Links{0}.iLinkId = {5} AND bBase = 0 AND tCore_Header{0}.bSuspended = 0 \r\n                                AND tCore_Data{0}.bSuspendLinkSaved = 0 AND tCore_Header{0}.iDate <= {3}\r\n                                Group by iRefId\r\n                            ) b \r\n                            ON a.iRefId = b.iRefId\r\n                        )B GROUP BY iTransactionId\r\n                    )LINK ON LINK.iTransactionId = tCore_Data{0}.iTransactionId\r\n                    WHERE tCore_Header{0}.bSuspended = 0 AND tCore_Data{0}.iAuthStatus = 1 {4}\r\n                    GROUP BY {2} ", text, list[num].ID, text3, value, (iFaTagId > 0) ? $"AND iFaTag = {iFaTagId}" : "", num3);
