					dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text3) : text3);
					while (dataReader.Read())
					{
						list18.Clear();
						for (iIndex = 0; iIndex < list17.Count; iIndex++)
						{
							list18.Add(new IdValuePair(list17[iIndex].FieldId, dataReader[list17[iIndex].FieldName]));
						}
						for (iIndex = 0; iIndex < arrData.Count; iIndex++)
						{
							if (arrData[iIndex].ProductId == Convert.ToInt32(dataReader["iMasterId"]))
							{
								arrData[iIndex].ItemExtra = list18.ToArray();
								break;
							}
						}
					}
					dataReader.Close();
				}
			}
		}
		catch (Exception ex)
		{
			quotationWiseData.Error = ex.Message;
			quotationWiseData.VoucherCount = -1;
		}
		quotationWiseData.QuotData = arrData;
