		quotationWiseData.VoucherCount = voucherCount;
		return quotationWiseData;
	}

	public IdNamePair saveQuotationLayout(QuotationLayout oData, int iCompId)
	{
		int num = 0;
		string empty = string.Empty;
		string suffix = FConvert.GetSuffix(iCompId);
		DbCommand dbCommand = null;
		Database database = null;
		DbTransaction dbTransaction = null;
		DbConnection dbConnection = null;
		database = DatabaseWrapper.GetDatabase2(iCompId);
		try
		{
			using (dbConnection = database.CreateConnection())
			{
				dbConnection.Open();
				using (dbTransaction = dbConnection.BeginTransaction())
				{
					if (oData.Default)
					{
						empty = string.Format("UPDATE cCore_QuotationLayouts{0} SET bDefault = 0", suffix, oData.LayoutId);
						dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
						database.ExecuteNonQuery(dbCommand, dbTransaction);
					}
					if (oData.LayoutId > 0)
					{
						empty = $"UPDATE cCore_QuotationLayouts{suffix} SET bDefault = {(oData.Default ? 1 : 0)} WHERE iLayoutId = {oData.LayoutId}";
						dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
						database.ExecuteNonQuery(dbCommand, dbTransaction);
						empty = $"DELETE FROM cCore_QuotationFields{suffix} WHERE iLayoutId = {oData.LayoutId}";
						dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
						database.ExecuteNonQuery(dbCommand, dbTransaction);
					}
					else
					{
						empty = $"INSERT INTO cCore_QuotationLayouts{suffix}(sLayoutName, bDefault) VALUES ('{oData.LayoutName}',{(oData.Default ? 1 : 0)});SELECT @@IDENTITY;";
						dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
						oData.LayoutId = Convert.ToInt32(database.ExecuteScalar(dbCommand, dbTransaction));
					}
					empty = string.Empty;
					if (oData.Columns != null && oData.Columns.Length != 0)
					{
						for (num = 0; num < oData.Columns.Length; num++)
						{
							empty += $"INSERT INTO cCore_QuotationFields{suffix}(iLayoutId, iFieldId, iType, sAliasName, iWidth, iFlag, iSubParentId) \r\n                                VALUES({oData.LayoutId}, {oData.Columns[num].FieldId}, {(int)oData.Columns[num].ColumnType}, N'{oData.Columns[num].ColumnName}', {oData.Columns[num].ColumnWidth}, {getQuotationFlags(oData.Columns[num])}, {oData.Columns[num].SubParentId});";
						}
						dbCommand = database.GetSqlStringCommand(PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
						database.ExecuteNonQuery(dbCommand, dbTransaction);
					}
					dbTransaction.Commit();
				}
				dbConnection.Close();
			}
		}
		catch (Exception ex)
		{
			dbTransaction.Rollback();
			return new IdNamePair(-1, ex.Message);
		}
		finally
		{
			if (dbConnection != null && dbConnection.State == ConnectionState.Open)
			{
				dbConnection.Close();
			}
		}
		return new IdNamePair(oData.LayoutId, oData.LayoutName);
	}

	private int getQuotationFlags(QuotationColumn oColumn)
	{
		return (int)(((oColumn.IsHidden ? 1u : 0u) << 3) | ((oColumn.ScrollTextToNextLine ? 1u : 0u) << 2) | ((oColumn.PrintUnderPreviousColumn ? 1u : 0u) << 1));
	}

	private void setQuotationFlags(int iValue, ref QuotationColumn oColumn)
	{
		oColumn.IsHidden = ((iValue >> 3) & 1) == 1;
		oColumn.ScrollTextToNextLine = ((iValue >> 2) & 1) == 1;
		oColumn.PrintUnderPreviousColumn = ((iValue >> 1) & 1) == 1;
	}

	public QuotationLayout getQuotationLayout(int iLayoutId, int iCompanyId)
	{
		string empty = string.Empty;
		string suffix = FConvert.GetSuffix(iCompanyId);
		Database database = null;
		IDataReader dataReader = null;
		QuotationLayout quotationLayout = null;
		List<QuotationColumn> list = null;
		QuotationColumn quotationColumn = null;
		quotationLayout = new QuotationLayout();
		quotationLayout.LayoutId = iLayoutId;
		try
		{
			database = DatabaseWrapper.GetDatabase2(iCompanyId, -1, bReplicationServer: true);
			empty = $"SELECT sLayoutName, bDefault FROM cCore_QuotationLayouts{suffix} WHERE iLayoutId = {iLayoutId}";
			dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
			if (dataReader.Read())
			{
				quotationLayout.LayoutName = Convert.ToString(dataReader["sLayoutName"]);
				quotationLayout.Default = Convert.ToBoolean(dataReader["bDefault"]);
			}
			dataReader.Close();
			empty = $"SELECT iFieldId, iType, sAliasName, ISNULL(iWidth,0)[iWidth], ISNULL(iFlag,bPrintUnderPrevCol)iFlag, ISNULL(iSubParentId,0)iSubParentId \r\n                    FROM cCore_QuotationFields{suffix} WHERE iLayoutId = {iLayoutId}";
			dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
			list = new List<QuotationColumn>();
			while (dataReader.Read())
			{
				quotationColumn = new QuotationColumn();
				quotationColumn.FieldId = Convert.ToInt32(dataReader["iFieldId"]);
				quotationColumn.ColumnName = Convert.ToString(dataReader["sAliasName"]);
				quotationColumn.ColumnType = (QuotationColumnType)Convert.ToInt32(dataReader["iType"]);
				quotationColumn.ColumnWidth = Convert.ToInt32(dataReader["iWidth"]);
				quotationColumn.SubParentId = Convert.ToInt32(dataReader["iSubParentId"]);
				setQuotationFlags(Convert.ToInt32(dataReader["iFlag"]), ref quotationColumn);
				list.Add(quotationColumn);
			}
			dataReader.Close();
			quotationLayout.Columns = list.ToArray();
			empty = $"SELECT iLayoutId FROM cCore_InvoiceLayout{suffix} WHERE iReportId = 201";
			quotationLayout.InvoiceLayout = Convert.ToInt32(database.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty));
		}
		catch (Exception ex)
		{
			quotationLayout.LayoutId = -1;
			quotationLayout.LayoutName = ex.Message;
		}
		return quotationLayout;
	}

	public string deleteQuotationLayout(int iLayoutId, int iCompId)
	{
		string empty = string.Empty;
		string suffix = FConvert.GetSuffix(iCompId);
		Database database = null;
		database = DatabaseWrapper.GetDatabase2(iCompId);
		try
		{
			if (iLayoutId > 0)
			{
				empty = string.Format("DELETE FROM cCore_QuotationFields{0} WHERE iLayoutId = {1};\r\n                    DELETE FROM cCore_QuotationLayouts{0} WHERE iLayoutId = {1}", suffix, iLayoutId);
				database.ExecuteNonQuery(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
			}
		}
		catch (Exception ex)
		{
			return ex.Message;
		}
		return string.Empty;
	}

	public List<IdNamePair> getQuotationLayouts(int iCompanyId)
	{
		string empty = string.Empty;
		string suffix = FConvert.GetSuffix(iCompanyId);
		IDataReader dataReader = null;
		List<IdNamePair> list = null;
		list = new List<IdNamePair>();
		try
		{
			Database database = DatabaseWrapper.GetDatabase2(iCompanyId);
			empty = $"SELECT iLayoutId, sLayoutName, bDefault FROM cCore_QuotationLayouts{suffix} ORDER BY bDefault DESC";
			dataReader = database.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(empty) : empty);
			while (dataReader.Read())
			{
				list.Add(new IdNamePair(Convert.ToInt32(dataReader["iLayoutId"]), Convert.ToString(dataReader["sLayoutName"]), Convert.ToBoolean(dataReader["bDefault"])));
			}
			dataReader.Close();
		}
		catch (Exception ex)
		{
			list.Clear();
			list.Add(new IdNamePair(-1, ex.Message, 1));
		}
		return list;
	}

