							}
							else if (Convert.ToBoolean(objReader["bGroup"]))
							{
								list5[num].Suppliers.AddRange(GetAccountNameInGroup(Convert.ToInt32(objReader["iSupplier"]), database));
							}
							else
							{
								list5[num].Suppliers.Add(new ComboData(Convert.ToInt32(objReader["iSupplier"]), Convert.ToString(objReader["Supplier"])));
							}
						}
					}
					objReader.Close();
				}
			}
		}
		catch (Exception ex)
		{
			list5.Clear();
			raiseRFQData = new RaiseRFQData();
			raiseRFQData.ProductId = -1;
			raiseRFQData.ProductName = ex.Message;
			list5.Add(raiseRFQData);
		}
		return list5;
	}

