	public string updateBaseQuotation(long[] arrTranIds, int iCompanyId)
	{
		string text = null;
		string text2 = null;
		long num = 0L;
		int num2 = 0;
		Database database = null;
		try
		{
			if (arrTranIds != null && arrTranIds.Length != 0)
			{
				database = DatabaseWrapper.GetDatabase2(iCompanyId);
				text2 = FConvert.GetSuffix(iCompanyId);
				for (num2 = 0; num2 < arrTranIds.Length; num2++)
				{
					text = string.Format("WITH RecursionCTE (iTransId, iParentId)  \r\n                        AS  \r\n                        (  \r\n                            SELECT iTransactionId, iRefId iParentId  FROM tCore_Links{0} \r\n                            WHERE iTransactionId = {1} AND bBase = 1\r\n                            UNION ALL  \r\n                            SELECT R1.iTransactionId, R1.iRefId iParentId FROM tCore_Links{0} AS R1 \r\n                            JOIN RecursionCTE AS R2 ON R1.iTransactionId = R2.iParentId AND R1.bBase = 0\r\n                        )\r\n                        SELECT iParentId FROM RecursionCTE \r\n                        JOIN tCore_Data{0} ON tCore_Data{0}.iTransactionId = RecursionCTE.iParentId\r\n                        JOIN tCore_Header{0} ON tCore_Data{0}.iHeaderId = tCore_Header{0}.iHeaderId \r\n                        AND tCore_Header{0}.iVoucherClass = {2}", text2, arrTranIds[num2], 7936);
					num = Convert.ToInt64(database.ExecuteScalar(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text));
					if (num > 0)
					{
						text = $"UPDATE tCore_Links{text2} SET bClosed = 1 WHERE iTransactionId = {num} and bBase = 1";
						database.ExecuteNonQuery(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
					}
				}
			}
			return null;
		}
		catch (Exception ex)
		{
			FConvert.LogFile("FQuery.log", "Exception QueryGenerator->updateBaseQuotation : " + ex.Message + " \r\n " + ex.StackTrace);
			return ex.Message;
		}
	}

