	private string GetPendingBillsHeaderIds(int iVoucherType, Database objDB)
	{
		List<string> list = new List<string>();
		if (iVoucherType == 3328 || iVoucherType == 768)
		{
			string text = string.Format("SELECT DISTINCT a.iHeaderId \r\n                FROM tCore_Header{0} a \r\n                JOIN tCore_Data{0} b ON a.iHeaderId = b.iHeaderId\r\n                JOIN tCore_Refrn{0} c WITH(READUNCOMMITTED) ON b.iBodyId = c.iBodyId\r\n                JOIN\r\n                (\r\n\t                SELECT iRef\r\n\t                FROM tCore_Data{0} a JOIN tCore_Refrn{0} b WITH(READUNCOMMITTED) ON a.iBodyId = b.iBodyId\r\n\t                GROUP BY iRef\r\n\t                HAVING SUM(mAmount) {1} 0\r\n                )d ON c.iRef = d.iRef AND c.iRefType < 2", Suffix, (iVoucherType == 3328) ? "<" : ">");
			text = ((iVoucherType != 3328) ? (text + $" WHERE a.iVoucherClass IN({iVoucherType},{1280},{9216})") : (text + $" WHERE a.iVoucherClass IN({iVoucherType},{6144},{11776})"));
			IDataReader dataReader = objDB.ExecuteReader(CommandType.Text, PostgreSQL.bUsePostgreSql ? PostgreSQL.ConvertSqlToPostgre(text) : text);
			while (dataReader.Read())
			{
				list.Add(Convert.ToString(dataReader[0]));
			}
			dataReader.Close();
		}
		else
		{
			list.Add("0");
		}
		return string.Join(",", list);
	}

