	{
		bool flag = false;
		InitFlags initFlags = null;
		try
		{
			sError = string.Empty;
			if (GetPreferenceValue(37, 0, iCompId) <= 0)
			{
				return false;
			}
			initFlags = new InitFlags();
			if (GetPreferenceValue(37, 5, iCompId) == 0)
			{
				initFlags.Batches = 2;
			}
			if (GetPreferenceValue(37, 2, iCompId) == 0)
			{
				initFlags.Links = 2;
			}
			if (GetPreferenceValue(37, 7, iCompId) == 0)
			{
				initFlags.Masters = 2;
			}
			if (GetPreferenceValue(37, 1, iCompId) == 0)
			{
				initFlags.Preferences = 2;
			}
			if (GetPreferenceValue(37, 8, iCompId) == 0)
			{
				initFlags.Pricebooks = 2;
			}
			if (GetPreferenceValue(37, 3, iCompId) == 0)
			{
				initFlags.Reservations = 2;
			}
			if (GetPreferenceValue(37, 6, iCompId) == 0)
			{
				initFlags.IBals = 2;
			}
			if (GetPreferenceValue(37, 4, iCompId) == 0)
			{
				initFlags.VoucherWizard = 2;
			}
			flag = false;
			ProngHorn.InitializeSocket(iCompId, initFlags, ref flag);
