	private string DefaultTranQuery(RepRecord objRec, Database objDb, bool bPreviousYear, FieldData[] arrFields, string[] arrExtraColumns, string strSecurityFilter, FieldData[] arrFilterFields)
	{
		bool bAuthStatus = true;
		string text = null;
		string text2 = null;
		string text3 = null;
		string text4 = $"tCore_Header{Suffix}.iHeaderId";
		int num = 0;
		bool flag = false;
		bool flag2 = false;
		bool flag3 = false;
		if ((byte)objRec.SubReportId == 1)
		{
			flag = IsHeaderFieldOnly(arrFields);
		}
		for (num = 0; num < arrFields.Length; num++)
		{
			if (arrFields[num].DataType == MasterDataType.Fraction)
			{
				flag2 = true;
			}
			if (arrFields[num].FieldId == -2)
			{
				flag3 = true;
			}
			if ((byte)objRec.SubReportId == 2 && arrFields[num].SubParentId == 23)
			{
				text4 = $"tCore_Data{Suffix}.iBodyId";
			}
		}
		if (objRec.ReportCustomize.Layout != null && objRec.ReportCustomize.Layout.Columns != null)
		{
			_ = objRec.ReportCustomize.Layout.Columns.Where((_Column p) => p.ColumnFilter != null && p.ColumnFilter.Length != 0).Count() > 0;
		}
		else
			_ = 0;
		if (!flag && !flag2 && objRec.ColumnSort == null)
		{
			text2 = "DISTINCT";
		}
		else if (objRec.ColumnSort != null)
		{
			objRec.ReportCustomize.DelayFetch = false;
		}
		int num2 = 0;
		if (objRec.FilterSource == null || objRec.FilterSource.Length == 0)
		{
			num2 = _focus.company(m_iCompId).getPreferenceValue(PreferenceCategories.Print, 32);
		}
		if (num2 > 0 && !objRec.IsSelectAll && (byte)objRec.SubReportId == 1)
		{
			text2 += $" TOP {num2} ";
			objRec.ReportCustomize.DelayFetch = false;
		}
		string committedString = MemDB.GetCommittedString(m_iCompId, objDb);
		switch ((CustomizeColumn)(byte)objRec.SubReportId)
		{
		case CustomizeColumn.HomePage:
		case CustomizeColumn.LinkVoucher:
		case CustomizeColumn.PendingBills:
		case CustomizeColumn.Drafts:
			text3 = ",0[Balance value], ''[Link Status]";
			m_arrLinkId = IsLinkField(objRec);
			if (m_arrLinkId != null && m_arrLinkId.Length != 0)
			{
				if ((byte)objRec.SubReportId == 2)
				{
					text3 = ((m_arrLinkId.Length <= 1 || flag3) ? string.Format(",SUM(vCore_Links{1}{0}.Balance)[Balance]\r\n                                ,CASE WHEN ISNULL(SUM(vCore_Links{1}{0}.bClosed), 0) > 0 OR (ISNULL(SUM(vCore_Links{1}{0}.Base), 0) <> 0 AND ISNULL(SUM(vCore_Links{1}{0}.Balance), 0) = 0) THEN 'Closed' \r\n                                WHEN ISNULL(SUM(vCore_Links{1}{0}.Base), 0) <> 0 AND ISNULL(SUM(vCore_Links{1}{0}.Balance), 0) > 0 \r\n                                AND ISNULL(SUM(vCore_Links{1}{0}.Base), 0) > ISNULL(SUM(vCore_Links{1}{0}.Balance), 0) THEN 'Partial Consumed'\r\n                                WHEN ISNULL(SUM(vCore_Links{1}{0}.Base), 0) <> 0 AND ISNULL(SUM(vCore_Links{1}{0}.Balance), 0) > 0 THEN 'Pending'\r\n                                ELSE '' END [Link Status]", Suffix, m_arrLinkId[0]) : string.Format(",SUM(vCore_Links{1}{0}.Balance)[Balance], '' [Link Status]", Suffix, m_arrLinkId[0]));
				}
				else
				{
					text3 = ((m_arrLinkId.Length <= 1 || flag3) ? string.Format(",SUM(vCore_Links{1}{0}.Balance)[Balance]\r\n,CASE WHEN ISNULL(SUM(vCore_Links{1}{0}.bClosed), 0) > 0 OR (ISNULL(SUM(vCore_Links{1}{0}.Base), 0) <> 0 AND ISNULL(SUM(vCore_Links{1}{0}.Balance), 0) = 0) THEN 'Closed' \r\nWHEN ISNULL(SUM(vCore_Links{1}{0}.Base), 0) <> 0 AND ISNULL(SUM(vCore_Links{1}{0}.Balance), 0) > 0 \r\nAND ISNULL(SUM(vCore_Links{1}{0}.Base), 0) > ISNULL(SUM(vCore_Links{1}{0}.Balance), 0) THEN 'Partial Consumed'\r\nWHEN ISNULL(SUM(vCore_Links{1}{0}.Base), 0) <> 0 AND ISNULL(SUM(vCore_Links{1}{0}.Balance), 0) > 0 THEN 'Pending'\r\nELSE '' END [Link Status]", Suffix, m_arrLinkId[0]) : ",0[Balance],''[Link Status]");
				}
			}
